LESSONS.push(
  {"id":"g9-chem-1-u1-1","grade":"g9","subject":"chemistry","term":1,"unit":1,"no":1,"title":"حالات المادّة","summary":"شرح متحرك بـ SVG لدرس حالات المادّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-states-of-matter-chem.html","video":"","pdf":"","notes":["صلب (اهتزاز منتظم) | سائل (انزلاق متقارب) | غاز (حركة عشوائية سريعة وقابل للانضغاط).","ثبات الحرارة أثناء الانصهار والغليان = استهلاك الطاقة لكسر قوى التجاذب؛ والشوائب تخفض الانصهار وترفع الغليان.","الغاز الأخف (Mr أصغر) ينتشر أسرع (NH₃ أسرع من HCl)."],"exercises":["قارن بين الصلب والسائل والغاز من حيث: ترتيب الجسيمات، حركة الجسيمات، وقابلية الانضغاط.","فسّر علميًا لماذا تكوّنت حلقة كلوريد الأمونيوم البيضاء أقرب إلى طرف حمض HCl في تجربة انتشار الغازات.","اشرح أثر إضافة الملح على درجتَي تجمّد وغليان الماء النقي، مع ذكر تطبيق حياتي واحد."],"levels":{"easy":[{"type":"mcq","q":"أي حالة من حالات المادة تكون جسيماتها متراصّة ومنتظمة وتهتز في مواضعها فقط؟","options":["الحالة الصلبة","الحالة السائلة","الحالة الغازية","المحاليل المائية"],"answer":0,"why":"في الصلب تهتز الجسيمات في مواقع ثابتة ومنتظمة."},{"type":"mcq","q":"يُسمّى تحوّل المادة من الحالة الصلبة إلى الغازية مباشرةً دون المرور بالسائلة:","options":["التكثّف","التسامي","التجمّد","الانصهار"],"answer":1,"why":"التسامي مثل تسامي اليود وثاني أكسيد الكربون الصلب."},{"type":"mcq","q":"لماذا تثبت درجة الحرارة أثناء انصهار قطعة جليد نقي رغم استمرار التسخين؟","options":["لأن الجليد لا يمتص حرارة","لأن التسخين توقف فجأة","لأن الطاقة الحرارية تُستخدم في التغلّب على قوى التجاذب بين الجسيمات","لأن الكتلة تختفي"],"answer":2,"why":"تُستهلك الطاقة في كسر قوى الترابط لا في رفع درجة الحرارة."},{"type":"mcq","q":"ما أثر وجود شوائب (كالملح) في عينة من الماء على درجتَي انصهاره وغليانه؟","options":["تجعلهما متساويتين","ترفع الانصهار وتخفض الغليان","لا تؤثر أبدًا","تُخفض درجة الانصهار وترفع درجة الغليان"],"answer":3,"why":"الشوائب تخفض درجة الانصهار وتمدّ نطاقها وترفع درجة الغليان."}],"medium":[{"type":"mcq","q":"في تجربة أنبوب الانتشار بين الأمونيا (Mr=17) وكلوريد الهيدروجين (Mr=36.5)، تتكوّن الحلقة البيضاء أقرب إلى طرف HCl لأن:","options":["جسيمات الأمونيا أخفّ فتنتشر أسرع وتقطع مسافةً أكبر","جسيمات HCl أخفّ","الأمونيا صلبة","الحرارة أعلى عند HCl"],"answer":0,"why":"الغاز ذو الكتلة الجزيئية الأصغر ينتشر بسرعة أكبر."},{"type":"mcq","q":"ما الفرق الصحيح بين التبخّر والغليان؟","options":["التبخّر عند ١٠٠°C فقط","التبخّر يحدث عند أي درجة ومن السطح فقط، والغليان عند درجة محددة وفي كل السائل","الغليان من السطح فقط","كلاهما نفس العملية تمامًا"],"answer":1,"why":"التبخر سطحي وفي أي درجة، والغليان شامل وعند درجة الغليان."},{"type":"mcq","q":"ما سبب ارتفاع ضغط الهواء داخل إطار سيارة متوقفة تحت شمس الصيف الحارة في عُمان؟","options":["يتحول الهواء إلى صلب","يزداد عدد الجسيمات داخل الإطار المغلق","تزداد طاقة حركة جسيمات الهواء فتزداد سرعة وتكرار تصادماتها بجدار الإطار","تنخفض سرعة الجسيمات"],"answer":2,"why":"ارتفاع الحرارة يزيد طاقة الحركة ومعدل التصادمات مع الجدار."},{"type":"tfr","q":"تثبت درجة حرارة المادة النقية أثناء عمليتَي الانصهار والغليان.","answer":true,"reasons":["لأن الطاقة المكتسبة تُستهلك في التغلب على قوى التجاذب بين الجسيمات","ترتفع باستمرار دون ثبات","تنخفض أثناء التسخين"],"reason":0},{"type":"tfr","q":"تنتشر جسيمات الغاز الأثقل (ذات الكتلة الجزيئية الأكبر) أسرع من جسيمات الغاز الأخف.","answer":false,"reasons":["نعم الأثقل أسرع","العكس تمامًا: الجسيمات الأخفّ تنتشر أسرع عند نفس درجة الحرارة","تنتشر كلها بنفس السرعة"],"reason":1},{"type":"essay","q":"قارن بين الصلب والسائل والغاز من حيث: ترتيب الجسيمات، حركة الجسيمات، وقابلية الانضغاط.","model":"الصلب: متراص منتظم، اهتزاز موضعي، غير قابل للانضغاط. السائل: متقارب غير منتظم، انزلاق، صعب الانضغاط جدًا. الغاز: متباعد عشوائي، حركة سريعة، سهل الانضغاط."},{"type":"essay","q":"فسّر علميًا لماذا تكوّنت حلقة كلوريد الأمونيوم البيضاء أقرب إلى طرف حمض HCl في تجربة انتشار الغازات.","model":"لأن الكتلة الجزيئية للأمونيا (NH₃ = 17) أصغر من كلوريد الهيدروجين (HCl = 36.5)، فتتحرك جسيمات الأمونيا وتنتشر أسرع وتقطع مسافةً أكبر قبل الالتقاء."}],"hard":[{"type":"mcq","q":"أي الغازات الآتية ينتشر بأسرع معدل عند نفس درجة الحرارة؟ (H₂=2, CH₄=16, O₂=32, CO₂=44)","options":["ثاني أكسيد الكربون CO₂","الميثان CH₄","الأكسجين O₂","الهيدروجين H₂"],"answer":3,"why":"H₂ له أصغر كتلة جزيئية نسبية (Mr = 2) فينتشر أسرع."},{"type":"mcq","q":"كيف تتحقّق مخبريًا من أن عينة ماء نقية تمامًا؟","options":["بقياس درجة غليانها (١٠٠°C بالضبط) أو تجمدها (٠°C بالضبط)","بلونها فقط","بطعمها فقط","بحجمها فقط"],"answer":0,"why":"الماء النقي يغلي عند ١٠٠°C بالضبط ويتجمد عند ٠°C بالضبط."},{"type":"mcq","q":"تنتقل رائحة البخور في غرفة ساكنة الهواء من الركن إلى باقي الغرفة بعملية:","options":["التكثّف","الانتشار","التقطير","الترشيح"],"answer":1,"why":"الانتشار هو حركة الجسيمات العشوائية من التركيز الأعلى للأقل."},{"type":"mcq","q":"أي حالة من حالات المادة قابلة للانضغاط بسهولة كبيرة؟","options":["السوائل","المواد الصلبة","الغازات (لوجود مسافات شاسعة بين جسيماتها)","الفلزات"],"answer":2,"why":"المسافات البينية الكبيرة في الغازات تسمح بضغطها بسهولة."},{"type":"tfr","q":"وجود الشوائب في مادة صلبة يؤدي إلى خفض درجة انصهارها وجعلها تنصهر على مدى حراري.","answer":true,"reasons":["لا يؤثر على درجة انصهارها","يرفع درجة انصهارها","لذا تُستخدم درجة الانصهار الحادة اختبارًا لنقاء المواد"],"reason":2},{"type":"tfr","q":"يحدث التبخّر في جميع أجزاء السائل وعند درجة حرارة ثابتة فقط.","answer":false,"reasons":["هذا وصف الغليان؛ أما التبخّر فيحدث من السطح فقط وعند أي درجة حرارة","نعم في كل السائل","يحدث في القاع فقط"],"reason":0},{"type":"tfr","q":"تزداد سرعة الانتشار في الغازات والسوائل عند رفع درجة الحرارة.","answer":true,"reasons":["تقل سرعة الانتشار","لأن ارتفاع الحرارة يزيد الطاقة الحركية وسرعة حركة الجسيمات","لا تتأثر بالحرارة"],"reason":1},{"type":"essay","q":"اشرح أثر إضافة الملح على درجتَي تجمّد وغليان الماء النقي، مع ذكر تطبيق حياتي واحد.","model":"الملح شائبة فيخفض درجة التجمّد (أقل من ٠°C) ويرفع درجة الغليان (أعلى من ١٠٠°C). التطبيق: رشّ الملح على الطرق الجليدية لمنع تجمد الماء وإذابة الجليد."},{"type":"essay","q":"ارسم بالكلمات شكل منحنى التسخين للماء من −١٠°C إلى ١١٠°C موضحًا سبب الجزأين الأفقيين.","model":"يرتفع المنحنى حتى ٠°C ثم يثبت أفقيًا أثناء الانصهار، ثم يرتفع حتى ١٠٠°C ويثبت أفقيًا أثناء الغليان ثم يرتفع للبخار؛ وسبب الثبات استهلاك الحرارة في التغلب على قوى التجاذب."},{"type":"essay","q":"فسّر باستخدام نظرية الجسيمات لماذا يزداد ضغط الغاز المحبوس داخل أسطوانة عند تقليل حجمها بثبات الحرارة.","model":"بتقليل الحجم تتقارب الجسيمات في مساحة أصغر فتزداد عدد تصادماتها مع جدران الأسطوانة في الثانية الواحدة، فيرتفع الضغط."}]}},
  {"id":"g9-chem-1-u1-2","grade":"g9","subject":"chemistry","term":1,"unit":1,"no":2,"title":"فصل المواد وتنقيتها","summary":"شرح متحرك بـ SVG لدرس فصل المواد وتنقيتها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-separation-and-purification.html","video":"","pdf":"","notes":["الترشيح (صلب غير ذائب) | التبلور (ملح ذائب) | التقطير البسيط (المذيب) | التجزيئي (سوائل ممتزجة بعمود تجزئة).","الكروماتوجرافيا: خط بداية بالرصاص، المذيب أسفل الخط، و Rf = مسافة البقعة ÷ مسافة المذيب (< ١).","المادة النقية لها درجة انصهار وغليان حادة وبقعة واحدة في الكروماتوجرام."],"exercises":["صف الخطوات العملية لفصل خليط من «مسحوق الطباشير (غير ذائب) وملح الطعام (ذائب)» للحصول على كل منهما جافًا ونقيًا.","في كروماتوجرام، قطع المذيب ١٢ سم، وقطعت البقعة A مسافة ٣ سم، والبقعة B مسافة ٩ سم. احسب Rf لكل منهما، وأيهما أكثر ذوبانًا في المذيب؟","قارن بين «التقطير البسيط» و«التقطير التجزيئي» من حيث الاستخدام والتركيب."],"levels":{"easy":[{"type":"mcq","q":"ما الطريقة الأنسب لفصل خليط من الإيثانول (غليانه ٧٨°C) والماء (غليانه ١٠٠°C)؟","options":["الترشيح","التقطير التجزيئي","التبلور","الفرز اليدوي"],"answer":1,"why":"سائلان ممتزجان مختلفان في درجة الغليان يُفصلان بالتقطير التجزيئي."},{"type":"mcq","q":"لماذا يُرسم خط البداية في تجربة الكروماتوجرافيا بـ«قلم الرصاص» لا بقلم الحبر؟","options":["لأن الحبر لا يكتب على الورق","لأن الرصاص أرخص فقط","لأن الجرافيت لا يذوب في المذيب فلا يتداخل مع البقع، بخلاف الحبر الذي يذوب وينفصل","لأن الرصاص يذوب أسرع"],"answer":2,"why":"الحبر خليط أصباغ سيذوب ويفسد الكروماتوجرام."},{"type":"mcq","q":"في تجربة كروماتوجرافيا، قطعت بقعة صبغة مسافة ٤٫٥ سم، وقطع المذيب ٩٫٠ سم. ما قيمة Rf؟","options":["٠٫٠٥","٢٫٠","٤٫٥","٠٫٥٠"],"answer":3,"why":"Rf = ٤٫٥ ÷ ٩٫٠ = ٠٫٥٠."},{"type":"mcq","q":"ما الخطأ الذي يفسد تجربة الكروماتوجرافيا إذا وُضع خط البداية «تحت» سطح المذيب؟","options":["تذوب عينات الأصباغ مباشرةً في المذيب بقاع الكأس بدل أن تصعد على الورقة","لا يتحرك المذيب أبدًا","تحترق الورقة","تزيد دقة التجربة"],"answer":0,"why":"يجب أن يكون المذيب أسفل خط البداية."}],"medium":[{"type":"mcq","q":"للحصول على «ماء شرب نقي» من ماء البحر المالح في المختبر نستخدم:","options":["الترشيح فقط","التقطير البسيط","قمع الفصل","الكروماتوجرافيا"],"answer":1,"why":"التقطير البسيط يبخّر الماء ثم يكثفه نقيًا ويبقي الملح."},{"type":"mcq","q":"ما وظيفة «عمود التجزئة» في جهاز التقطير التجزيئي؟","options":["ترشيح الرمل","تبريد الدورق","توفير مساحة سطح لتكثيف السائل الأعلى غليانًا وإعادته للدورق والسماح للأقل غليانًا بالمرور أولًا","تلوين السائل"],"answer":2,"why":"يضمن فصلًا دقيقًا بين السوائل المتقاربة في الغليان."},{"type":"mcq","q":"أعطت عينة دواء ٣ بقع منفصلة في الكروماتوجرام؛ هذا يعني أن العينة:","options":["لا تذوب في المذيب","مادة نقية تمامًا","عنصر كيميائي","خليط يحتوي على ٣ مواد على الأقل (غير نقية)"],"answer":3,"why":"المادة النقية تعطي بقعةً واحدةً فقط."},{"type":"tfr","q":"قيمة معامل الإعاقة (Rf) في الكروماتوجرافيا تكون دائمًا أصغر من ١.","answer":true,"reasons":["تكون أكبر من ١ دائمًا","لأن البقعة لا يمكن أن تقطع مسافةً أكبر من مسافة المذيب نفسه","تساوي ١٠ دائمًا"],"reason":1},{"type":"tfr","q":"يمكن فصل الملح الذائب في الماء باستخدام ورقة الترشيح فقط.","answer":false,"reasons":["يبقى الملح فوق ورقة الترشيح","نعم بالترشيح فقط","الأيونات الذائبة صغيرة جدًا فتمر عبر مسام ورقة الترشيح؛ نفصله بالتبلور أو التقطير"],"reason":2},{"type":"essay","q":"صف الخطوات العملية لفصل خليط من «مسحوق الطباشير (غير ذائب) وملح الطعام (ذائب)» للحصول على كل منهما جافًا ونقيًا.","model":"١) نضيف ماءً ونحرّك ليذوب الملح ويبقى الطباشير. ٢) نرشّح الخليط فيبقى الطباشير راسبًا نغسله ونجففه. ٣) نسخن الراشح (المحلول الملحي) للتبلور ثم نبرّده ونرشّح بلورات الملح ونجففها."},{"type":"essay","q":"في كروماتوجرام، قطع المذيب ١٢ سم، وقطعت البقعة A مسافة ٣ سم، والبقعة B مسافة ٩ سم. احسب Rf لكل منهما، وأيهما أكثر ذوبانًا في المذيب؟","model":"Rf(A) = ٣÷١٢ = ٠٫٢٥. Rf(B) = ٩÷١٢ = ٠٫٧٥. المادة B أكثر ذوبانًا في المذيب لأنها قطعت مسافةً أبعد."}],"hard":[{"type":"mcq","q":"لإظهار بقع مواد «عديمة اللون» (كالأحماض الأمينية) على ورقة الكروماتوجرافيا نستخدم:","options":["عامل تحديد موقع (Locating agent) يتفاعل معها ويعطي لونًا","الترشيح","التجميد","المغناطيس"],"answer":0,"why":"عامل تحديد الموقع يلوّن البقع غير المرئية."},{"type":"mcq","q":"ما الطريقة الصحيحة لفصل خليط من الرمل والملح معًا؟","options":["تسخين مباشر للخليط الجاف","إضافة ماء ← ترشيح لفصل الرمل ← تبلور لفصل الملح","تقطير تجزيئي فقط","استخدام مغناطيس"],"answer":1,"why":"الذوبانية المختلفة تسمح بفصل الرمل بالترشيح ثم الملح بالتبلور."},{"type":"mcq","q":"كيف يُفصل سائلان «غير ممتزجين» مثل الزيت والماء؟","options":["بالكروماتوجرافيا","بالتبلور","باستخدام قمع الفصل (Separating funnel)","بالتسامي"],"answer":2,"why":"السائل الأكثر كثافةً (الماء) ينزل أولًا من صنبور قمع الفصل."},{"type":"mcq","q":"في التقطير، كيف يتدفق ماء التبريد داخل المكثّف (Condenser)؟","options":["يُغلى داخل المكثف","يدخل من الأعلى ويخرج من الأسفل","لا يحتاج ماء تبريد","يدخل من الفتحة السفلية ويخرج من العلوية ليمتلئ المكثّف تمامًا"],"answer":3,"why":"الدخول من الأسفل يضمن امتلاء الغلاف بالماء البارد وكفاءة التكثيف."},{"type":"tfr","q":"في الكروماتوجرافيا، المادة الأكثر ذوبانًا في المذيب تقطع مسافةً أبعد على الورقة.","answer":true,"reasons":["فيكون لها قيمة Rf أكبر من المادة الأقل ذوبانًا","تبقى عند خط البداية","تتجه للأسفل"],"reason":0},{"type":"tfr","q":"التقطير التجزيئي هو الطريقة الصناعية المستخدمة في مصفاة صحار لفصل مكونات النفط الخام.","answer":true,"reasons":["يُفصل النفط بالترشيح","لاختلاف درجات غليان مشتقات النفط (غاز، بنزين، كيروسين، ديزل...)","يُفصل بالكروماتوجرافيا"],"reason":1},{"type":"tfr","q":"نستخدم التبلور بدلًا من التبخير حتى الجفاف التام للحصول على بلورات ملح نقية دون أن تتحلل بالحرارة.","answer":true,"reasons":["التبلور لا يحتاج تبريدًا","التبخير التام يعطي بلورات أكبر دائمًا","فبعض الأملاح المائية تفقد ماء تبلورها أو تتفكك بالتسخين الشديد حتى الجفاف"],"reason":2},{"type":"essay","q":"قارن بين «التقطير البسيط» و«التقطير التجزيئي» من حيث الاستخدام والتركيب.","model":"البسيط: يفصل مذيبًا عن مادة صلبة ذائبة (كماء البحر) دون عمود تجزئة. التجزيئي: يفصل سائلين ممتزجين أو أكثر مختلفَي الغليان (كالإيثانول والماء أو النفط) ويحتوي عمود تجزئة."},{"type":"essay","q":"اذكر احتياطين أساسيين عند إعداد ورقة الكروماتوجرافيا ووضّح سبب كل منهما.","model":"١) رسم خط البداية بقلم الرصاص (لا يذوب في المذيب). ٢) وضع مستوى المذيب أسفل خط البداية (حتى لا تذوب العينات في قاع الكأس قبل الصعود)."},{"type":"essay","q":"كيف يمكنك التأكد من أن عينة من مركب «الأسبرين» المصنّع في المختبر نقية تمامًا؟","model":"بقياس درجة انصهارها (يجب أن تكون حادة ومطابقة للقيمة القياسية) أو بإجراء كروماتوجرافيا (يجب أن تعطي بقعة واحدة فقط)."}]}},
  {"id":"g9-chem-1-u2-1","grade":"g9","subject":"chemistry","term":1,"unit":2,"no":1,"title":"الذرّات والجُزيئات","summary":"شرح متحرك بـ SVG لدرس الذرّات والجُزيئات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-atoms-and-molecules.html","video":"","pdf":"","notes":["العنصر: نوع واحد من الذرات (Fe، O₂) | المركّب: اتحاد كيميائي بنسبة ثابتة وخصائص جديدة (H₂O، FeS).","المخلوط: امتزاج فيزيائي يحتفظ بخصائص مكوناته ويُفصل فيزيائيًا (الهواء، ماء البحر).","انتبه لحجم الحروف في الرموز: CO (مركّب) ≠ Co (عنصر الكوبالت)."],"exercises":["قارن في جدول بين «المركّب» و«المخلوط» من حيث: الاتحاد الكيميائي، النسب، الخصائص، وطريقة الفصل.","صنّف المواد الآتية إلى عنصر أو مركّب أو مخلوط: النحاس (Cu)، ثاني أكسيد الكربون (CO₂)، الهواء، ماء البحر، غاز النيتروجين (N₂).","اشرح تجربة الحديد والكبريت قبل التسخين وبعده لتوضيح الفرق بين المخلوط والمركّب."],"levels":{"easy":[{"type":"mcq","q":"أي مما يأتي يُعدّ «عنصرًا» يتكوّن من جزيئات ثنائية الذرة؟","options":["ثاني أكسيد الكربون CO₂","الماء H₂O","غاز الأكسجين O₂","ملح الطعام NaCl"],"answer":2,"why":"O₂ يتكون من نوع واحد من الذرات (أكسجين) مرتبطتين معًا."},{"type":"mcq","q":"عند تسخين خليط من برادة الحديد ومسحوق الكبريت بشدة يتكوّن كبريتيد الحديد (FeS)؛ ما الدليل على أنه أصبح «مركّبًا»؟","options":["تبقى ألوانه منفصلة","يبقى الحديد منجذبًا للمغناطيس","يذوب الحديد في الماء","تتغير خصائصه ولا ينجذب للمغناطيس ولا يُفصل بطرق فيزيائية"],"answer":3,"why":"فقدان الخواص الأصلية (المغناطيسية) دليل تكوّن مركّب جديد."},{"type":"mcq","q":"يُصنّف «الهواء الجوي» علميًا على أنه:","options":["مخلوط من عدة غازات (عناصر ومركبات)","عنصر نقي","مركّب كيميائي واحد","سبيكة فلزية"],"answer":0,"why":"الهواء خليط من N₂ و O₂ و Ar و CO₂ بنسب متغيرة دون اتحاد كيميائي."},{"type":"mcq","q":"ما الفرق بين الرمزين CO و Co في الكيمياء؟","options":["كلاهما نفس العنصر","CO مركّب (أول أكسيد الكربون)، أما Co فعنصر (الكوبالت)","كلاهما مركب","CO عنصر و Co مركب"],"answer":1,"why":"الحرف الثاني الكبير يعني عنصرًا ثانيًا (مركّب)، والصغير تابع للأول (عنصر)."}],"medium":[{"type":"mcq","q":"أي العبارات الآتية تصف «المركّب الكيميائي» بدقة؟","options":["يُفصل بالترشيح بسهولة","تحتفظ عناصره بخصائصها الأصلية","يتكوّن من عنصرين أو أكثر متحدين كيميائيًا بنسب ثابتة وخصائصه مختلفة عن عناصره","يتكوّن بنسب عشوائية متغيرة"],"answer":2,"why":"الاتحاد الكيميائي يثبّت النسب ويولّد خصائص جديدة تمامًا."},{"type":"mcq","q":"أي المواد الآتية يُعدّ «مخلوطًا» وليس مركّبًا؟","options":["كلوريد الصوديوم (NaCl)","الماء المقطّر (H₂O)","السكر النقي","ماء البحر"],"answer":3,"why":"ماء البحر مخلوط من ماء وأملاح ذائبة يمكن فصلها بالتقطير."},{"type":"mcq","q":"توجد الغازات النبيلة مثل الهيليوم (He) والنيون (Ne) في الطبيعة على هيئة:","options":["ذرات منفردة (أحادية الذرة)","جزيئات ثنائية الذرة","بلورات أيونية","مركبات معقدة"],"answer":0,"why":"الغازات النبيلة مستقرة فتوجد كذرات منفردة."},{"type":"tfr","q":"المركّب الكيميائي يحتفظ بنفس خصائص العناصر التي تكوّن منها.","answer":false,"reasons":["في الغازات فقط","نعم يحتفظ بها","بل تختلف خصائصه تمامًا عن عناصره (كالماء H₂O مقارنةً بـ H₂ و O₂)"],"reason":2},{"type":"tfr","q":"يمكن فصل برادة الحديد عن الكبريت بالمغناطيس قبل التسخين، لكن لا يمكن ذلك بعد التسخين وتكوّن FeS.","answer":true,"reasons":["لأنه تحوّل من مخلوط فيزيائي إلى مركّب كيميائي جديد","يمكن فصله بالمغناطيس بعد التسخين أيضًا","لا ينجذب الحديد أبدًا"],"reason":0},{"type":"essay","q":"قارن في جدول بين «المركّب» و«المخلوط» من حيث: الاتحاد الكيميائي، النسب، الخصائص، وطريقة الفصل.","model":"المركب: اتحاد كيميائي، نسب ثابتة، خصائص جديدة، يُفصل كيميائيًا فقط. المخلوط: بلا اتحاد، أي نسب، يحتفظ بخصائص مكوناته، يُفصل فيزيائيًا."},{"type":"essay","q":"صنّف المواد الآتية إلى عنصر أو مركّب أو مخلوط: النحاس (Cu)، ثاني أكسيد الكربون (CO₂)، الهواء، ماء البحر، غاز النيتروجين (N₂).","model":"عنصر: النحاس، غاز النيتروجين. مركّب: ثاني أكسيد الكربون. مخلوط: الهواء، ماء البحر."}],"hard":[{"type":"mcq","q":"ما الطريقة التي يمكن بها فصل الهيدروجين والأكسجين في مركّب الماء (H₂O)؟","options":["الترشيح","طريقة كيميائية مثل التحليل الكهربائي","التقطير البسيط","المغناطيس"],"answer":1,"why":"المركبات لا تُفصل إلى عناصرها إلا بطرق كيميائية."},{"type":"mcq","q":"جزيء الميثان (CH₄) يتكوّن من:","options":["٤ ذرات كربون وذرة هيدروجين","٥ ذرات كربون","ذرة كربون واحدة و٤ ذرات هيدروجين (مركّب)","عنصر واحد فقط"],"answer":2,"why":"يحتوي عنصرين مختلفين (C و H) بنسبة ١ : ٤."},{"type":"mcq","q":"أي خاصية تميّز «المخلوط» عن «المركّب»؟","options":["نسبه ثابتة لا تتغير","تتحد مكوناته بروابط كيميائية","له درجة انصهار ثابتة وحادة دائمًا","تُفصل مكونات المخلوط بطرق فيزيائية وتبقى خواصها كما هي"],"answer":3,"why":"المخلوط لا يحدث فيه تفاعل كيميائي."},{"type":"mcq","q":"الرمز الكيميائي الصحيح لعنصر الصوديوم هو:","options":["Na","NA","So","S"],"answer":0,"why":"الحرف الأول كبير والثاني صغير: Na (من اللاتينية Natrium)."},{"type":"tfr","q":"الهواء الجوي مركّب كيميائي له صيغة كيميائية ثابتة.","answer":false,"reasons":["نعم مركب","بل هو مخلوط من عدة غازات (نيتروجين وأكسجين وأرجون وCO₂)","هو عنصر واحد"],"reason":1},{"type":"tfr","q":"الجزيء قد يكون جزيء عنصر (مثل O₂) أو جزيء مركّب (مثل CO₂).","answer":true,"reasons":["الجزيء للعناصر فقط","الجزيء للمركبات فقط","المهم أن يتكون من ذرتين أو أكثر مرتبطتين معًا"],"reason":2},{"type":"tfr","q":"كتابة الحرف الثاني كبيرًا في الرمز الكيميائي (مثل CO بدل Co) تغيّر المعنى من عنصر إلى مركّب.","answer":true,"reasons":["CO أول أكسيد الكربون (مركب)، بينما Co عنصر الكوبالت","لا فرق بينهما","كلاهما صحيح للكوبالت"],"reason":0},{"type":"essay","q":"اشرح تجربة الحديد والكبريت قبل التسخين وبعده لتوضيح الفرق بين المخلوط والمركّب.","model":"قبل التسخين: مخلوط يُرى فيه الأصفر والرمادي وينجذب الحديد للمغناطيس. بعد التسخين: تفاعل كيميائي ينتج مركب كبريتيد الحديد الأسود (FeS) الذي لا ينجذب للمغناطيس."},{"type":"essay","q":"لماذا يُعدّ ملح الطعام (NaCl) آمنًا للأكل رغم أن الصوديوم فلز نشط خطر والكلور غاز سام؟","model":"لأنه مركّب كيميائي ناتج عن اتحاد كيميائي، والمركبات تكتسب خصائص جديدةً تمامًا تختلف عن خصائص عناصرها الأصلية."},{"type":"essay","q":"ميّز بين «الذرة» و«الجزيء» مع ذكر مثال لجزيء عنصر ومثال لجزيء مركّب.","model":"الذرة أصغر وحدة للعنصر، والجزيء ذرتان أو أكثر مرتبطتان معًا. جزيء عنصر: O₂ أو H₂. جزيء مركّب: H₂O أو CO₂."}]}},
  {"id":"g9-chem-1-u2-2","grade":"g9","subject":"chemistry","term":1,"unit":2,"no":2,"title":"تركيب الذرّة","summary":"شرح متحرك بـ SVG لدرس تركيب الذرّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-atomic-structure.html","video":"","pdf":"","notes":["p (+1، كتلة 1) و n (0، كتلة 1) في النواة | e (-1، كتلة 1/1840) حول النواة.","في الذرة المتعادلة: p = e = العدد الذري (Z)، و n = A − Z.","النظائر: نفس البروتونات والإلكترونات (نفس التفاعلات الكيميائية) وتختلف في النيوترونات والكتلة."],"exercises":["أكمل بيانات الذرات المتعادلة الآتية (p، n، e): (أ) ¹⁶₈O، (ب) ⁴⁰₂₀Ca، (ج) ³⁷₁₇Cl.","عرّف «النظائر»، وفسّر لماذا تتطابق في خصائصها الكيميائية وتختلف قليلًا في خصائصها الفيزيائية كالكثافة.","قارن في جدول بين البروتون والنيوترون والإلكترون من حيث: الموقع، الشحنة النسبية، والكتلة النسبية."],"levels":{"easy":[{"type":"mcq","q":"ما الشحنة النسبية والكتلة النسبية للنيوترون؟","options":["الشحنة +1 والكتلة 0","الشحنة +1 والكتلة 1","الشحنة -1 والكتلة 1/1840","الشحنة 0 والكتلة النسبية 1"],"answer":3,"why":"النيوترون متعادل الشحنة وكتلته النسبية ١ داخل النواة."},{"type":"mcq","q":"كم عدد النيوترونات في ذرة الألومنيوم ²⁷₁₃Al؟","options":["١٤ نيوترونًا","١٣ نيوترونًا","٢٧ نيوترونًا","٤٠ نيوترونًا"],"answer":0,"why":"n = العدد الكتلي − العدد الذري = ٢٧ − ١٣ = ١٤."},{"type":"mcq","q":"لماذا تكون الذرة متعادلةً كهربائيًا في حالتها العادية؟","options":["لأنها لا تحتوي أي شحنات","لتساوي عدد البروتونات الموجبة مع عدد الإلكترونات السالبة","لتساوي البروتونات والنيوترونات","لأن الإلكترونات موجبة"],"answer":1,"why":"الشحنات الموجبة تلغي الشحنات السالبة بالضبط."},{"type":"mcq","q":"النظائر هي ذرات للعنصر نفسه تتفق في:","options":["العدد الكتلي وتختلف في الذري","عدد النيوترونات وتختلف في البروتونات","عدد البروتونات وتختلف في عدد النيوترونات","الكتلة وتختلف في الشحنة"],"answer":2,"why":"تتفق في العدد الذري (البروتونات) وتختلف في النيوترونات."}],"medium":[{"type":"mcq","q":"لماذا تتشابه نظائر العنصر الواحد (مثل Cl-35 و Cl-37) في «خصائصها الكيميائية»؟","options":["لأنها غازات نبيلة","لأن لها نفس عدد النيوترونات","لأن لها نفس الكتلة الذرية","لأن لها نفس عدد الإلكترونات ونفس الترتيب الإلكتروني"],"answer":3,"why":"التفاعلات الكيميائية تعتمد على الإلكترونات لا النيوترونات."},{"type":"mcq","q":"أين تتركز معظم كتلة الذرة؟","options":["في النواة (لأن كتلة البروتون والنيوترون أكبر بـ ١٨٤٠ مرة من الإلكترون)","في مستويات الطاقة الخارجية","في الإلكترونات فقط","موزعة بالتساوي في الفراغ"],"answer":0,"why":"الإلكترونات خفيفة جدًا مقارنة بالبروتونات والنيوترونات في النواة."},{"type":"mcq","q":"ذرة لها ١٩ بروتونًا و٢٠ نيوترونًا؛ ما عددها الكتلي (A)؟","options":["١٩","٣٩","٢٠","١"],"answer":1,"why":"A = p + n = ١٩ + ٢٠ = ٣٩ (البوتاسيوم K)."},{"type":"tfr","q":"كتلة الإلكترون النسبية تساوي ١ وهي مساوية لكتلة البروتون.","answer":false,"reasons":["بل كتلته ضئيلة جدًا (١/١٨٤٠) مقارنة بكتلة البروتون والنيوترون (=١)","نعم متساويتان","الإلكترون أثقل من البروتون"],"reason":0},{"type":"tfr","q":"تتشابه نظائر العنصر الواحد في التفاعلات الكيميائية لأن لها نفس عدد الإلكترونات.","answer":true,"reasons":["تختلف تمامًا في التفاعلات","فالاختلاف في النيوترونات يؤثر في الكتلة لا في السلوك الكيميائي","لها نفس عدد النيوترونات"],"reason":1},{"type":"essay","q":"أكمل بيانات الذرات المتعادلة الآتية (p، n، e): (أ) ¹⁶₈O، (ب) ⁴⁰₂₀Ca، (ج) ³⁷₁₇Cl.","model":"(أ) O: p=8, e=8, n=8. (ب) Ca: p=20, e=20, n=20. (ج) Cl: p=17, e=17, n=20."},{"type":"essay","q":"عرّف «النظائر»، وفسّر لماذا تتطابق في خصائصها الكيميائية وتختلف قليلًا في خصائصها الفيزيائية كالكثافة.","model":"النظائر ذرات لنفس العنصر تتفق في عدد البروتونات وتختلف في النيوترونات. تتطابق كيميائيًا لتساوي عدد وترتيب الإلكترونات، وتختلف في الكثافة لاختلاف الكتلة (عدد النيوترونات)."}],"hard":[{"type":"mcq","q":"ما الكتلة الذرية النسبية للكلور (٧٥٪ نظير Cl-35 و٢٥٪ نظير Cl-37)؟","options":["٣٥٫٠","٣٦٫٠","٣٥٫٥","٣٧٫٠"],"answer":2,"why":"(٣٥×٧٥ + ٣٧×٢٥) ÷ ١٠٠ = ٣٥٫٥."},{"type":"mcq","q":"ما الجسيم الذي يحدّد «هوية العنصر الكيميائي»؟","options":["حجم الذرة","عدد النيوترونات","العدد الكتلي فقط","عدد البروتونات (العدد الذري)"],"answer":3,"why":"كل عنصر له عدد بروتونات فريد لا يشاركه فيه غيره."},{"type":"mcq","q":"أي مما يأتي يُعدّ من الاستخدامات السلمية للنظائر المشعة؟","options":["علاج الأورام وتعقيم الأدوات الطبية وفحص تسربات الأنابيب","تحلية ماء البحر بالترشيح","زيادة الصدأ","صناعة الملح"],"answer":0,"why":"للنظائر المشعة تطبيقات طبية وصناعية مهمة."},{"type":"mcq","q":"ذرة كربون ⁶C تحتوي ٨ نيوترونات؛ ما عددها الكتلي؟","options":["١٢","١٤ (نظير الكربون-١٤)","٨","٦"],"answer":1,"why":"A = ٦ + ٨ = ١٤."},{"type":"tfr","q":"العدد الكتلي يساوي مجموع عدد البروتونات والنيوترونات في النواة.","answer":true,"reasons":["يساوي البروتونات + الإلكترونات","يساوي عدد الإلكترونات فقط","ولذلك عدد النيوترونات = العدد الكتلي − العدد الذري"],"reason":2},{"type":"tfr","q":"الذرة المتعادلة التي عددها الذري ١٢ تحتوي على ١٢ بروتونًا و١٢ إلكترونًا.","answer":true,"reasons":["لتساوي الشحنات الموجبة والسالبة في الذرة المتعادلة","تحتوي ١٢ نيوترونًا فقط","تحتوي ٦ إلكترونات"],"reason":0},{"type":"tfr","q":"إذا تغيّر عدد البروتونات في نواة ذرة، فإنها تبقى نفس العنصر الكيميائي.","answer":false,"reasons":["نعم تبقى نفس العنصر","بل تتحوّل إلى عنصر كيميائي آخر مختلف تمامًا","تتحول إلى نظير"],"reason":1},{"type":"essay","q":"قارن في جدول بين البروتون والنيوترون والإلكترون من حيث: الموقع، الشحنة النسبية، والكتلة النسبية.","model":"البروتون: النواة، +1، 1. النيوترون: النواة، 0، 1. الإلكترون: مستويات الطاقة حول النواة، -1، 1/1840."},{"type":"essay","q":"احسب الكتلة الذرية النسبية لعنصر البورون إذا كان يتكوّن في الطبيعة من ٢٠٪ نظير B-10 و٨٠٪ نظير B-11.","model":"Ar = (10 × 20 + 11 × 80) ÷ 100 = (200 + 880) ÷ 100 = 10.8."},{"type":"essay","q":"اذكر تطبيقين طبيين أو صناعيين للنظائر المشعة.","model":"١) استخدام الكوبالت-٦٠ في علاج الأورام السرطانية وتعقيم الأدوات الطبية. ٢) استخدام النظائر في كشف تسربات أنابيب النفط وتحديد عمر الحفريات (كربون-١٤)."}]}},
  {"id":"g9-chem-1-u2-3","grade":"g9","subject":"chemistry","term":1,"unit":2,"no":3,"title":"ترتيب الإلكترونات في الذرّات","summary":"شرح متحرك بـ SVG لدرس ترتيب الإلكترونات في الذرّات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-electron-arrangement.html","video":"","pdf":"","notes":["سعة المستويات لأول ٢٠ عنصرًا: ٢، ٨، ٨، ٢.","عدد إلكترونات التكافؤ = رقم المجموعة | عدد المستويات = رقم الدورة.","الفلزات تفقد ← أيون موجب (+) | اللافلزات تكتسب ← أيون سالب (−) للوصول لتركيب الغاز النبيل."],"exercises":["اكتب التوزيع الإلكتروني وحدّد رقم الدورة والمجموعة لكل من: N (7)، Mg (12)، Cl (17)، K (19).","فسّر لماذا تتشابه عناصر المجموعة الواحدة (مثل الليثيوم والصوديوم والبوتاسيوم) في تفاعلاتها الكيميائية.","قارن بين ذرة الكلور (Cl, Z=17) وأيون الكلوريد (Cl⁻) من حيث: عدد البروتونات، عدد الإلكترونات، والتوزيع الإلكتروني."],"levels":{"easy":[{"type":"mcq","q":"ما التوزيع الإلكتروني الصحيح لذرة الكالسيوم (Z = 20)؟","options":["٢، ٨، ٨، ٢","٢، ٨، ١٠","٢، ٨، ٨، ١","٢، ٦، ٨، ٤"],"answer":0,"why":"المستوى الثالث يأخذ ٨ والرابع يأخذ ٢ لأول ٢٠ عنصرًا."},{"type":"mcq","q":"عنصر توزيعه الإلكتروني (٢، ٨، ٥)؛ في أي دورة وأي مجموعة يقع في الجدول الدوري؟","options":["الدورة الخامسة، المجموعة الثالثة","الدورة الثالثة، المجموعة الخامسة (V)","الدورة الثانية، المجموعة الخامسة","الدورة الثالثة، المجموعة الثامنة"],"answer":1,"why":"٣ مستويات = الدورة ٣، و٥ إلكترونات خارجية = المجموعة ٥."},{"type":"mcq","q":"لماذا تكون الغازات النبيلة (مثل النيون والأرجون) خاملةً كيميائيًا؟","options":["لأنها مواد صلبة","لأنها لا تحتوي بروتونات","لأن مستوى الطاقة الخارجي فيها ممتلئ تمامًا بالإلكترونات","لأن عددها الذري فردي"],"answer":2,"why":"امتلاء الغلاف الخارجي يمنحها استقرارًا كيميائيًا تامًا."},{"type":"mcq","q":"ما التوزيع الإلكتروني لأيون الألومنيوم Al³⁺ علمًا بأن العدد الذري للألومنيوم ١٣؟","options":["٢، ٨، ٨","٢، ٨، ٣","٢، ٨، ٦","٢، ٨"],"answer":3,"why":"الذرة ٢، ٨، ٣ تفقد ٣ إلكترونات فتصبح ٢، ٨."}],"medium":[{"type":"mcq","q":"ما شحنة الأيون الذي تكوّنه ذرة الكبريت S (Z = 16، توزيعها ٢، ٨، ٦) لتستقر؟","options":["S²⁻ (تكتسب إلكترونين)","S²⁺ (تفقد إلكترونين)","S⁶⁺","لا تكوّن أيونات"],"answer":0,"why":"تحتاج إلكترونين لإكمال غلافها الخارجي إلى ٨ فتصبح S²⁻."},{"type":"mcq","q":"أقصى عدد من الإلكترونات يستوعبه مستوى الطاقة «الأول» هو:","options":["٨ إلكترونات","٢ إلكترون","١٨ إلكترونًا","٤ إلكترونات"],"answer":1,"why":"المستوى الأول سعته القصوى إلكترونان فقط."},{"type":"mcq","q":"عنصران توزيعهما (٢، ١) و(٢، ٨، ١)؛ لماذا يتشابهان في الخصائص الكيميائية؟","options":["لأن لهما نفس الكتلة","لأن لهما نفس عدد المستويات","لأن كليهما يحتوي على إلكترون واحد في المستوى الخارجي (نفس المجموعة)","لأنهما في نفس الدورة"],"answer":2,"why":"تساوي إلكترونات التكافؤ يسبب تشابه الخصائص الكيميائية."},{"type":"tfr","q":"عدد إلكترونات المستوى الخارجي في ذرة متعادلة يساوي رقم مجموعتها في الجدول الدوري (للمجموعات I–VII).","answer":true,"reasons":["يساوي رقم دورتها","وعدد مستويات الطاقة المشغولة يساوي رقم دورتها","يساوي عدد نيوتروناتها"],"reason":1},{"type":"tfr","q":"التوزيع الإلكتروني لذرة الكالسيوم (Z=20) هو ٢، ٨، ١٠.","answer":false,"reasons":["الصواب ٢، ٦، ٨، ٤","نعم ٢، ٨، ١٠","الصواب ٢، ٨، ٨، ٢ (المستوى الرابع به إلكترونان)"],"reason":2},{"type":"essay","q":"اكتب التوزيع الإلكتروني وحدّد رقم الدورة والمجموعة لكل من: N (7)، Mg (12)، Cl (17)، K (19).","model":"N: (2,5) دورة ٢ مجموعة ٥. Mg: (2,8,2) دورة ٣ مجموعة ٢. Cl: (2,8,7) دورة ٣ مجموعة ٧. K: (2,8,8,1) دورة ٤ مجموعة ١."},{"type":"essay","q":"فسّر لماذا تتشابه عناصر المجموعة الواحدة (مثل الليثيوم والصوديوم والبوتاسيوم) في تفاعلاتها الكيميائية.","model":"لأن جميعها تمتلك نفس عدد الإلكترونات في مستوى الطاقة الخارجي (إلكترونًا واحدًا)، فتفقد كلها إلكترونًا واحدًا عند التفاعل."}],"hard":[{"type":"mcq","q":"أي الأيونات الآتية له نفس التوزيع الإلكتروني للغاز النبيل الأرجون (٢، ٨، ٨)؟","options":["أيون الليثيوم Li⁺ (Z=3)","أيون الصوديوم Na⁺ (Z=11)","أيون الأكسيد O²⁻ (Z=8)","أيون الكلوريد Cl⁻ (Z=17) وأيون البوتاسيوم K⁺ (Z=19)"],"answer":3,"why":"Cl⁻ (17+1=18) و K⁺ (19-1=18) كلاهما (٢، ٨، ٨)."},{"type":"mcq","q":"ما الخطأ في كتابة التوزيع الإلكتروني للبوتاسيوم (Z=19) على صورة (٢، ٨، ٩)؟","options":["المستوى الثالث لا يأخذ أكثر من ٨ قبل بدء ملء الرابع؛ الصواب (٢، ٨، ٨، ١)","المستوى الأول يجب أن يأخذ ٣","مجموعها ليس ١٩","لا خطأ فيه"],"answer":0,"why":"الإلكترون الـ ١٩ يدخل المستوى الرابع: ٢، ٨، ٨، ١."},{"type":"mcq","q":"رغم أن الهيليوم (He) يمتلك إلكترونين في غلافه الخارجي، إلا أنه يقع في المجموعة الثامنة/الصفرية لأن:","options":["هو فلز قلوي","غلافه الأول ممتلئ تمامًا بإلكترونين فهو غاز نبيل خامل","له ٣ مستويات","يميل لفقد إلكترونين"],"answer":1,"why":"المستوى الأول يمتلئ بـ ٢ فيحقق الاستقرار الكامل."},{"type":"mcq","q":"عندما تتحوّل ذرة الصوديوم (Na) إلى أيون (Na⁺)، فإن عدد البروتونات في نواتها:","options":["يزيد إلى ١٢","ينقص إلى ١٠","يبقى ثابتًا (١١ بروتونًا) ولا يتغيّر","يصبح صفرًا"],"answer":2,"why":"تكوّن الأيون يغيّر الإلكترونات فقط، أما النواة فلا تتغير."},{"type":"tfr","q":"تميل ذرات الفلزات إلى فقد إلكترونات غلافها الخارجي لتكوين أيونات موجبة مستقرة.","answer":true,"reasons":["مثل Na⁺ و Mg²⁺ و Al³⁺","تميل لاكتساب إلكترونات","تكوّن أيونات سالبة"],"reason":0},{"type":"tfr","q":"أيون الأكسيد O²⁻ (Z=8) وأيون المغنيسيوم Mg²⁺ (Z=12) لهما نفس التوزيع الإلكتروني (٢، ٨).","answer":true,"reasons":["توزيعهما مختلف تمامًا","لأن O يكتسب ٢ (8+2=10) و Mg يفقد ٢ (12-2=10)","كلاهما ٢، ٨، ٨"],"reason":1},{"type":"tfr","q":"يتغير عدد البروتونات في نواة الذرة عندما تكتسب إلكترونًا لتصبح أيونًا سالبًا.","answer":false,"reasons":["ينقص البروتون","نعم يزيد البروتون","تبقى النواة ثابتة تمامًا ولا يتغيّر إلا عدد الإلكترونات"],"reason":2},{"type":"essay","q":"قارن بين ذرة الكلور (Cl, Z=17) وأيون الكلوريد (Cl⁻) من حيث: عدد البروتونات، عدد الإلكترونات، والتوزيع الإلكتروني.","model":"الذرة Cl: ١٧ بروتونًا، ١٧ إلكترونًا، التوزيع (٢، ٨، ٧). الأيون Cl⁻: ١٧ بروتونًا، ١٨ إلكترونًا، التوزيع (٢، ٨، ٨)."},{"type":"essay","q":"علّل: يوضع الهيليوم (Z=2) مع الغازات النبيلة (المجموعة 0/VIII) وليس مع عناصر المجموعة الثانية كالمغنيسيوم.","model":"لأن المستوى الأول للهيليوم يمتلئ تمامًا بإلكترونين فيكون مستقرًا وخاملًا كالغازات النبيلة، بعكس المغنيسيوم النشط الذي يفقد إلكترونين."},{"type":"essay","q":"إذا كان توزيع أيون عنصر X²⁺ هو (٢، ٨، ٨)، فما العدد الذري للعنصر X؟ وما اسمه وموقعه في الجدول الدوري؟","model":"فقد إلكترونين فأصله (٢، ٨، ٨، ٢) ← العدد الذري = ٢٠ (الكالسيوم Ca)، يقع في الدورة الرابعة والمجموعة الثانية."}]}},
  {"id":"g9-chem-1-u3-1","grade":"g9","subject":"chemistry","term":1,"unit":3,"no":1,"title":"الجدول الدوري للعناصر: تصنيف العناصر","summary":"شرح متحرك بـ SVG لدرس الجدول الدوري للعناصر: تصنيف العناصر (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-periodic-table-classification.html","video":"","pdf":"","notes":["الجدول الدوري الحديث مرتّب تصاعديًا حسب العدد الذري (Z).","المجموعة I (قلوية لينة، نشاط ↑ للأسفل) | VII (هالوجينات، نشاط ↓ للأسفل، إحلال) | 0 (نبيلة خاملة).","الانتقالية: صلبة وكثيفة + مركبات ملوّنة + شحنات متعددة + عوامل حفّازة."],"exercises":["قارن في جدول بين «فلزات المجموعة الأولى (القلوية)» و«العناصر الانتقالية» من حيث: الصلابة والكثافة، لون المركبات، والنشاط مع الماء.","توقّع ما يحدث عند إضافة ماء الكلور إلى محلول يوديد البوتاسيوم (KI) مع كتابة المعادلة اللفظية والرمزية.","صف تدرّج الحالة الفيزيائية واللون ودرجة الغليان والنشاط الكيميائي عند النزول لأسفل في المجموعة السابعة (Cl₂ → Br₂ → I₂)."],"levels":{"easy":[{"type":"mcq","q":"على أي أساس تُرتّب العناصر في الجدول الدوري الحديث؟","options":["حسب الكتلة الذرية فقط","تصاعديًا حسب العدد الذري (عدد البروتونات)","حسب الترتيب الأبجدي","حسب الكثافة"],"answer":1,"why":"الترتيب الحديث يقوم على العدد الذري التصاعدي."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة الأولى (الفلزات القلوية)، فإن النشاط الكيميائي:","options":["يبقى ثابتًا","يقلّ تدريجيًا","يزداد (البوتاسيوم أنشط من الصوديوم والليثيوم)","ينعدم تمامًا"],"answer":2,"why":"يزداد نصف القطر فيسهل فقد الإلكترون الخارجي فيزداد النشاط."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة السابعة (الهالوجينات)، فإن النشاط الكيميائي:","options":["يتحول إلى غاز نبيل","يزداد بشدة","يبقى ثابتًا","يقلّ (الفلور والكلور أنشط من البروم واليود)"],"answer":3,"why":"الذرة الأصغر في الأعلى تجذب الإلكترون بقوة أكبر فتكون أنشط."},{"type":"mcq","q":"ما الحالة الفيزيائية واللون لـ«البروم (Br₂)» عند درجة حرارة الغرفة؟","options":["سائل بني محمر","غاز أصفر مخضر","صلب رمادي داكن","غاز عديم اللون"],"answer":0,"why":"الكلور غاز أصفر مخضر، البروم سائل بني محمر، اليود صلب رمادي داكن."}],"medium":[{"type":"mcq","q":"أُضيف ماء الكلور إلى محلول بروميد البوتاسيوم (KBr) فتغيّر اللون إلى البرتقالي لأن:","options":["البروم أنشط من الكلور","الكلور أنشط من البروم فيحلّ محله ويطرد البروم (Br₂)","لم يحدث تفاعل","تكون غاز الهيدروجين"],"answer":1,"why":"الهالوجين الأكثر نشاطًا يطرد الأقل نشاطًا من محلول ملحه."},{"type":"mcq","q":"لماذا يُستخدم «الهيليوم» بدلًا من «الهيدروجين» في ملء المناطيد الهوائية؟","options":["لأن الهيدروجين غاز نبيل","لأن الهيليوم أثقل من الهواء","لأن الهيليوم خامل غير قابل للاشتعال مع كونه قليل الكثافة، بينما الهيدروجين شديد الاشتعال","لأن الهيليوم سائل"],"answer":2,"why":"الأمان والخمول الكيميائي هما ميزة الهيليوم الكبرى."},{"type":"mcq","q":"لماذا يُملأ مصباح الفتيل المتوهج بغاز «الأرجون» بدلًا من الهواء؟","options":["لأنه أثقل من الحديد","لأنه يتفاعل مع الفتيل ليعطي ضوءًا","لأنه يبرّد المصباح إلى ٠°C","لأنه غاز نبيل خامل يمنع تأكسد واحتراق فتيل التنجستن الساخن"],"answer":3,"why":"الأرجون يوفر وسطًا خاملًا يحمي الفتيل من الأكسجين."},{"type":"tfr","q":"تقع الفلزات على يسار ووسط الجدول الدوري، بينما تقع اللافلزات على يمينه.","answer":true,"reasons":["مختلطة عشوائيًا","العكس تمامًا","ويفصل بينهما خط متعرج يضم أشباه الفلزات كالسيليكون"],"reason":2},{"type":"tfr","q":"يزداد النشاط الكيميائي بالنزول لأسفل في كلٍّ من المجموعة الأولى والمجموعة السابعة معًا.","answer":false,"reasons":["يزداد للأسفل في المجموعة الأولى، لكنه «يقلّ» للأسفل في المجموعة السابعة!","نعم يزداد في كليهما","يقلّ في كليهما"],"reason":0},{"type":"essay","q":"قارن في جدول بين «فلزات المجموعة الأولى (القلوية)» و«العناصر الانتقالية» من حيث: الصلابة والكثافة، لون المركبات، والنشاط مع الماء.","model":"المجموعة الأولى: لينة منخفضة الكثافة، مركباتها بيضاء عديمة اللون، تتفاعل بشدة مع الماء البارد. الانتقالية: صلبة عالية الكثافة والانصهار، مركباتها ملوّنة، لا تتفاعل مع الماء البارد (أو بطيئة جدًا) وتعمل كحفازات."},{"type":"essay","q":"توقّع ما يحدث عند إضافة ماء الكلور إلى محلول يوديد البوتاسيوم (KI) مع كتابة المعادلة اللفظية والرمزية.","model":"يتغير لون المحلول إلى البني الداكن بسبب تحرّر اليود لأن الكلور أنشط من اليود. كلور + يوديد البوتاسيوم ← كلوريد البوتاسيوم + يود. Cl₂ + 2KI → 2KCl + I₂."}],"hard":[{"type":"mcq","q":"أي خاصية مما يأتي «تميّز العناصر الانتقالية» عن فلزات المجموعة الأولى؟","options":["تكوين مركّبات ملوّنة وتعدد الشحنات والعمل كعوامل حفّازة","ليونتها وسهولة قطعها بالسكين","انخفاض كثافتها وطَفوها على الماء","تفاعلها العنيف مع الماء البارد"],"answer":0,"why":"الانتقالية صلبة وكثيفة وملوّنة المركبات وحفّازة."},{"type":"mcq","q":"ما الغاز المتصاعد عند وضع قطعة صغيرة من الصوديوم في الماء؟","options":["غاز الأكسجين (O₂)","غاز الهيدروجين (H₂) ويتكوّن محلول قلوي (NaOH)","غاز الكلور (Cl₂)","ثاني أكسيد الكربون"],"answer":1,"why":"2Na + 2H₂O → 2NaOH + H₂."},{"type":"mcq","q":"أي لافلز يُعدّ استثناءً مهمًا لأنه «يوصل الكهرباء»؟","options":["اليود","الكبريت","الجرافيت (الكربون)","الفوسفور"],"answer":2,"why":"الجرافيت لافلز موصل للكهرباء لوجود إلكترونات حرة متحركة."},{"type":"mcq","q":"لماذا يُحفظ الصوديوم والبوتاسيوم تحت طبقة من الزيت (البرافين)؟","options":["لزيادة كثافتهما","لإذابتهما في الزيت","لتغيير لونهما","لمنع تفاعلهما السريع مع أكسجين ورطوبة الهواء"],"answer":3,"why":"الزيت يعزلهما عن الهواء والماء."},{"type":"tfr","q":"يمكن لليود (I₂) أن يحل محل الكلور في محلول كلوريد الصوديوم (NaCl).","answer":false,"reasons":["نعم يحل محله","لا يحدث تفاعل لأن اليود أقل نشاطًا من الكلور","يطرد الصوديوم"],"reason":1},{"type":"tfr","q":"تتميّز العناصر الانتقالية بصلابتها وكثافتها العالية وتكوينها لمركبات ملوّنة.","answer":true,"reasons":["مركباتها بيضاء دائمًا","هي لينة وتطفو على الماء","مثل أملاح النحاس الزرقاء وأملاح الحديد الخضراء والبنية"],"reason":2},{"type":"tfr","q":"استخدم مندليف الفراغات في جدوله للتنبؤ بخصائص عناصر لم تكن مكتشفةً بعد.","answer":true,"reasons":["ولما اكتُشفت لاحقًا (كالجاليوم والجرمانيوم) طابقت توقعاته بدقة مذهلة","لم يترك أي فراغات","رتّبها أبجديًا"],"reason":0},{"type":"essay","q":"صف تدرّج الحالة الفيزيائية واللون ودرجة الغليان والنشاط الكيميائي عند النزول لأسفل في المجموعة السابعة (Cl₂ → Br₂ → I₂).","model":"الحالة: غاز ← سائل ← صلب. اللون يغمق: أصفر مخضر ← بني محمر ← رمادي داكن. درجة الغليان: تزداد. النشاط الكيميائي: يقلّ."},{"type":"essay","q":"اذكر استخدامين صناعيين للغازات النبيلة وفسّر ارتباط كل استخدام بخصائصها.","model":"١) الهيليوم في المناطيد: كثافته منخفضة جدًا وخامل غير قابل للاشتعال. ٢) الأرجون في مصابيح الفتيل واللحام: خامل يمنع تأكسد الفلز الساخن."},{"type":"essay","q":"كيف تتغير خصائص العناصر عند الانتقال عبر الدورة الثالثة من اليسار (Na) إلى اليمين (Ar)؟","model":"تتدرج من فلزات نشطة (Na, Mg, Al) ← شبه فلز (Si) ← لافلزات (P, S, Cl) ← غاز نبيل خامل (Ar)، وتتحول الأكاسيد من قاعدية إلى مترددة إلى حمضية."}]}},
  {"id":"g9-chem-1-u3-2","grade":"g9","subject":"chemistry","term":1,"unit":3,"no":2,"title":"دورية خصائص العناصر في الجدول الدوري","summary":"شرح متحرك بـ SVG لدرس دورية خصائص العناصر في الجدول الدوري (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-periodic-trends.html","video":"","pdf":"","notes":["الدورية سببها تكرار عدد إلكترونات التكافؤ (١–٨) في كل دورة.","عبر الدورة: فلز موصل (أكسيد قاعدي) ← شبه فلز (ذروة الانصهار) ← لافلز عازل (أكسيد حمضي).","لأسفل المجموعة يزداد حجم الذرة ويضعف جذب النواة ← يزداد نشاط I (فقد أسهل) ويقل نشاط VII (اكتساب أصعب)."],"exercises":["فسّر علميًا (بدلالة التركيب الذري) لماذا يزداد النشاط الكيميائي للأسفل في المجموعة الأولى بينما يقلّ للأسفل في المجموعة السابعة.","صف التدرّج الدوري في الدورة الثالثة (Na إلى Ar) من حيث: الصفة الفلزية، التوصيل الكهربائي، وطبيعة الأكاسيد.","علّل: لماذا تنخفض درجة الانصهار فجأةً بعد السيليكون (Si) عند الانتقال إلى الفوسفور والكبريت والكلور؟"],"levels":{"easy":[{"type":"mcq","q":"ما السبب الأساسي لتكرار الخصائص الكيميائية بانتظام في الجدول الدوري؟","options":["تساوي الكتل الذرية","تساوي عدد النيوترونات","تكرار عدد إلكترونات المستوى الخارجي (التكافؤ) في بداية كل دورة","تشابه ألوان العناصر"],"answer":2,"why":"إلكترونات التكافؤ هي التي تتحكم في السلوك الكيميائي."},{"type":"mcq","q":"عند الانتقال من اليسار إلى اليمين في الدورة الثالثة (من Na إلى Ar)، أي مما يأتي صحيح؟","options":["تصبح كلها فلزات قلوية","يزداد عدد مستويات الطاقة","تزداد الصفة الفلزية","تقل الصفة الفلزية وتزداد الصفة اللافلزية ويبقى عدد المستويات ٣"],"answer":3,"why":"في الدورة نفسها يثبت عدد المستويات ويزداد التكافؤ تدريجيًا."},{"type":"mcq","q":"لماذا يكون البوتاسيوم K (٢، ٨، ٨، ١) أنشط كيميائيًا من الصوديوم Na (٢، ٨، ١)؟","options":["لأن ذرة البوتاسيوم أكبر (٤ مستويات) فيضعف جذب النواة للإلكترون الخارجي ويسهل فقده","لأن البوتاسيوم يكتسب إلكترونًا أسهل","لأن البوتاسيوم أصغر حجمًا","لأن الصوديوم غاز نبيل"],"answer":0,"why":"زيادة البُعد عن النواة تسهّل فقد الإلكترون في الفلزات."},{"type":"mcq","q":"لماذا يكون الكلور Cl (٢، ٨، ٧) أنشط من اليود I في المجموعة السابعة؟","options":["لأن الكلور يفقد إلكترونًا أسهل","لأن ذرة الكلور أصغر فيكون جذب نواتها أقوى لاكتساب إلكترون جديد","لأن اليود غاز","لأن الكلور فلز"],"answer":1,"why":"في اللافلزات صغر الذرة يقوّي جذب الإلكترون المراد اكتسابه."}],"medium":[{"type":"mcq","q":"في الدورة الثالثة، أي عنصر له «أعلى درجة انصهار»؟","options":["الكلور (Cl₂)","الصوديوم (Na)","السيليكون (Si) بسبب تركيبه التساهمي الضخم","الأرجون (Ar)"],"answer":2,"why":"المجموعة الرابعة (C و Si) تبلغ ذروة الانصهار لترابطها التساهمي الضخم."},{"type":"mcq","q":"درجة انصهار الليثيوم ١٨١°C والصوديوم ٩٨°C والبوتاسيوم ٦٣°C؛ ما التوقع المنطقي لدرجة انصهار الروبيديوم (أسفل البوتاسيوم)؟","options":["١٥٠°C","حوالي ٢٥٠°C","حوالي ١٠٠٠°C","حوالي ٣٩°C (أقل من ٦٣°C)"],"answer":3,"why":"تنخفض درجة انصهار المجموعة الأولى بالنزول للأسفل."},{"type":"mcq","q":"أي عنصر في الدورة الثالثة يُعدّ «شبه موصّل» للكهرباء؟","options":["السيليكون (Si)","الصوديوم (Na)","الأرجون (Ar)","الكبريت (S)"],"answer":0,"why":"السيليكون شبه فلز وشبه موصّل."},{"type":"tfr","q":"في الدورة الواحدة يكون لجميع العناصر نفس عدد مستويات الطاقة المشغولة.","answer":true,"reasons":["فجميع عناصر الدورة الثالثة لها ٣ مستويات طاقة","لها نفس عدد إلكترونات التكافؤ","لها نفس العدد الذري"],"reason":0},{"type":"tfr","q":"يزداد حجم الذرة كلما نزلنا إلى أسفل في المجموعة الواحدة.","answer":true,"reasons":["يقل حجم الذرة للأسفل","بسبب زيادة عدد مستويات الطاقة حول النواة","يبقى ثابتًا"],"reason":1},{"type":"essay","q":"فسّر علميًا (بدلالة التركيب الذري) لماذا يزداد النشاط الكيميائي للأسفل في المجموعة الأولى بينما يقلّ للأسفل في المجموعة السابعة.","model":"بالنزول للأسفل يزداد عدد المستويات ويكبر حجم الذرة فيضعف جذب النواة للإلكترونات الخارجية: في المجموعة الأولى (فلزات) يسهُل «فقد» الإلكترون فيزداد النشاط؛ وفي المجموعة السابعة (لافلزات) يصعُب «اكتساب» إلكترون جديد فيقل النشاط."},{"type":"essay","q":"صف التدرّج الدوري في الدورة الثالثة (Na إلى Ar) من حيث: الصفة الفلزية، التوصيل الكهربائي، وطبيعة الأكاسيد.","model":"الصفة: فلزات (Na,Mg,Al) ← شبه فلز (Si) ← لافلزات (P,S,Cl,Ar). التوصيل: موصل ← شبه موصل ← عازل. الأكاسيد: قاعدية ← مترددة ← حمضية."}],"hard":[{"type":"mcq","q":"ما التوقع الصحيح للحالة الفيزيائية والنشاط لعنصر «الأستاتين» (يقع أسفل اليود في المجموعة السابعة)؟","options":["غاز أصفر وأنشط من الفلور","صلب داكن اللون وأقل نشاطًا من اليود","سائل شفاف","فلز قلوي لامع"],"answer":1,"why":"بالنزول في المجموعة VII تزداد درجة الغليان ويغمق اللون ويقل النشاط."},{"type":"mcq","q":"عند الانتقال من اليسار إلى اليمين عبر الدورة الثالثة، تتغير طبيعة الأكاسيد من:","options":["متعادلة كلها","حمضية ← قاعدية فقط","قاعدية (Na₂O) ← مترددة (Al₂O₃) ← حمضية (SO₂)","قاعدية كلها"],"answer":2,"why":"تدرج دوري واضح من القاعدي إلى المتردد إلى الحمضي."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في أي مجموعة بالجدول الدوري، فإن «حجم الذرة (نصف القطر)»:","options":["يصبح صفرًا","يقلّ دائمًا","يبقى ثابتًا","يزداد بسبب إضافة مستوى طاقة جديد في كل دورة"],"answer":3,"why":"كل دورة جديدة تضيف غلافًا إلكترونيًا جديدًا فيكبر الحجم."},{"type":"mcq","q":"أي العناصر الآتية له أعلى نشاط كيميائي ضمن اللافلزات في المجموعة السابعة؟","options":["الفلور (F₂)","اليود (I₂)","البروم (Br₂)","الأستاتين (At₂)"],"answer":0,"why":"الفلور أصغر ذرة في المجموعة VII وأقواها جذبًا للإلكترون."},{"type":"tfr","q":"تُعدّ عناصر المجموعة الرابعة (الكربون والسيليكون) الأقل في درجة الانصهار في دورتيها.","answer":false,"reasons":["تساوي صفرًا","نعم الأقل","بل هي «الأعلى» في درجة الانصهار بسبب تراكيبها التساهمية الضخمة"],"reason":2},{"type":"tfr","q":"تفسير زيادة نشاط المجموعة الأولى للأسفل هو نفسه تفسير نقصان نشاط المجموعة السابعة للأسفل (كبر حجم الذرة وضعف جذب النواة).","answer":true,"reasons":["ضعف جذب النواة يسهّل الفقد في الفلزات ويصعّب الاكتساب في اللافلزات!","لا علاقة لحجم الذرة بالنشاط","كلاهما يزداد للأسفل"],"reason":0},{"type":"tfr","q":"يمكن التنبؤ بخصائص عنصر غير مألوف بدقة بالاعتماد على خصائص العناصر المجاورة له في نفس المجموعة.","answer":true,"reasons":["لا يمكن التنبؤ بأي خاصية","وهذه هي القيمة التنبؤية الكبرى للجدول الدوري","الخصائص عشوائية"],"reason":1},{"type":"essay","q":"علّل: لماذا تنخفض درجة الانصهار فجأةً بعد السيليكون (Si) عند الانتقال إلى الفوسفور والكبريت والكلور؟","model":"لأن السيليكون تركيب تساهمي ضخم يحتاج طاقةً هائلةً لكسر روابطه القوية، بينما الفوسفور والكبريت والكلور جزيئات تساهمية بسيطة ذات قوى تجاذب ضعيفة جدًا بين جزيئاتها."},{"type":"essay","q":"إذا علمت أن درجة غليان الكلور −٣٥°C والبروم +٥٩°C واليود +١٨٤°C، فتوقّع حالة ودرجة غليان الأستاتين (أسفل اليود).","model":"سيكون صلبًا داكنًا، ودرجة غليانه أعلى من ١٨٤°C (حوالي ٣٠٠–٣٣٧°C) تبعًا للتدرج التصاعدي في المجموعة."},{"type":"essay","q":"ما العلاقة بين «الدورية في الجدول الدوري» و«التوزيع الإلكتروني»؟","model":"تتكرر خصائص العناصر في كل دورة لأن عدد إلكترونات التكافؤ في المستوى الخارجي يتكرر بالنمط نفسه (من ١ إلى ٨) في كل دورة."}]}},
  {"id":"g9-chem-1-u4-1","grade":"g9","subject":"chemistry","term":1,"unit":4,"no":1,"title":"الروابط الكيميائيّة وأهميتها","summary":"شرح متحرك بـ SVG لدرس الروابط الكيميائيّة وأهميتها (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-chemical-bonding.html","video":"","pdf":"","notes":["أيونية (فلز+لافلز: تجاذب أيونات، انصهار عالٍ، توصل مصهورة/محلولًا فقط).","تساهمية بسيطة (لافلز+لافلز: مشاركة إلكترونات، قوى بين جزيئية ضعيفة، انصهار منخفض، لا توصل).","فلزية (أيونات موجبة + بحر إلكترونات حرة ← توصيل كهربائي وحراري وقابلية للطرق)."],"exercises":["قارن في جدول بين المركّبات الأيونية والجزيئات التساهمية البسيطة من حيث: نوع العناصر، درجة الانصهار، والتوصيل الكهربائي.","صف تكوّن الرابطة الأيونية في أكسيد المغنيسيوم (MgO) بدلالة انتقال الإلكترونات وشحنات الأيونات.","فسّر لماذا يوصل الفلز (النحاس) الكهرباء وهو صلب، بينما لا يوصل الملح (NaCl) الكهرباء وهو صلب."],"levels":{"easy":[{"type":"mcq","q":"أي المركّبات الآتية يحتوي على «رابطة أيونية»؟","options":["الأمونيا (NH₃)","ثاني أكسيد الكربون (CO₂)","الميثان (CH₄)","أكسيد المغنيسيوم (MgO)"],"answer":3,"why":"المغنيسيوم فلز والأكسجين لافلز ← رابطة أيونية."},{"type":"mcq","q":"لماذا «لا يوصل» كلوريد الصوديوم الصلب الكهرباء، بينما يوصلها عند إذابته في الماء أو صهره؟","options":["لأن الأيونات في الصلب مقيدة الحركة، وتصبح حرة الحركة عند الصهر أو الذوبان","لأنه يحتوي إلكترونات حرة فقط في الماء","لأن الماء يحوله إلى فلز","لأن الروابط التساهمية تنكسر"],"answer":0,"why":"شرط التوصيل الكهربائي وجود جسيمات مشحونة حرة الحركة."},{"type":"mcq","q":"ما نوع الرابطة بين ذرتَي النيتروجين في جزيء (N₂)؟","options":["رابطة تساهمية أحادية","رابطة تساهمية ثلاثية (٣ أزواج مشتركة)","رابطة أيونية","رابطة فلزية"],"answer":1,"why":"كل ذرة نيتروجين (٢، ٥) تحتاج ٣ إلكترونات فتتشاركان بثلاثة أزواج (N≡N)."},{"type":"mcq","q":"لماذا تكون درجة غليان غاز الميثان (CH₄) منخفضةً جدًا (−١٦١°C)؟","options":["لأنه مركب أيوني","لضعف الرابطة التساهمية بين C و H","لضعف قوى التجاذب «بين» جزيئات الميثان التساهمية البسيطة","لأنه فلز قلوي"],"answer":2,"why":"الروابط داخل الجزيء قوية، لكن القوى بين الجزيئات ضعيفة جدًا."}],"medium":[{"type":"mcq","q":"ما الذي يفسّر «قابلية الفلزات للطرق والسحب» دون أن تتكسّر؟","options":["عدم وجود أيونات موجبة","وجود فراغات فارغة بدون روابط","تكون روابط تساهمية","انزلاق طبقات الأيونات الموجبة فوق بعضها مع بقاء بحر الإلكترونات ممسكًا بها"],"answer":3,"why":"الرابطة الفلزية غير اتجاهية فتسمح بانزلاق الطبقات."},{"type":"mcq","q":"كم زوجًا من الإلكترونات تتشارك به ذرتا الأكسجين في جزيء الأكسجين (O₂)؟","options":["زوجان (رابطة تساهمية ثنائية O=O)","زوج واحد","ثلاثة أزواج","لا تتشاركان"],"answer":0,"why":"كل ذرة أكسجين (٢، ٦) تحتاج إلكترونين فتتشاركان بزوجين."},{"type":"mcq","q":"لماذا لا يوصل محلول السكر في الماء التيار الكهربائي؟","options":["لأنه لا يذوب في الماء","لأنه مركب تساهمي لا يحتوي على أيونات أو إلكترونات حرة الحركة","لأنه فلز","لأنه مادة صلبة"],"answer":1,"why":"غياب الأيونات الحرة يمنع التوصيل الكهربائي."},{"type":"tfr","q":"المركّبات الأيونية توصل التيار الكهربائي في الحالة الصلبة والمصهورة على حدٍّ سواء.","answer":false,"reasons":["نعم توصل في الصلبة","لا توصل في الحالة الصلبة لأن أيوناتها مقيدة، وتوصل فقط مصهورةً أو مذابةً","لا توصل أبدًا"],"reason":1},{"type":"tfr","q":"السبب في انخفاض درجة غليان الماء والميثان هو ضعف الروابط التساهمية داخل الجزيء.","answer":false,"reasons":["بسبب الرابطة الأيونية","نعم ضعف الروابط داخل الجزيء","بل بسبب ضعف «قوى التجاذب بين الجزيئات»، أما الروابط التساهمية داخل الجزيء فقوية جدًا!"],"reason":2},{"type":"essay","q":"قارن في جدول بين المركّبات الأيونية والجزيئات التساهمية البسيطة من حيث: نوع العناصر، درجة الانصهار، والتوصيل الكهربائي.","model":"الأيونية: فلز+لافلز، انصهار عالٍ جدًا، توصل مصهورة/محلولًا ولا توصل صلبة. التساهمية البسيطة: لافلز+لافلز، انصهار منخفض، لا توصل في أي حالة."},{"type":"essay","q":"صف تكوّن الرابطة الأيونية في أكسيد المغنيسيوم (MgO) بدلالة انتقال الإلكترونات وشحنات الأيونات.","model":"تفقد ذرة المغنيسيوم (٢،٨،٢) إلكترونين فتصبح Mg²⁺ (٢،٨)، وتكتسبهما ذرة الأكسجين (٢،٦) فتصبح O²⁻ (٢،٨)، فتتجاذب الأيونات بقوة كهروستاتيكية مكوّنةً MgO."}],"hard":[{"type":"mcq","q":"ما نوع الرابطة الكيميائية في جزيء الأمونيا (NH₃)؟","options":["فلزية","أيونية","تساهمية أحادية بين النيتروجين وكل ذرة هيدروجين","تساهمية ثلاثية"],"answer":2,"why":"كلاهما لافلز، وتتشارك ذرة N بزوج مع كل ذرة H."},{"type":"mcq","q":"تنشأ الرابطة الأيونية نتيجة:","options":["تجاذب نيوترونات","مشاركة إلكترونات بين لافلزين","بحر إلكترونات حرة في فلز","قوة تجاذب كهروستاتيكي قوية بين الأيونات الموجبة والسالبة"],"answer":3,"why":"انتقال الإلكترونات يولّد أيونات متعاكسة الشحنة تتجاذب بقوة."},{"type":"mcq","q":"مادة صلبة درجة انصهارها ٨٠٠°C، تذوب في الماء، توصل الكهرباء مصهورة ولا توصلها صلبة. نوع ترابطها هو:","options":["ترابط أيوني","ترابط تساهمي بسيط","ترابط فلزي","غاز نبيل"],"answer":0,"why":"هذه الخصائص الثلاث هي البصمة الكاملة للمركب الأيوني."},{"type":"mcq","q":"ما الجسيمات المسؤولة عن توصيل الكهرباء في «أسلاك النحاس»؟","options":["الأيونات الموجبة المتحركة","الإلكترونات الحرة (غير المتمركزة)","النيوترونات","الجزيئات المتعادلة"],"answer":1,"why":"في الفلزات توصل الإلكترونات الحرة الكهرباء، أما في الأيونية المصهورة فتوصّلها الأيونات."},{"type":"tfr","q":"تنشأ الرابطة التساهمية بين ذرات اللافلزات عبر المشاركة بأزواج الإلكترونات.","answer":true,"reasons":["مثل H₂O و CO₂ و CH₄ و Cl₂","تنشأ بين فلز ولافلز","تنشأ بفقد الإلكترونات"],"reason":0},{"type":"tfr","q":"تتكون الرابطة الفلزية من تجاذب بين شبكة الأيونات الموجبة وبحر الإلكترونات الحرة.","answer":true,"reasons":["تتكون من أيونات سالبة فقط","وهو ما يفسر التوصيل الكهربائي والحراري والقابلية للطرق والسحب","لا توجد إلكترونات حرة"],"reason":1},{"type":"tfr","q":"في جزيء ثاني أكسيد الكربون (CO₂) ترتبط ذرة الكربون بكل ذرة أكسجين برابطة تساهمية ثنائية (O=C=O).","answer":true,"reasons":["برابطة أيونية","برابطة أحادية فقط","لأن الكربون يحتاج ٤ إلكترونات وكل أكسجين يحتاج إلكترونين"],"reason":2},{"type":"essay","q":"فسّر لماذا يوصل الفلز (النحاس) الكهرباء وهو صلب، بينما لا يوصل الملح (NaCl) الكهرباء وهو صلب.","model":"النحاس به إلكترونات حرة متحركة حتى وهو صلب؛ أما NaCl الصلب فأيوناته مقيدة في الشبكة البلورية ولا تتحرك إلا بالصهر أو الذوبان."},{"type":"essay","q":"بيّن نوع وعدد الروابط التساهمية في كل جزيء: (أ) H₂O، (ب) O₂، (ج) N₂.","model":"(أ) H₂O: رابطتان تساهميتان أحاديتان. (ب) O₂: رابطة تساهمية ثنائية. (ج) N₂: رابطة تساهمية ثلاثية."},{"type":"essay","q":"لماذا يُعدّ كلوريد الهيدروجين (HCl) غازًا عند درجة حرارة الغرفة بينما كلوريد الصوديوم (NaCl) صلب ينصهر عند ٨٠١°C؟","model":"HCl جزيء تساهمي بسيط قوى التجاذب بين جزيئاته ضعيفة جدًا، أما NaCl فشبكة أيونية ذات قوى تجاذب كهروستاتيكية قوية جدًا تحتاج طاقةً هائلةً لتفكيكها."}]}},
  {"id":"g9-chem-1-u4-2","grade":"g9","subject":"chemistry","term":1,"unit":4,"no":2,"title":"الصيَغ الكيميائيّة","summary":"شرح متحرك بـ SVG لدرس الصيَغ الكيميائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-chemical-formulae.html","video":"","pdf":"","notes":["مجموع الشحنات في المركب الأيوني = صفر (استخدم قاعدة المقص ثم بسّط النسبة).","احفظ المجموعات الأيونية: OH⁻, NO₃⁻, NH₄⁺ (١) | CO₃²⁻, SO₄²⁻ (٢) | PO₄³⁻ (٣).","ضع أقواسًا حول المجموعة الأيونية عند تكرارها: Ca(OH)₂، Mg(NO₃)₂، Al₂(SO₄)₃."],"exercises":["اكتب الصيغ الكيميائية للمركبات الآتية: (أ) كلوريد المغنيسيوم، (ب) نترات الألومنيوم، (ج) كبريتات النحاس (II)، (د) هيدروكسيد البوتاسيوم.","احسب عدد ذرات كل عنصر والعدد الكلي للذرات في: (أ) (NH₄)₂SO₄، (ب) Fe₂(CO₃)₃.","صحّح الصيغ الكيميائية الخاطئة الآتية مع بيان السبب: CaOH₂، Mg₂O₂، NaCl₂."],"levels":{"easy":[{"type":"mcq","q":"ما الصيغة الكيميائية الصحيحة لمركّب «هيدروكسيد الكالسيوم» (Ca²⁺ و OH⁻)؟","options":["Ca(OH)₂","CaOH₂","Ca₂OH","Ca(OH)"],"answer":0,"why":"تكافؤ الكالسيوم ٢ فنضع مجموعة الهيدروكسيد بين قوسين مع الرقم ٢."},{"type":"mcq","q":"ما الصيغة الكيميائية الصحيحة لمركّب «أكسيد الألومنيوم» (Al³⁺ و O²⁻)؟","options":["Al₃O₂","Al₂O₃","AlO","Al₂O"],"answer":1,"why":"بالمقص: ٢ للألومنيوم و٣ للأكسجين ليكون المجموع (+6) + (-6) = 0."},{"type":"mcq","q":"ما الصيغة الكيميائية الصحيحة لمركّب «كبريتات الحديد (III)» (Fe³⁺ و SO₄²⁻)؟","options":["FeSO₄","Fe₃(SO₄)₂","Fe₂(SO₄)₃","Fe₂SO₄"],"answer":2,"why":"الحديد (III) شحنته +3 والكبريتات -2 ← بالتبادل Fe₂(SO₄)₃."},{"type":"mcq","q":"كم عدد ذرات الأكسجين (O) الموجودة في وحدة صيغة واحدة من Ca(NO₃)₂؟","options":["ذرتان","٣ ذرات أكسجين","٥ ذرات أكسجين","٦ ذرات أكسجين"],"answer":3,"why":"٣ × ٢ = ٦ ذرات أكسجين (الرقم خارج القوس يُضرب في ما داخله)."}],"medium":[{"type":"mcq","q":"ما الصيغة الصحيحة لمركّب «كربونات الصوديوم» (Na⁺ و CO₃²⁻)؟","options":["Na₂CO₃","NaCO₃","Na(CO₃)₂","Na₂(CO₃)₂"],"answer":0,"why":"تكافؤ الكربونات ٢ والصوديوم ١ ← Na₂CO₃."},{"type":"mcq","q":"ما الصيغة الصحيحة لمركّب «أكسيد المغنيسيوم» (Mg²⁺ و O²⁻)؟","options":["Mg₂O₂","MgO","MgO₂","Mg₂O"],"answer":1,"why":"التكافؤان ٢ و ٢ يُختصران إلى ١ : ١ ← MgO."},{"type":"mcq","q":"ما شحنة أيون «النترات» وأيون «الكبريتات» على الترتيب؟","options":["NO₃⁺ و SO₄²⁺","NO₃²⁻ و SO₄⁻","NO₃⁻ و SO₄²⁻","NO₃³⁻ و SO₄³⁻"],"answer":2,"why":"النترات أحادية سالبة (−١)، والكبريتات ثنائية سالبة (−٢)."},{"type":"tfr","q":"في الصيغة الكيميائية، إذا تساوى تكافؤ الأيونين (مثل Ca²⁺ و O²⁻) نكتبهما Ca₂O₂ دون تبسيط.","answer":false,"reasons":["تُكتب CaO₂","نعم لا نبسّط","بل نبسّط النسبة لأبسط صورة فتُكتب CaO"],"reason":2},{"type":"tfr","q":"يجب وضع أقواس حول المجموعة الأيونية عند تكرارها أكثر من مرة في الصيغة مثل Mg(NO₃)₂.","answer":true,"reasons":["حتى يشمل الرقم السفلي جميع ذرات المجموعة الأيونية","لا حاجة للأقواس أبدًا","تُوضع الأقواس حول الفلز فقط"],"reason":0},{"type":"essay","q":"اكتب الصيغ الكيميائية للمركبات الآتية: (أ) كلوريد المغنيسيوم، (ب) نترات الألومنيوم، (ج) كبريتات النحاس (II)، (د) هيدروكسيد البوتاسيوم.","model":"(أ) MgCl₂. (ب) Al(NO₃)₃. (ج) CuSO₄. (د) KOH."},{"type":"essay","q":"احسب عدد ذرات كل عنصر والعدد الكلي للذرات في: (أ) (NH₄)₂SO₄، (ب) Fe₂(CO₃)₃.","model":"(أ) N=2, H=8, S=1, O=4 (المجموع ١٥ ذرة). (ب) Fe=2, C=3, O=9 (المجموع ١٤ ذرة)."}],"hard":[{"type":"mcq","q":"ما الاسم الكيميائي الصحيح للصيغة CuCl₂؟","options":["أكسيد النحاس (II)","كلوريد النحاس (I)","كلوريد الكربون","كلوريد النحاس (II)"],"answer":3,"why":"بما أن هناك أيونَي Cl⁻ (−٢) فشحنة النحاس +٢ ← النحاس (II)."},{"type":"mcq","q":"ما الصيغة الصحيحة لمركّب «كلوريد الأمونيوم» (NH₄⁺ و Cl⁻)؟","options":["NH₄Cl","NH₄Cl₂","(NH₄)₂Cl","NH₃Cl"],"answer":0,"why":"كلا الأيونين أحادي الشحنة (+1 و -1) ← NH₄Cl."},{"type":"mcq","q":"ما الصيغة الكيميائية الصحيحة لـ«حمض الكبريتيك»؟","options":["HCl","H₂SO₄","HNO₃","H₂CO₃"],"answer":1,"why":"حمض الكبريتيك H₂SO₄، والهيدروكلوريك HCl، والنيتريك HNO₃."},{"type":"mcq","q":"مجموع الشحنات الموجبة والسالبة في أي صيغة لمركّب أيوني متعادل يجب أن يساوي:","options":["−١","+١","صفرًا","+٢"],"answer":2,"why":"المركّب الأيوني متعادل كهربائيًا (مجموع الشحنات = صفر)."},{"type":"tfr","q":"الرقم الروماني في «أكسيد الحديد (III)» يدل على عدد ذرات الحديد في الصيغة.","answer":false,"reasons":["نعم يدل على عدد الذرات","بل يدل على شحنة/تكافؤ أيون الحديد (+3)، وصيغته Fe₂O₃","يدل على عدد ذرات الأكسجين"],"reason":1},{"type":"tfr","q":"تحتوي الصيغة Al₂(SO₄)₃ على ٣ ذرات كبريت و١٢ ذرة أكسجين.","answer":true,"reasons":["تحتوي ٧ ذرات أكسجين","تحتوي ذرة كبريت واحدة","S = 1×3 = 3، و O = 4×3 = 12"],"reason":2},{"type":"tfr","q":"مجموعة الأمونيوم (NH₄⁺) هي المجموعة الأيونية الموجبة الشحنة الأكثر شهرةً في الكيمياء المدرسية.","answer":true,"reasons":["وتكوّن أملاحًا مثل NH₄Cl و (NH₄)₂SO₄","شحنتها سالبة","هي عنصر فلزي"],"reason":0},{"type":"essay","q":"صحّح الصيغ الكيميائية الخاطئة الآتية مع بيان السبب: CaOH₂، Mg₂O₂، NaCl₂.","model":"Ca(OH)₂ (لزم وضع أقواس حول الهيدروكسيد). MgO (اختصار التكافؤ ٢:٢). NaCl (تكافؤ الصوديوم +1 والكلور -1)."},{"type":"essay","q":"استنتج شحنة الفلز الانتقالي في كل مركب واكتب اسمه بالرقم الروماني: FeCl₂، FeCl₃، CuO.","model":"FeCl₂: Fe²⁺ ← كلوريد الحديد (II). FeCl₃: Fe³⁺ ← كلوريد الحديد (III). CuO: Cu²⁺ ← أكسيد النحاس (II)."},{"type":"essay","q":"اشرح لماذا تُعدّ قاعدة «مجموع الشحنات = صفر» أساسًا لكل الصيغ الأيونية.","model":"لأن المركّب الأيوني متعادل كهربائيًا، فيجب أن تتساوى الشحنات الموجبة الكلية للأيونات الموجبة مع الشحنات السالبة الكلية للأيونات السالبة."}]}},
  {"id":"g9-chem-1-u4-3","grade":"g9","subject":"chemistry","term":1,"unit":4,"no":3,"title":"البلّورات","summary":"شرح متحرك بـ SVG لدرس البلّورات (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-crystals-and-structures.html","video":"","pdf":"","notes":["الألماس (٤ روابط، صلب، عازل) × الجرافيت (٣ روابط، طبقات منزلقة، موصّل بإلكترونات حرة).","السيليكا SiO₂: تركيب تساهمي ضخم كالألماس (صلبة، انصهار عالٍ، عازلة) بعكس CO₂ الغازي البسيط.","البلورات الأيونية (NaCl) عالية الانصهار لكنها هشّة بسبب تنافر الشحنات المتماثلة عند الطرق."],"exercises":["قارن في جدول بين «الألماس» و«الجرافيت» من حيث: عدد الروابط لكل ذرة كربون، الصلابة، التوصيل الكهربائي، واستخدام واحد لكل منهما.","فسّر لماذا تتشابه خصائص «السيليكا (SiO₂)» مع خصائص «الألماس» وتختلف جذريًا عن «ثاني أكسيد الكربون (CO₂)».","علّل: يمتلك الجرافيت درجة انصهار عالية جدًا رغم أنه ناعم وطري في قلم الرصاص."],"levels":{"easy":[{"type":"mcq","q":"بكم ذرة كربون ترتبط كل ذرة كربون في بلورة «الألماس»؟","options":["٣ ذرات كربون","٤ ذرات كربون بروابط تساهمية قوية","ذرتين فقط","٦ ذرات"],"answer":1,"why":"كل ذرة كربون ترتبط بـ ٤ ذرات في شبكة رباعية الأوجه شديدة الصلابة."},{"type":"mcq","q":"لماذا يوصل «الجرافيت» التيار الكهربائي رغم أنه لافلز؟","options":["لأنه فلز انتقالي","لأنه يحتوي أيونات صوديوم","لأن كل ذرة كربون ترتبط بـ ٣ ذرات فقط ويبقى الإلكترون الرابع حرّ الحركة بين الطبقات","لأنه يذوب في الماء"],"answer":2,"why":"وجود إلكترونات حرة غير متمركزة يمكّنه من التوصيل الكهربائي."},{"type":"mcq","q":"لماذا يُستخدم «الجرافيت» في صناعة أقلام الرصاص وكمادة تشحيم جافة؟","options":["لأن روابطه أيونية","لأنه أصلب من الألماس","لأنه سائل","لأن طبقاته السداسية مرتبطة بقوى جذب ضعيفة فتنزلق فوق بعضها بسهولة"],"answer":3,"why":"انزلاق الطبقات يمنحه نعومةً وزلاقةً مميزةً."},{"type":"mcq","q":"لماذا يُستخدم «الألماس» في رؤوس آلات حفر الآبار وقطع الزجاج؟","options":["لصلابته الفائقة الناتجة عن شبكته التساهمية الضخمة رباعية الأوجه","لأنه ناعم وزلق","لأنه موصل للكهرباء","لأن درجة انصهاره منخفضة"],"answer":0,"why":"جميع روابطه تساهمية قوية جدًا في ثلاثة أبعاد."}],"medium":[{"type":"mcq","q":"أي مادة لها تركيب تساهمي ضخم يشبه الألماس وتُكوّن الرمل والكوارتز؟","options":["ثاني أكسيد الكربون (CO₂)","ثاني أكسيد السيليكون (السيليكا SiO₂)","كلوريد الصوديوم (NaCl)","الميثان (CH₄)"],"answer":1,"why":"السيليكا SiO₂ تركيب تساهمي ضخم صلب وعازل وعالي الانصهار."},{"type":"mcq","q":"لماذا يكون CO₂ غازًا عند درجة حرارة الغرفة بينما SiO₂ صلبًا ينصهر عند ١٧٠٠°C؟","options":["لأن السيليكون غاز نبيل","لأن CO₂ أيوني","CO₂ جزيئات تساهمية بسيطة ذات قوى بينية ضعيفة، بينما SiO₂ تركيب تساهمي ضخم","لأن SiO₂ يحتوي إلكترونات حرة"],"answer":2,"why":"اختلاف نوع التركيب (جزيئي بسيط × تساهمي ضخم) يصنع هذا الفرق الهائل."},{"type":"mcq","q":"ما نوع الجسيمات المكوّنة للشبكة البلورية في «كلوريد الصوديوم (NaCl)»؟","options":["إلكترونات حرة فقط","ذرات كربون فقط","جزيئات ماء","أيونات موجبة (Na⁺) وأيونات سالبة (Cl⁻) متبادلة بانتظام"],"answer":3,"why":"بلورة أيونية ضخمة من أيونات Na⁺ و Cl⁻."},{"type":"tfr","q":"الألماس والجرافيت يتكوّنان من ذرات الكربون نفسها لكنهما يختلفان في طريقة الترابط البلوري.","answer":true,"reasons":["الألماس ٤ روابط شبكية، والجرافيت ٣ روابط في طبقات منزلقة","الألماس من السيليكون","الجرافيت من الرصاص المعدني"],"reason":0},{"type":"tfr","q":"الجرافيت والألماس كلاهما لهما درجة انصهار مرتفعة جدًا.","answer":true,"reasons":["الجرافيت ينصهر عند ٥٠°C","لأن صهر كليهما يتطلب كسر روابط تساهمية قوية جدًا في تركيب ضخم","الألماس ينصهر عند ١٠٠°C"],"reason":1},{"type":"essay","q":"قارن في جدول بين «الألماس» و«الجرافيت» من حيث: عدد الروابط لكل ذرة كربون، الصلابة، التوصيل الكهربائي، واستخدام واحد لكل منهما.","model":"الألماس: ٤ روابط، أصلب مادة، عازل كهربائي، يُستخدم في القطع والحفر. الجرافيت: ٣ روابط (طبقات)، ناعم وزلق، موصل للكهرباء، يُستخدم في أقلام الرصاص والأقطاب والتشحيم."},{"type":"essay","q":"فسّر لماذا تتشابه خصائص «السيليكا (SiO₂)» مع خصائص «الألماس» وتختلف جذريًا عن «ثاني أكسيد الكربون (CO₂)».","model":"السيليكا والألماس كلاهما تراكيب تساهمية ضخمة ثلاثية الأبعاد (صلبة جدًا، انصهار هائل، عازلة)، بينما CO₂ جزيء تساهمي بسيط قوى التجاذب بين جزيئاته ضعيفة فيكون غازًا."}],"hard":[{"type":"mcq","q":"لماذا «لا يوصل الألماس» الكهرباء؟","options":["لأن جميع إلكترونات التكافؤ الأربعة مرتبطة في روابط تساهمية ولا توجد إلكترونات حرة","لأنه صلب فقط","لأنه يذوب في الماء","لأنه يحتوي أيونات مقيدة"],"answer":0,"why":"غياب الإلكترونات والأيونات الحرة يجعله عازلًا كهربائيًا."},{"type":"mcq","q":"لماذا يُستخدم الجرافيت في صناعة «الأقطاب الكهربائية» في خلايا التحليل الكهربائي؟","options":["لأنه ينصهر بسرعة","لأنه موصل جيد للكهرباء وخامل كيميائيًا ودرجة انصهاره عالية جدًا","لأنه يتفاعل مع الأحماض بعنف","لأنه عازل كهربائي"],"answer":1,"why":"يجمع بين التوصيل الكهربائي والانصهار العالي والخمول."},{"type":"mcq","q":"تُسمّى ظاهرة وجود العنصر الواحد (كالكربون) في أكثر من صورة بلورية مختلفة الخصائص بـ:","options":["النظائر","التسامي","التآصل (Allotropy)","التبلور"],"answer":2,"why":"الألماس والجرافيت متآصلان لعنصر الكربون."},{"type":"mcq","q":"لماذا تكون البلّورات الأيونية (كملح الطعام) «هشّة» وتنكسر عند الطرق القوي؟","options":["لأنها سائلة","لأن روابطها ضعيفة جدًا","لأنها تحتوي إلكترونات حرة","لأن انزلاق الطبقة يجعل الأيونات المتماثلة الشحنة تتقابل فتتنافر وتنكسر البلورة"],"answer":3,"why":"التنافر بين الشحنات المتشابهة عند الإزاحة يسبب الهشاشة."},{"type":"tfr","q":"ثاني أكسيد السيليكون (SiO₂) يوصل الكهرباء بشدة مثل الجرافيت.","answer":false,"reasons":["هو فلز","نعم يوصل الكهرباء","بل هو عازل كهربائي كالألماس لعدم وجود إلكترونات حرة"],"reason":2},{"type":"tfr","q":"في الجرافيت، قوى التجاذب «بين الطبقات» السداسية ضعيفة فتسمح لها بالانزلاق.","answer":true,"reasons":["وهذا سبب نعومته واستخدامه في أقلام الرصاص والتشحيم","بل الروابط بين الطبقات أيونية قوية","لا ينزلق الجرافيت"],"reason":0},{"type":"tfr","q":"قلم الرصاص العادي لا يحتوي على عنصر الرصاص (Pb) السام، بل يحتوي على خليط من الجرافيت والطين.","answer":true,"reasons":["يحتوي على رصاص نقي","سُمّي رصاصًا لتسمية تاريخية قديمة فقط!","يحتوي على ألماس"],"reason":1},{"type":"essay","q":"علّل: يمتلك الجرافيت درجة انصهار عالية جدًا رغم أنه ناعم وطري في قلم الرصاص.","model":"لأن نعومته ناتجة عن ضعف القوى «بين الطبقات» فتنزلق بسهولة، أما صهره فيتطلب كسر الروابط التساهمية القوية جدًا «داخل الطبقات» مما يحتاج حرارةً هائلةً!"},{"type":"essay","q":"اشرح لماذا تكون الفلزات قابلةً للطرق والسحب بينما تكون البلّورات الأيونية هشّةً وتنكسر عند الطرق.","model":"في الفلزات تنزلق طبقات الأيونات الموجبة مع بقاء بحر الإلكترونات ممسكًا بها؛ أما في الأيونية فانزلاق الطبقة يضع الشحنات المتماثلة أمام بعضها فتتنافر بقوة وتنكسر البلورة."},{"type":"essay","q":"اذكر ثلاثة أسباب تجعل الجرافيت مثاليًا لصناعة الأقطاب الكهربائية في المختبر.","model":"١) يوصل الكهرباء لوجود إلكترونات حرة. ٢) درجة انصهاره مرتفعة جدًا. ٣) خامل كيميائيًا ولا يتفاعل مع معظم المحاليل."}]}},
  {"id":"g9-chem-1-u5-1","grade":"g9","subject":"chemistry","term":1,"unit":5,"no":1,"title":"معدّل سرعة التفاعل الكيميائي","summary":"شرح متحرك بـ SVG لدرس معدّل سرعة التفاعل الكيميائي (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-rate-of-reaction.html","video":"","pdf":"","notes":["معدّل السرعة = التغيّر في الكمية ÷ الزمن.","طرق القياس: محقنة الغاز، نقصان الكتلة (بسدادة قطن)، وإخفاء علامة X (السرعة ∝ ١/زمن).","على المنحنى: أشد ميل في البداية (أسرع) ← يقل الميل (يتباطأ) ← خط أفقي (انتهى التفاعل)."],"exercises":["في تجربة تفاعل المغنيسيوم مع حمض HCl، جمع طالب ٤٨ سم³ من الهيدروجين في ٢٤ ثانية ثم ثبت الحجم. احسب متوسط السرعة، وصف شكل المنحنى في المراحل الثلاث.","اذكر ثلاث طرق عملية مختلفة لقياس معدل سرعة تفاعل كيميائي مع مثال لكل طريقة.","علّل: لماذا نضع سدادة قطن (وليس سدادة مطاطية محكمة) عند قياس سرعة التفاعل على الميزان؟"],"levels":{"easy":[{"type":"mcq","q":"تصاعد ٨٠ سم³ من غاز CO₂ خلال ٤٠ ثانية حتى توقف التفاعل. ما متوسط معدّل سرعة التفاعل؟","options":["٣٢٠٠ سم³/ث","٠٫٥ سم³/ث","٢ سم³/ث","٤٠ سم³/ث"],"answer":2,"why":"٨٠ ÷ ٤٠ = ٢ سم³/ث."},{"type":"mcq","q":"لماذا توضع «سدادة من القطن» في فوهة الدورق عند قياس سرعة التفاعل بنقصان الكتلة على الميزان؟","options":["لزيادة كتلة الدورق","لمنع خروج الغاز تمامًا","لتسخين التفاعل","لتسمح بخروج الغاز المتصاعد وتمنع تطاير رذاذ السائل الحمضي للخارج"],"answer":3,"why":"تمنع فقدان رذاذ السائل وتسمح بهروب CO₂ لتكون قراءة الميزان دقيقة."},{"type":"mcq","q":"في منحنى (حجم الغاز مقابل الزمن)، متى يكون التفاعل في «أقصى سرعة» له؟","options":["في البداية تمامًا (حيث يكون ميل المنحنى أشدّ انحدارًا)","عندما يصبح المنحنى أفقيًا","في آخر ثانية قبل التوقف","السرعة ثابتة طوال التفاعل"],"answer":0,"why":"تركيز المتفاعلات أعلى ما يمكن في البداية فيكون الميل أشد."},{"type":"mcq","q":"ماذا يعني تحوّل منحنى (حجم الغاز مقابل الزمن) إلى «خط أفقي»؟","options":["تسارع التفاعل لأقصى حد","توقّف التفاعل تمامًا لاستهلاك المادة المحدّدة","بدء تفاعل جديد","تعطل محقنة الغاز"],"answer":1,"why":"الميل = صفر يعني لم يعد يتصاعد أي غاز إضافي."}],"medium":[{"type":"mcq","q":"لماذا يتباطأ التفاعل الكيميائي تدريجيًا مع مرور الوقت؟","options":["لأن الكتلة تزداد","لأن النواتج تزيد التركيز","بسبب استهلاك المتفاعلات ونقص تركيزها فتقل التصادمات","لأن الزمن يقل"],"answer":2,"why":"نقص تركيز المتفاعلات يقلل معدل التصادمات الفعالة."},{"type":"mcq","q":"في تجربة إخفاء علامة (X) بتكوّن راسب الكبريت، استغرقت التجربة (أ) ١٥ ثانية والتجربة (ب) ٤٥ ثانية. أيهما أسرع؟","options":["التجربة (أ) لم تحدث","التجربة (ب) أسرع","لهما نفس السرعة","التجربة (أ) أسرع ٣ مرات من (ب)"],"answer":3,"why":"الزمن الأقصر يعني تفاعلًا أسرع (٤٥ ÷ ١٥ = ٣ أضعاف)."},{"type":"mcq","q":"ما الأداة الأدق لجمع وقياس حجم الغاز المتصاعد من تفاعل كيميائي؟","options":["محقنة الغاز المدرّجة (Gas syringe)","الميزان ذو الكفتين","ورقة الترشيح","الترمومتر"],"answer":0,"why":"محقنة الغاز تقيس الحجم مباشرةً بدقة عالية."},{"type":"tfr","q":"يكون التفاعل الكيميائي أسرع ما يمكن في بدايته ثم يتباطأ تدريجيًا حتى يتوقف.","answer":true,"reasons":["يكون أسرع في النهاية","لأن تركيز المتفاعلات يكون أعلى ما يمكن في البداية ثم يُستهلك تدريجيًا","سرعته ثابتة دائمًا"],"reason":1},{"type":"tfr","q":"سدادة القطن في تجربة نقصان الكتلة تمنع خروج غاز CO₂ من الدورق.","answer":false,"reasons":["تُمتص الحمض كله","نعم تمنع خروج الغاز","بل تسمح بخروج غاز CO₂ وتمنع فقط تطاير رذاذ المحلول الحمضي"],"reason":2},{"type":"essay","q":"في تجربة تفاعل المغنيسيوم مع حمض HCl، جمع طالب ٤٨ سم³ من الهيدروجين في ٢٤ ثانية ثم ثبت الحجم. احسب متوسط السرعة، وصف شكل المنحنى في المراحل الثلاث.","model":"متوسط السرعة = ٤٨ ÷ ٢٤ = ٢ سم³/ث. المنحنى: شديد الانحدار في البداية (أسرع)، ثم يقل ميله تدريجيًا (يتباطأ)، ثم يصبح أفقيًا عند ٤٨ سم³ (توقف التفاعل)."},{"type":"essay","q":"اذكر ثلاث طرق عملية مختلفة لقياس معدل سرعة تفاعل كيميائي مع مثال لكل طريقة.","model":"١) قياس حجم الغاز بمحقنة غاز (Mg + HCl). ٢) قياس نقصان الكتلة على ميزان إلكتروني مع سدادة قطن (CaCO₃ + HCl). ٣) قياس زمن اختفاء علامة X لتكوّن راسب (ثيوكبريتات الصوديوم + HCl)."}],"hard":[{"type":"mcq","q":"لماذا لا تصلح طريقة «نقصان الكتلة على الميزان» جيدًا عند تصاعد غاز الهيدروجين (H₂)؟","options":["لأن الهيدروجين لا يخرج من القطن","لأن غاز الهيدروجين خفيف جدًا فيكون التغيّر في الكتلة ضئيلًا يصعب قياسه بدقة","لأن الهيدروجين سائل","لأنه أثقل من CO₂"],"answer":1,"why":"الكتلة المولية لـ H₂ هي ٢ فقط بينما CO₂ هي ٤٤."},{"type":"mcq","q":"إذا أُعيد تفاعل كربونات الكالسيوم مع «ضعف» كمية المادة المحدّدة، فماذا يحدث لارتفاع الخط الأفقي النهائي؟","options":["يقل إلى النصف","يبقى كما هو","يتضاعف الحجم النهائي للغاز إلى الضعف","يصبح صفرًا"],"answer":2,"why":"كمية الناتج الكلي تتناسب طرديًا مع كمية المادة المحدّدة."},{"type":"mcq","q":"أي التفاعلات الآتية يُعدّ مثالًا لتفاعل كيميائي بطيء جدًا؟","options":["تفاعل الصوديوم مع الماء","احتراق الألعاب النارية","فوران قرص فيتامين سي في الماء","صدأ الحديد في الهواء الرطب"],"answer":3,"why":"صدأ الحديد يستغرق أيامًا وأشهرًا."},{"type":"mcq","q":"لقياس سرعة تفاعل لحظية عند زمن محدد من منحنى (الحجم–الزمن)، نحسب:","options":["ميل المماس للمنحنى عند تلك النقطة","المساحة تحت المنحنى","أعلى نقطة فقط","مجموع الأزمنة"],"answer":0,"why":"ميل المماس يعطي معدل التغير اللحظي (السرعة اللحظية)."},{"type":"tfr","q":"المنحنى الأكثر انحدارًا (أكبر ميل) على رسم (حجم الغاز–الزمن) يمثّل التفاعل الأسرع.","answer":true,"reasons":["ويصل إلى الخط الأفقي في زمن أقصر","يمثل التفاعل الأبطأ","يدل على توقف التفاعل"],"reason":0},{"type":"tfr","q":"في تجربة إخفاء علامة (X)، كلما زاد الزمن المستغرق لاختفاء العلامة كان التفاعل أسرع.","answer":false,"reasons":["نعم الزمن الأطول أسرع","العكس تمامًا: الزمن الأقصر يدل على التفاعل الأسرع (السرعة ∝ ١/الزمن)","لا علاقة للزمن بالسرعة"],"reason":1},{"type":"tfr","q":"ثبات قراءة الميزان أو حجم الغاز في المحقنة يعني انتهاء التفاعل لاستهلاك أحد المتفاعلات.","answer":true,"reasons":["يعني زيادة السرعة","يعني أن التفاعل بدأ للتو","وهو ما يظهر كخط أفقي على الرسم البياني"],"reason":2},{"type":"essay","q":"علّل: لماذا نضع سدادة قطن (وليس سدادة مطاطية محكمة) عند قياس سرعة التفاعل على الميزان؟","model":"لأن السدادة المطاطية تحبس الغاز فلا تنقص الكتلة وقد ينفجر الدورق، بينما القطن يسمح بخروج غاز CO₂ ويمنع تطاير رذاذ الحمض للخارج."},{"type":"essay","q":"قارن بين منحنيين لتفاعلَين ينتجان نفس الحجم الكلي للغاز (٦٠ سم³)، لكن التفاعل A توقف بعد ٢٠ ثانية و B بعد ٥٠ ثانية.","model":"كلاهما يصل لنفس الخط الأفقي (٦٠ سم³)، لكن منحنى A أشد انحدارًا (أكبر ميل) ويصل للأفقي أولًا لأنه أسرع من B."},{"type":"essay","q":"فسّر لماذا تقل سرعة التفاعل تدريجيًا من الثانية الأولى حتى توقفه.","model":"مع استمرار التفاعل تُستهلك جسيمات المتفاعلات فيقل تركيزها، فتقل عدد التصادمات الفعالة في الثانية حتى ينفد أحد المتفاعلات ويتوقف التفاعل."}]}},
  {"id":"g9-chem-1-u5-2","grade":"g9","subject":"chemistry","term":1,"unit":5,"no":2,"title":"العوامل المؤثّرة في معدّل سرعة التفاعل","summary":"شرح متحرك بـ SVG لدرس العوامل المؤثّرة في معدّل سرعة التفاعل (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-factors-affecting-rate.html","video":"","pdf":"","notes":["نظرية التصادم: سرعة التفاعل تزداد بزيادة معدل التصادمات الفعّالة (بطاقة ≥ Ea).","العوامل الخمسة: التركيز (والضغط للغازات)، مساحة السطح (المسحوق)، الحرارة (أثر مزدوج)، الحفّاز (يخفض Ea ولا يُستهلك)، والضوء.","تسريع التفاعل مع ثبات المادة المحددة يعطي ميلًا أشد ونفس كمية الناتج النهائي."],"exercises":["فسّر باستخدام «نظرية التصادم» أثر كل من: (أ) رفع درجة الحرارة، (ب) سحق المادة الصلبة إلى مسحوق، على سرعة التفاعل.","عرّف «العامل الحفّاز»، واشرح كيف تتحقق مخبريًا من أن MnO₂ لم يُستهلك بعد تفكك H₂O₂.","في تفاعل Mg مع زيادة من حمض HCl، كيف يتغير شكل منحنى (حجم الغاز–الزمن) إذا كررنا التجربة عند حرارة أعلى مع نفس كتلة المغنيسيوم؟"],"levels":{"easy":[{"type":"mcq","q":"ما الشرط الأساسي لحدوث «تصادم فعّال» ينتج عنه تفاعل كيميائي؟","options":["أن تكون المادة صلبة فقط","مجرد أي تصادم مهما كانت طاقته ضعيفة","أن تكون الجسيمات ساكنة","أن تتصادم الجسيمات بطاقة تساوي أو تفوق طاقة التنشيط (Ea)"],"answer":3,"why":"بدون بلوغ طاقة التنشيط يرتد الجسيمان دون تفاعل."},{"type":"mcq","q":"كيف يعمل «العامل الحفّاز» على زيادة سرعة التفاعل الكيميائي؟","options":["يوفّر مسارًا بديلًا للتفاعل بطاقة تنشيط (Ea) أقل، ولا يُستهلك","يرفع درجة حرارة التفاعل","يزيد تركيز المتفاعلات","يزيد كمية الناتج النهائي للضعف"],"answer":0,"why":"خفض طاقة التنشيط يسمح لعدد أكبر من التصادمات بالنجاح."},{"type":"mcq","q":"لماذا يتفاعل مسحوق كربونات الكالسيوم مع حمض HCl أسرع من قطع الرخام الكبيرة بنفس الكتلة؟","options":["لأن كتلة المسحوق أكبر","لأن للمسحوق مساحة سطح أكبر معرّضة للتصادمات في الثانية الواحدة","لأن تركيز الحمض يتضاعف","لأن المسحوق عامل حفاز"],"answer":1,"why":"تفتيت المادة الصلبة يضاعف مساحة السطح المعرّضة للتصادم."},{"type":"mcq","q":"لماذا يسرّع رفع درجة الحرارة التفاعل الكيميائي بشكل كبير جدًا؟","options":["لأن الحجم يصبح صفرًا","لأن كتلة الجسيمات تقل","لأن الجسيمات تتحرك أسرع فتتصادم أكثر، ونسبة أكبر منها تمتلك طاقةً ≥ طاقة التنشيط","لأنه يخفض طاقة التنشيط"],"answer":2,"why":"الحرارة لها أثر مزدوج: زيادة تكرار التصادمات وزيادة طاقتها."}],"medium":[{"type":"mcq","q":"لماذا تُعدّ الإنزيمات داخل جسم الإنسان «عوامل حفّازة حيوية»؟","options":["لأنها تبطئ الهضم","لأنها تُستهلك بالكامل في كل وجبة","لأنها ترفع حرارة الجسم لـ ١٠٠°C","لأنها تسرّع التفاعلات الحيوية كالهضم عند ٣٧°C دون أن تُستهلك"],"answer":3,"why":"الإنزيمات بروتينات تعمل كحفازات حيوية متخصصة."},{"type":"mcq","q":"عند إضافة العامل الحفّاز MnO₂ لتفكك H₂O₂ (بنفس كمية H₂O₂)، ماذا يحدث لـ«الحجم الكلي لغاز الأكسجين» الناتج؟","options":["يبقى كما هو تمامًا، لكنه يتجمّع في زمن أقصر","يتضاعف إلى الضعف","يقلّ إلى النصف","ينعدم تمامًا"],"answer":0,"why":"الحفّاز يسرّع الوصول للنهاية ولا يغيّر كمية الناتج."},{"type":"mcq","q":"زيادة «الضغط» تؤثّر بشكل مباشر وواضح في سرعة التفاعلات التي تتضمن:","options":["مواد صلبة فقط","غازات متفاعلة","سوائل فقط","الحديد فقط"],"answer":1,"why":"الضغط يقارب جسيمات الغاز في وحدة الحجم فيزيد التصادمات."},{"type":"tfr","q":"يعمل العامل الحفّاز على زيادة سرعة التفاعل عن طريق «خفض طاقة التنشيط».","answer":true,"reasons":["عن طريق زيادة كتلة المتفاعلات","عن طريق رفع طاقة التنشيط","بتوفير مسار بديل أسهل للتفاعل دون أن يُستهلك"],"reason":2},{"type":"tfr","q":"إضافة عامل حفّاز لتفاعل كيميائي تضاعف كمية الناتج النهائي إلى الضعف.","answer":false,"reasons":["لا يغير الحفّاز كمية الناتج أبدًا، بل يختصر الزمن اللازم للحصول على نفس الكمية","نعم تضاعف الناتج","تقلل الناتج للنصف"],"reason":0},{"type":"essay","q":"فسّر باستخدام «نظرية التصادم» أثر كل من: (أ) رفع درجة الحرارة، (ب) سحق المادة الصلبة إلى مسحوق، على سرعة التفاعل.","model":"(أ) الحرارة تزيد طاقة حركة الجسيمات فتتصادم أسرع وأكثر، ونسبة أكبر منها تبلغ طاقة التنشيط فتزيد التصادمات الفعالة. (ب) المسحوق يزيد مساحة السطح المعرّض فتزداد التصادمات في الثانية."},{"type":"essay","q":"عرّف «العامل الحفّاز»، واشرح كيف تتحقق مخبريًا من أن MnO₂ لم يُستهلك بعد تفكك H₂O₂.","model":"الحفاز مادة تسرع التفاعل بخفض طاقة التنشيط دون أن تُستهلك. للتحقق: نزن MnO₂ قبل التجربة، ثم بعد انتهاء التفاعل نرشّحه ونغسله ونجففه ونعيد وزنه فنجد كتلته لم تتغير."}],"hard":[{"type":"mcq","q":"لماذا قد يحدث انفجار خطير في مطاحن الدقيق عند وجود شرر كهربائي؟","options":["لأن الدقيق غاز نبيل","لأن الدقيق فلز قلوي","لأن غبار الدقيق الناعم له مساحة سطح هائلة فيتفاعل بالاحتراق بسرعة انفجارية","لأن الحرارة منخفضة"],"answer":2,"why":"مساحة السطح الضخمة تجعل معدل التصادم مع الأكسجين هائلًا."},{"type":"mcq","q":"لماذا تُحفظ بعض الأدوية والمحاليل الحساسة (مثل نترات الفضة) في زجاجات بنية داكنة؟","options":["لمنع دخول النيتروجين","لجعل لونها جميلًا فقط","لرفع درجة حرارتها","لحمايتها من الضوء الذي يسرّع تحللها الكيميائي"],"answer":3,"why":"الزجاج الداكن يحجب الضوء عن التفاعلات الضوئية."},{"type":"mcq","q":"لماذا نحفظ اللحوم والحليب داخل الثلاجة؟","options":["لأن خفض الحرارة يقلّل طاقة حركة الجسيمات والتصادمات الفعالة فيبطّئ تفاعلات الفساد ونشاط البكتيريا","لأن الثلاجة تقتل كل التفاعلات إلى الأبد","لأن الثلاجة تزيد التركيز","لأن البرد يرفع طاقة التنشيط"],"answer":0,"why":"تبريد الطعام يبطّئ سرعة التفاعلات الكيميائية والحيوية."},{"type":"mcq","q":"إذا أردنا إثبات أن مادة X تعمل كـ«عامل حفّاز» في تفاعل، ما الشرطان اللذان نتحقق منهما؟","options":["أنها تذوب وتختفي تمامًا","أنها تسرّع التفاعل، وتبقى كتلتها وتركيبها الكيميائي ثابتين دون تغير في نهاية التفاعل","أنها تضاعف كمية الناتج","أنها تبطئ التفاعل"],"answer":1,"why":"التسريع + ثبات الكتلة والتركيب الكيميائي."},{"type":"tfr","q":"زيادة تركيز الحمض تزيد عدد الجسيمات في وحدة الحجم فيزداد معدل التصادمات الفعالة.","answer":true,"reasons":["تقلل عدد الجسيمات","فتزداد سرعة التفاعل ويصبح منحنى (الحجم–الزمن) أشد انحدارًا","تبطئ التفاعل"],"reason":1},{"type":"tfr","q":"يُعدّ مسحوق الخارصين أبطأ تفاعلًا مع الحمض من قطعة خارصين كبيرة لها نفس الكتلة.","answer":false,"reasons":["لهما نفس السرعة","نعم أبطأ","بل أسرع بكثير لأن مساحة سطحه المعرّضة أكبر بكثير"],"reason":2},{"type":"tfr","q":"الضوء عامل يؤثّر في سرعة بعض التفاعلات الخاصة مثل التمثيل الضوئي وتفكك أملاح الفضة.","answer":true,"reasons":["وكلما زادت شدة الضوء زادت سرعة هذه التفاعلات","الضوء لا يؤثر في أي تفاعل","يبطئ التمثيل الضوئي"],"reason":0},{"type":"essay","q":"في تفاعل Mg مع زيادة من حمض HCl، كيف يتغير شكل منحنى (حجم الغاز–الزمن) إذا كررنا التجربة عند حرارة أعلى مع نفس كتلة المغنيسيوم؟","model":"يبدأ المنحنى الجديد بميل أشد انحدارًا ويصل للخط الأفقي في زمن أقصر، لكنه يثبت عند «نفس الارتفاع النهائي» لأن كتلة المغنيسيوم (المادة المحددة) لم تتغير."},{"type":"essay","q":"اذكر تطبيقين من حياتنا اليومية نتحكم فيهما بسرعة التفاعل الكيميائي (واحد للتسريع وواحد للإبطاء).","model":"للتسريع: طحن البن أو استخدام المحوّل الحفّاز في عادم السيارة أو تسخين الطعام. للإبطاء: حفظ الأغذية في الثلاجة أو طلاء الحديد لمنع الصدأ."},{"type":"essay","q":"علّل: لماذا يؤثّر زيادة الضغط في سرعة التفاعلات الغازية ولا يؤثّر يُذكر في تفاعلات المواد الصلبة والسائلة؟","model":"لأن الغازات قابلة للانضغاط فيقارب الضغط جسيماتها ويزيد تركيزها ومعدل تصادماتها، بينما الصلب والسائل غير قابلين للانضغاط تقريبًا."}]}},
  {"id":"g9-chem-1-u5-3","grade":"g9","subject":"chemistry","term":1,"unit":5,"no":3,"title":"تغيّرات الطاقة في التفاعُلات الكيميائيّة","summary":"شرح متحرك بـ SVG لدرس تغيّرات الطاقة في التفاعُلات الكيميائيّة (الصف التاسع - الفصل الثاني)، يليه ٤ أسئلة تفاعلية وأنشطة بثلاثة مستويات.","page":"lesson-energy-changes-in-reactions.html","video":"","pdf":"","notes":["طارد للحرارة: حرارة الوسط ↑، ΔH سالب (−)، النواتج أسفل المتفاعلات (الاحتراق، التعادل).","ماصّ للحرارة: حرارة الوسط ↓، ΔH موجب (+)، النواتج أعلى المتفاعلات (التمثيل الضوئي، الكمادة الباردة).","ΔH = طاقة كسر الروابط (ماص) − طاقة تكوين الروابط (طارد) | الحفّاز يخفض Ea ولا يغيّر ΔH."],"exercises":["قارن في جدول بين «التفاعل الطارد للحرارة» و«التفاعل الماصّ للحرارة» من حيث: تغيّر حرارة الوسط، إشارة ΔH، طاقة النواتج مقارنةً بالمتفاعلات، ومثال لكل منهما.","احسب ΔH لتفاعل تكوين الماء (2H₂ + O₂ → 2H₂O) علمًا بأن طاقات الروابط: H-H=436، O=O=498، O-H=464 kJ/mol، وحدّد هل التفاعل طارد أم ماص؟","فسّر لماذا يكون التفاعل الكيميائي طاردًا للحرارة بدلالة كسر الروابط وتكوينها."],"levels":{"easy":[{"type":"mcq","q":"أُضيفت مادة صلبة إلى ماء في كأس فانخفضت درجة الحرارة من ٢٥°C إلى ١٧°C. هذا التغير يُعدّ:","options":["ماصًّا للحرارة (Endothermic)","طاردًا للحرارة (Exothermic)","تفاعل احتراق","تفاعل تعادل"],"answer":0,"why":"انخفاض حرارة الوسط يعني امتصاص الطاقة من الماء."},{"type":"mcq","q":"أي العمليات الآتية يُعدّ مثالًا لتفاعل «طارد للحرارة»؟","options":["التحلل الحراري لكربونات الكالسيوم","الاحتراق وتفاعل التعادل بين حمض وقلوي","التمثيل الضوئي","الكمادة الباردة الفورية"],"answer":1,"why":"الاحتراق والتعادل يطلقان حرارةً للوسط المحيط."},{"type":"mcq","q":"في مخطط مستويات الطاقة لتفاعل «طارد للحرارة»، يكون مستوى طاقة النواتج:","options":["مساويًا للمتفاعلات تمامًا","أعلى من مستوى طاقة المتفاعلات","أقل من مستوى طاقة المتفاعلات (وΔH سالب)","لا يوجد فرق طاقة"],"answer":2,"why":"طاقة المتفاعلات تنخفض بإطلاق الطاقة للوسط فتكون النواتج أسفل."},{"type":"mcq","q":"عملية «كسر الروابط» في المتفاعلات وعملية «تكوين الروابط» في النواتج هما على الترتيب:","options":["كلاهما ماصّ للطاقة","طاردة للطاقة، ثم ماصّة للطاقة","كلاهما طارد للطاقة","ماصّة للطاقة، ثم طاردة للطاقة"],"answer":3,"why":"كسر الرابطة يحتاج طاقة (ماص)، وتكوينها يحرّر طاقة (طارد)."}],"medium":[{"type":"mcq","q":"في تفاعل ما، كانت طاقة كسر الروابط ٥٠٠ kJ، وطاقة تكوين الروابط ٦٥٠ kJ. ما قيمة ΔH ونوع التفاعل؟","options":["−١٥٠ kJ (طارد للحرارة)","+١٥٠ kJ (ماص للحرارة)","+١١٥٠ kJ (ماص)","−١١٥٠ kJ (طارد)"],"answer":0,"why":"ΔH = ٥٠٠ − ٦٥٠ = −١٥٠ kJ (سالب ← طارد للحرارة)."},{"type":"mcq","q":"ماذا يحدث لقيمة «ΔH» وقيمة «طاقة التنشيط Ea» عند إضافة عامل حفّاز للتفاعل؟","options":["تتغيّر ΔH وتبقى Ea ثابتة","تنخفض طاقة التنشيط Ea، بينما تبقى قيمة ΔH ثابتةً لا تتغيّر","تنخفض كلتاهما","ترتفع طاقة التنشيط"],"answer":1,"why":"الحفّاز يخفض قمة التنشيط فقط ولا يغير طاقة المتفاعلات أو النواتج."},{"type":"mcq","q":"لماذا نستخدم «كأس البوليسترين (الفوم)» بدلًا من كأس زجاجي عند قياس تغيّر الحرارة في المختبر؟","options":["لأنه يتفاعل مع الأحماض","لأنه موصل ممتاز للحرارة","لأنه عازل حراري يقلّل فقدان الحرارة إلى الهواء المحيط","لأنه شفاف فقط"],"answer":2,"why":"العزل الحراري يحافظ على دقة قياس ΔT."},{"type":"tfr","q":"في التفاعل الطارد للحرارة ترتفع درجة حرارة الوسط المحيط وتكون إشارة ΔH سالبة.","answer":true,"reasons":["لأن الطاقة تنتقل من النظام الكيميائي إلى الوسط المحيط","تنخفض حرارة الوسط","تكون إشارة ΔH موجبة"],"reason":0},{"type":"tfr","q":"كسر الروابط الكيميائية عملية طاردة للطاقة.","answer":false,"reasons":["نعم طاردة","بل كسر الروابط عملية «ماصّة» للطاقة، وتكوين الروابط عملية «طاردة» للطاقة","لا تحتاج طاقة"],"reason":1},{"type":"essay","q":"قارن في جدول بين «التفاعل الطارد للحرارة» و«التفاعل الماصّ للحرارة» من حيث: تغيّر حرارة الوسط، إشارة ΔH، طاقة النواتج مقارنةً بالمتفاعلات، ومثال لكل منهما.","model":"الطارد: ترتفع حرارة الوسط، ΔH سالب، النواتج أقل طاقة، مثل الاحتراق والتعادل. الماصّ: تنخفض حرارة الوسط، ΔH موجب، النواتج أعلى طاقة، مثل التمثيل الضوئي والكمادة الباردة."},{"type":"essay","q":"احسب ΔH لتفاعل تكوين الماء (2H₂ + O₂ → 2H₂O) علمًا بأن طاقات الروابط: H-H=436، O=O=498، O-H=464 kJ/mol، وحدّد هل التفاعل طارد أم ماص؟","model":"الكسر = 2(436) + 498 = 1370 kJ. التكوين = 4(464) = 1856 kJ. ΔH = 1370 − 1856 = −486 kJ (سالب ← طارد للحرارة جدًا)."}],"hard":[{"type":"mcq","q":"ما الناتج الوحيد لاحتراق غاز الهيدروجين (الوقود الأخضر) في الأكسجين؟","options":["ثاني أكسيد الكبريت","ثاني أكسيد الكربون","أول أكسيد الكربون","الماء النقي فقط (H₂O) دون أي غازات دفيئة"],"answer":3,"why":"2H₂ + O₂ → 2H₂O، مما يجعله وقودًا نظيفًا تمامًا."},{"type":"mcq","q":"أي التفاعلات الآتية «ماصّ للحرارة» (ΔH موجب)؟","options":["التحلل الحراري للحجر الجيري (CaCO₃ → CaO + CO₂) والتمثيل الضوئي","احتراق الميثان","صدأ الحديد","التنفس الهوائي"],"answer":0,"why":"التحلل الحراري والتمثيل الضوئي يمتصان طاقةً باستمرار."},{"type":"mcq","q":"في تفاعل ماصّ للحرارة تكون الطاقة اللازمة لكسر روابط المتفاعلات:","options":["أقل من الطاقة المنطلقة عند تكوين الروابط","أكبر من الطاقة المنطلقة عند تكوين روابط النواتج","مساوية للصفر","مساوية تمامًا لطاقة التكوين"],"answer":1,"why":"الكسر > التكوين ← صافي امتصاص طاقة (ΔH > 0)."},{"type":"mcq","q":"تعمل «الكمادة الباردة الفورية» المستخدمة في الملاعب الرياضية على مبدأ:","options":["تفاعل تعادل طارد","تفاعل احتراق","تفاعل أو ذوبان ماصّ للحرارة (مثل نترات الأمونيوم في الماء) يمتص الحرارة من الجلد","تسخين كهربائي"],"answer":2,"why":"يمتص الحرارة من الموضع المصاب فيبرده فورًا."},{"type":"tfr","q":"تُعدّ عملية التمثيل الضوئي في النباتات تفاعلًا ماصًّا للطاقة.","answer":true,"reasons":["تفاعل احتراق","تفاعل طارد للحرارة","لأنها تمتص طاقة الضوء لتحويل CO₂ والماء إلى جلوكوز"],"reason":2},{"type":"tfr","q":"إضافة عامل حفّاز تقلّل طاقة التنشيط Ea لكنها لا تغيّر مقدار تغيّر الطاقة ΔH بين المتفاعلات والنواتج.","answer":true,"reasons":["فمستوى المتفاعلات ومستوى النواتج يبقيان ثابتين تمامًا","تغيّر قيمة ΔH","ترفع طاقة التنشيط"],"reason":0},{"type":"tfr","q":"احتراق الهيدروجين يُعدّ وقودًا نظيفًا لأنه يُطلق طاقةً كبيرةً ولا يُنتج سوى الماء النقي.","answer":true,"reasons":["ينتج غاز CO₂ بكثرة","ولذلك تستثمر سلطنة عُمان بقوة في مشاريع الهيدروجين الأخضر","هو تفاعل ماص للحرارة"],"reason":1},{"type":"essay","q":"فسّر لماذا يكون التفاعل الكيميائي طاردًا للحرارة بدلالة كسر الروابط وتكوينها.","model":"لأن الطاقة المنطلقة عند تكوين الروابط الجديدة في النواتج أكبر من الطاقة الممتصة لكسر الروابط في المتفاعلات، فيُطلق الفرق كحرارة للوسط المحيط."},{"type":"essay","q":"اذكر ميزتين وتحديًا واحدًا لاستخدام «الهيدروجين» كوقود للسيارات ومحطات الطاقة.","model":"الميزتان: ١) يُطلق طاقة عالية جدًا لكل جرام. ٢) نظيف تمامًا ناتجه الماء فقط بلا CO₂. التحدي: صعوبة وتكلفة تخزينه ونقله بأمان لأنه غاز شديد الاشتعال."},{"type":"essay","q":"صف كيف يظهر تأثير «العامل الحفّاز» على مخطط مستويات الطاقة لتفاعل طارد للحرارة.","model":"يبقى مستوى المتفاعلات (أعلى) ومستوى النواتج (أسفل) وفرق الطاقة ΔH ثابتة، لكن المنحنى الجديد مع الحفّاز يكون ذا «قمة أخفض» تمثّل طاقة تنشيط أقل."}]}},
  {"id":"g9-chem-2-u6-1","grade":"g9","subject":"chemistry","term":2,"unit":6,"no":1,"title":"الأحماض والقواعد والقلويات","summary":"شرح متحرك بـ SVG لخصائص الأحماض والقواعد والقلويات وأيونات H⁺ و OH⁻ وتفاعل التعادل، ثم أنشطة بثلاثة مستويات.","page":"lesson-acids-bases-and-alkalis.html","video":"","pdf":"","notes":["الحمض مادة تُنتج أيونات H⁺ عند ذوبانها في الماء (مثل HCl, H₂SO₄, HNO₃، وحمض الستريك في الليمون).","القاعدة مادة تتفاعل مع الحمض لتكوّن ملحًا وماءً؛ والقلوي هو قاعدة تذوب في الماء وتُنتج أيونات OH⁻ (مثل NaOH, KOH).","كل قلوي قاعدة، وليس كل قاعدة قلويًا (أكسيد النحاس قاعدة غير ذائبة).","تفاعل التعادل: حمض + قاعدة ← ملح + ماء، والمعادلة الأيونية: H⁺ + OH⁻ → H₂O.","الحمض القوي يتأين كليًا في الماء، والضعيف يتأين جزئيًا فقط."],"exercises":["فسّر سبب استخدام أقراص هيدروكسيد المغنيسيوم لعلاج حموضة المعدة.","صنّف المواد الآتية إلى أحماض وقلويات وقواعد غير ذائبة: HCl، NaOH، CuO، عصير الليمون.","اكتب المعادلة الأيونية العامة لتفاعل التعادل."],"levels":{"easy":[{"type":"mcq","q":"الأيون الذي تنتجه الأحماض عند ذوبانها في الماء هو:","options":["H⁺","OH⁻","Cl⁻","Na⁺"],"answer":0,"why":"تتميز المحاليل الحمضية بوجود أيونات الهيدروجين H⁺."},{"type":"mcq","q":"الأيون الذي تنتجه القلويات عند ذوبانها في الماء هو:","options":["H⁺","OH⁻","O²⁻","SO₄²⁻"],"answer":1,"why":"تطلق القلويات أيونات الهيدروكسيد OH⁻ في الماء."},{"type":"mcq","q":"يُسمّى التفاعل بين الحمض والقاعدة لتكوين ملح وماء:","options":["التبخر","الاحتراق","التعادل","الانصهار"],"answer":2,"why":"التعادل هو تفاعل حمض مع قاعدة لإنتاج ملح وماء."},{"type":"mcq","q":"أي المواد الآتية يُعد حمضًا مخبريًا قويًا؟","options":["كلوريد الصوديوم","هيدروكسيد الصوديوم NaOH","الماء المقطّر","حمض الهيدروكلوريك HCl"],"answer":3,"why":"HCl حمض معدني قوي يتأين كليًا في الماء."}],"medium":[{"type":"mcq","q":"أي العبارات الآتية صحيحة تمامًا؟","options":["كل قلوي هو قاعدة، ولكن ليست كل قاعدة قلويًا","كل قاعدة هي قلوي","القلويات لا تذوب في الماء","الأحماض تطلق أيونات OH⁻"],"answer":0,"why":"القلويات هي القواعد القابلة للذوبان في الماء فقط."},{"type":"mcq","q":"يُعد أكسيد النحاس (CuO) قاعدةً وليس قلويًا لأنه:","options":["يذوب في الماء ويعطي H⁺","يتفاعل مع الحمض لكنه لا يذوب في الماء","لا يتفاعل مع الأحماض","مادة غازية"],"answer":1,"why":"القاعدة التي لا تذوب في الماء لا تُسمّى قلويًا."},{"type":"mcq","q":"الفرق الأساسي بين الحمض القوي والحمض الضعيف هو:","options":["الكتلة المولية فقط","اللون فقط","مدى التأين في الماء (كلي في القوي وجزئي في الضعيف)","درجة الغليان"],"answer":2,"why":"الحمض القوي يتأين بالكامل بينما الضعيف يتأين جزئيًا."},{"type":"tfr","q":"يمكن تذوّق الأحماض المخبرية للتحقق من طعمها الحامض.","answer":false,"reasons":["لأنها مواد آكلة وخطيرة قد تسبب حروقًا شديدة، ونفحصها بالكواشف لا بالتذوق","لأنها بلا طعم","لأنها تتحول إلى ماء فورًا"],"reason":0},{"type":"tfr","q":"المعادلة الأيونية الصافية لأي تفاعل تعادل بين حمض قوي وقلوي قوي هي H⁺ + OH⁻ → H₂O.","answer":true,"reasons":["لأن الملح يختفي","لأن أيونات H⁺ من الحمض تتحد مع OH⁻ من القلوي لتكوين جزيئات ماء متعادلة","لأن الماء حمض قوي"],"reason":1},{"type":"essay","q":"قارن بين القاعدة والقلوي مع ذكر مثال واحد لكل منهما.","model":"القاعدة مادة تتفاعل مع الحمض لإنتاج ملح وماء (مثل أكسيد النحاس CuO الذي لا يذوب في الماء). القلوي قاعدة تذوب في الماء وتطلق أيونات OH⁻ (مثل هيدروكسيد الصوديوم NaOH)."},{"type":"essay","q":"اذكر تطبيقين من حياتك اليومية لتفاعل التعادل.","model":"١) استخدام معجون الأسنان القلوي لمعادلة الأحماض في الفم وحماية الأسنان. ٢) تناول مضادات الحموضة القاعدية لمعادلة حمض الهيدروكلوريك الزائد في المعدة."}],"hard":[{"type":"mcq","q":"يحتوي محلول حمض الإيثانويك (الخل) على أيونات H⁺ أقل من محلول HCl بنفس التركيز لأن:","options":["الخل لا يحتوي هيدروجين","الخل قاعدة وليس حمضًا","HCl لا يتأين في الماء","حمض الإيثانويك حمض ضعيف يتأين جزئيًا فقط"],"answer":3,"why":"التأين الجزئي للحمض الضعيف ينتج تركيزًا أقل من أيونات H⁺."},{"type":"mcq","q":"يضيف المزارعون أحيانًا الجير المطفأ Ca(OH)₂ إلى تربة مزرعة حمضية بهدف:","options":["معادلة الحموضة الزائدة ورفع pH التربة لنمو أفضل للنباتات","زيادة حموضة التربة","منع امتصاص الماء","قتل الجذور"],"answer":0,"why":"Ca(OH)₂ قلوي يعادل الأحماض في التربة."},{"type":"mcq","q":"عند تخفيف حمض الكبريتيك المركّز بالماء في المختبر، الإجراء الآمن هو:","options":["إضافة الماء دفعة واحدة إلى الحمض المركّز","إضافة الحمض ببطء إلى الماء مع التحريك","تسخين الحمض أولًا","خلطه باليد"],"answer":1,"why":"إضافة الحمض للماء تشتّت الحرارة المتولدة وتمنع تطاير رذاذ الحمض."},{"type":"mcq","q":"أي من المواد الآتية يُعد قلويًا ضعيفًا؟","options":["هيدروكسيد البوتاسيوم (KOH)","هيدروكسيد الصوديوم (NaOH)","محلول الأمونيا (NH₃)","حمض النيتريك (HNO₃)"],"answer":2,"why":"الأمونيا تتأين جزئيًا في الماء فتُعد قلويًا ضعيفًا."},{"type":"tfr","q":"يمكن أن يكون لدينا محلول مخفّف من حمض قوي، ومحلول مركّز من حمض ضعيف.","answer":true,"reasons":["لأن الحمض القوي لا يُخفّف","لأن القوة والتركيز نفس المفهوم","لأن القوة تعتمد على نسبة التأين بينما التركيز يعتمد على كمية المذاب في حجم الماء"],"reason":2},{"type":"tfr","q":"محلول هيدروكسيد الكالسيوم (ماء الجير) يُعد قلويًا لأنه يذوب قليلًا في الماء ويطلق OH⁻.","answer":true,"reasons":["ذوبانه الجزئي في الماء ينتج محلولًا قلويًا يحتوي على أيونات OH⁻","لأنه حمض قوي","لأنه لا يتفاعل مع الأحماض"],"reason":0},{"type":"tfr","q":"عند لسعة نحلة (إفراز حمضي)، يُفضّل وضع خل (حمض) لتخفيف الألم.","answer":false,"reasons":["لأن لسعة النحلة قلوية","لأن الخل حمض يزيد الحموضة؛ يُفضّل وضع مادة قلوية لطيفة مثل صودا الخبز لمعادلة الحمض","لأن الخل قلوي"],"reason":1},{"type":"essay","q":"ميّز بوضوح بين «حمض قوي مخفّف» و«حمض ضعيف مركّز» من حيث الجسيمات في المحلول.","model":"الحمض القوي المخفّف فيه عدد قليل من جزيئات الحمض لكل لتر لكنها جميعًا متأينة كليًا إلى أيونات H⁺. أما الحمض الضعيف المركّز ففيه جزيئات كثيرة لكل لتر لكن نسبة صغيرة منها فقط تتأين إلى H⁺."},{"type":"essay","q":"فسّر لماذا ينصح الأطباء بعدم تنظيف الأسنان بالفرشاة فور شرب عصير ليمون حامض، والاكتفاء بالمضمضة بالماء أولًا.","model":"لأن الحمض يُضعف طبقة المينا مؤقتًا، والمضمضة بالماء تخفّف الحمض وتزيله قبل التفريش بالمعجون القلوي الذي يعادل ما تبقى."},{"type":"essay","q":"اكتب المعادلة اللفظية والرمزية لتفاعل تعادل حمض الهيدروكلوريك مع هيدروكسيد الصوديوم.","model":"اللفظية: حمض الهيدروكلوريك + هيدروكسيد الصوديوم → كلوريد الصوديوم + ماء. الرمزية: HCl + NaOH → NaCl + H₂O."}]}},
  {"id":"g9-chem-2-u6-2","grade":"g9","subject":"chemistry","term":2,"unit":6,"no":2,"title":"الكواشف والرقم الهيدروجيني pH","summary":"شرح متحرك بـ SVG لمقياس pH من ٠ إلى ١٤ والكاشف العام وتباع الشمس والميثيل البرتقالي والفينولفثالين، ثم أنشطة بثلاثة مستويات.","page":"lesson-indicators-and-ph.html","video":"","pdf":"","notes":["الكاشف مادة يتغيّر لونها في الوسط الحمضي عنه في الوسط القلوي.","تباع الشمس: أحمر في الحمض، أزرق في القلوي. الميثيل البرتقالي: أحمر في الحمض، أصفر في القلوي. الفينولفثالين: عديم اللون في الحمض، وردي في القلوي.","مقياس pH: من 0 إلى 6 حمضي (الأقوى قرب 0)، 7 متعادل، من 8 إلى 14 قلوي (الأقوى قرب 14).","الكاشف العام يعطي تدرج ألوان (أحمر ← أصفر ← أخضر عند 7 ← أزرق ← بنفسجي عند 14).","جهاز قياس pH الرقمي أدق من الكاشف العام ويصلح للمحاليل الملونة."],"exercises":["لديك أربعة محاليل قيم pH لها: 2، 6، 7، 13. صنّفها إلى حمض قوي، حمض ضعيف، متعادل، وقلوي قوي.","ماذا يحدث للون ورقة تباع الشمس الحمراء عند غمسها في: (أ) خل، (ب) ماء مقطر، (ج) محلول صابون؟","اذكر ميزتين لجهاز قياس pH الرقمي مقارنةً بورق الكاشف العام."],"levels":{"easy":[{"type":"mcq","q":"قيمة pH للماء المقطّر النقي (المتعادل) تساوي:","options":["1","7","14","0"],"answer":1,"why":"الوسط المتعادل قيمته pH = 7."},{"type":"mcq","q":"يُحوّل المحلول الحمضي لون ورقة تباع الشمس الزرقاء إلى:","options":["البنفسجي","الأخضر","الأحمر","الأصفر"],"answer":2,"why":"الأحماض تحوّل تباع الشمس الأزرق إلى أحمر."},{"type":"mcq","q":"لون الكاشف العام في محلول قلوي قوي (pH = 14) هو:","options":["الأصفر","الأحمر","الأخضر","البنفسجي"],"answer":3,"why":"القلويات القوية تعطي لونًا بنفسجيًا داكنًا مع الكاشف العام."},{"type":"mcq","q":"أي قيم pH الآتية تمثّل حمضًا ضعيفًا؟","options":["pH = 5","pH = 1","pH = 7","pH = 12"],"answer":0,"why":"الأحماض الضعيفة تقع عادةً بين pH 4 و 6."}],"medium":[{"type":"mcq","q":"ما لون كاشف الميثيل البرتقالي في الحمض وفي القلوي على الترتيب؟","options":["أزرق في الحمض، وأحمر في القلوي","أحمر في الحمض، وأصفر في القلوي","أخضر في الحمض، ووردي في القلوي","عديم اللون في كليهما"],"answer":1,"why":"الميثيل البرتقالي أحمر في الحمض وأصفر في القلوي."},{"type":"mcq","q":"محلول X يُبقي الفينولفثالين عديم اللون ويحوّل تباع الشمس الأزرق إلى أحمر. إذن X هو:","options":["قلوي ضعيف","قلوي قوي","حمض","ماء نقي"],"answer":2,"why":"تحويل الأزرق لأحمر يثبت أنه حمض، والفينولفثالين عديم اللون في الحمض."},{"type":"mcq","q":"أي الكواشف الآتية لا يميّز بين الحمض القوي والحمض الضعيف؟","options":["شرائط pH متعددة الألوان","الكاشف العام","جهاز قياس pH الرقمي","ورق تباع الشمس"],"answer":3,"why":"تباع الشمس يعطي لونًا أحمر واحدًا لكل الأحماض دون تفريق في القوة."},{"type":"tfr","q":"كلما زادت قيمة pH فوق 7، زادت قوة المحلول القلوي.","answer":true,"reasons":["لأن القلويات تقع تحت 7","لأن القلوية تزداد من 8 (قلوي ضعيف) حتى 14 (قلوي قوي جدًّا)","لأن 14 يعني متعادلًا"],"reason":1},{"type":"tfr","q":"لا يتغيّر لون ورقة تباع الشمس الحمراء عند وضعها في محلول حمضي.","answer":true,"reasons":["لأنه يتحول إلى أخضر","لأنه يتحول إلى أزرق","لأن تباع الشمس في الحمض يكون أحمر أصلًا، فيبقى أحمر دون تغير"],"reason":2},{"type":"essay","q":"رتّب المحاليل التالية من الأكثر حموضة إلى الأكثر قلوية: حليب (6.5)، ليمون (2)، منظف أفران (13)، ماء بحر (8)، ماء نقي (7).","model":"ليمون (2) ← حليب (6.5) ← ماء نقي (7) ← ماء بحر (8) ← منظف أفران (13)."},{"type":"essay","q":"لماذا لا يكفي استخدام ورقة تباع شمس حمراء وحدها للتأكد أن محلولًا ما هو «حمض»؟","model":"لأن الورقة الحمراء تبقى حمراء في الحمض وفي المحلول المتعادل أيضًا! لذا يلزم اختبار الورقة الزرقاء كذلك (تتحول للأحمر في الحمض فقط)."}],"hard":[{"type":"mcq","q":"أُضيف محلول هيدروكسيد الصوديوم تدريجيًا إلى حمض HCl يحتوي كاشفًا عامًا حتى تغيّر اللون إلى الأخضر. هذا يعني أن:","options":["التعادل اكتمل وأصبح pH = 7","المحلول ما زال حمضًا قويًا","القلوي زاد بكثرة","الحمض تبخر"],"answer":0,"why":"اللون الأخضر في الكاشف العام يدل على نقطة التعادل (pH = 7)."},{"type":"mcq","q":"مزارع فحص تربة حقل فوجد pH = 5.5، والمحصول يحتاج تربة متعادلة (7). ماذا عليه أن يضيف؟","options":["حمض الكبريتيك","مادة قاعدية مثل الجير (أكسيد أو هيدروكسيد الكالسيوم)","الخل","ماءً حامضيًا"],"answer":1,"why":"التربة حمضية وتحتاج قاعدة لرفع pH نحو 7."},{"type":"mcq","q":"إذا خفّفنا حمضًا قويًا (pH = 1) بإضافة كمية كبيرة من الماء المقطر، فإن قيمة pH للمحلول:","options":["ترتفع فوق 10","تنخفض إلى 0","ترتفع تدريجيًا نحو 7 لكنها تبقى أقل من 7","تبقى ثابتة عند 1"],"answer":2,"why":"التخفيف يقلل تركيز H⁺ فيرتفع pH نحو 7 دون أن يصبح قلويًا."},{"type":"mcq","q":"في محلول ملحي متعادل (NaCl)، ما لون كل من الفينولفثالين والكاشف العام على الترتيب؟","options":["أزرق، أصفر","وردي، أحمر","أصفر، بنفسجي","عديم اللون، أخضر"],"answer":3,"why":"عند pH = 7 يكون الفينولفثالين عديم اللون والكاشف العام أخضر."},{"type":"tfr","q":"يمكن لمحلول حمض قوي أن يكون له pH = 12 إذا كان مركّزًا جدًّا.","answer":false,"reasons":["لأن جميع الأحماض (مهما كان تركيزها) قيمتها أقل من 7، بينما 12 قلوي قوي","لأن الأحماض القوية لها pH = 14","لأن التركيز يحول الحمض لقلوي"],"reason":0},{"type":"tfr","q":"يحتوي الكاشف العام على خليط من عدة كواشف تتغير ألوانها عند قيم pH مختلفة.","answer":true,"reasons":["لأنه مادة نقية واحدة فقط","وهذا ما يجعله يعطي طيفًا كاملًا من الألوان من الأحمر (1) حتى البنفسجي (14)","لأنه يعطي لونين فقط"],"reason":1},{"type":"tfr","q":"يزداد تركيز أيونات H⁺ كلما انخفضت قيمة pH في المحلول.","answer":true,"reasons":["لأن pH لا يرتبط بأيونات H⁺","لأن H⁺ يزداد عند pH = 14","لأن مقياس pH عكسي لتركيز H⁺، فـ pH = 1 أكثر حموضة بكثير من pH = 4"],"reason":2},{"type":"essay","q":"صمّم تجربةً سريعةً للتمييز بين ثلاث زجاجات غير مُعنونة تحتوي على: ماء نقي، حمض HCl، ومحلول NaOH باستخدام ورق تباع الشمس فقط.","model":"نغمس ورقتي تباع شمس (حمراء وزرقاء) في عينة من كل زجاجة: الزجاجة التي تحوّل الزرقاء لأحمر هي HCl، والتي تحوّل الحمراء لأزرق هي NaOH، والتي لا تغيّر لون أي منهما هي الماء النقي."},{"type":"essay","q":"قارن بين الكاشف العام وجهاز قياس pH الرقمي من حيث الدقة والتكلفة والاستخدام مع المحاليل الملونة.","model":"الكاشف العام رخيص وسهل الاستخدام لكنه يعطي قيمة تقريبية تعتمد على العين ولا يصلح للمحاليل الملونة. جهاز pH الرقمي أغلى ويحتاج معايرة، لكنه يعطي قراءة رقمية دقيقة (مثل 4.25) ويعمل مع المحاليل الملونة."},{"type":"essay","q":"فسّر لماذا ينخفض pH محلول قلوي (pH = 13) عند إضافة الماء المقطر إليه، لكنه لا يصل أبدًا إلى أقل من 7.","model":"إضافة الماء تقلل تركيز أيونات OH⁻ فيقل pH مقتربًا من 7 (الماء المتعادل)، ولا يمكن أن يصبح حمضيًا (< 7) لأننا لم نضف أي حمض."}]}},
  {"id":"g9-chem-2-u6-3","grade":"g9","subject":"chemistry","term":2,"unit":6,"no":3,"title":"تحديد الأحماض والقواعد","summary":"شرح متحرك بـ SVG لتفاعلات الأحماض المميّزة (مع الفلزات والكربونات والقواعد) وتفاعل القواعد مع أملاح الأمونيوم، ثم أنشطة بثلاثة مستويات.","page":"lesson-identifying-acids-and-bases.html","video":"","pdf":"","notes":["حمض + فلز نشط ← ملح + هيدروجين (H₂ يشتعل بفرقعة). النحاس لا يتفاعل مع الأحماض المخففة.","حمض + كربونات الفلز ← ملح + ماء + ثاني أكسيد الكربون (CO₂ يعكّر ماء الجير).","حمض + قاعدة (أكسيد أو هيدروكسيد) ← ملح + ماء (تفاعل تعادل بلا غاز).","قاعدة + ملح أمونيوم (بالتسخين) ← ملح + ماء + غاز الأمونيا (NH₃ يحوّل تباع الشمس الحمراء الرطبة إلى زرقاء).","تسمية الأملاح: HCl → كلوريد، H₂SO₄ → كبريتات، HNO₃ → نترات."],"exercises":["أكمل المعادلات اللفظية: (أ) خارصين + حمض الكبريتيك ← ...، (ب) كربونات النحاس + حمض النيتريك ← ...","علّل: لا يُنصح بإضافة الجير (CaO) إلى التربة في نفس وقت إضافة سماد نترات الأمونيوم.","كيف تميّز عمليًا بين غازي H₂ و CO₂؟"],"levels":{"easy":[{"type":"mcq","q":"الغاز المتصاعد عند تفاعل الخارصين مع حمض الهيدروكلوريك المخفف هو:","options":["ثاني أكسيد الكربون CO₂","الأكسجين O₂","الهيدروجين H₂","الأمونيا NH₃"],"answer":2,"why":"الفلزات النشطة تطرد الهيدروجين من الأحماض المخففة."},{"type":"mcq","q":"يتعكّر ماء الجير الرائق عند إمرار غاز:","options":["النيتروجين N₂","الهيدروجين H₂","الأمونيا NH₃","ثاني أكسيد الكربون CO₂"],"answer":3,"why":"تفاعل CO₂ مع ماء الجير يُكوّن كربونات كالسيوم بيضاء غير ذائبة."},{"type":"mcq","q":"يُنتج حمض النيتريك (HNO₃) عند تفاعله مع القواعد أملاح:","options":["النترات","الكبريتات","الكلوريدات","الكربونات"],"answer":0,"why":"الأملاح المشتقة من حمض النيتريك تُسمّى النترات."},{"type":"mcq","q":"عند تسخين قاعدة مع ملح أمونيوم يتصاعد غاز:","options":["الهيدروجين H₂","الأمونيا NH₃","ثاني أكسيد الكربون CO₂","الكلور Cl₂"],"answer":1,"why":"القواعد تطرد غاز الأمونيا القلوي من أملاح الأمونيوم."}],"medium":[{"type":"mcq","q":"أي الفلزات الآتية لا يتفاعل مع حمض الهيدروكلوريك المخفف لإنتاج الهيدروجين؟","options":["الخارصين","المغنيسيوم","النحاس","الحديد"],"answer":2,"why":"النحاس أقل نشاطًا من الهيدروجين فلا يحل محله في الحمض المخفف."},{"type":"mcq","q":"للكشف عن غاز الأمونيا المتصاعد نستخدم ورقة تباع شمس:","options":["لا يتغير لونها","زرقاء جافة فتتحوّل إلى حمراء","بيضاء فتتحول إلى سوداء","حمراء رطبة فتتحوّل إلى زرقاء"],"answer":3,"why":"يجب أن تكون الورقة رطبة ليذوب غاز الأمونيا فيها ويكوّن محلولًا قلويًا يزرّقها."},{"type":"mcq","q":"النواتج الكاملة لتفاعل كربونات الكالسيوم مع حمض الهيدروكلوريك هي:","options":["كلوريد الكالسيوم + ماء + ثاني أكسيد الكربون","كلوريد الكالسيوم + هيدروجين","كبريتات الكالسيوم + ماء","كالسيوم + كلور"],"answer":0,"why":"حمض + كربونات ← ملح + ماء + CO₂."},{"type":"tfr","q":"يتصاعد غاز الهيدروجين عند تفاعل حمض الهيدروكلوريك مع هيدروكسيد الصوديوم.","answer":false,"reasons":["لأن CO₂ هو الذي يتصاعد","لأن الصوديوم يتبخر","لأن تفاعل الحمض مع القلوي ينتج ملحًا وماءً فقط دون أي غاز"],"reason":2},{"type":"tfr","q":"تُستخدم كربونات الكالسيوم أحيانًا لمعادلة حموضة البحيرات المتأثرة بالمطر الحمضي.","answer":true,"reasons":["لأن الكربونات تتفاعل مع الأحماض وتُعادلها فتُرفع قيمة pH الماء","لأن الكربونات حمض قوي","لأنها تزيد الحموضة"],"reason":0},{"type":"essay","q":"اكتب المعادلة اللفظية لتفاعل: (أ) أكسيد المغنيسيوم + حمض النيتريك، (ب) هيدروكسيد الكالسيوم + كلوريد الأمونيوم.","model":"أ) أكسيد المغنيسيوم + حمض النيتريك → نترات المغنيسيوم + ماء. ب) هيدروكسيد الكالسيوم + كلوريد الأمونيوم → كلوريد الكالسيوم + ماء + أمونيا."},{"type":"essay","q":"فسّر لماذا يجب ترطيب ورقة تباع الشمس الحمراء بالماء عند اختبار غاز الأمونيا.","model":"لأن الأمونيا تظهر صفتها القلوية (إطلاق أيونات OH⁻) فقط عند ذوبانها في الماء الموجود على الورقة الرطبة."}],"hard":[{"type":"mcq","q":"خلط مزارع الجير المطفأ Ca(OH)₂ مع سماد كبريتات الأمونيوم في التربة. ما الأثر السلبي الناتج؟","options":["تتجمد التربة","يتفاعلان وينطلق غاز الأمونيا فيفقد السماد عنصر النيتروجين اللازم للنبات","ينطلق غاز الأكسجين","يزداد النيتروجين في التربة"],"answer":1,"why":"القاعدة تطرد غاز NH₃ من ملح الأمونيوم فيتطاير النيتروجين للهواء."},{"type":"mcq","q":"أُضيف حمض مخفف إلى مسحوق أبيض فحدث فوران وتصاعد غاز عكّر ماء الجير، وتكوّن محلول عديم اللون. المسحوق الأبيض يُرجَّح أنه:","options":["فلز المغنيسيوم","أكسيد النحاس","كربونات فلز (مثل كربونات الكالسيوم أو الصوديوم)","كلوريد الصوديوم"],"answer":2,"why":"تصاعد CO₂ مع الحمض دليل قاطع على وجود الكربونات."},{"type":"mcq","q":"في تفاعل حمض الكبريتيك مع كربونات النحاس الخضراء، الملح المتكوّن يكون لونه:","options":["أصفر","أحمر","أسود","أزرق (كبريتات النحاس)"],"answer":3,"why":"محلول كبريتات النحاس (II) يتميّز بلونه الأزرق الجميل."},{"type":"mcq","q":"أي التفاعلات الآتية يُنتج ماءً فقط (إضافةً إلى الملح) دون أي غاز؟","options":["حمض الكبريتيك + أكسيد الخارصين","حمض الكبريتيك + الخارصين","حمض الكبريتيك + كربونات الخارصين","هيدروكسيد الصوديوم + كلوريد الأمونيوم"],"answer":0,"why":"حمض + أكسيد فلز ← ملح + ماء فقط."},{"type":"tfr","q":"يمكن التمييز بين مسحوق أكسيد المغنيسيوم ومسحوق كربونات المغنيسيوم بإضافة حمض HCl المخفف لكل منهما.","answer":true,"reasons":["لأنهما لا يتفاعلان مع الحمض","لأن كربونات المغنيسيوم تُحدث فورانًا وتطلق CO₂، بينما أكسيد المغنيسيوم يذوب مكونًا ملحًا وماءً بلا فوران","لأن الأكسيد يطلق الهيدروجين"],"reason":1},{"type":"tfr","q":"عند تفاعل المغنيسيوم مع حمض الهيدروكلوريك، تقل كتلة الوعاء المفتوح قليلًا مع مرور الوقت.","answer":true,"reasons":["لأن القانون لا يحفظ الكتلة","لأن المغنيسيوم يتبخر","بسبب هروب غاز الهيدروجين المتصاعد إلى الهواء المحيط"],"reason":2},{"type":"tfr","q":"يتفاعل حمض النيتريك مع هيدروكسيد البوتاسيوم لإنتاج كبريتات البوتاسيوم وماء.","answer":false,"reasons":["ينتج «نترات البوتاسيوم» وماء لأن الحمض هو حمض النيتريك وليس الكبريتيك","ينتج كلوريد البوتاسيوم","لا يحدث تفاعل"],"reason":0},{"type":"essay","q":"لديك ٣ مساحيق بيضاء: أكسيد الكالسيوم، كربونات الكالسيوم، وكلوريد الأمونيوم. كيف تميّز بينها باستخدام حمض HCl وقلوي NaOH؟","model":"نضيف حمض HCl لكل منها: الذي يُحدث فورانًا ويعكر ماء الجير هو كربونات الكالسيوم، والذي يذوب بحرارة بلا فوران هو أكسيد الكالسيوم. ثم نسخن الثالث مع NaOH فيتصاعد غاز الأمونيا الذي يزرق تباع الشمس الرطبة، وهو كلوريد الأمونيوم."},{"type":"essay","q":"قارن بين نواتج تفاعل حمض الكبريتيك المخفف مع كل من: الخارصين، أكسيد الخارصين، وكربونات الخارصين.","model":"مع الخارصين: كبريتات الخارصين + هيدروجين. مع أكسيد الخارصين: كبريتات الخارصين + ماء. مع كربونات الخارصين: كبريتات الخارصين + ماء + ثاني أكسيد الكربون."},{"type":"essay","q":"فسّر لماذا ينصح الكيميائيون بعدم تنظيف الرخام (كربونات الكالسيوم) بمنظفات تحتوي على أحماض قوية.","model":"لأن الحمض يتفاعل مع كربونات الكالسيوم في الرخام مكوّنًا ملحًا ذائبًا وماءً وغاز CO₂، مما يؤدي إلى تآكل سطح الرخام وفقدان لمعانه."}]}},
  {"id":"g9-chem-2-u6-4","grade":"g9","subject":"chemistry","term":2,"unit":6,"no":4,"title":"أكاسيد الفلزّات وأكاسيد اللافلزّات","summary":"شرح متحرك بـ SVG لتصنيف الأكاسيد إلى قاعدية وحمضية ومتعادلة ومتردّدة (أمفوتيرية) وعلاقتها بالمطر الحمضي، ثم أنشطة بثلاثة مستويات.","page":"lesson-metal-and-nonmetal-oxides.html","video":"","pdf":"","notes":["الأكاسيد القاعدية: أكاسيد الفلزات (مثل MgO, CaO, CuO, Na₂O)؛ تتفاعل مع الأحماض لإنتاج ملح وماء.","الأكاسيد الحمضية: أكاسيد اللافلزات (مثل CO₂, SO₂, NO₂)؛ تذوب في الماء مكونةً أحماضًا وتتفاعل مع القواعد.","الأكاسيد المتعادلة: لا تتفاعل مع الأحماض ولا القواعد (مثل H₂O, CO, NO).","الأكاسيد المتردّدة (الأمفوتيرية): تتفاعل مع كل من الأحماض والقواعد لإنتاج ملح وماء (مثل Al₂O₃, ZnO)."],"exercises":["صنّف الأكاسيد الآتية إلى قاعدية وحمضية ومتعادلة ومترددة: SO₂، CuO، CO، ZnO، CaO، Al₂O₃.","اشرح كيف تُعالج محطات الكهرباء غاز ثاني أكسيد الكبريت قبل انطلاقه للغلاف الجوي.","كيف تتحقق عمليًا من أن أكسيدًا مجهولًا هو أكسيد متردّد؟"],"levels":{"easy":[{"type":"mcq","q":"تُصنّف معظم أكاسيد الفلزات على أنها أكاسيد:","options":["غازية","حمضية","متعادلة","قاعدية"],"answer":3,"why":"أكاسيد الفلزات مثل MgO و CuO أكاسيد قاعدية."},{"type":"mcq","q":"تُصنّف معظم أكاسيد اللافلزات على أنها أكاسيد:","options":["حمضية","قاعدية","متردّدة","فلزية"],"answer":0,"why":"أكاسيد اللافلزات مثل CO₂ و SO₂ أكاسيد حمضية."},{"type":"mcq","q":"الأكسيد الذي يتفاعل مع كل من الأحماض والقواعد يُسمّى أكسيدًا:","options":["متعادلًا","متردّدًا (أمفوتيريًا)","حمضيًا فقط","قاعديًا فقط"],"answer":1,"why":"الأكاسيد المترددة تسلك سلوك الحمض مع القاعدة وسلوك القاعدة مع الحمض."},{"type":"mcq","q":"أي المواد الآتية مثال على أكسيد متعادل؟","options":["ثاني أكسيد الكبريت SO₂","أكسيد الكالسيوم CaO","الماء H₂O وأول أكسيد الكربون CO","أكسيد الخارصين ZnO"],"answer":2,"why":"H₂O و CO لا يتفاعلان مع الأحماض ولا القواعد."}],"medium":[{"type":"mcq","q":"أُذيب غاز أكسيد عنصر X في الماء فحوّل الكاشف العام إلى اللون الأحمر (pH = 2). العنصر X هو على الأرجح:","options":["فلز مثل النحاس","فلز مثل الصوديوم","فلز مثل المغنيسيوم","لافلز مثل الكبريت"],"answer":3,"why":"المحلول الحمضي ينتج عن أكاسيد اللافلزات مثل SO₂."},{"type":"mcq","q":"أي زوج من الأكاسيد الآتية كلاهما «متردّد» (أمفوتيري)؟","options":["Al₂O₃ و ZnO","CO₂ و SO₂","MgO و CaO","CO و NO"],"answer":0,"why":"أكسيد الألمنيوم وأكسيد الخارصين هما المثالان القياسيان للأكاسيد المترددة."},{"type":"mcq","q":"ما ناتج ذوبان أكسيد الكالسيوم (CaO) في الماء؟","options":["حمض الكبريتيك","هيدروكسيد الكالسيوم (محلول قلوي)","محلول حمضي","غاز الهيدروجين"],"answer":1,"why":"CaO + H₂O → Ca(OH)₂ وهو محلول قلوي."},{"type":"tfr","q":"ثاني أكسيد الكربون (CO₂) وأول أكسيد الكربون (CO) كلاهما أكاسيد حمضية.","answer":false,"reasons":["لأن CO₂ أكسيد حمضي، بينما CO أكسيد متعادل لا يتفاعل مع القواعد","لأنهما قاعديان","لأن CO₂ متعادل"],"reason":0},{"type":"tfr","q":"أكسيد النحاس (CuO) لا يذوب في الماء لكنه يُعد أكسيدًا قاعديًا.","answer":true,"reasons":["لأنه يحول تباع الشمس للأزرق فورًا في الماء","لأنه يتفاعل مع الأحماض ويعادلها مكونًا ملحًا وماءً","لأنه أكسيد لافلز"],"reason":1},{"type":"essay","q":"كيف تثبت مخبريًا أن أكسيد الخارصين (ZnO) أكسيد متردّد (أمفوتيري)؟","model":"نضيف عينة منه إلى حمض HCl المخفف فنلاحظ ذوبانه وتفاعله، ونضيف عينة أخرى منه إلى محلول قلوي NaOH فنلاحظ ذوبانه وتفاعله أيضًا؛ تفاعله مع كليهما يثبت أنه متردّد."},{"type":"essay","q":"قارن بين ناتج ذوبان MgO في الماء وناتج ذوبان SO₂ في الماء وتأثير كل منهما على الكاشف العام.","model":"MgO يعطي محلولًا قلويًا (هيدروكسيد المغنيسيوم) يحول الكاشف العام للأزرق. SO₂ يعطي محلولًا حمضيًا (حمض الكبريتوز) يحول الكاشف العام للأحمر/البرتقالي."}],"hard":[{"type":"mcq","q":"أكسيد صلب أبيض لا يذوب في الماء، لكنه يتفاعل ويذوب في كل من HCl و NaOH. هذا الأكسيد هو:","options":["ثاني أكسيد السيليكون SiO₂","أكسيد المغنيسيوم MgO","أكسيد الألمنيوم Al₂O₃","أكسيد الكالسيوم CaO"],"answer":2,"why":"التفاعل مع الحمض والقلوي معًا صفة الأكاسيد المترددة مثل Al₂O₃."},{"type":"mcq","q":"يُعد ثاني أكسيد السيليكون (SiO₂ — الرمل) أكسيدًا حمضيًا رغم أنه لا يذوب في الماء لأنه:","options":["مادة فلزية","يذوب في الماء ويعطي pH = 1","يتفاعل مع الأحماض بشدة","يتفاعل مع القلويات المنصهرة أو المركزة الساخنة مكونًا أملاح السيليكات وماءً"],"answer":3,"why":"تفاعله مع القواعد الساخنة يصنّفه ضمن الأكاسيد الحمضية."},{"type":"mcq","q":"في الجدول الدوري، بالانتقال من اليسار (الفلزات) إلى اليمين (اللافلزات) عبر الدورة الثالثة، تتغير طبيعة الأكاسيد من:","options":["قاعدية ← متردّدة ← حمضية","حمضية ← متردّدة ← قاعدية","متعادلة فقط","حمضية فقط"],"answer":0,"why":"مثال الدورة الثالثة: Na₂O و MgO (قاعدية) ← Al₂O₃ (متردّد) ← SiO₂ و SO₂ (حمضية)."},{"type":"mcq","q":"لتنقية غاز أول أكسيد الكربون (CO) الملوّث بغاز ثاني أكسيد الكربون (CO₂)، نمرّر الخليط في محلول:","options":["حمض الهيدروكلوريك","هيدروكسيد الصوديوم (NaOH) ليمتص CO₂ الحمضي ويمرّ CO المتعادل","الماء المثلّج فقط","ملح الطعام"],"answer":1,"why":"القلوي يتفاعل مع CO₂ الحمضي ويمتصه بينما لا يتفاعل مع CO المتعادل."},{"type":"tfr","q":"يتفاعل أكسيد الكالسيوم (القاعدي) مع ثاني أكسيد الكبريت (الحمضي) لإنتاج كبريتيت الكالسيوم.","answer":true,"reasons":["لإنتاج غاز الهيدروجين","لأنهما لا يتفاعلان أبدًا","لتقليل انبعاثات SO₂ المسببة للمطر الحمضي من مداخن محطات الطاقة"],"reason":2},{"type":"tfr","q":"أكسيد الصوديوم (Na₂O) يذوب في الماء بسهولة مكوّنًا محلولًا له pH = 2.","answer":false,"reasons":["لأنه أكسيد فلز قاعدي يكون محلول NaOH القلوي القوي وله pH ≈ 13–14","لأنه متعادل وله pH = 7","لأنه لا يذوب في الماء"],"reason":0},{"type":"tfr","q":"لا يُغيّر أول أكسيد الكربون (CO) لون ورقة تباع الشمس الرطبة (الحمراء أو الزرقاء).","answer":true,"reasons":["لأنه يزرق الورقة الحمراء","لأنه أكسيد متعادل ليس له خصائص حمضية أو قلوية","لأنه يحمر الورقة الزرقاء"],"reason":1},{"type":"essay","q":"اشرح التدرّج في طبيعة أكاسيد عناصر الدورة الثالثة (Na₂O, MgO, Al₂O₃, SO₂) مع التفسير.","model":"على اليسار تقع الفلزات القوية فتكون أكاسيدها قاعدية (Na₂O, MgO)، وفي الوسط يقع الألمنيوم فيكون أكسيده مترددًا (Al₂O₃)، وعلى اليمين تقع اللافلزات فتكون أكاسيدها حمضية (SO₂)."},{"type":"essay","q":"لماذا لا تتأثر جميع أكاسيد اللافلزات بالقواعد؟ أعطِ مثالين.","model":"لأن بعض أكاسيد اللافلزات «متعادلة» مثل أول أكسيد الكربون (CO) وأكسيد النيتروجين (NO) والماء (H₂O)، فهي لا تملك صفة حمضية ولا تتفاعل مع القواعد."},{"type":"essay","q":"توقّع ما يحدث عند إمرار خليط من غازي SO₂ و CO عبر محلول ماء الجير، مع التفسير.","model":"يمتص ماء الجير (القلوي) غاز SO₂ الحمضي بالتفاعل معه، بينما يخرج غاز CO المتعادل دون أن يتفاعل."}]}},
  {"id":"g9-chem-2-u7-1","grade":"g9","subject":"chemistry","term":2,"unit":7,"no":1,"title":"المعادلات الكيميائية","summary":"شرح متحرك بـ SVG للمعادلات اللفظية والرمزية ومبدأ حفظ الكتلة وموازنة المعادلات الكيميائية خطوة بخطوة، ثم أنشطة بثلاثة مستويات.","page":"lesson-chemical-equations.html","video":"","pdf":"","notes":["المعادلة اللفظية تُظهر أسماء المتفاعلات والنواتج، والمعادلة الرمزية الموزونة تستخدم الصيغ وتحقق قانون حفظ الكتلة.","قانون حفظ الكتلة: عدد ذرات كل عنصر في المتفاعلات يساوي عدده في النواتج.","عند الموازنة: نغيّر المعاملات أمام الصيغ فقط، ويُمنع تغيير الأرقام السفلية داخل الصيغة.","الجزيئات ثنائية الذرة: H₂, N₂, O₂, F₂, Cl₂, Br₂, I₂."],"exercises":["وازن المعادلات الآتية: (أ) Fe + Cl₂ → FeCl₃، (ب) Al + O₂ → Al₂O₃.","احسب عدد ذرات كل عنصر في 2Ca(OH)₂.","لماذا لا نكتب H₂ + O₂ → H₂O₂ لموازنة معادلة تكوين الماء؟"],"levels":{"easy":[{"type":"mcq","q":"المبدأ العلمي الذي يفرض موازنة المعادلات الكيميائية هو:","options":["قانون حفظ الكتلة","قانون التمدد الحراري","قانون الانعكاس","قانون الكثافة"],"answer":0,"why":"الذرات لا تفنى ولا تُستحدث، لذا تبقى الكتلة الكلية محفوظة."},{"type":"mcq","q":"ما المعامل الصحيح أمام Mg في المعادلة: ___ Mg + O₂ → 2MgO؟","options":["1","2","4","3"],"answer":1,"why":"لأن النواتج تحتوي 2 ذرة Mg."},{"type":"mcq","q":"كم ذرة أكسجين توجد في 2H₂SO₄؟","options":["6 ذرات","4 ذرات","8 ذرات","2 ذرة"],"answer":2,"why":"2 × 4 = 8 ذرات أكسجين."},{"type":"mcq","q":"أي الجزيئات الآتية يُكتب دائمًا ثنائي الذرة عند كونه عنصرًا حرًا؟","options":["الكربون C","الصوديوم Na","المغنيسيوم Mg","الأكسجين O₂"],"answer":3,"why":"الأكسجين غاز ثنائي الذرة O₂."}],"medium":[{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الحديد مع الأكسجين: Fe + O₂ → Fe₂O₃؟","options":["4Fe + 3O₂ → 2Fe₂O₃","2Fe + O₂ → Fe₂O₃","2Fe + 3O₂ → Fe₂O₃","Fe + O₂ → Fe₂O₃"],"answer":0,"why":"في الطرفين: 4 ذرات Fe و 6 ذرات O."},{"type":"mcq","q":"عند موازنة: Zn + ___ HCl → ZnCl₂ + H₂، ما المعامل المناسب أمام HCl؟","options":["1","2","3","4"],"answer":1,"why":"نحتاج 2 ذرة H و 2 ذرة Cl، إذن 2HCl."},{"type":"mcq","q":"كم عدد ذرات الهيدروجين في 3Ca(OH)₂؟","options":["3 ذرات","2 ذرة","6 ذرات","5 ذرات"],"answer":2,"why":"داخل القوس 2 ذرة H × المعامل 3 = 6 ذرات."},{"type":"tfr","q":"يجوز تغيير الصيغة الكيميائية لـ MgO إلى MgO₂ لتسهيل موازنة الأكسجين.","answer":false,"reasons":["لأن MgO₂ هو نفسه MgO","لأن تغيير الرقم السفلي يغيّر هوية المركب كيميائيًا؛ يجب تغيير المعاملات فقط","لأن الأكسجين لا يوازن بالمعاملات"],"reason":1},{"type":"tfr","q":"مجموع كتل المتفاعلات في إناء مغلق يساوي دائمًا مجموع كتل النواتج.","answer":true,"reasons":["لأن الكتلة تزداد بالتسخين","لأن الذرات تختفي","تحقيقًا لقانون حفظ الكتلة حيث يُعاد ترتيب الذرات نفسها دون فقد أو زيادة"],"reason":2},{"type":"essay","q":"وازن المعادلتين الآتيتين مع توضيح عدد الذرات في كل طرف: (أ) K + H₂O → KOH + H₂، (ب) Al + O₂ → Al₂O₃.","model":"أ) 2K + 2H₂O → 2KOH + H₂ (كل طرف: 2K, 4H, 2O). ب) 4Al + 3O₂ → 2Al₂O₃ (كل طرف: 4Al, 6O)."},{"type":"essay","q":"فسّر لماذا تزداد كتلة شريط مغنيسيوم عند حرقه في الهواء المفتوح رغم أن الكتلة محفوظة.","model":"لأن المغنيسيوم يتحد مع غاز الأكسجين من الهواء لتكوين أكسيد المغنيسيوم الصلب؛ وكتلة MgO تساوي بالضبط كتلة Mg + كتلة O₂ الممتص."}],"hard":[{"type":"mcq","q":"ما المعامل الصحيح أمام O₂ عند موازنة احتراق الإيثان: 2C₂H₆ + ___ O₂ → 4CO₂ + 6H₂O؟","options":["14","5","6","7"],"answer":3,"why":"في النواتج: (4×2) + 6 = 14 ذرة O، إذن نحتاج 7O₂."},{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الألمنيوم مع حمض الهيدروكلوريك: Al + HCl → AlCl₃ + H₂؟","options":["2Al + 6HCl → 2AlCl₃ + 3H₂","Al + 3HCl → AlCl₃ + H₂","2Al + 3HCl → 2AlCl₃ + 3H₂","Al + 6HCl → AlCl₃ + 3H₂"],"answer":0,"why":"في كل طرف: 2Al، 6H، 6Cl."},{"type":"mcq","q":"ما مجموع المعاملات الصحيحة (بأبسط نسبة) في المعادلة الموزونة: N₂ + H₂ → NH₃؟","options":["4","6 (1 + 3 + 2)","5","7"],"answer":1,"why":"المعادلة هي 1N₂ + 3H₂ → 2NH₃، ومجموع المعاملات = 1 + 3 + 2 = 6."},{"type":"mcq","q":"عند تسخين 10 g من كربونات الكالسيوم في إناء مفتوح، نتج 5.6 g من أكسيد الكالسيوم الصلب. ما كتلة غاز CO₂ المتصاعد؟","options":["5.6 g","15.6 g","4.4 g","10 g"],"answer":2,"why":"بحفظ الكتلة: 10 − 5.6 = 4.4 g من CO₂."},{"type":"tfr","q":"في المعادلة الموزونة: Fe₂O₃ + 3CO → 2Fe + 3CO₂، عدد ذرات الأكسجين في كل طرف هو 6.","answer":true,"reasons":["في اليسار: 3 + 3 = 6، وفي اليمين: 3 × 2 = 6 ذرات أكسجين","في اليسار 4 وفي اليمين 6","في كل طرف 3 ذرات"],"reason":0},{"type":"tfr","q":"تدل المعادلة اللفظية وحدها على النسبة العددية الدقيقة للذرات المتفاعلة.","answer":false,"reasons":["لأن اللفظية تحتوي معاملات","المعادلة اللفظية تذكر أسماء المواد فقط، بينما المعادلة الرمزية الموزونة هي التي تُظهر النسب الذرية","لأن الرمزية بلا أرقام"],"reason":1},{"type":"tfr","q":"إذا وُضعت كربونات الكالسيوم مع حمض داخل دورق مغلق ببالون على ميزان حساس، تبقى قراءة الميزان ثابتةً تقريبًا.","answer":true,"reasons":["لأن الغاز بلا كتلة","لأن التفاعل يتوقف","لأن الغاز المتصاعد يُحبس داخل البالون فلا تُفقد أي كتلة من النظام"],"reason":2},{"type":"essay","q":"وازن المعادلات الآتية: (أ) NaOH + H₂SO₄ → Na₂SO₄ + H₂O، (ب) CaCO₃ + HCl → CaCl₂ + H₂O + CO₂.","model":"أ) 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. ب) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂."},{"type":"essay","q":"لماذا يُفضّل الكيميائيون المعادلات الرمزية الموزونة على المعادلات اللفظية في المصانع والمختبرات؟","model":"لأنها عالمية ومختصرة، وتُظهر الصيغ الدقيقة والنسب المولية والكتلية اللازمة لحساب كميات المتفاعلات دون هدر."},{"type":"essay","q":"احسب كتلة أكسيد المغنيسيوم الناتجة عن تفاعل 2.4 g من المغنيسيوم تمامًا مع 1.6 g من الأكسجين.","model":"بحسب قانون حفظ الكتلة: كتلة MgO = 2.4 + 1.6 = 4.0 g."}]}},
  {"id":"g9-chem-2-u7-2","grade":"g9","subject":"chemistry","term":2,"unit":7,"no":2,"title":"المزيد عن المعادلات الكيميائيّة","summary":"شرح متحرك بـ SVG لرموز الحالة الفيزيائية (s, l, g, aq) وكتابة المعادلات الأيونية الصافية وحذف الأيونات المتفرّجة، ثم أنشطة بثلاثة مستويات.","page":"lesson-more-about-chemical-equations.html","video":"","pdf":"","notes":["رموز الحالة الفيزيائية: (s) صلب، (l) سائل نقي، (g) غاز، (aq) محلول مائي (مذاب في الماء).","الماء النقي يُكتب H₂O(l) دائمًا وليس (aq).","الأيونات المتفرّجة: أيونات توجد في المحلول دون أن تشارك أو تتغير في التفاعل.","خطوات المعادلة الأيونية الصافية: فكّك المحاليل (aq) فقط ← احذف الأيونات المتفرّجة ← تحقق من توازن الذرات والشحنات."],"exercises":["أضف رموز الحالة الفيزيائية للمعادلة: CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂.","اكتب المعادلة الأيونية الصافية لتفاعل: CuSO₄(aq) + 2NaOH(aq) → Cu(OH)₂(s) + Na₂SO₄(aq).","حدّد الأيونات المتفرّجة في تفاعل Mg(s) + CuSO₄(aq) → MgSO₄(aq) + Cu(s)."],"levels":{"easy":[{"type":"mcq","q":"الرمز (aq) في المعادلة الكيميائية يعني أن المادة:","options":["صلبة","مذابة في الماء (محلول مائي)","غازية","منصهرة بالتسخين"],"answer":1,"why":"aq اختصار لـ aqueous أي محلول مائي."},{"type":"mcq","q":"يُكتب الراسب الصلب المتكوّن في قاع الأنبوب برمز الحالة:","options":["(l)","(aq)","(s)","(g)"],"answer":2,"why":"الراسب مادة صلبة غير ذائبة فرمزها (s)."},{"type":"mcq","q":"تُسمّى الأيونات التي لا تتغيّر أثناء التفاعل الكيميائي:","options":["الجزيئات الثنائية","الأيونات النشطة","النواتج","الأيونات المتفرّجة"],"answer":3,"why":"الأيونات المتفرجة تبقى كما هي في الطرفين وتُحذف."},{"type":"mcq","q":"المعادلة الأيونية الصافية لجميع تفاعلات التعادل بين الأحماض القوية والقلويات القوية هي:","options":["H⁺(aq) + OH⁻(aq) → H₂O(l)","Na⁺ + Cl⁻ → NaCl","H₂ + O₂ → H₂O","H⁺ + Cl⁻ → HCl"],"answer":0,"why":"في التعادل يتحد H⁺ مع OH⁻ لتكوين H₂O(l)."}],"medium":[{"type":"mcq","q":"ما المعادلة الأيونية الصافية لتفاعل: BaCl₂(aq) + Na₂SO₄(aq) → BaSO₄(s) + 2NaCl(aq)؟","options":["Na⁺ + Cl⁻ → NaCl","Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s)","Ba + SO₄ → BaSO₄","2Na⁺ + SO₄²⁻ → Na₂SO₄"],"answer":1,"why":"تُحذف Na⁺ و Cl⁻ كأيونات متفرّجة ويبقى تكوّن الراسب BaSO₄(s)."},{"type":"mcq","q":"لماذا لا نحذف Zn(s) مع Zn²⁺(aq) في تفاعل الخارصين مع الحمض؟","options":["لأن Zn غاز","لأنهما متطابقان تمامًا","لأن Zn(s) ذرة متعادلة صلبة بينما Zn²⁺(aq) أيون موجب ذائب؛ فهما مختلفان","لأن الشحنات لا تهم"],"answer":2,"why":"الأيون المتفرّج يجب أن يتطابق في الشحنة والحالة في الطرفين."},{"type":"mcq","q":"في المعادلة: CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g)، ما الأيون المتفرّج الوحيد؟","options":["CO₃²⁻","Ca²⁺(aq)","H⁺(aq)","Cl⁻(aq)"],"answer":3,"why":"أيون Cl⁻ فقط بقي ذائبًا دون تغيير في الطرفين."},{"type":"tfr","q":"يُكتب رمز الحالة للماء الناتج عن تفاعل التعادل على الصورة H₂O(aq).","answer":false,"reasons":["لأن الماء صلب","لأن الماء غاز دائمًا","لأن الماء سائل نقي فيُكتب H₂O(l) وليس (aq)"],"reason":2},{"type":"tfr","q":"يجب أن يتساوى مجموع الشحنات الكهربائية في طرفي المعادلة الأيونية الموزونة.","answer":true,"reasons":["تمامًا كما يجب أن يتساوى عدد الذرات في الطرفين","لأن الشحنات لا تُوازن","لأن كل الأيونات موجبة"],"reason":0},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لتفاعل: Mg(s) + CuSO₄(aq) → MgSO₄(aq) + Cu(s) وحدّد الأيون المتفرّج.","model":"بتفكيك (aq): Mg(s) + Cu²⁺(aq) + SO₄²⁻(aq) → Mg²⁺(aq) + SO₄²⁻(aq) + Cu(s). الأيون المتفرّج: SO₄²⁻(aq). الصافية: Mg(s) + Cu²⁺(aq) → Mg²⁺(aq) + Cu(s)."},{"type":"essay","q":"ما الفرق بين NaCl(s) و NaCl(l) و NaCl(aq)؟","model":"NaCl(s) ملح طعام صلب، NaCl(l) ملح طعام منصهر بالتسخين الشديد، و NaCl(aq) ملح طعام مذاب في الماء (محلول مائي)."}],"hard":[{"type":"mcq","q":"ما المعادلة الأيونية الصافية لتفاعل محلول كبريتات النحاس(II) مع هيدروكسيد الصوديوم لإنتاج راسب Cu(OH)₂(s)؟","options":["Cu²⁺(aq) + 2OH⁻(aq) → Cu(OH)₂(s)","Cu⁺ + OH⁻ → CuOH","Na⁺ + SO₄²⁻ → Na₂SO₄","Cu(s) + 2OH⁻ → Cu(OH)₂"],"answer":0,"why":"أيون النحاس الثنائي يتحد مع أيوني هيدروكسيد مكونًا الراسب الأزرق."},{"type":"mcq","q":"ما مجموع الشحنات في كل طرف من المعادلة الأيونية: 2Al(s) + 6H⁺(aq) → 2Al³⁺(aq) + 3H₂(g)؟","options":["+3 في كل طرف","+6 في كل طرف","0 في كل طرف","+2 في كل طرف"],"answer":1,"why":"يسارًا: 6 × (+1) = +6. يمينًا: 2 × (+3) = +6."},{"type":"mcq","q":"في تفاعل إزاحة الهالوجين: Cl₂(aq) + 2KBr(aq) → 2KCl(aq) + Br₂(aq)، ما الأيون المتفرّج؟","options":["Br⁻(aq)","Cl⁻(aq)","K⁺(aq)","لا يوجد أيون متفرّج"],"answer":2,"why":"أيون البوتاسيوم K⁺ بقي ذائبًا دون تغير، بينما تحوّل Cl₂ إلى Cl⁻ و Br⁻ إلى Br₂."},{"type":"mcq","q":"أي المعادلات الأيونية الآتية غير موزونة شحنيًا؟","options":["Cu²⁺ + 2OH⁻ → Cu(OH)₂","Ag⁺ + Cl⁻ → AgCl","H⁺ + OH⁻ → H₂O","Fe³⁺ + OH⁻ → Fe(OH)₃"],"answer":3,"why":"في الأولى الشحنة يسارًا +2 ويمينًا 0؛ الصحيح Fe³⁺ + 3OH⁻ → Fe(OH)₃."},{"type":"tfr","q":"تُستخدم المعادلات الأيونية الصافية لتوضيح أن جميع تفاعلات الترسيب لنفس الراسب لها نفس التغيّر الكيميائي الأساسي.","answer":true,"reasons":["لأنها تخفي الراسب","فسواء استخدمنا NaCl أو KCl مع AgNO₃ فإن التفاعل الحقيقي هو دائمًا Ag⁺ + Cl⁻ → AgCl(s)","لأنها لا تحفظ الكتلة"],"reason":1},{"type":"tfr","q":"في المعادلة: CuO(s) + 2HCl(aq) → CuCl₂(aq) + H₂O(l)، يُفكّك CuO(s) إلى Cu²⁺ + O²⁻.","answer":false,"reasons":["لأن الماء يتفكك","لأن HCl لا يتفكك","لأن CuO(s) مادة صلبة غير ذائبة فلا تُفكّك في المعادلة الأيونية"],"reason":2},{"type":"tfr","q":"المعادلة الأيونية الصافية لتفاعل CuO(s) + 2HCl(aq) هي: CuO(s) + 2H⁺(aq) → Cu²⁺(aq) + H₂O(l).","answer":true,"reasons":["بحذف 2Cl⁻ المتفرّج من الطرفين تبقى هذه المعادلة الموزونة ذريًا وشحنيًا","لأن CuO يُحذف","لأن H⁺ متفرّج"],"reason":0},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لتفاعل: CaCO₃(s) + 2HCl(aq) → CaCl₂(aq) + H₂O(l) + CO₂(g).","model":"بتفكيك المحاليل المائية فقط: CaCO₃(s) + 2H⁺(aq) + 2Cl⁻(aq) → Ca²⁺(aq) + 2Cl⁻(aq) + H₂O(l) + CO₂(g). بحذف 2Cl⁻: CaCO₃(s) + 2H⁺(aq) → Ca²⁺(aq) + H₂O(l) + CO₂(g)."},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لتفاعل الكلور مع بروميد البوتاسيوم: Cl₂(aq) + 2KBr(aq) → 2KCl(aq) + Br₂(aq).","model":"بحذف 2K⁺(aq) المتفرّجة: Cl₂(aq) + 2Br⁻(aq) → 2Cl⁻(aq) + Br₂(aq)."},{"type":"essay","q":"فسّر لماذا يعطي تفاعل H₂SO₄ مع KOH نفس المعادلة الأيونية الصافية لتفاعل HNO₃ مع NaOH.","model":"لأن الكبريتات والنترات والصوديوم والبوتاسيوم كلها أيونات متفرّجة تُحذف، ويبقى التفاعل الفعلي في الحالتين هو H⁺(aq) + OH⁻(aq) → H₂O(l)."}]}},
  {"id":"g9-chem-2-u8-1","grade":"g9","subject":"chemistry","term":2,"unit":8,"no":1,"title":"تفاعُلات تكوين الأملاح","summary":"شرح متحرك بـ SVG لطرق تحضير الأملاح الذائبة (طريقة الفائض والترشيح، والمعايرة) والأملاح غير الذائبة (الترسيب)، ثم أنشطة بثلاثة مستويات.","page":"lesson-salt-formation-reactions.html","video":"","pdf":"","notes":["طريقة الفائض والترشيح: للأملاح الذائبة (مثل CuSO₄, MgCl₂) بإضافة فائض من فلز أو أكسيد أو كربونات للحمض ثم الترشيح والتبخير الجزئي والتبلور.","طريقة المعايرة: لأملاح الصوديوم والبوتاسيوم والأمونيوم الذائبة (حيث المتفاعلان ذائبان) باستخدام سحاحة وكاشف، ثم تكرار التجربة دون كاشف والتبلور.","طريقة الترسيب: للأملاح غير الذائبة (مثل BaSO₄, AgCl) بخلط محلولين ذائبين، ثم الترشيح والغسل بماء مقطر والتجفيف.","لا نستخدم الصوديوم أو البوتاسيوم مباشرة مع الأحماض لشدة خطورتهما."],"exercises":["اشرح بالخطوات كيف تحضّر بلورات نقية وجافة من كبريتات المغنيسيوم بدءًا من حمض الكبريتيك وكربونات المغنيسيوم.","علّل: نكرّر خطوة الخلط في المعايرة بدون إضافة الكاشف بعد معرفة الحجم الدقيق.","اقترح محلولين ذائبين لتحضير راسب يوديد الرصاص (PbI₂) واكتب خطوات تنقيته."],"levels":{"easy":[{"type":"mcq","q":"الطريقة المستخدمة لتحضير ملح غير ذائب في الماء هي:","options":["التقطير","المعايرة","الترسيب","الكروماتوجرافيا"],"answer":2,"why":"الأملاح غير الذائبة تُحضّر بخلط محلولين ذائبين لتكوين راسب."},{"type":"mcq","q":"لفصل فائض أكسيد النحاس الصلب عن محلول كبريتات النحاس نستخدم عملية:","options":["الانصهار","التقطير","المعايرة","الترشيح"],"answer":3,"why":"الترشيح يفصل المادة الصلبة غير الذائبة عن المحلول."},{"type":"mcq","q":"الأداة المخبرية المستخدمة لإضافة الحمض قطرةً قطرةً بدقة في المعايرة هي:","options":["السحّاحة (Burette)","المسطرة","الكأس العادي","المغناطيس"],"answer":0,"why":"السحاحة تقيس الحجوم المتغيرة بدقة عالية في المعايرة."},{"type":"mcq","q":"عند تحضير ملح كلوريد البوتاسيوم (KCl) من KOH و HCl نستخدم طريقة:","options":["الترسيب","المعايرة","التسامي","فائض فلز البوتاسيوم"],"answer":1,"why":"لأن KOH و HCl و KCl جميعها محاليل ذائبة."}],"medium":[{"type":"mcq","q":"لماذا يُسخّن حمض الكبريتيك برفق قبل إضافة أكسيد النحاس عند تحضير كبريتات النحاس؟","options":["لإذابة ورقة الترشيح","لتجميد الحمض","لزيادة سرعة التفاعل","لمنع تكون الملح"],"answer":2,"why":"التسخين يسرّع التفاعل بين الأكسيد الصلب والحمض."},{"type":"mcq","q":"بعد ترشيح راسب كبريتات الباريوم (BaSO₄)، الخطوتان التاليتان للحصول على عينة نقية وجافة هما:","options":["خلطه بالرمل","إذابته في ماء مغلي ثم ترشيحه","إضافة كاشف عام","غسله بماء مقطّر ثم تجفيفه بين ورقتي ترشيح أو في فرن دافئ"],"answer":3,"why":"الغسل يزيل المحلول العالق والتجفيف يزيل الماء."},{"type":"mcq","q":"أي زوج من المحاليل الذائبة يصلح لتحضير راسب كربونات الكالسيوم (CaCO₃)؟","options":["نترات الكالسيوم + كربونات الصوديوم","كبريتات الكالسيوم + ماء","أكسيد الكالسيوم + رمل","كلوريد الصوديوم + نترات البوتاسيوم"],"answer":0,"why":"نترات الكالسيوم توفر Ca²⁺ وكربونات الصوديوم توفر CO₃²⁻ وكلاهما ذائبان."},{"type":"tfr","q":"لا يمكن تحضير كبريتات النحاس بتفاعل فلز النحاس مباشرة مع حمض الكبريتيك المخفف.","answer":true,"reasons":["لأن النحاس لا يتفاعل مع الأحماض المخففة، لذا نستخدم أكسيد النحاس أو كربونات النحاس بدلًا منه","لأن النحاس ينفجر مع الحمض","لأن كبريتات النحاس غير ذائبة"],"reason":0},{"type":"tfr","q":"في طريقة المعايرة، نضيف الكاشف فقط لتحديد الحجم الدقيق اللازم للتعادل، ثم نعيد التجربة بدونه.","answer":true,"reasons":["لأن الكاشف يمنع التفاعل","حتى لا يلوّث الكاشف لون ونقاوة بلورات الملح الناتج","لأن الكاشف يذيب الزجاج"],"reason":1},{"type":"essay","q":"لماذا نُوقف تسخين محلول كبريتات النحاس عند «نقطة التبلور» ولا نبخّر الماء كله حتى الجفاف؟","model":"لأن التبريد البطيء من نقطة التبلور يُكوّن بلورات زرقاء منتظمة وكبيرة تحتفظ بماء تبلورها، بينما التسخين للجفاف قد يفقدها ماء التبلور ويحولها لمسحوق أبيض أو يفككها."},{"type":"essay","q":"صف باختصار خطوات تحضير ملح نترات البوتاسيوم (KNO₃) النقي من HNO₃ و KOH.","model":"نقيس حجمًا محددًا من KOH بالماصة ونضيف كاشفًا، ثم نعاير بـ HNO₃ من السحاحة حتى يتغير اللون ونسجل الحجم. نعيد الخلط بنفس الحجمين دون كاشف، ثم نبخّر جزئيًا ونتركه يتبلور ونجفف البلورات."}],"hard":[{"type":"mcq","q":"أضاف طالب فائضًا من كربونات المغنيسيوم إلى حمض النيتريك. كيف يعرف أن الحمض استُهلك بالكامل؟","options":["عندما يغلي المحلول","عندما يتوقف الفوران وتبقى كمية صلبة غير ذائبة في القاع","عندما يتحول اللون إلى الأسود","عندما يتجمد المحلول"],"answer":1,"why":"توقف الفقاعات وبقاء مسحوق في القاع يؤكد انتهاء كل الحمض."},{"type":"mcq","q":"ما الخطأ في محاولة تحضير كلوريد الصوديوم بإضافة فائض من NaOH الصلب إلى HCl ثم الترشيح؟","options":["أن NaCl غير ذائب","أن NaOH لا يتفاعل مع HCl","أن فائض NaOH يذوب في الماء فيمر عبر ورق الترشيح ويلوّث الملح","أن HCl صلب"],"answer":2,"why":"الترشيح لا يفصل المواد الذائبة في الماء."},{"type":"mcq","q":"لتحضير كبريتات الرصاص (PbSO₄) غير الذائبة، نخلط محلول نترات الرصاص مع محلول:","options":["كربونات الكالسيوم الصلبة","كلوريد الصوديوم","نترات البوتاسيوم","كبريتات الصوديوم أو حمض الكبريتيك المخفف"],"answer":3,"why":"نحتاج مصدرًا ذائبًا لأيون الكبريتات SO₄²⁻."},{"type":"mcq","q":"يمكن استخدام «الفحم النشط» أحيانًا بدلًا من إعادة المعايرة دون كاشف بغرض:","options":["امتزاز وإزالة لون الكاشف ثم ترشيح الفحم","زيادة حموضة المحلول","ترسيب الملح","تحويل القلوي إلى حمض"],"answer":0,"why":"الفحم النشط يمتص صبغة الكاشف ثم يُفصل بالترشيح."},{"type":"tfr","q":"جميع أملاح النترات وأملاح الصوديوم والبوتاسيوم ذائبة في الماء، مما يجعلها مثالية لتحضير الرواسب.","answer":true,"reasons":["لأنها لا تحتوي أيونات","لأنها غير ذائبة","لأنها تضمن توفير الأيونات الموجبة والسالبة في صورة محاليل مائية صافية لخلطها"],"reason":2},{"type":"tfr","q":"لا يُصلح استخدام فلز البوتاسيوم مع حمض الكبريتيك لتحضير كبريتات البوتاسيوم في المختبر المدرسي.","answer":true,"reasons":["لأن تفاعل البوتاسيوم مع الحمض شديد العنف والخطورة وقد يسبب انفجارًا","لأن البوتاسيوم لا يتفاعل","لأن كبريتات البوتاسيوم غير ذائبة"],"reason":0},{"type":"tfr","q":"في عملية الترسيب، نحتاج لإجراء خطوة التبخير والتبلور للحصول على الراسب.","answer":false,"reasons":["لأن الراسب ذائب","الراسب صلب بالفعل فيُفصل مباشرة بالترشيح ثم الغسل والتجفيف دون تبخير","لأن الترشيح يذيب الراسب"],"reason":1},{"type":"essay","q":"قارن بين خطوات تنقية الملح الذائب المحضّر بطريقة الفائض وخطوات تنقية الملح غير الذائب المحضّر بالترسيب.","model":"في الملح الذائب: نرشح للتخلص من الفائض الصلب ونحتفظ بالرشيح السائل ثم نبخّره جزئيًا ونبرّده للتبلور ونجفف البلورات. في الملح غير الذائب: نرشح للاحتفاظ بالراسب الصلب فوق ورق الترشيح، ثم نغسله بماء مقطر ونجففه."},{"type":"essay","q":"اشرح لماذا ينجح تحضير كلوريد الخارصين باستخدام فلز الخارصين مع HCl، بينما لا ينجح تحضير كلوريد النحاس باستخدام فلز النحاس مع HCl.","model":"لأن الخارصين أنشط من الهيدروجين فيتفاعل مع HCl منتجًا ZnCl₂ + H₂، أما النحاس فأقل نشاطًا من الهيدروجين فلا يتفاعل مع الحمض المخفف؛ لذا نستخدم CuO أو CuCO₃ بدلًا منه."},{"type":"essay","q":"اكتب خطوات تحضير عينة نقية وجافة من كلوريد الفضة (AgCl) مع المعادلة الرمزية الموزونة ورموز الحالة.","model":"نخلط محلول نترات الفضة مع محلول كلوريد الصوديوم فيتكون راسب أبيض من AgCl. نرشح الخليط ونغسل الراسب بماء مقطر ثم نجففه. المعادلة: AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq)."}]}},
  {"id":"g9-chem-2-u8-2","grade":"g9","subject":"chemistry","term":2,"unit":8,"no":2,"title":"الأملاح","summary":"شرح متحرك بـ SVG لقواعد ذوبانية الأملاح في الماء والأملاح المائية واللامائية (ماء التبلور) واستخداماتها، ثم أنشطة بثلاثة مستويات.","page":"lesson-salts.html","video":"","pdf":"","notes":["قواعد الذوبانية: جميع أملاح Na⁺, K⁺, NH₄⁺ والنترات NO₃⁻ ذائبة في الماء دائمًا.","معظم الكلوريدات ذائبة عدا AgCl و PbCl₂؛ ومعظم الكبريتات ذائبة عدا BaSO₄ و PbSO₄ و CaSO₄.","معظم الكربونات والهيدروكسيدات غير ذائبة عدا أملاح Na⁺ و K⁺ و NH₄⁺ (و Ca(OH)₂ شحيح الذوبان).","الملح المائي يحتوي ماء تبلور داخل بلوراته (CuSO₄·5H₂O أزرق)، واللامائي خالٍ من الماء (CuSO₄ أبيض)."],"exercises":["صنّف الأملاح الآتية إلى ذائبة وغير ذائبة: K₂CO₃، BaSO₄، Pb(NO₃)₂، AgCl، CuCO₃، NH₄Cl.","اشرح المقصود بكل من: الملح المائي، الملح اللامائي، وماء التبلور.","لماذا يُعد شرب كبريتات الباريوم (BaSO₄) قبل الأشعة السينية آمنًا رغم أن أيونات الباريوم سامة؟"],"levels":{"easy":[{"type":"mcq","q":"أي الأملاح الآتية يذوب في الماء؟","options":["كربونات النحاس CuCO₃","كلوريد الفضة AgCl","كبريتات الباريوم BaSO₄","نترات الرصاص Pb(NO₃)₂"],"answer":3,"why":"جميع أملاح النترات ذائبة في الماء دون استثناء."},{"type":"mcq","q":"أي الأملاح الآتية «غير ذائب» في الماء؟","options":["كبريتات الباريوم BaSO₄","كبريتات الصوديوم Na₂SO₄","كلوريد البوتاسيوم KCl","نترات الأمونيوم NH₄NO₃"],"answer":0,"why":"كبريتات الباريوم من استثناءات الكبريتات غير الذائبة."},{"type":"mcq","q":"الماء المرتبط كيميائيًا داخل البلورات الصلبة للملح يُسمّى:","options":["ماء الجير","ماء التبلور","الماء المالح","بخار التقطير"],"answer":1,"why":"ماء التبلور يمنح كثيرًا من البلورات شكلها الهندسي ولونها."},{"type":"mcq","q":"لون بلورات كبريتات النحاس المائية (CuSO₄·5H₂O) هو:","options":["الوردي","الأبيض","الأزرق","الأسود"],"answer":2,"why":"وجود ماء التبلور يعطي كبريتات النحاس لونها الأزرق."}],"medium":[{"type":"mcq","q":"أي الكربونات الآتية «تذوب» في الماء؟","options":["كربونات المغنيسيوم MgCO₃","كربونات الكالسيوم CaCO₃","كربونات النحاس CuCO₃","كربونات البوتاسيوم K₂CO₃"],"answer":3,"why":"جميع أملاح البوتاسيوم (والصوديوم والأمونيوم) ذائبة."},{"type":"mcq","q":"كم جزيء ماء تبلور يرتبط بكل وحدة في الصيغة CuSO₄·5H₂O؟","options":["5 جزيئات ماء","1 جزيء ماء","4 جزيئات ماء","10 جزيئات ماء"],"answer":0,"why":"الرقم 5 أمام H₂O يحدد عدد جزيئات ماء التبلور."},{"type":"mcq","q":"عند تسخين بلورات كبريتات النحاس الزرقاء في أنبوب اختبار، ماذا تلاحظ على الجدار العلوي البارد للأنبوب؟","options":["تحولها للون الأخضر","تكاثف قطرات ماء وتحوّل البلورات إلى مسحوق أبيض","انصهار الزجاج","لا يحدث شيء"],"answer":1,"why":"يتبخر ماء التبلور ويتكاثف عند فوهة الأنبوب البارد."},{"type":"tfr","q":"جميع أملاح الكبريتات تذوب في الماء دون استثناء.","answer":false,"reasons":["لأن الكبريتات كلها غير ذائبة","لأن كبريتات الباريوم والرصاص والكالسيوم لا تذوب في الماء","لأن كبريتات الصوديوم غير ذائبة"],"reason":1},{"type":"tfr","q":"تحوّل كبريتات النحاس المائية إلى لامائية بالتسخين هو تفاعل عكسي.","answer":true,"reasons":["لأنها تتحول إلى نحاس صلب","لأنها لا تعود زرقاء أبدًا","لأنه يمكن إعادتها إلى اللون الأزرق المائي بإضافة الماء مرة أخرى"],"reason":2},{"type":"essay","q":"لماذا يُعطى المرضى «وجبة الباريوم» من كبريتات الباريوم (BaSO₄) قبل التصوير بالأشعة السينية رغم أن أيونات الباريوم سامة؟","model":"لأن كبريتات الباريوم ملح غير ذائب إطلاقًا في الماء أو حمض المعدة، فلا يمتصّه الجسم ويمر عبر الجهاز الهضمي بأمان تام."},{"type":"essay","q":"توقّع هل سيتكوّن راسب عند خلط محلول نترات الفضة مع محلول كلوريد البوتاسيوم، وحدّد اسم الراسب إن وُجد.","model":"نعم، يتكوّن راسب أبيض من كلوريد الفضة (AgCl) لأنه غير ذائب في الماء، بينما تبقى نترات البوتاسيوم ذائبة."}],"hard":[{"type":"mcq","q":"عند خلط محلولي Na₂SO₄(aq) و KCl(aq)، ماذا يحدث؟","options":["يتكوّن راسب أزرق","يتكوّن راسب أبيض من NaCl","لا يتكوّن أي راسب لأن جميع النواتج المحتملة (NaCl و K₂SO₄) ذائبة","يتصاعد غاز الهيدروجين"],"answer":2,"why":"أملاح الصوديوم والبوتاسيوم كلها ذائبة فلا يحدث ترسيب."},{"type":"mcq","q":"سخّن طالب 5.0 g من بلورات كبريتات النحاس المائية حتى ثبتت كتلتها عند 3.2 g من الملح اللامائي. ما كتلة ماء التبلور المتبخر؟","options":["2.0 g","8.2 g","3.2 g","1.8 g"],"answer":3,"why":"كتلة الماء = 5.0 − 3.2 = 1.8 g."},{"type":"mcq","q":"للتأكد أن جميع ماء التبلور قد تبخّر تمامًا عند التسخين في المختبر، نكرّر عملية:","options":["التسخين والتبريد والوزن حتى ثبات الكتلة","إضافة الماء","الترشيح","المعايرة"],"answer":0,"why":"ثبات الكتلة يؤكد عدم بقاء أي ماء تبلور داخل العينة."},{"type":"mcq","q":"أي زوج من الأملاح الآتية كلاهما «غير ذائب» في الماء؟","options":["Na₂CO₃ و AgCl","PbCl₂ و CuCO₃","Pb(NO₃)₂ و BaSO₄","NH₄Cl و K₂SO₄"],"answer":1,"why":"كلوريد الرصاص وكربونات النحاس كلاهما غير ذائبين."},{"type":"tfr","q":"تنطلق طاقة حرارية (تفاعل طارد للحرارة) عند إضافة الماء إلى كبريتات النحاس اللامائية البيضاء.","answer":true,"reasons":["لأن عكس التسخين الماص للحرارة هو تفاعل طارد للحرارة يرفع حرارة الأنبوب","لأن التفاعل يبرد الأنبوب","لأنه لا يحدث تغير في الطاقة"],"reason":0},{"type":"tfr","q":"يمكن فصل خليط صلب من كلوريد الصوديوم وكلوريد الفضة بإضافة الماء ثم الترشيح.","answer":true,"reasons":["لأنهما يذوبان معًا","لأن NaCl يذوب في الماء ويمر مع الرشيح، بينما AgCl غير ذائب فيبقى فوق ورق الترشيح","لأنهما لا يذوبان"],"reason":1},{"type":"tfr","q":"الصيغة CoCl₂·6H₂O تمثّل ملحًا لامائيًا أزرق اللون.","answer":false,"reasons":["لأنه غير ذائب","لأنه ملح أبيض","وجود 6H₂O يعني أنه ملح «مائي» لونه وردي، أما اللامائي فهو CoCl₂ الأزرق"],"reason":2},{"type":"essay","q":"اشرح خطوات فصل خليط من مسحوقَي كربونات الكالسيوم ونترات الصوديوم للحصول على كل منهما نقيًا وجافًا.","model":"نضيف ماءً مقطرًا ونحرّك فتذوب نترات الصوديوم ولا تذوب كربونات الكالسيوم. نرشح الخليط: نغسل راسب كربونات الكالسيوم ونجففه، ونبخّر رشيح نترات الصوديوم جزئيًا ثم نبرده للتبلور ونجففه."},{"type":"essay","q":"قارن بين التغيّر اللوني عند إضافة الماء إلى كل من: كبريتات النحاس اللامائية، وكلوريد الكوبلت اللامائي.","model":"كبريتات النحاس اللامائية تتحوّل من الأبيض إلى الأزرق، بينما كلوريد الكوبلت اللامائي يتحوّل من الأزرق إلى الوردي."},{"type":"essay","q":"أعطِ مثالين من قواعد الذوبانية يوضّحان لماذا يختار الكيميائيون أملاح النترات والصوديوم دائمًا عند تحضير الرواسب.","model":"لأن جميع أملاح النترات (مثل AgNO₃ و Ba(NO₃)₂) وجميع أملاح الصوديوم (مثل NaCl و Na₂SO₄) ذائبة في الماء بلا استثناء، فتوفّر الأيونات المطلوبة للترسيب بسهولة."}]}},
  {"id":"g9-chem-2-u9-1","grade":"g9","subject":"chemistry","term":2,"unit":9,"no":1,"title":"أهمّيّة التحليل الكيميائي","summary":"شرح متحرك بـ SVG لمفهوم التحليل الكيميائي والفرق بين التحليل النوعي والكمي وأهميته في الماء والغذاء والدواء والبيئة، ثم أنشطة بثلاثة مستويات.","page":"lesson-importance-of-chemical-analysis.html","video":"","pdf":"","notes":["التحليل الكيميائي: تحديد هوية مكونات مادة مجهولة أو قياس كمياتها والتأكد من نقائها.","التحليل النوعي: يحدّد «نوع» العناصر أو الأيونات الموجودة في العينة.","التحليل الكمي: يحدّد «كمية أو تركيز» كل مكون بالأرقام.","مجالاته: فحص المياه والأغذية، التحاليل الطبية، صناعة الأدوية، مراقبة التلوث البيئي، الزراعة، والأدلة الجنائية.","يُشترط استخدام الماء المقطّر في الاختبارات المخبرية لتجنّب الأيونات الدخيلة الموجودة في ماء الصنبور."],"exercises":["صنّف العبارتين إلى تحليل نوعي وكمي: (أ) وجود أيون الكلوريد في عينة ماء، (ب) تركيز السكر في الدم 95 mg/dL.","اذكر ثلاثة مجالات حيوية يُستخدم فيها التحليل الكيميائي في سلطنة عُمان.","علّل: يجب غسل أنابيب الاختبار بالماء المقطّر قبل الكشف عن الأيونات."],"levels":{"easy":[{"type":"mcq","q":"الفرع الذي يحدّد «هوية ونوع» الأيونات في عينة مجهولة هو:","options":["التحليل النوعي","التحليل الكمي","التقطير","الانصهار"],"answer":0,"why":"التحليل النوعي يكشف عن نوع المواد الموجودة."},{"type":"mcq","q":"الفرع الذي يقيس «مقدار أو تركيز» مادة معينة في عينة هو:","options":["التحليل النوعي","التحليل الكمي","الترشيح","التسامي"],"answer":1,"why":"التحليل الكمي يعطي قيمًا عددية للكمية أو التركيز."},{"type":"mcq","q":"الماء المناسب لإذابة العينات قبل اختبارات الكشف عن الأيونات هو:","options":["ماء الصنبور","ماء البحر","الماء المقطّر","الماء المعدني"],"answer":2,"why":"الماء المقطّر نقي وخالٍ من الأيونات المذابة."},{"type":"mcq","q":"فحص عينة من مصنع أدوية للتأكد من خلوها من الشوائب يُسمّى:","options":["الصدأ","الاحتباس الحراري","التعادل","مراقبة الجودة"],"answer":3,"why":"التحليل الكيميائي أساس مراقبة الجودة في المصانع."}],"medium":[{"type":"mcq","q":"إثبات وجود غاز ثاني أكسيد الكربون بتعكير ماء الجير هو مثال على:","options":["التحليل النوعي","التحليل الكمي","التقطير التجزيئي","المعايرة الحجمية"],"answer":0,"why":"تحديد هوية الغاز دون قياس كتلته هو تحليل نوعي."},{"type":"mcq","q":"استخدام المعايرة لمعرفة تركيز حمض مجهول بوحدة mol/dm³ يُعد:","options":["تحليلًا نوعيًا فقط","تحليلًا كميًا","ترشيحًا","تبلورًا"],"answer":1,"why":"حساب التركيز العددي هو تحليل كمي."},{"type":"mcq","q":"ما الخطر المحتمل إذا استخدم طالب ماء الصنبور لإجراء اختبار الكشف عن أيونات الكلوريد؟","options":["توقف الذوبان","انفجار الأنبوب","الحصول على نتيجة إيجابية كاذبة بسبب وجود كلوريد في ماء الصنبور أصلًا","تغير لون الزجاج"],"answer":2,"why":"ماء الصنبور المعالج يحتوي أيونات كلوريد قد تضلل نتيجة الاختبار."},{"type":"tfr","q":"تعتمد المختبرات الطبية على التحليل الكيميائي النوعي والكمي معًا لتشخيص الأمراض.","answer":true,"reasons":["لأن التحاليل نوعية فقط","لأن الطب لا يستخدم الكيمياء","فالكشف عن وجود مادة غير طبيعية نوعي، وقياس نسبتها في الدم كمي"],"reason":2},{"type":"tfr","q":"الأجهزة التحليلية الآلية الحديثة أقل حساسية من الاختبارات اليدوية البسيطة.","answer":false,"reasons":["بل هي أكثر حساسية وسرعة بكثير ويمكنها كشف تراكيز ضئيلة جدًّا","لأنها لا تعمل على العينات الصغيرة","لأنها تعتمد على التذوق"],"reason":0},{"type":"essay","q":"قارن بين التحليل الكيميائي النوعي والتحليل الكمي مع مثال واحد لكل منهما.","model":"التحليل النوعي يحدد نوع المادة الموجودة (مثل التأكد من وجود أيون النحاس في عينة ماء). التحليل الكمي يقيس كمية أو تركيز المادة (مثل قياس تركيز النحاس بـ 0.5 mg/L)."},{"type":"essay","q":"اذكر فائدتين للتحليل الكيميائي في حماية البيئة الزراعية والبحرية.","model":"١) قياس pH وعناصر التربة لتحديد السماد المناسب دون إفراط. ٢) رصد الملوثات الكيميائية أو المعادن الثقيلة في مياه البحر والهواء مبكرًا."}],"hard":[{"type":"mcq","q":"في حادث تسرب نفطي محتمل، أخذ باحث عينة ماء بحر فأثبت وجود مركبات هيدروكربونية بتركيز 12 mg/L. ما نوع التحليل الذي أجراه؟","options":["فيزيائي فقط","نوعي فقط","كمي فقط","تحليل نوعي (إثبات الوجود) وكمي (قياس 12 mg/L)"],"answer":3,"why":"تحديد الهوية نوعي، وقياس التركيز 12 mg/L كمي."},{"type":"mcq","q":"لماذا تُفضّل شركات الأدوية أجهزة التحليل الآلي في خطوط الإنتاج؟","options":["لسرعتها الفائقة ودقتها العالية وقدرتها على تحليل عينات صغيرة جدًّا بتكرار موثوق","لأنها مجانية تمامًا","لأنها لا تحتاج إلى فنيين","لأنها تغيّر تركيب الدواء"],"answer":0,"why":"الدقة والسرعة والحساسية العالية أساسية لضمان أمان الدواء."},{"type":"mcq","q":"أي من الآتي يُعد مثالًا على استخدام التحليل الكيميائي في الأدلة الجنائية؟","options":["بناء الجسور","التعرف على آثار سموم أو ألياف أو بقايا بارود في مسرح حادث","صناعة الزجاج","توليد الكهرباء"],"answer":1,"why":"التحليل الجنائي يطابق آثار المواد الكيميائية في مسرح الحادث."},{"type":"mcq","q":"عند معايرة عينة تربة حمضية، يحدد الفحص الأول أنها حمضية (pH < 7) والفحص الثاني يحدد كمية الجير اللازمة بالضبط لكل هكتار. الفحصان على الترتيب هما:","options":["كلاهما نوعي","كمي ثم نوعي","نوعي ثم كمي","كلاهما فيزيائي"],"answer":2,"why":"معرفة الحموضة نوعي، وحساب الكمية الدقيقة اللازمة كمي."},{"type":"tfr","q":"يمكن أن يُعطي التحليل النوعي وحده جميع المعلومات اللازمة لتحديد هل مستوى الرصاص في الماء آمن أم سام.","answer":false,"reasons":["لأن الرصاص لا يُقاس كميًا","نحتاج للتحليل الكمي أيضًا لمعرفة هل تركيز الرصاص يتجاوز الحد الآمن المسموح به أم لا","لأن النوعي يعطي أرقامًا"],"reason":1},{"type":"tfr","q":"تسهم المعايرة الدقيقة لأجهزة التحليل الكيميائي في تقليل الأخطاء المنتظمة وزيادة موثوقية النتائج.","answer":true,"reasons":["الأجهزة لا تحتاج معايرة","المعايرة تزيد الأخطاء","المعايرة بمحاليل قياسية معروفة تضمن صحة القراءات الرقمية"],"reason":2},{"type":"tfr","q":"يُعد فحص نسبة الملوحة في محطات تحلية المياه بسلطنة عُمان تطبيقًا عمليًا للتحليل الكمي.","answer":true,"reasons":["لأنه يقيس تركيز الأملاح الذائبة بالأرقام للتأكد من صلاحية المياه للشرب","لأنه تحليل نوعي فقط","لأنه لا يستخدم الكيمياء"],"reason":0},{"type":"essay","q":"اشرح كيف يتكامل التحليل النوعي والكمي عند فحص مصنع لمياه الشرب المعبأة.","model":"أولًا يكشف التحليل النوعي عن الأيونات الموجودة والتأكد من خلوها من مواد سامة، ثم يقيس التحليل الكمي تركيز كل أيون (مثل الصوديوم والكالسيوم والنترات) للتأكد من بقائه ضمن الحدود الصحية الآمنة."},{"type":"essay","q":"ما أبرز ثلاث مزايا وثلاثة تحديات لاستخدام أجهزة التحليل الآلية الحديثة مقارنةً بالطرق اليدوية؟","model":"المزايا: سرعة عالية، دقة وحساسية فائقة، تحتاج عينات صغيرة جدًّا. التحديات: تكلفتها الشرائية والصيانة العالية، تحتاج كهرباء وتدريبًا متخصصًا، وتحتاج معايرة مستمرة."},{"type":"essay","q":"اقترح خطة فحص كيميائي سريعة لشكوى مزارع من ضعف نمو محصوله وتغيّر طعم ماء البئر.","model":"١) قياس pH التربة والماء. ٢) تحليل نوعي للأيونات (كالكلوريد والكبريتات والحديد) والملوحة. ٣) تحليل كمي لتركيز الأملاح الذائبة والعناصر المغذية لتحديد سبب المشكلة وعلاجها."}]}},
  {"id":"g9-chem-2-u9-2","grade":"g9","subject":"chemistry","term":2,"unit":9,"no":2,"title":"اختبارات الكشف عن الماء","summary":"شرح متحرك بـ SVG للاختبارات الكيميائية للكشف عن وجود الماء (كبريتات النحاس وكلوريد الكوبلت) والاختبار الفيزيائي لنقاء الماء، ثم أنشطة بثلاثة مستويات.","page":"lesson-tests-for-water.html","video":"","pdf":"","notes":["الاختبار الكيميائي لوجود الماء (١): كبريتات النحاس اللامائية تتحول من الأبيض إلى الأزرق.","الاختبار الكيميائي لوجود الماء (٢): ورق كلوريد الكوبلت اللامائي يتحول من الأزرق إلى الوردي.","الاختبارات الكيميائية تثبت «وجود» الماء فقط ولا تثبت «نقاءه».","الاختبار الفيزيائي لنقاء الماء: يغلي بالضبط عند 100°C ويتجمّد بالضبط عند 0°C (عند الضغط القياسي).","الشوائب الذائبة ترفع درجة غليان الماء (> 100°C) وتخفض درجة تجمّده (< 0°C)."],"exercises":["قارن في جدول بين اختبارَي كبريتات النحاس اللامائية وكلوريد الكوبلت اللامائي للكشف عن الماء.","غلى سائل شفاف عند 103°C وحوّل كبريتات النحاس البيضاء إلى الزرقاء. ماذا تستنتج عنه؟","علّل: يُحفظ ورق كلوريد الكوبلت الأزرق في وعاء جاف محكم الإغلاق."],"levels":{"easy":[{"type":"mcq","q":"تتحوّل كبريتات النحاس اللامائية عند إضافة الماء إليها من:","options":["الأزرق إلى الأبيض","الأبيض إلى الأزرق","الأزرق إلى الوردي","الوردي إلى الأخضر"],"answer":1,"why":"CuSO₄ اللامائي أبيض، ومع الماء يصبح CuSO₄·5H₂O أزرق."},{"type":"mcq","q":"يتحوّل ورق كلوريد الكوبلت اللامائي عند ملامسته للماء من:","options":["الوردي إلى الأزرق","الأبيض إلى الأزرق","الأزرق إلى الوردي","الأحمر إلى الأزرق"],"answer":2,"why":"كلوريد الكوبلت الجاف أزرق ومع الماء يصبح ورديًا."},{"type":"mcq","q":"درجة غليان الماء النقي عند الضغط الجوي القياسي هي:","options":["0°C","90°C","105°C","100°C بالضبط"],"answer":3,"why":"يغلي الماء النقي عند 100°C بالضبط."},{"type":"mcq","q":"الاختبار الذي يثبت أن عينة الماء «نقية» وخالية من الأملاح هو:","options":["قياس درجة غليانها أو تجمّدها","إضافة كبريتات النحاس البيضاء فقط","إضافة كلوريد الكوبلت الأزرق فقط","النظر إلى شفافيتها"],"answer":0,"why":"نقاء الماء يُقاس فيزيائيًا بدرجة غليانه (100°C) أو تجمّده (0°C)."}],"medium":[{"type":"mcq","q":"سائل شفاف حوّل ورق كلوريد الكوبلت من الأزرق إلى الوردي، وتجمّد عند -3°C. إذن السائل هو:","options":["ماء نقي 100%","ماء غير نقي (يحتوي شوائب ذائبة)","كحول نقي لا يحتوي ماء","حمض لا يحتوي ماء"],"answer":1,"why":"تغير الكوبلت يثبت وجود الماء، وتجمّده تحت 0°C يثبت وجود شوائب."},{"type":"mcq","q":"إذا سخّنت ورقة كلوريد كوبلت وردية بلطف فوق لهب ضعيف، فإنها:","options":["تبقى وردية دائمًا","تتحول للون الأبيض","تعود زرقاء لأن الماء يتبخر منها","تتحول للون الأخضر"],"answer":2,"why":"التسخين يطرد الماء فيعود كلوريد الكوبلت لامائيًا أزرق."},{"type":"mcq","q":"إضافة الملح إلى الماء النقي تجعل درجة غليانه:","options":["تبقى 100°C بالضبط","أقل من 100°C","تساوي 0°C","أعلى من 100°C"],"answer":3,"why":"المواد المذابة ترفع درجة غليان الماء."},{"type":"tfr","q":"إذا حوّل سائلٌ كبريتات النحاس البيضاء إلى الزرقاء فهذا دليل قاطع أنه ماء نقي صالح للشرب.","answer":false,"reasons":["لأن أي محلول مائي (حتى لو كان حمضًا أو ماءً مالحًا) يحوّلها للأزرق؛ النقاء يُفحص بدرجة الغليان/التجمد","لأن كبريتات النحاس لا تكشف الماء","لأن الماء النقي لا يغير لونها"],"reason":0},{"type":"tfr","q":"يحتوي الهواء الرطب على بخار ماء كافٍ لتحويل ورق كلوريد الكوبلت الأزرق إلى وردي مع الوقت.","answer":true,"reasons":["لأن الهواء يحوله للأبيض","لذلك يُحفظ في وعاء محكم وجاف بعيدًا عن الرطوبة","لأن الكوبلت يتفاعل مع النيتروجين"],"reason":1},{"type":"essay","q":"كيف تثبت أن بخار الماء هو أحد نواتج احتراق شمعة في الهواء؟","model":"نضع قمعًا باردًا فوق اللهب ونمرر الغازات الناتجة في أنبوب مبرد فيتكاثف سائل شفاف؛ نختبره بكبريتات النحاس اللامائية البيضاء فتتحول إلى الأزرق (أو كلوريد الكوبلت الأزرق للوردي)."},{"type":"essay","q":"اشرح الفرق بين الاختبار الكيميائي والاختبار الفيزيائي للماء.","model":"الاختبار الكيميائي يكشف «وجود» الماء بتغيّر لون كاشف (CuSO₄ أو CoCl₂)، أما الاختبار الفيزيائي فيفحص «نقاء» الماء بقياس ثبات درجة غليانه (100°C) أو تجمّده (0°C)."}],"hard":[{"type":"mcq","q":"اختبر طالب سائلين شفافين (أ) و (ب): (أ) غلى عند 78°C ولم يغيّر لون CuSO₄ الأبيض، و (ب) غلى عند 100°C وحوّل CuSO₄ للأزرق. إذن:","options":["(ب) ماء نقي، و (أ) سائل آخر غير مائي كالإيثانول","(أ) ماء نقي و (ب) ماء مالح","كلاهما ماء نقي","كلاهما كحول"],"answer":0,"why":"السائل (ب) اجتاز اختبارَي الوجود والنقاء."},{"type":"mcq","q":"في جهاز تقطير ماء البحر، كيف يتأكد الطالب أن الماء المقطّر المتجمّع أصبح نقيًا خاليًا من الملح؟","options":["يحول كلوريد الكوبلت للوردي فقط","يغلي عند 100°C بالضبط (ولا يترك أي راسب عند التبخير)","يكون شفافًا فقط","يتجمد عند -5°C"],"answer":1,"why":"ثبات الغليان عند 100°C يؤكد خلوه من الأملاح المذابة."},{"type":"mcq","q":"لماذا قد يغلي الماء النقي على قمة الجبل الأخضر في عُمان عند درجة أقل قليلًا من 100°C (نحو 94°C)؟","options":["لأن الجاذبية معدومة","لأن الماء هناك غير نقي","بسبب انخفاض الضغط الجوي مع الارتفاع عن سطح البحر","لأن الحرارة هناك سالبة"],"answer":2,"why":"درجة الغليان القياسية 100°C تكون عند الضغط الجوي القياسي على مستوى سطح البحر، وتقل بانخفاض الضغط."},{"type":"mcq","q":"ما الكتلة الناتجة من ماء التبلور إذا تحوّل 16 g من CuSO₄ اللامائي تمامًا إلى 25 g من CuSO₄·5H₂O الأزرق؟","options":["5 g","41 g","16 g","9 g"],"answer":3,"why":"كتلة الماء الممتص = 25 − 16 = 9 g."},{"type":"tfr","q":"يتجمّد ماء البحر المالح عند درجة حرارة أقل من 0°C بسبب الأملاح الذائبة فيه.","answer":true,"reasons":["الملح يرفع درجة التجمد","ماء البحر يتجمد عند 4°C","الشوائب والأملاح المذابة تخفض درجة تجمد الماء تحت الصفر السيليزي"],"reason":2},{"type":"tfr","q":"يمكن إعادة استخدام ورق كلوريد الكوبلت بعد أن يصبح ورديًا بتسخينه برفق لتجفيفه.","answer":true,"reasons":["لأن التفاعل عكسي، فتبخر الماء يعيد اللون الأزرق اللامائي","لأنه يتلف نهائيًا","لأنه يتحول لأبيض"],"reason":0},{"type":"tfr","q":"الإيثانول النقي (سائل شفاف لا يحتوي ماء) يُحوّل كبريتات النحاس اللامائية إلى الأزرق.","answer":false,"reasons":["يحولها للأحمر","لا يُغيّر لونها وتبقى بيضاء لعدم وجود جزيئات ماء","يحولها للوردي"],"reason":1},{"type":"essay","q":"صمّم خطوات عملية للتمييز بين ثلاث عينات شفافة: ماء نقي، ماء مالح، وإيثانول نقي.","model":"١) نختبر كل عينة بكبريتات النحاس اللامائية البيضاء: الذي لا يغير لونها هو الإيثانول النقي. ٢) نقيس درجة غليان العينتين الباقيتين: التي تغلي عند 100°C بالضبط هي الماء النقي، والتي تغلي فوق 100°C هي الماء المالح."},{"type":"essay","q":"لماذا يُنصح بوضع سائل مانع للتجمد والغليان في مشعاع السيارة بدلًا من الماء وحده؟","model":"لأن المواد المذابة فيه ترفع درجة غليان الماء فوق 100°C (مهم جدًّا في حرارة صيف عُمان) وتخفض درجة تجمده تحت 0°C في الأجواء الباردة."},{"type":"essay","q":"اكتب المعادلة الرمزية العكسية لاختبار الكشف عن الماء بكبريتات النحاس اللامائية موضحًا الألوان.","model":"CuSO₄ (أبيض) + 5H₂O ⇌ CuSO₄·5H₂O (أزرق)."}]}},
  {"id":"g9-chem-2-u9-3","grade":"g9","subject":"chemistry","term":2,"unit":9,"no":3,"title":"اختبارات الكشف عن الغازات","summary":"شرح متحرك بـ SVG لاختبارات الكشف عن الغازات الستة: الهيدروجين، الأكسجين، ثاني أكسيد الكربون، الأمونيا، الكلور، وثاني أكسيد الكبريت، ثم أنشطة بثلاثة مستويات.","page":"lesson-tests-for-gases.html","video":"","pdf":"","notes":["الهيدروجين (H₂): شظية مشتعلة ← صوت فرقعة.","الأكسجين (O₂): شظية متوهّجة ← تشتعل مجددًا.","ثاني أكسيد الكربون (CO₂): يُمرّر في ماء الجير الرائق ← يتعكّر (راسب CaCO₃).","الأمونيا (NH₃): ورقة تباع شمس حمراء رطبة ← تتحوّل إلى زرقاء.","الكلور (Cl₂): ورقة تباع شمس رطبة ← تُبيَّض (يزول لونها)."],"exercises":["قارن بين اختبار الكشف عن الهيدروجين واختبار الكشف عن الأكسجين.","لماذا لا يجمع الكيميائيون غاز الأمونيا (NH₃) بطريقة إزاحة الماء؟","اكتب المعادلة الكيميائية لتعكير ماء الجير بغاز CO₂."],"levels":{"easy":[{"type":"mcq","q":"الاختبار القياسي للكشف عن غاز الهيدروجين (H₂) هو:","options":["استخدام ورقة تباع شمس","إمراره في ماء الجير","تقريب شظية مشتعلة فيحدث صوت فرقعة","تقريب شظية متوهجة فتشتعل"],"answer":2,"why":"الهيدروجين يشتعل بفرقعة عند تقريب شظية مشتعلة."},{"type":"mcq","q":"الاختبار القياسي للكشف عن غاز الأكسجين (O₂) هو:","options":["سماع صوت فرقعة","إمراره في ماء الجير","تبييض ورق تباع الشمس","تقريب شظية متوهّجة فتشتعل مجددًا"],"answer":3,"why":"الأكسجين يعيد إشعال الشظية المتوهجة."},{"type":"mcq","q":"الغاز الذي يُعكّر ماء الجير الرائق هو:","options":["ثاني أكسيد الكربون CO₂","الكلور Cl₂","الأمونيا NH₃","الهيدروجين H₂"],"answer":0,"why":"تفاعل CO₂ مع Ca(OH)₂ يكون راسبًا أبيض يعكّر المحلول."},{"type":"mcq","q":"الغاز الذي يُبيّض ورقة تباع الشمس الرطبة هو:","options":["الأكسجين O₂","الكلور Cl₂","الأمونيا NH₃","الهيدروجين H₂"],"answer":1,"why":"الكلور مادة مبيّضة تزيل لون ورق تباع الشمس الرطب."}],"medium":[{"type":"mcq","q":"ما السبب الكيميائي لتعكّر ماء الجير عند إمرار غاز CO₂ فيه؟","options":["تصاعد الهيدروجين","تجمّد الماء","تكوّن راسب أبيض غير ذائب من كربونات الكالسيوم CaCO₃","ذوبان الزجاج"],"answer":2,"why":"Ca(OH)₂(aq) + CO₂(g) → CaCO₃(s) + H₂O(l)."},{"type":"mcq","q":"أُجري اختبار على غاز مجهول بورقة تباع شمس حمراء رطبة فتحوّلت إلى زرقاء. هذا الغاز هو:","options":["الأكسجين O₂","الكلور Cl₂","ثاني أكسيد الكربون CO₂","الأمونيا NH₃"],"answer":3,"why":"الأمونيا هي الغاز القلوي الذي يزرّق تباع الشمس الحمراء الرطبة."},{"type":"mcq","q":"أي الغازات الآتية يُجمع بأنبوب اختبار «مقلوب» (إزاحة الهواء للأسفل) لأنه أخف من الهواء؟","options":["الهيدروجين H₂ والأمونيا NH₃","ثاني أكسيد الكربون CO₂ والكلور Cl₂","ثاني أكسيد الكبريت SO₂","الأكسجين فقط"],"answer":0,"why":"الغازات الأقل كثافة من الهواء تصعد لأعلى الأنبوب المقلوب."},{"type":"tfr","q":"لا يصلح جمع غاز الأمونيا (NH₃) فوق الماء لأنه يذوب بشراهة عالية جدًّا في الماء.","answer":true,"reasons":["لأن الأمونيا غير ذائبة","فيختفي الغاز ذائبًا في الماء بدل أن يتجمّع في الأنبوب","لأن الأمونيا أثقل من الماء"],"reason":1},{"type":"tfr","q":"الكلور غاز عديم اللون تمامًا وعديم الرائحة.","answer":false,"reasons":["لأنه غاز قلوي","لأنه غاز أزرق","لأن الكلور غاز لونه أخضر مصفر وله رائحة نفاذة وسام، لذا يُفحص داخل خزانة الغازات"],"reason":2},{"type":"essay","q":"لماذا يجب أن نطفئ لهب الشظية لتبقى «متوهّجة فقط» عند اختبار غاز الأكسجين؟","model":"لأنها لو كانت مشتعلة بلهب أصلًا فلن نلاحظ بوضوح إعادة اشتعالها؛ أما المتوهّجة فتشتعل فجأة بلهب ساطع في وجود الأكسجين."},{"type":"essay","q":"اذكر التغيّر الملاحظ عند إمرار غاز ثاني أكسيد الكبريت (SO₂) في محلول برمنجنات البوتاسيوم المحمّض.","model":"يزول اللون البنفسجي لمحلول برمنجنات البوتاسيوم المحمّض ويصبح عديم اللون."}],"hard":[{"type":"mcq","q":"سخّن طالب ملحًا مجهولًا فتصاعد غازان: أحدهما عكّر ماء الجير والآخر حوّل كلوريد الكوبلت من الأزرق إلى الوردي. ما الغازان؟","options":["الأكسجين والهيدروجين","ثاني أكسيد الكربون وبخار الماء","الكلور والأمونيا","النيتروجين والهيليوم"],"answer":1,"why":"تعكير ماء الجير = CO₂، وتحول الكوبلت للوردي = بخار ماء."},{"type":"mcq","q":"ما التغيّر الذي يطرأ على ورقة تباع الشمس «الزرقاء الرطبة» عند تعريضها لغاز الكلور (Cl₂)؟","options":["تتحول للون الأسود","تبقى زرقاء داكنة","تحمرّ أولًا (لأن الكلور يكوّن حمضًا مع الماء) ثم تُبيَّض بسرعة","تتحول للون الأخضر"],"answer":2,"why":"يذوب الكلور في الرطوبة مكونًا حمضًا ثم يقوم بتبييض الورقة."},{"type":"mcq","q":"لماذا يُجري الكيميائيون اختبارات غاز الكلور والأمونيا داخل «خزانة طرد الغازات» (Fume Cupboard)؟","options":["لزيادة شدة الضوء","لتبريد الغازات","لمنع ذوبانها","لأن كلا الغازين سامّ ومهيّج للجهاز التنفسي والعينين"],"answer":3,"why":"خزانة الغازات تسحب الأبخرة السامة بعيدًا عن الطالب."},{"type":"mcq","q":"عند التحليل الكهربائي لماء محمّض، ينطلق غاز عند المهبط يشتعل بفرقعة، وغاز عند المصعد يُشعل شظية متوهّجة. الغازان هما:","options":["الهيدروجين (مهبط) والأكسجين (مصعد)","الأكسجين (مهبط) والهيدروجين (مصعد)","الكلور والأمونيا","CO₂ و SO₂"],"answer":0,"why":"الفرقعة للهيدروجين وإعادة الاشتعال للأكسجين."},{"type":"tfr","q":"يمكن التمييز بين غازي CO₂ و N₂ باستخدام ماء الجير الرائق.","answer":true,"reasons":["لأن CO₂ يعكّر ماء الجير بينما N₂ غاز خامل لا يعكّره","لأن N₂ يشتعل بفرقعة","لأن كليهما يعكّر ماء الجير"],"reason":0},{"type":"tfr","q":"تُستخدم الشظية المشتعلة للتفريق بين الهيدروجين وثاني أكسيد الكربون لأن H₂ يشتعل بفرقعة بينما CO₂ يُطفئ الشظية.","answer":true,"reasons":["لأن CO₂ يشتعل بفرقعة","فـ CO₂ لا يشتعل ولا يساعد على الاشتعال فيطفئ اللهب فورًا","لأن H₂ يطفئ اللهب"],"reason":1},{"type":"tfr","q":"يمكن جمع غاز الهيدروجين بإزاحة الهواء للأعلى (أنبوب قائم وفوهته للأعلى).","answer":false,"reasons":["لأنه سائل","لأنه أثقل من الهواء","لأن الهيدروجين أخف الغازات على الإطلاق فسيطير خارج الأنبوب؛ يُجمع بأنبوب مقلوب أو فوق الماء"],"reason":2},{"type":"essay","q":"قارن في جدول مختصر بين اختبارات الغازات الخمسة (H₂, O₂, CO₂, NH₃, Cl₂) موضحًا الأداة والنتيجة الإيجابية.","model":"H₂: شظية مشتعلة ← فرقعة. O₂: شظية متوهجة ← تشتعل. CO₂: ماء الجير ← يتعكر. NH₃: تباع شمس حمراء رطبة ← زرقاء. Cl₂: تباع شمس رطبة ← تُبيّض."},{"type":"essay","q":"اشرح لماذا يُفضّل جمع غاز الأكسجين بإزاحة الماء في المختبر المدرسي.","model":"لأن الأكسجين شحيح الذوبان في الماء، ولأن كثافته قريبة جدًّا من كثافة الهواء فيصعب جمعه نقيًا بإزاحة الهواء، كما نرى بوضوح امتلاء الأنبوب بالغاز."},{"type":"essay","q":"اكتب المعادلة الرمزية الموزونة لتعكّر ماء الجير بغاز CO₂ مع رموز الحالة.","model":"Ca(OH)₂(aq) + CO₂(g) → CaCO₃(s) + H₂O(l)."}]}},
  {"id":"g9-chem-2-u9-4","grade":"g9","subject":"chemistry","term":2,"unit":9,"no":4,"title":"اختبارات الكشف عن الكاتيونات (الأيونات الموجبة)","summary":"شرح متحرك بـ SVG لاختبارات الكشف عن الأيونات الموجبة (Cu²⁺, Fe²⁺, Fe³⁺, Al³⁺, Zn²⁺, Ca²⁺, NH₄⁺) بهيدروكسيد الصوديوم والأمونيا واختبار اللهب، ثم أنشطة بثلاثة مستويات.","page":"lesson-tests-for-cations.html","video":"","pdf":"","notes":["مع NaOH(aq): Cu²⁺ راسب أزرق، Fe²⁺ راسب أخضر، Fe³⁺ راسب بني محمر.","الرواسب البيضاء مع NaOH(aq): Ca²⁺ (لا يذوب بالفائض)، Al³⁺ (يذوب بفائض NaOH فقط)، Zn²⁺ (يذوب بفائض NaOH وفائض NH₃).","أيون النحاس Cu²⁺ مع فائض الأمونيا NH₃ يذوب مكونًا محلولًا أزرق داكنًا.","أيون الأمونيوم NH₄⁺: إضافة NaOH + تسخين ← يتصاعد غاز NH₃ يزرّق تباع الشمس الحمراء الرطبة.","ألوان اللهب: Li⁺ أحمر قرمزي، Na⁺ أصفر، K⁺ ليلكي، Ca²⁺ أحمر طوبي، Cu²⁺ أخضر مزرق."],"exercises":["كيف تميّز عمليًا بين محلولي كبريتات الحديد (II) وكبريتات الحديد (III)؟","أعطى محلول مجهول راسبًا أبيض مع NaOH ذاب في الفائض. كيف تحدّد هل هو Al³⁺ أم Zn²⁺؟","اذكر خطوات إجراء اختبار اللهب لملح كلوريد البوتاسيوم ولون اللهب المتوقع."],"levels":{"easy":[{"type":"mcq","q":"لون الراسب الناتج عن إضافة NaOH(aq) إلى محلول أيونات النحاس Cu²⁺ هو:","options":["بني محمر","أخضر","أبيض","أزرق"],"answer":3,"why":"يتكون راسب أزرق من هيدروكسيد النحاس Cu(OH)₂."},{"type":"mcq","q":"لون الراسب الناتج عن إضافة NaOH(aq) إلى محلول أيونات الحديد الثنائي Fe²⁺ هو:","options":["أخضر","أزرق","بني محمر","أصفر"],"answer":0,"why":"Fe(OH)₂ راسب أخضر اللون."},{"type":"mcq","q":"لون اللهب لأيونات البوتاسيوم (K⁺) هو:","options":["أصفر","بنفسجي فاتح (ليلكي)","أخضر","أزرق"],"answer":1,"why":"يعطي البوتاسيوم لهبًا ليلكيًا (بنفسجيًا فاتحًا)."},{"type":"mcq","q":"عند إضافة NaOH(aq) والتسخين إلى محلول يحتوي NH₄⁺ يتصاعد غاز:","options":["ثاني أكسيد الكربون CO₂","الهيدروجين H₂","الأمونيا NH₃","الأكسجين O₂"],"answer":2,"why":"يتصاعد غاز الأمونيا الذي يزرق ورقة تباع الشمس الحمراء الرطبة."}],"medium":[{"type":"mcq","q":"للتمييز بين محلول يحتوي Al³⁺ ومحلول يحتوي Zn²⁺ نستخدم:","options":["شظية مشتعلة","قطرات قليلة من NaOH فقط","ماء الجير","فائضًا من محلول الأمونيا NH₃(aq) فيذوب راسب Zn²⁺ ولا يذوب Al³⁺"],"answer":3,"why":"كلاهما يذوب في فائض NaOH، لكن Zn²⁺ فقط يذوب في فائض الأمونيا."},{"type":"mcq","q":"ماذا يحدث للراسب الأزرق لـ Cu(OH)₂ عند إضافة «فائض» من محلول الأمونيا NH₃(aq)؟","options":["يذوب ويتكوّن محلول أزرق داكن صافٍ","يتحول إلى أبيض","يتحول إلى بني محمر","يبقى راسبًا لا يذوب"],"answer":0,"why":"يذوب راسب هيدروكسيد النحاس في فائض الأمونيا مكونًا محلولًا أزرق داكنًا."},{"type":"mcq","q":"لماذا يُنظّف سلك البلاتين بحمض HCl المركز قبل اختبار اللهب؟","options":["لتغيير لون السلك للأزرق","لإزالة أي شوائب أو أملاح سابقة قد تلوّث لون اللهب","لإذابة السلك","لإنتاج غاز الأكسجين"],"answer":1,"why":"تنظيف السلك يضمن أن اللون الظاهر ناتج عن العينة الجديدة فقط."},{"type":"tfr","q":"يعطي أيون الكالسيوم (Ca²⁺) راسبًا أبيض لا يذوب في فائض NaOH.","answer":true,"reasons":["لأنه يعطي راسبًا أزرق","لأن Ca(OH)₂ متردد","بخلاف Al³⁺ و Zn²⁺ اللذين تذوب رواسبهما في فائض NaOH"],"reason":2},{"type":"tfr","q":"يتحوّل سطح راسب Fe(OH)₂ الأخضر تدريجيًا إلى اللون البني عند تركه معرضًا للهواء.","answer":true,"reasons":["بسبب تأكسد Fe²⁺ بأكسجين الهواء إلى Fe³⁺ البني المحمر","لأنه يجف ويصبح أبيض","لأنه يذوب في الهواء"],"reason":0},{"type":"essay","q":"قارن بين نتيجة إضافة NaOH(aq) (قليل ثم فائض) و NH₃(aq) (قليل ثم فائض) إلى محلولي Al³⁺ و Zn²⁺.","model":"مع NaOH: كلاهما يعطي راسبًا أبيض يذوب في الفائض. مع NH₃: كلاهما يعطي راسبًا أبيض، لكن في الفائض يذوب راسب Zn²⁺ بينما لا يذوب راسب Al³⁺."},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لتكوّن راسب هيدروكسيد الحديد (III) عند إضافة NaOH.","model":"Fe³⁺(aq) + 3OH⁻(aq) → Fe(OH)₃(s)."}],"hard":[{"type":"mcq","q":"أعطى ملح صلب لهبًا أحمر طوبيًا (برتقاليًا محمرًا)، وعند إذابته في الماء وإضافة NaOH أعطى راسبًا أبيض لا يذوب في الفائض. الكاتيون هو:","options":["Zn²⁺","Na⁺","Ca²⁺","Cu²⁺"],"answer":2,"why":"اللهب الأحمر الطوبي والراسب الأبيض غير الذائب في الفائض يميزان الكالسيوم Ca²⁺."},{"type":"mcq","q":"ما عيب اختبار اللهب إذا احتوى الخليط على أيونات الصوديوم (Na⁺) مع البوتاسيوم (K⁺)؟","options":["لا يشتعل اللهب","البوتاسيوم يخفي الصوديوم","يتحول اللهب للأخضر","اللون الأصفر الساطع للصوديوم يُخفي اللون الليلكي الخافت للبوتاسيوم"],"answer":3,"why":"لهب الصوديوم شديد السطوع ويغطي على الألوان الأضعف كالليلكي."},{"type":"mcq","q":"محلول مجهول لم يُكوّن أي راسب مع محلول الأمونيا NH₃(aq)، لكنه كوّن راسبًا أبيض مع NaOH(aq) لم يذب في الفائض. الكاتيون هو:","options":["Ca²⁺","Al³⁺","Zn²⁺","Fe²⁺"],"answer":0,"why":"الكالسيوم لا يكوّن راسبًا (أو راسبًا طفيفًا جدًّا) مع الأمونيا، ويعطي راسبًا أبيض مع NaOH لا يذوب."},{"type":"mcq","q":"لماذا تُستخدم أملاح النحاس والسترونتيوم والصوديوم في صناعة الألعاب النارية؟","options":["لأنها تطفئ النار","لأن أيوناتها تُصدر ألوان لهب زاهية ومميزة عند تسخينها","لأنها لا تحتوي إلكترونات","لأنها عديمة اللون في اللهب"],"answer":1,"why":"نفس مبدأ اختبار اللهب يعطي الألعاب النارية ألوانها المميزة."},{"type":"tfr","q":"المعادلة الأيونية الصافية لتفاعل أيونات النحاس مع NaOH هي: Cu²⁺(aq) + 2OH⁻(aq) → Cu(OH)₂(s).","answer":true,"reasons":["الصحيح Cu⁺ + OH⁻","أيون النحاس الثنائي يحتاج أيوني هيدروكسيد لتكوين الراسب الأزرق المتعادل","النحاس لا يترسب"],"reason":1},{"type":"tfr","q":"يُستخدم اللهب الأصفر المضيء في موقد بنزن لإجراء اختبار اللهب.","answer":false,"reasons":["لأن الأزرق يخفي الألوان","لأن اللهب الأصفر أبرد وأوضح","يجب استخدام اللهب الأزرق غير المضيء حتى يظهر لون العنصر بوضوح دون تداخل اللون الأصفر"],"reason":2},{"type":"tfr","q":"يمكن التمييز بين محلولي NH₄Cl و NaCl بإضافة NaOH(aq) والتسخين.","answer":true,"reasons":["لأن NH₄Cl يطلق غاز الأمونيا الذي يزرق تباع الشمس الحمراء الرطبة، بينما NaCl لا يتفاعل","لأن NaCl يطلق أمونيا","لأنهما يعطيان راسبًا أزرق"],"reason":0},{"type":"essay","q":"لديك 4 محاليل غير مُعنونة: CuSO₄، FeSO₄، Fe₂(SO₄)₃، و Al₂(SO₄)₃. كيف تميّز بينها باستخدام NaOH(aq) فقط؟","model":"نضيف NaOH(aq) لكل منها: الراسب الأزرق = CuSO₄، الأخضر = FeSO₄، البني المحمر = Fe₂(SO₄)₃، والأبيض الذي يذوب في الفائض = Al₂(SO₄)₃."},{"type":"essay","q":"لماذا يجب إضافة NaOH «قطرات قليلة أولًا» ثم «فائضًا» عند الكشف عن الكاتيونات؟","model":"لأن إضافة فائض فورًا قد تذيب راسب Al³⁺ أو Zn²⁺ بسرعة فلا نلاحظ تكوّن الراسب الأبيض في البداية."},{"type":"essay","q":"اكتب المعادلة الأيونية لتفاعل أيونات الأمونيوم مع أيونات الهيدروكسيد بالتسخين.","model":"NH₄⁺(aq) + OH⁻(aq) → NH₃(g) + H₂O(l)."}]}},
  {"id":"g9-chem-2-u9-5","grade":"g9","subject":"chemistry","term":2,"unit":9,"no":5,"title":"اختبارات الكشف عن الأنيونات (الأيونات السالبة)","summary":"شرح متحرك بـ SVG لاختبارات الكشف عن الأنيونات: الكربونات (CO₃²⁻)، الهاليدات (Cl⁻, Br⁻, I⁻)، الكبريتات (SO₄²⁻)، والنترات (NO₃⁻)، ثم أنشطة بثلاثة مستويات.","page":"lesson-tests-for-anions.html","video":"","pdf":"","notes":["الكربونات (CO₃²⁻): إضافة حمض مخفف ← فوران وغاز CO₂ يعكّر ماء الجير.","الهاليدات (Cl⁻, Br⁻, I⁻): إضافة HNO₃ مخفف ثم AgNO₃(aq) ← أبيض (AgCl)، كريمي (AgBr)، أصفر (AgI).","الكبريتات (SO₄²⁻): إضافة HCl أو HNO₃ مخفف ثم Ba(NO₃)₂ أو BaCl₂ ← راسب أبيض (BaSO₄).","النترات (NO₃⁻): إضافة NaOH(aq) + رقائق ألمنيوم + تسخين ← يتصاعد غاز NH₃ يزرّق تباع الشمس الحمراء الرطبة.","سبب التحميض قبل اختبار الهاليدات والكبريتات: التخلّص من أي أيونات كربونات قد تعطي راسبًا أبيض كاذبًا."],"exercises":["حدّد اسم الملح المجهول: أعطى راسبًا بنيًا محمرًا مع NaOH، وراسبًا أبيض مع BaCl₂ المحمّض.","علّل: يُمنع استخدام حمض الكبريتيك المخفف للتحميض في اختبار الكشف عن الكبريتات.","قارن بين اختبار الكشف عن أيون الأمونيوم NH₄⁺ واختبار الكشف عن أيون النترات NO₃⁻."],"levels":{"easy":[{"type":"mcq","q":"لون الراسب المتكوّن عند الكشف عن أيونات الكلوريد (Cl⁻) بنترات الفضة المحمّضة هو:","options":["أبيض","أصفر","أخضر","أزرق"],"answer":0,"why":"كلوريد الفضة AgCl راسب أبيض."},{"type":"mcq","q":"لون الراسب المتكوّن عند الكشف عن أيونات البروميد (Br⁻) بنترات الفضة المحمّضة هو:","options":["أزرق","كريمي (أبيض مصفر)","بني محمر","أخضر"],"answer":1,"why":"بروميد الفضة AgBr راسب كريمي."},{"type":"mcq","q":"يتكوّن راسب أبيض من كبريتات الباريوم (BaSO₄) عند الكشف عن أيون:","options":["الكربونات CO₃²⁻","النترات NO₃⁻","الكبريتات SO₄²⁻","اليوديد I⁻"],"answer":2,"why":"Ba²⁺ + SO₄²⁻ → BaSO₄(s)."},{"type":"mcq","q":"نستخدم رقائق الألمنيوم مع NaOH والتسخين للكشف عن أيون:","options":["الكربونات CO₃²⁻","الكلوريد Cl⁻","الكبريتات SO₄²⁻","النترات NO₃⁻"],"answer":3,"why":"هذا هو الاختبار القياسي لأيون النترات."}],"medium":[{"type":"mcq","q":"لماذا يُمنع استخدام حمض الكبريتيك (H₂SO₄) لتحميض العينة قبل إضافة كلوريد الباريوم؟","options":["لأنه يحتوي أيونات SO₄²⁻ فسيُكوّن راسبًا أبيض كاذبًا حتى لو خلت العينة من الكبريتات","لأنه لا يتفاعل مع الكربونات","لأنه مادة قلوية","لأنه يُذيب الباريوم"],"answer":0,"why":"إضافة H₂SO₄ تدخل أيونات SO₄²⁻ من الحمض نفسه."},{"type":"mcq","q":"أعطى ملح مجهول لهبًا أصفر ذهبيًا ساطعًا، وراسبًا أصفر مع HNO₃ + AgNO₃. الملح هو:","options":["كلوريد الصوديوم NaCl","يوديد الصوديوم NaI","كبريتات الصوديوم Na₂SO₄","يوديد البوتاسيوم KI"],"answer":1,"why":"اللهب الأصفر = Na⁺، والراسب الأصفر مع AgNO₃ = I⁻."},{"type":"mcq","q":"الهدف من إضافة حمض النيتريك المخفف قبل AgNO₃ عند فحص الهاليدات هو:","options":["ترسيب الصوديوم","زيادة لون الراسب","التخلّص من أي أيونات كربونات قد ترسّب كربونات الفضة البيضاء","منع تكون AgCl"],"answer":2,"why":"الحمض يفكك الكربونات إلى CO₂ فيمنع النتائج الإيجابية الكاذبة."},{"type":"tfr","q":"لا يمكن الكشف عن أيون النترات (NO₃⁻) بتكوين راسب لأن جميع أملاح النترات ذائبة في الماء.","answer":true,"reasons":["لذلك نختزله برقائق الألمنيوم و NaOH الساخن لإنتاج غاز الأمونيا","لأن النترات غير ذائبة","لأنها تكوّن راسبًا أصفر"],"reason":0},{"type":"tfr","q":"أعطى محلول فورانًا مع حمض HCl المخفف وعكّر الغاز ماء الجير؛ إذن الأنيون هو الكبريتات SO₄²⁻.","answer":false,"reasons":["بل الأنيون هو الكلوريد","بل الأنيون هو الكربونات CO₃²⁻ لأن الكربونات هي التي تطلق CO₂ مع الحمض","بل الأنيون هو النترات"],"reason":1},{"type":"essay","q":"حدّد هوية الملح المجهول (Y) إذا أعطى: (١) راسبًا أخضر مع NaOH، (٢) راسبًا أبيض مع HNO₃ + Ba(NO₃)₂.","model":"الراسب الأخضر مع NaOH يثبت وجود Fe²⁺، والراسب الأبيض مع الباريوم المحمّض يثبت وجود SO₄²⁻؛ إذن الملح (Y) هو «كبريتات الحديد (II) — FeSO₄»."},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لتكوّن راسب يوديد الفضة الأصفر.","model":"Ag⁺(aq) + I⁻(aq) → AgI(s)."}],"hard":[{"type":"mcq","q":"أضاف طالب HCl المخفف إلى ملح مجهول، ثم أضاف AgNO₃ فتكوّن راسب أبيض. هل يثبت ذلك وجود Cl⁻ في الملح؟","options":["نعم، ويثبت وجود الكبريتات","نعم، بالتأكيد","نعم، ويثبت وجود اليوديد","لا، لأن حمض HCl نفسه أضاف أيونات Cl⁻ في المحلول (نتيجة غير صالحة)"],"answer":3,"why":"استخدام HCl بدل HNO₃ يفسد اختبار الكلوريد بإدخال Cl⁻ خارجي."},{"type":"mcq","q":"ملح مجهول أعطى مع NaOH الساخن (دون ألمنيوم) غازًا يزرّق تباع الشمس، ومع HNO₃ + AgNO₃ أعطى راسبًا كريميًا. ما اسم الملح؟","options":["بروميد الأمونيوم NH₄Br","نترات الأمونيوم NH₄NO₃","كلوريد الأمونيوم NH₄Cl","بروميد الصوديوم NaBr"],"answer":0,"why":"الأمونيا بدون ألمنيوم = NH₄⁺، والراسب الكريمي مع AgNO₃ = Br⁻."},{"type":"mcq","q":"إذا كان محلول يحتوي على أيونات NH₄⁺ وأردت اختباره لاحقًا لأيونات NO₃⁻ برقائق الألمنيوم و NaOH، ما الخطوة اللازمة أولًا؟","options":["إضافة الألمنيوم فورًا","غلي المحلول مع NaOH حتى يتصاعد كل NH₃ الناتج من NH₄⁺، ثم إضافة رقائق الألمنيوم والتسخين مجددًا","إضافة نترات الفضة","إضافة حمض الكبريتيك"],"answer":1,"why":"حتى نتأكد أن الأمونيا الثانية ناتجة عن اختزال NO₃⁻ وليس من NH₄⁺ الأصلي."},{"type":"mcq","q":"أي زوج من الأيونات الآتية يعطي كلاهما راسبًا أبيض مع كاشفه المحمّض المخصّص؟","options":["NO₃⁻ و Cl⁻","I⁻ و Br⁻","Cl⁻ (مع AgNO₃) و SO₄²⁻ (مع Ba(NO₃)₂)","CO₃²⁻ و NO₃⁻"],"answer":2,"why":"AgCl راسب أبيض و BaSO₄ راسب أبيض."},{"type":"tfr","q":"يمكن التمييز بين محلولي NaCl و NaI بإضافة حمض النيتريك المخفف ثم محلول نترات الفضة.","answer":true,"reasons":["لأن NaI لا يترسب","لأنهما يعطيان نفس اللون","لأن NaCl يعطي راسبًا أبيض (AgCl) بينما NaI يعطي راسبًا أصفر (AgI)"],"reason":2},{"type":"tfr","q":"تُستخدم أملاح الباريوم الذائبة (مثل نترات الباريوم) في اختبار الكبريتات لأن BaSO₄ غير ذائب إطلاقًا في الماء والحمض.","answer":true,"reasons":["فيترسب BaSO₄ كراسب أبيض واضح ومؤكد لوجود SO₄²⁻","لأن BaSO₄ ذائب","لأن الباريوم يترسب مع النترات"],"reason":0},{"type":"tfr","q":"عند إضافة حمض النيتريك المخفف إلى كربونات الصوديوم تتكوّن فقاعات غاز الهيدروجين.","answer":false,"reasons":["تتكون فقاعات أكسجين","تتكوّن فقاعات غاز ثاني أكسيد الكربون CO₂ الذي يعكّر ماء الجير","لا يحدث تفاعل"],"reason":1},{"type":"essay","q":"صف كيف تتحقّق مخبريًا أن ملحًا أبيض مجهولًا هو «نترات البوتاسيوم KNO₃» وليس «كلوريد الصوديوم NaCl».","model":"١) اختبار اللهب: يعطي لهبًا ليلكيًا يثبت K⁺ (وليس أصفر Na⁺). ٢) اختبار الأنيون: نضيف HNO₃ + AgNO₃ فلا يتكون راسب أبيض (نفي Cl⁻)، ثم نضيف NaOH + رقائق ألمنيوم ونسخّن فيتصاعد غاز أمونيا يزرّق تباع الشمس الحمراء الرطبة (إثبات NO₃⁻)."},{"type":"essay","q":"لماذا يجب إجراء اختبار الكربونات (إضافة حمض مخفف) أو التحميض دائمًا قبل اختبار الكلوريد والكبريتات؟","model":"لأن أيونات الكربونات تتفاعل أيضًا مع أيونات الفضة والباريوم مكوّنة رواسب بيضاء (Ag₂CO₃ و BaCO₃) تشبه AgCl و BaSO₄، وإضافة الحمض تزيل الكربونات كغاز CO₂ فتمنع الخطأ."},{"type":"essay","q":"اكتب المعادلة الأيونية الصافية لكل من: (أ) اختبار الكبريتات، (ب) اختبار البروميد.","model":"أ) Ba²⁺(aq) + SO₄²⁻(aq) → BaSO₄(s). ب) Ag⁺(aq) + Br⁻(aq) → AgBr(s)."}]}},
  {"id":"g9-chem-2-u10-1","grade":"g9","subject":"chemistry","term":2,"unit":10,"no":1,"title":"غازات الغلاف الجوّي","summary":"شرح متحرك بـ SVG لمكونات الهواء الجاف النقي وفصلها بالتقطير التجزيئي للهواء المسال وملوثات الهواء والاحتباس الحراري والمحول الحفاز، ثم أنشطة بثلاثة مستويات.","page":"lesson-atmospheric-gases.html","video":"","pdf":"","notes":["مكونات الهواء الجاف النقي: 78% نيتروجين (N₂)، 21% أكسجين (O₂)، ~0.9% أرجون (Ar)، ~0.04% CO₂.","يُفصل الهواء صناعيًا بالتقطير التجزيئي للهواء المسال؛ يغلي N₂ عند −196°C قبل O₂ (−183°C).","أول أكسيد الكربون (CO): ينتج من الاحتراق غير الكامل للوقود، وهو غاز سام يقلل قدرة الدم على نقل الأكسجين.","ثاني أكسيد الكبريت (SO₂) وأكاسيد النيتروجين (NOₓ): تسبّب المطر الحمضي ومشكلات تنفسية.","المحوّل الحفّاز يحوّل الغازات الضارة: 2CO + 2NO → 2CO₂ + N₂."],"exercises":["اشرح كيف تُقاس نسبة الأكسجين في الهواء باستخدام محقنتين ونحاس ساخن.","قارن بين مصدر وأضرار كل من: CO، SO₂، و NOₓ.","اكتب المعادلة الموزونة للتفاعل الذي يحدث داخل المحوّل الحفّاز في السيارة."],"levels":{"easy":[{"type":"mcq","q":"الغاز الأكثر وفرةً في الغلاف الجوي للأرض هو:","options":["الأكسجين (21%)","النيتروجين (78%)","ثاني أكسيد الكربون (0.04%)","الأرجون (0.9%)"],"answer":1,"why":"يمثّل النيتروجين نحو 78% من الهواء الجاف."},{"type":"mcq","q":"أي الغازات الآتية يشكّل نحو 21% من الهواء الجاف النقي؟","options":["الميثان CH₄","النيتروجين N₂","الأكسجين O₂","الهيدروجين H₂"],"answer":2,"why":"نسبة الأكسجين في الهواء الجاف تقارب 21%."},{"type":"mcq","q":"الغاز السام الناتج عن الاحتراق غير الكامل للوقود هو:","options":["الأكسجين O₂","النيتروجين N₂","الأرجون Ar","أول أكسيد الكربون CO"],"answer":3,"why":"الاحتراق غير الكامل ينتج CO السام."},{"type":"mcq","q":"المبدأ الفيزيائي الذي يعتمد عليه التقطير التجزيئي للهواء المسال هو اختلاف الغازات في:","options":["درجة الغليان","اللون","الرائحة","الذوبان في الزيت"],"answer":0,"why":"يغلي النيتروجين عند −196°C والأكسجين عند −183°C."}],"medium":[{"type":"mcq","q":"لماذا تُعبّأ أكياس رقائق البطاطس بغاز النيتروجين (N₂)؟","options":["لأنه يساعد على الاحتراق","لأنه غاز خامل يمنع تأكسد الدهون وتلف الطعام","لأنه يرفع حموضة الطعام","لأنه يعطي لونًا أزرق"],"answer":1,"why":"النيتروجين غير نشط كيميائيًا فيحفظ الطعام طازجًا."},{"type":"mcq","q":"كيف تتكوّن أكاسيد النيتروجين (NOₓ) داخل محركات السيارات؟","options":["من صدأ الهيكل","من وجود النيتروجين في ماء التبريد","بتفاعل نيتروجين الهواء مع أكسجين الهواء عند درجات الحرارة العالية في المحرك","من إطارات السيارة"],"answer":2,"why":"الحرارة العالية في المحرك تكفي لكسر رابطة N₂ وتفاعله مع O₂."},{"type":"mcq","q":"أي زوج من الغازات الآتية يُعد المسبّب الرئيس لظاهرة المطر الحمضي؟","options":["CH₄ و He","N₂ و Ar","O₂ و H₂","SO₂ و NOₓ"],"answer":3,"why":"تذوب SO₂ و NO₂ في ماء المطر مكونةً أحماض الكبريتوز والنيتريك."},{"type":"tfr","q":"يجب انتظار تبريد الأنبوب حتى درجة حرارة الغرفة قبل قراءة الحجم النهائي في تجربة النحاس والهواء.","answer":true,"reasons":["لأن النحاس يذوب باردًا","لأن الهواء الساخن يكون متمددًا فيعطي قراءة حجم أكبر من الحقيقي ويقلل نسبة الأكسجين المحسوبة","لأن الأكسجين يعود للهواء"],"reason":1},{"type":"tfr","q":"يُعد غازا ثاني أكسيد الكربون والميثان من الغازات الدفيئة المسؤولة عن الاحتباس الحراري.","answer":true,"reasons":["لأنهما يسببان صدأ الحديد فقط","لأنهما يبردان الأرض","لأنهما يمتصان الأشعة تحت الحمراء الصادرة من الأرض ويعيدان إشعاعها نحوها"],"reason":2},{"type":"essay","q":"لماذا يُعد أول أكسيد الكربون (CO) غازًا شديد الخطورة على الإنسان؟","model":"لأنه غاز عديم اللون والرائحة (يصعب اكتشافه) ويرتبط بقوة بهيموجلوبين الدم فيمنعه من نقل الأكسجين إلى خلايا الجسم، ما قد يسبب الاختناق والوفاة."},{"type":"essay","q":"اذكر طريقتين عمليتين لتقليل انبعاثات الغازات المسبّبة للمطر الحمضي من السيارات ومحطات الطاقة.","model":"١) إزالة الكبريت من الوقود قبل حرقه أو معالجة غازات المداخن بأكسيد الكالسيوم لتقليل SO₂. ٢) تركيب المحوّل الحفّاز في عوادم السيارات لتحويل NO و CO إلى N₂ و CO₂."}],"hard":[{"type":"mcq","q":"في تجربة تمرير 80 cm³ من الهواء فوق نحاس ساخن حتى ثبات الحجم بعد التبريد، ما الحجم المتوقّع للهواء المتبقي؟","options":["نحو 63 cm³","نحو 17 cm³","نحو 80 cm³","نحو 40 cm³"],"answer":0,"why":"يُستهلك 21% من 80 cm³ (≈ 16.8 cm³)، فيبقى 80 − 16.8 ≈ 63 cm³."},{"type":"mcq","q":"في برج التقطير التجزيئي للهواء المسال، لماذا يُزال بخار الماء وثاني أكسيد الكربون «قبل» التبريد الشديد؟","options":["لأنهما يغليان قبل النيتروجين","لأنهما يتجمّدان إلى جليد وجليد جاف فيسدّان الأنابيب","لأنهما يتفاعلان مع الأرجون","لأنهما غير موجودين في الهواء"],"answer":1,"why":"تجمد H₂O عند 0°C و CO₂ عند −78°C يغلق أنابيب المصنع."},{"type":"mcq","q":"ما الغاز الذي يخرج «أولًا» من أعلى برج التقطير التجزيئي للهواء المسال (علما أن غليان N₂ = −196°C، Ar = −186°C، O₂ = −183°C)؟","options":["الأرجون Ar","الأكسجين O₂","النيتروجين N₂ (لأن درجة غليانه هي الأدنى)","تخرج جميعها معًا"],"answer":2,"why":"المادة ذات درجة الغليان الأدنى (−196°C) تتبخر أولًا عند التسخين التدريجي."},{"type":"mcq","q":"أي من الآتي يفسّر لماذا لا يُستخدم المحوّل الحفّاز لتقليل غاز ثاني أكسيد الكربون (CO₂)؟","options":["لأن السيارات لا تنتج CO₂","لأن CO₂ غاز سام أكثر من CO","لأن البلاتين يمتص CO₂","لأن المحوّل الحفّاز يُنتج CO₂ أصلًا عند أكسدة CO السام (2CO + 2NO → 2CO₂ + N₂)"],"answer":3,"why":"المحوّل الحفّاز يحوّل CO السام إلى CO₂ الأقل سمّية، لكنه لا يزيل CO₂."},{"type":"tfr","q":"تُستخدم فلزات انتقالية ثمينة كالبلاتين والروديوم في المحوّل الحفّاز لأنها تعمل كعوامل حفّازة تسرّع التفاعلات دون أن تُستهلك.","answer":true,"reasons":["وتُصمَّم على شكل قرص عسل ذي مساحة سطح كبيرة جدًّا لزيادة كفاءة التحويل","لأنها تذوب في العادم","لأنها تمنع خروج الغازات"],"reason":0},{"type":"tfr","q":"يؤدي استخدام الوقود المحتوي على الرصاص إلى «تسميم» المحوّل الحفّاز وإتلافه.","answer":true,"reasons":["لأن الرصاص ينشّط الحفاز","لأن الرصاص يغطّي سطح البلاتين الحفّاز ويمنع الغازات من التفاعل؛ لذا نستخدم بنزينًا خاليًا من الرصاص","لأن الرصاص يتبخر دون أثر"],"reason":1},{"type":"tfr","q":"الأرجون غاز نشط جدًّا يُستخدم في صناعة الأسمدة الزراعية.","answer":false,"reasons":["الأرجون يسبب المطر الحمضي","الأرجون يشكّل 78% من الهواء","الأرجون غاز نبيل خامل جدًّا (المجموعة ١٨)، أما النيتروجين فهو المستخدم في صناعة الأمونيا والأسمدة"],"reason":2},{"type":"essay","q":"اشرح خطوات فصل الأكسجين والنيتروجين من الهواء الجوي بالتقطير التجزيئي مع ذكر درجات الغليان.","model":"١) يُرشّح الهواء ويُزال منه بخار الماء و CO₂ لمنع انسداد الأنابيب. ٢) يُضغط ويُبرّد حتى −200°C فيتحول إلى سائل. ٣) يُسخّن تدريجيًا في برج التقطير: يتبخر النيتروجين أولًا عند −196°C ويُجمع من الأعلى، ثم الأرجون (−186°C)، ويبقى الأكسجين السائل ليغلي عند −183°C."},{"type":"essay","q":"لماذا يختلف حجم الغاز المتبقي في تجربة النحاس الساخن إذا لم يُستخدم «فائض» من النحاس؟","model":"إذا لم يوجد فائض من النحاس فقد لا يتفاعل كل الأكسجين الموجود في الهواء، فيبقى حجم الهواء أكبر من 79% وتكون نسبة الأكسجين المحسوبة أقل من 21%."},{"type":"essay","q":"اكتب المعادلة الرمزية الموزونة لتفاعل النحاس مع الأكسجين في تجربة قياس نسبة الأكسجين، واذكر التغيّر اللوني الملاحظ.","model":"2Cu(s) + O₂(g) → 2CuO(s). يتغيّر لون النحاس من البني المحمر اللامع إلى الأسود (أكسيد النحاس)."}]}},
  {"id":"g9-chem-2-u10-2","grade":"g9","subject":"chemistry","term":2,"unit":10,"no":2,"title":"مُنتجات من الأرض: الحجر الجيري","summary":"شرح متحرك بـ SVG لدورة الحجر الجيري (التفكك الحراري لكربونات الكالسيوم، الجير الحي، الجير المطفأ، وماء الجير) واستخداماتها في البناء والزراعة والصناعة، ثم أنشطة بثلاثة مستويات.","page":"lesson-limestone-products.html","video":"","pdf":"","notes":["الحجر الجيري يتكوّن أساسًا من كربونات الكالسيوم (CaCO₃).","التفكك الحراري (ماص للحرارة): CaCO₃(s) → CaO(s) + CO₂(g) (الجير الحي).","إطفاء الجير (طارد للحرارة): CaO(s) + H₂O(l) → Ca(OH)₂(s) (الجير المطفأ)، ومحلوله المائي هو «ماء الجير».","إغلاق الدورة: Ca(OH)₂(aq) + CO₂(g) → CaCO₃(s) + H₂O(l).","استخداماته: صناعة الإسمنت (مع الطين)، والخرسانة، والزجاج، وإزالة شوائب الحديد، ومعادلة حموضة التربة، وإزالة SO₂ من غازات المداخن."],"exercises":["ارسم أو اكتب دورة الحجر الجيري كاملةً مع المعادلات الرمزية الموزونة للخطوات الثلاث.","قارن بين تفاعل التفكك الحراري للحجر الجيري وتفاعل إضافة الماء للجير الحي من حيث امتصاص أو طرد الحرارة.","اذكر ميزتين وتحديين بيئيين لفتح محجر حجر جيري قرب منطقة سكنية."],"levels":{"easy":[{"type":"mcq","q":"الصيغة الكيميائية للحجر الجيري (كربونات الكالسيوم) هي:","options":["Ca(OH)₂","CaO","CaCO₃","CaCl₂"],"answer":2,"why":"الحجر الجيري يتكوّن أساسًا من كربونات الكالسيوم CaCO₃."},{"type":"mcq","q":"يُعرف هيدروكسيد الكالسيوم الصلب Ca(OH)₂ بالاسم الشائع:","options":["الجبس","الجير الحي","الحجر الجيري","الجير المطفأ"],"answer":3,"why":"Ca(OH)₂ الصلب هو الجير المطفأ، ومحلوله المائي هو ماء الجير."},{"type":"mcq","q":"الغاز المنطلق عند التفكك الحراري لكربونات الكالسيوم هو:","options":["ثاني أكسيد الكربون CO₂","الأكسجين O₂","الهيدروجين H₂","الأمونيا NH₃"],"answer":0,"why":"CaCO₃ → CaO + CO₂."},{"type":"mcq","q":"يُصنع الإسمنت بتسخين الحجر الجيري مع:","options":["الخشب","الطين","البلاستيك","الملح"],"answer":1,"why":"تسخين الحجر الجيري مع الطين ينتج الإسمنت."}],"medium":[{"type":"mcq","q":"أي التفاعلات الآتية في دورة الحجر الجيري يُعد تفاعلًا «طاردًا للحرارة» بقوة؟","options":["تبخر الماء","التفكك الحراري للحجر الجيري: CaCO₃ → CaO + CO₂","إضافة الماء إلى الجير الحي: CaO + H₂O → Ca(OH)₂","انصهار الجليد"],"answer":2,"why":"إطفاء الجير الحي بالماء يطلق حرارة وبخارًا بقوة."},{"type":"mcq","q":"يُستخدم أكسيد الكالسيوم أو كربونات الكالسيوم في مداخن محطات الكهرباء لإزالة غاز:","options":["الأرجون Ar","الأكسجين O₂","النيتروجين N₂","ثاني أكسيد الكبريت SO₂ الحمضي"],"answer":3,"why":"تعادل هذه القواعد غاز SO₂ الحمضي وتمنع المطر الحمضي."},{"type":"mcq","q":"كيف نحصل على «الخرسانة» المستخدمة في بناء الجسور والمنازل؟","options":["بخلط الإسمنت مع الرمل والحصى والماء","بتسخين الرمل وحده","بإذابة الجير في حمض","بتبريد الهواء"],"answer":0,"why":"الخرسانة خليط متين من الإسمنت والرمل والحصى والماء."},{"type":"tfr","q":"التفكك الحراري لكربونات الكالسيوم هو تفاعل «ماصّ للحرارة».","answer":true,"reasons":["لأنه يحدث في الثلاجة","لأنه ينطلق منه لهب","لأنه يتطلب تزويدًا مستمرًا بالحرارة العالية لكسر الروابط وتفكيك CaCO₃"],"reason":2},{"type":"tfr","q":"ماء الجير هو الاسم الشائع لمحلول أكسيد الكالسيوم الصلب غير الذائب.","answer":false,"reasons":["ماء الجير هو المحلول المائي الرائق لهيدروكسيد الكالسيوم Ca(OH)₂(aq)","ماء الجير هو حمض الكربونيك","ماء الجير هو CaCO₃ الذائب"],"reason":0},{"type":"essay","q":"علّل: يُفضّل المزارعون أحيانًا استخدام الحجر الجيري المسحوق (CaCO₃) على الجير الحي (CaO) لمعادلة التربة الحمضية.","model":"لأن الحجر الجيري أرخص وأكثر أمانًا في التعامل، ولا يذوب في الماء فلا يرفع قلوية التربة بشكل مفرط إذا أُضيف فائض منه، بخلاف CaO القلوي القوي."},{"type":"essay","q":"اذكر ثلاثة استخدامات صناعية رئيسة للحجر الجيري ومشتقاته.","model":"١) صناعة الإسمنت والخرسانة. ٢) صناعة الزجاج. ٣) إزالة الشوائب الحمضية (كالرمل SiO₂) في الفرن العالي لاستخلاص الحديد (أو معادلة التربة وإزالة SO₂)."}],"hard":[{"type":"mcq","q":"لماذا تساهم صناعة الإسمنت والجير الحي في زيادة ظاهرة الاحتباس الحراري؟","options":["لأنها تستهلك كل الأكسجين","لأن تفكك CaCO₃ وحرق الوقود لتسخين الأفران يطلقان كميات كبيرة من غاز CO₂","لأنها تنتج غاز الهيليوم","لأن الإسمنت يبرد الهواء"],"answer":1,"why":"ينتج CO₂ من التفكك الكيميائي لـ CaCO₃ ومن احتراق وقود الفرن معًا."},{"type":"mcq","q":"في الفرن العالي لاستخلاص الحديد، يتفاعل أكسيد الكالسيوم (القاعدي) مع الشوائب الرملية SiO₂ (الحمضية) لتكوين:","options":["حمض الكبريتيك","كربونات الكالسيوم","سيليكات الكالسيوم CaSiO₃ (الخبث)","الحديد النقي"],"answer":2,"why":"CaO + SiO₂ → CaSiO₃ (الخبث المنصهر الذي يطفو فوق الحديد ويُزال)."},{"type":"mcq","q":"ملاط البناء (المونة) يحتوي على الجير المطفأ Ca(OH)₂ ويتصلّب تدريجيًا عند تعرضه للهواء بسبب:","options":["تحوله إلى ماء","ذوبانه في الهواء","تفاعله مع النيتروجين","تفاعله البطيء مع CO₂ في الهواء ليعود إلى كربونات الكالسيوم الصلبة CaCO₃"],"answer":3,"why":"Ca(OH)₂ + CO₂ → CaCO₃ + H₂O يُكسب الملاط صلابة قوية."},{"type":"mcq","q":"إذا تفكّك 100 g من كربونات الكالسيوم النقية تفكّكًا حراريًا كاملًا فنتج 56 g من الجير الحي (CaO)، فما كتلة CO₂ المنطلق؟","options":["44 g","156 g","56 g","22 g"],"answer":0,"why":"بقانون حفظ الكتلة: 100 − 56 = 44 g من CO₂."},{"type":"tfr","q":"يُعد الحجر الجيري موردًا غير متجدد لكنه متوفر بكثرة في القشرة الأرضية، ويمكن إعادة تأهيل المحاجر بعد إغلاقها.","answer":true,"reasons":["لأن الحجر الجيري ينمو كل سنة كالأشجار","يمكن تحويل المحاجر المغلقة إلى بحيرات أو محميات طبيعية لتقليل الأثر البيئي","لأن المحاجر بلا أثر بيئي"],"reason":1},{"type":"tfr","q":"عند إضافة حمض الكبريتيك المخفف إلى قطعة حجر جيري، يتوقف التفاعل سريعًا نسبيًا مقارنةً بحمض HCl.","answer":true,"reasons":["لأن CaCl₂ غير ذائب","لأن حمض الكبريتيك لا يتفاعل مع الكربونات","لأن كبريتات الكالسيوم CaSO₄ الناتجة شحيحة الذوبان فتغطي سطح الحجر الجيري وتمنع استمرار التفاعل"],"reason":2},{"type":"tfr","q":"كربونات المغنيسيوم لا تتفكك حراريًا إطلاقًا بالتسخين.","answer":false,"reasons":["تتفكك كربونات الفلزات الأخرى (مثل MgCO₃ و CuCO₃) حراريًا أيضًا إلى أكسيد الفلز + CO₂","تتفكك لإنتاج الأكسجين فقط","تتحول إلى ذهب"],"reason":0},{"type":"essay","q":"قارن بين المزايا الاقتصادية والآثار البيئية لمحاجر الحجر الجيري، واقترح إجراءين لتقليل الأضرار البيئية.","model":"المزايا: توفير الإسمنت ومواد البناء، فرص عمل، دعم الصناعة المحلية. الأضرار: غبار وضوضاء، تدمير المواطن الطبيعية، انبعاث CO₂. الحلول: رش المياه وتركيب فلاتر للغبار، وتقليل الشاحنات أو نقلها بعيدًا عن السكان، وإعادة تشجير وتأهيل المحجر بعد انتهائه."},{"type":"essay","q":"اكتب المعادلات الرمزية الموزونة الثلاث التي تكوّن «دورة الحجر الجيري» كاملة مع رموز الحالة.","model":"١) CaCO₃(s) → CaO(s) + CO₂(g). ٢) CaO(s) + H₂O(l) → Ca(OH)₂(s). ٣) Ca(OH)₂(aq) + CO₂(g) → CaCO₃(s) + H₂O(l)."},{"type":"essay","q":"فسّر لماذا يتفاعل الجير المطفأ مع المطر الحمضي بينما لا يُنصح بتركه مكشوفًا في الهواء الرطب طويلًا.","model":"لأنه قاعدة قوية تتعادل مع الأحماض، وإذا تُرك مكشوفًا في الهواء يمتص غاز CO₂ تدريجيًا ويتحوّل إلى كربونات الكالسيوم الصلبة CaCO₃."}]}}
);
UNITS.push(
  {"id":"g9-chem-1-u1","grade":"g9","subject":"chemistry","term":1,"title":"الوحدة الأولى: طبيعة المادّة","levels":{"easy":[{"type":"mcq","q":"أي حالة من حالات المادة تكون جسيماتها متراصّة ومنتظمة وتهتز في مواضعها فقط؟","options":["الحالة السائلة","الحالة الصلبة","الحالة الغازية","المحاليل المائية"],"answer":1,"why":"في الصلب تهتز الجسيمات في مواقع ثابتة ومنتظمة."},{"type":"mcq","q":"يُسمّى تحوّل المادة من الحالة الصلبة إلى الغازية مباشرةً دون المرور بالسائلة:","options":["التكثّف","التجمّد","التسامي","الانصهار"],"answer":2,"why":"التسامي مثل تسامي اليود وثاني أكسيد الكربون الصلب."},{"type":"mcq","q":"لماذا تثبت درجة الحرارة أثناء انصهار قطعة جليد نقي رغم استمرار التسخين؟","options":["لأن الجليد لا يمتص حرارة","لأن التسخين توقف فجأة","لأن الكتلة تختفي","لأن الطاقة الحرارية تُستخدم في التغلّب على قوى التجاذب بين الجسيمات"],"answer":3,"why":"تُستهلك الطاقة في كسر قوى الترابط لا في رفع درجة الحرارة."},{"type":"mcq","q":"ما أثر وجود شوائب (كالملح) في عينة من الماء على درجتَي انصهاره وغليانه؟","options":["تُخفض درجة الانصهار وترفع درجة الغليان","ترفع الانصهار وتخفض الغليان","لا تؤثر أبدًا","تجعلهما متساويتين"],"answer":0,"why":"الشوائب تخفض درجة الانصهار وتمدّ نطاقها وترفع درجة الغليان."}],"medium":[{"type":"mcq","q":"في تجربة أنبوب الانتشار بين الأمونيا (Mr=17) وكلوريد الهيدروجين (Mr=36.5)، تتكوّن الحلقة البيضاء أقرب إلى طرف HCl لأن:","options":["جسيمات HCl أخفّ","جسيمات الأمونيا أخفّ فتنتشر أسرع وتقطع مسافةً أكبر","الأمونيا صلبة","الحرارة أعلى عند HCl"],"answer":1,"why":"الغاز ذو الكتلة الجزيئية الأصغر ينتشر بسرعة أكبر."},{"type":"mcq","q":"ما الفرق الصحيح بين التبخّر والغليان؟","options":["التبخّر عند ١٠٠°C فقط","الغليان من السطح فقط","التبخّر يحدث عند أي درجة ومن السطح فقط، والغليان عند درجة محددة وفي كل السائل","كلاهما نفس العملية تمامًا"],"answer":2,"why":"التبخر سطحي وفي أي درجة، والغليان شامل وعند درجة الغليان."},{"type":"mcq","q":"ما سبب ارتفاع ضغط الهواء داخل إطار سيارة متوقفة تحت شمس الصيف الحارة في عُمان؟","options":["يتحول الهواء إلى صلب","يزداد عدد الجسيمات داخل الإطار المغلق","تنخفض سرعة الجسيمات","تزداد طاقة حركة جسيمات الهواء فتزداد سرعة وتكرار تصادماتها بجدار الإطار"],"answer":3,"why":"ارتفاع الحرارة يزيد طاقة الحركة ومعدل التصادمات مع الجدار."},{"type":"tfr","q":"تزداد سرعة الانتشار في الغازات والسوائل عند رفع درجة الحرارة.","answer":true,"reasons":["تقل سرعة الانتشار","لأن ارتفاع الحرارة يزيد الطاقة الحركية وسرعة حركة الجسيمات","لا تتأثر بالحرارة"],"reason":1},{"type":"tfr","q":"قيمة معامل الإعاقة (Rf) في الكروماتوجرافيا تكون دائمًا أصغر من ١.","answer":true,"reasons":["تكون أكبر من ١ دائمًا","تساوي ١٠ دائمًا","لأن البقعة لا يمكن أن تقطع مسافةً أكبر من مسافة المذيب نفسه"],"reason":2}],"hard":[{"type":"mcq","q":"أي الغازات الآتية ينتشر بأسرع معدل عند نفس درجة الحرارة؟ (H₂=2, CH₄=16, O₂=32, CO₂=44)","options":["الهيدروجين H₂","الميثان CH₄","الأكسجين O₂","ثاني أكسيد الكربون CO₂"],"answer":0,"why":"H₂ له أصغر كتلة جزيئية نسبية (Mr = 2) فينتشر أسرع."},{"type":"mcq","q":"كيف تتحقّق مخبريًا من أن عينة ماء نقية تمامًا؟","options":["بلونها فقط","بقياس درجة غليانها (١٠٠°C بالضبط) أو تجمدها (٠°C بالضبط)","بطعمها فقط","بحجمها فقط"],"answer":1,"why":"الماء النقي يغلي عند ١٠٠°C بالضبط ويتجمد عند ٠°C بالضبط."},{"type":"mcq","q":"تنتقل رائحة البخور في غرفة ساكنة الهواء من الركن إلى باقي الغرفة بعملية:","options":["التكثّف","التقطير","الانتشار","الترشيح"],"answer":2,"why":"الانتشار هو حركة الجسيمات العشوائية من التركيز الأعلى للأقل."},{"type":"essay","q":"قارن بين الصلب والسائل والغاز من حيث: ترتيب الجسيمات، حركة الجسيمات، وقابلية الانضغاط.","model":"الصلب: متراص منتظم، اهتزاز موضعي، غير قابل للانضغاط. السائل: متقارب غير منتظم، انزلاق، صعب الانضغاط جدًا. الغاز: متباعد عشوائي، حركة سريعة، سهل الانضغاط."},{"type":"essay","q":"فسّر علميًا لماذا تكوّنت حلقة كلوريد الأمونيوم البيضاء أقرب إلى طرف حمض HCl في تجربة انتشار الغازات.","model":"لأن الكتلة الجزيئية للأمونيا (NH₃ = 17) أصغر من كلوريد الهيدروجين (HCl = 36.5)، فتتحرك جسيمات الأمونيا وتنتشر أسرع وتقطع مسافةً أكبر قبل الالتقاء."}]},"test":[{"type":"mcq","q":"أي حالة من حالات المادة تكون جسيماتها متراصّة ومنتظمة وتهتز في مواضعها فقط؟","options":["الحالة السائلة","الحالة الصلبة","الحالة الغازية","المحاليل المائية"],"answer":1,"why":"في الصلب تهتز الجسيمات في مواقع ثابتة ومنتظمة."},{"type":"mcq","q":"يُسمّى تحوّل المادة من الحالة الصلبة إلى الغازية مباشرةً دون المرور بالسائلة:","options":["التكثّف","التجمّد","التسامي","الانصهار"],"answer":2,"why":"التسامي مثل تسامي اليود وثاني أكسيد الكربون الصلب."},{"type":"mcq","q":"لماذا تثبت درجة الحرارة أثناء انصهار قطعة جليد نقي رغم استمرار التسخين؟","options":["لأن الجليد لا يمتص حرارة","لأن التسخين توقف فجأة","لأن الكتلة تختفي","لأن الطاقة الحرارية تُستخدم في التغلّب على قوى التجاذب بين الجسيمات"],"answer":3,"why":"تُستهلك الطاقة في كسر قوى الترابط لا في رفع درجة الحرارة."},{"type":"mcq","q":"ما أثر وجود شوائب (كالملح) في عينة من الماء على درجتَي انصهاره وغليانه؟","options":["تُخفض درجة الانصهار وترفع درجة الغليان","ترفع الانصهار وتخفض الغليان","لا تؤثر أبدًا","تجعلهما متساويتين"],"answer":0,"why":"الشوائب تخفض درجة الانصهار وتمدّ نطاقها وترفع درجة الغليان."},{"type":"mcq","q":"في تجربة أنبوب الانتشار بين الأمونيا (Mr=17) وكلوريد الهيدروجين (Mr=36.5)، تتكوّن الحلقة البيضاء أقرب إلى طرف HCl لأن:","options":["جسيمات HCl أخفّ","جسيمات الأمونيا أخفّ فتنتشر أسرع وتقطع مسافةً أكبر","الأمونيا صلبة","الحرارة أعلى عند HCl"],"answer":1,"why":"الغاز ذو الكتلة الجزيئية الأصغر ينتشر بسرعة أكبر."},{"type":"mcq","q":"ما الفرق الصحيح بين التبخّر والغليان؟","options":["التبخّر عند ١٠٠°C فقط","الغليان من السطح فقط","التبخّر يحدث عند أي درجة ومن السطح فقط، والغليان عند درجة محددة وفي كل السائل","كلاهما نفس العملية تمامًا"],"answer":2,"why":"التبخر سطحي وفي أي درجة، والغليان شامل وعند درجة الغليان."},{"type":"mcq","q":"ما سبب ارتفاع ضغط الهواء داخل إطار سيارة متوقفة تحت شمس الصيف الحارة في عُمان؟","options":["يتحول الهواء إلى صلب","يزداد عدد الجسيمات داخل الإطار المغلق","تنخفض سرعة الجسيمات","تزداد طاقة حركة جسيمات الهواء فتزداد سرعة وتكرار تصادماتها بجدار الإطار"],"answer":3,"why":"ارتفاع الحرارة يزيد طاقة الحركة ومعدل التصادمات مع الجدار."},{"type":"mcq","q":"أي الغازات الآتية ينتشر بأسرع معدل عند نفس درجة الحرارة؟ (H₂=2, CH₄=16, O₂=32, CO₂=44)","options":["الهيدروجين H₂","الميثان CH₄","الأكسجين O₂","ثاني أكسيد الكربون CO₂"],"answer":0,"why":"H₂ له أصغر كتلة جزيئية نسبية (Mr = 2) فينتشر أسرع."},{"type":"mcq","q":"كيف تتحقّق مخبريًا من أن عينة ماء نقية تمامًا؟","options":["بلونها فقط","بقياس درجة غليانها (١٠٠°C بالضبط) أو تجمدها (٠°C بالضبط)","بطعمها فقط","بحجمها فقط"],"answer":1,"why":"الماء النقي يغلي عند ١٠٠°C بالضبط ويتجمد عند ٠°C بالضبط."},{"type":"mcq","q":"تنتقل رائحة البخور في غرفة ساكنة الهواء من الركن إلى باقي الغرفة بعملية:","options":["التكثّف","التقطير","الانتشار","الترشيح"],"answer":2,"why":"الانتشار هو حركة الجسيمات العشوائية من التركيز الأعلى للأقل."},{"type":"mcq","q":"أي حالة من حالات المادة قابلة للانضغاط بسهولة كبيرة؟","options":["السوائل","المواد الصلبة","الفلزات","الغازات (لوجود مسافات شاسعة بين جسيماتها)"],"answer":3,"why":"المسافات البينية الكبيرة في الغازات تسمح بضغطها بسهولة."},{"type":"mcq","q":"ما الطريقة الأنسب لفصل خليط من الإيثانول (غليانه ٧٨°C) والماء (غليانه ١٠٠°C)؟","options":["التقطير التجزيئي","الترشيح","التبلور","الفرز اليدوي"],"answer":0,"why":"سائلان ممتزجان مختلفان في درجة الغليان يُفصلان بالتقطير التجزيئي."},{"type":"tf","q":"تثبت درجة حرارة المادة النقية أثناء عمليتَي الانصهار والغليان.","answer":true,"why":"لأن الطاقة المكتسبة تُستهلك في التغلب على قوى التجاذب بين الجسيمات"},{"type":"tf","q":"تنتشر جسيمات الغاز الأثقل (ذات الكتلة الجزيئية الأكبر) أسرع من جسيمات الغاز الأخف.","answer":false,"why":"العكس تمامًا: الجسيمات الأخفّ تنتشر أسرع عند نفس درجة الحرارة"},{"type":"tf","q":"وجود الشوائب في مادة صلبة يؤدي إلى خفض درجة انصهارها وجعلها تنصهر على مدى حراري.","answer":true,"why":"لذا تُستخدم درجة الانصهار الحادة اختبارًا لنقاء المواد"},{"type":"tf","q":"يحدث التبخّر في جميع أجزاء السائل وعند درجة حرارة ثابتة فقط.","answer":false,"why":"هذا وصف الغليان؛ أما التبخّر فيحدث من السطح فقط وعند أي درجة حرارة"},{"type":"tfr","q":"تزداد سرعة الانتشار في الغازات والسوائل عند رفع درجة الحرارة.","answer":true,"reasons":["تقل سرعة الانتشار","لأن ارتفاع الحرارة يزيد الطاقة الحركية وسرعة حركة الجسيمات","لا تتأثر بالحرارة"],"reason":1},{"type":"tfr","q":"قيمة معامل الإعاقة (Rf) في الكروماتوجرافيا تكون دائمًا أصغر من ١.","answer":true,"reasons":["تكون أكبر من ١ دائمًا","تساوي ١٠ دائمًا","لأن البقعة لا يمكن أن تقطع مسافةً أكبر من مسافة المذيب نفسه"],"reason":2},{"type":"tfr","q":"يمكن فصل الملح الذائب في الماء باستخدام ورقة الترشيح فقط.","answer":false,"reasons":["الأيونات الذائبة صغيرة جدًا فتمر عبر مسام ورقة الترشيح؛ نفصله بالتبلور أو التقطير","نعم بالترشيح فقط","يبقى الملح فوق ورقة الترشيح"],"reason":0},{"type":"tfr","q":"في الكروماتوجرافيا، المادة الأكثر ذوبانًا في المذيب تقطع مسافةً أبعد على الورقة.","answer":true,"reasons":["تبقى عند خط البداية","فيكون لها قيمة Rf أكبر من المادة الأقل ذوبانًا","تتجه للأسفل"],"reason":1},{"type":"essay","q":"قارن بين الصلب والسائل والغاز من حيث: ترتيب الجسيمات، حركة الجسيمات، وقابلية الانضغاط.","model":"الصلب: متراص منتظم، اهتزاز موضعي، غير قابل للانضغاط. السائل: متقارب غير منتظم، انزلاق، صعب الانضغاط جدًا. الغاز: متباعد عشوائي، حركة سريعة، سهل الانضغاط."},{"type":"essay","q":"فسّر علميًا لماذا تكوّنت حلقة كلوريد الأمونيوم البيضاء أقرب إلى طرف حمض HCl في تجربة انتشار الغازات.","model":"لأن الكتلة الجزيئية للأمونيا (NH₃ = 17) أصغر من كلوريد الهيدروجين (HCl = 36.5)، فتتحرك جسيمات الأمونيا وتنتشر أسرع وتقطع مسافةً أكبر قبل الالتقاء."},{"type":"essay","q":"اشرح أثر إضافة الملح على درجتَي تجمّد وغليان الماء النقي، مع ذكر تطبيق حياتي واحد.","model":"الملح شائبة فيخفض درجة التجمّد (أقل من ٠°C) ويرفع درجة الغليان (أعلى من ١٠٠°C). التطبيق: رشّ الملح على الطرق الجليدية لمنع تجمد الماء وإذابة الجليد."},{"type":"essay","q":"ارسم بالكلمات شكل منحنى التسخين للماء من −١٠°C إلى ١١٠°C موضحًا سبب الجزأين الأفقيين.","model":"يرتفع المنحنى حتى ٠°C ثم يثبت أفقيًا أثناء الانصهار، ثم يرتفع حتى ١٠٠°C ويثبت أفقيًا أثناء الغليان ثم يرتفع للبخار؛ وسبب الثبات استهلاك الحرارة في التغلب على قوى التجاذب."},{"type":"essay","q":"فسّر باستخدام نظرية الجسيمات لماذا يزداد ضغط الغاز المحبوس داخل أسطوانة عند تقليل حجمها بثبات الحرارة.","model":"بتقليل الحجم تتقارب الجسيمات في مساحة أصغر فتزداد عدد تصادماتها مع جدران الأسطوانة في الثانية الواحدة، فيرتفع الضغط."}]},
  {"id":"g9-chem-1-u2","grade":"g9","subject":"chemistry","term":1,"title":"الوحدة الثانية: التركيب الذري","levels":{"easy":[{"type":"mcq","q":"أي مما يأتي يُعدّ «عنصرًا» يتكوّن من جزيئات ثنائية الذرة؟","options":["ثاني أكسيد الكربون CO₂","الماء H₂O","غاز الأكسجين O₂","ملح الطعام NaCl"],"answer":2,"why":"O₂ يتكون من نوع واحد من الذرات (أكسجين) مرتبطتين معًا."},{"type":"mcq","q":"عند تسخين خليط من برادة الحديد ومسحوق الكبريت بشدة يتكوّن كبريتيد الحديد (FeS)؛ ما الدليل على أنه أصبح «مركّبًا»؟","options":["تبقى ألوانه منفصلة","يبقى الحديد منجذبًا للمغناطيس","يذوب الحديد في الماء","تتغير خصائصه ولا ينجذب للمغناطيس ولا يُفصل بطرق فيزيائية"],"answer":3,"why":"فقدان الخواص الأصلية (المغناطيسية) دليل تكوّن مركّب جديد."},{"type":"mcq","q":"يُصنّف «الهواء الجوي» علميًا على أنه:","options":["مخلوط من عدة غازات (عناصر ومركبات)","عنصر نقي","مركّب كيميائي واحد","سبيكة فلزية"],"answer":0,"why":"الهواء خليط من N₂ و O₂ و Ar و CO₂ بنسب متغيرة دون اتحاد كيميائي."},{"type":"mcq","q":"ما الفرق بين الرمزين CO و Co في الكيمياء؟","options":["كلاهما نفس العنصر","CO مركّب (أول أكسيد الكربون)، أما Co فعنصر (الكوبالت)","كلاهما مركب","CO عنصر و Co مركب"],"answer":1,"why":"الحرف الثاني الكبير يعني عنصرًا ثانيًا (مركّب)، والصغير تابع للأول (عنصر)."}],"medium":[{"type":"mcq","q":"أي العبارات الآتية تصف «المركّب الكيميائي» بدقة؟","options":["يُفصل بالترشيح بسهولة","تحتفظ عناصره بخصائصها الأصلية","يتكوّن من عنصرين أو أكثر متحدين كيميائيًا بنسب ثابتة وخصائصه مختلفة عن عناصره","يتكوّن بنسب عشوائية متغيرة"],"answer":2,"why":"الاتحاد الكيميائي يثبّت النسب ويولّد خصائص جديدة تمامًا."},{"type":"mcq","q":"أي المواد الآتية يُعدّ «مخلوطًا» وليس مركّبًا؟","options":["كلوريد الصوديوم (NaCl)","الماء المقطّر (H₂O)","السكر النقي","ماء البحر"],"answer":3,"why":"ماء البحر مخلوط من ماء وأملاح ذائبة يمكن فصلها بالتقطير."},{"type":"mcq","q":"توجد الغازات النبيلة مثل الهيليوم (He) والنيون (Ne) في الطبيعة على هيئة:","options":["ذرات منفردة (أحادية الذرة)","جزيئات ثنائية الذرة","بلورات أيونية","مركبات معقدة"],"answer":0,"why":"الغازات النبيلة مستقرة فتوجد كذرات منفردة."},{"type":"tfr","q":"كتابة الحرف الثاني كبيرًا في الرمز الكيميائي (مثل CO بدل Co) تغيّر المعنى من عنصر إلى مركّب.","answer":true,"reasons":["كلاهما صحيح للكوبالت","لا فرق بينهما","CO أول أكسيد الكربون (مركب)، بينما Co عنصر الكوبالت"],"reason":2},{"type":"tfr","q":"كتلة الإلكترون النسبية تساوي ١ وهي مساوية لكتلة البروتون.","answer":false,"reasons":["بل كتلته ضئيلة جدًا (١/١٨٤٠) مقارنة بكتلة البروتون والنيوترون (=١)","نعم متساويتان","الإلكترون أثقل من البروتون"],"reason":0}],"hard":[{"type":"mcq","q":"ما الطريقة التي يمكن بها فصل الهيدروجين والأكسجين في مركّب الماء (H₂O)؟","options":["الترشيح","طريقة كيميائية مثل التحليل الكهربائي","التقطير البسيط","المغناطيس"],"answer":1,"why":"المركبات لا تُفصل إلى عناصرها إلا بطرق كيميائية."},{"type":"mcq","q":"جزيء الميثان (CH₄) يتكوّن من:","options":["٤ ذرات كربون وذرة هيدروجين","٥ ذرات كربون","ذرة كربون واحدة و٤ ذرات هيدروجين (مركّب)","عنصر واحد فقط"],"answer":2,"why":"يحتوي عنصرين مختلفين (C و H) بنسبة ١ : ٤."},{"type":"mcq","q":"أي خاصية تميّز «المخلوط» عن «المركّب»؟","options":["نسبه ثابتة لا تتغير","تتحد مكوناته بروابط كيميائية","له درجة انصهار ثابتة وحادة دائمًا","تُفصل مكونات المخلوط بطرق فيزيائية وتبقى خواصها كما هي"],"answer":3,"why":"المخلوط لا يحدث فيه تفاعل كيميائي."},{"type":"essay","q":"قارن في جدول بين «المركّب» و«المخلوط» من حيث: الاتحاد الكيميائي، النسب، الخصائص، وطريقة الفصل.","model":"المركب: اتحاد كيميائي، نسب ثابتة، خصائص جديدة، يُفصل كيميائيًا فقط. المخلوط: بلا اتحاد، أي نسب، يحتفظ بخصائص مكوناته، يُفصل فيزيائيًا."},{"type":"essay","q":"صنّف المواد الآتية إلى عنصر أو مركّب أو مخلوط: النحاس (Cu)، ثاني أكسيد الكربون (CO₂)، الهواء، ماء البحر، غاز النيتروجين (N₂).","model":"عنصر: النحاس، غاز النيتروجين. مركّب: ثاني أكسيد الكربون. مخلوط: الهواء، ماء البحر."}]},"test":[{"type":"mcq","q":"أي مما يأتي يُعدّ «عنصرًا» يتكوّن من جزيئات ثنائية الذرة؟","options":["ثاني أكسيد الكربون CO₂","الماء H₂O","غاز الأكسجين O₂","ملح الطعام NaCl"],"answer":2,"why":"O₂ يتكون من نوع واحد من الذرات (أكسجين) مرتبطتين معًا."},{"type":"mcq","q":"عند تسخين خليط من برادة الحديد ومسحوق الكبريت بشدة يتكوّن كبريتيد الحديد (FeS)؛ ما الدليل على أنه أصبح «مركّبًا»؟","options":["تبقى ألوانه منفصلة","يبقى الحديد منجذبًا للمغناطيس","يذوب الحديد في الماء","تتغير خصائصه ولا ينجذب للمغناطيس ولا يُفصل بطرق فيزيائية"],"answer":3,"why":"فقدان الخواص الأصلية (المغناطيسية) دليل تكوّن مركّب جديد."},{"type":"mcq","q":"يُصنّف «الهواء الجوي» علميًا على أنه:","options":["مخلوط من عدة غازات (عناصر ومركبات)","عنصر نقي","مركّب كيميائي واحد","سبيكة فلزية"],"answer":0,"why":"الهواء خليط من N₂ و O₂ و Ar و CO₂ بنسب متغيرة دون اتحاد كيميائي."},{"type":"mcq","q":"ما الفرق بين الرمزين CO و Co في الكيمياء؟","options":["كلاهما نفس العنصر","CO مركّب (أول أكسيد الكربون)، أما Co فعنصر (الكوبالت)","كلاهما مركب","CO عنصر و Co مركب"],"answer":1,"why":"الحرف الثاني الكبير يعني عنصرًا ثانيًا (مركّب)، والصغير تابع للأول (عنصر)."},{"type":"mcq","q":"أي العبارات الآتية تصف «المركّب الكيميائي» بدقة؟","options":["يُفصل بالترشيح بسهولة","تحتفظ عناصره بخصائصها الأصلية","يتكوّن من عنصرين أو أكثر متحدين كيميائيًا بنسب ثابتة وخصائصه مختلفة عن عناصره","يتكوّن بنسب عشوائية متغيرة"],"answer":2,"why":"الاتحاد الكيميائي يثبّت النسب ويولّد خصائص جديدة تمامًا."},{"type":"mcq","q":"أي المواد الآتية يُعدّ «مخلوطًا» وليس مركّبًا؟","options":["كلوريد الصوديوم (NaCl)","الماء المقطّر (H₂O)","السكر النقي","ماء البحر"],"answer":3,"why":"ماء البحر مخلوط من ماء وأملاح ذائبة يمكن فصلها بالتقطير."},{"type":"mcq","q":"توجد الغازات النبيلة مثل الهيليوم (He) والنيون (Ne) في الطبيعة على هيئة:","options":["ذرات منفردة (أحادية الذرة)","جزيئات ثنائية الذرة","بلورات أيونية","مركبات معقدة"],"answer":0,"why":"الغازات النبيلة مستقرة فتوجد كذرات منفردة."},{"type":"mcq","q":"ما الطريقة التي يمكن بها فصل الهيدروجين والأكسجين في مركّب الماء (H₂O)؟","options":["الترشيح","طريقة كيميائية مثل التحليل الكهربائي","التقطير البسيط","المغناطيس"],"answer":1,"why":"المركبات لا تُفصل إلى عناصرها إلا بطرق كيميائية."},{"type":"mcq","q":"جزيء الميثان (CH₄) يتكوّن من:","options":["٤ ذرات كربون وذرة هيدروجين","٥ ذرات كربون","ذرة كربون واحدة و٤ ذرات هيدروجين (مركّب)","عنصر واحد فقط"],"answer":2,"why":"يحتوي عنصرين مختلفين (C و H) بنسبة ١ : ٤."},{"type":"mcq","q":"أي خاصية تميّز «المخلوط» عن «المركّب»؟","options":["نسبه ثابتة لا تتغير","تتحد مكوناته بروابط كيميائية","له درجة انصهار ثابتة وحادة دائمًا","تُفصل مكونات المخلوط بطرق فيزيائية وتبقى خواصها كما هي"],"answer":3,"why":"المخلوط لا يحدث فيه تفاعل كيميائي."},{"type":"mcq","q":"الرمز الكيميائي الصحيح لعنصر الصوديوم هو:","options":["Na","NA","So","S"],"answer":0,"why":"الحرف الأول كبير والثاني صغير: Na (من اللاتينية Natrium)."},{"type":"mcq","q":"ما الشحنة النسبية والكتلة النسبية للنيوترون؟","options":["الشحنة +1 والكتلة 0","الشحنة 0 والكتلة النسبية 1","الشحنة -1 والكتلة 1/1840","الشحنة +1 والكتلة 1"],"answer":1,"why":"النيوترون متعادل الشحنة وكتلته النسبية ١ داخل النواة."},{"type":"tf","q":"المركّب الكيميائي يحتفظ بنفس خصائص العناصر التي تكوّن منها.","answer":false,"why":"بل تختلف خصائصه تمامًا عن عناصره (كالماء H₂O مقارنةً بـ H₂ و O₂)"},{"type":"tf","q":"يمكن فصل برادة الحديد عن الكبريت بالمغناطيس قبل التسخين، لكن لا يمكن ذلك بعد التسخين وتكوّن FeS.","answer":true,"why":"لأنه تحوّل من مخلوط فيزيائي إلى مركّب كيميائي جديد"},{"type":"tf","q":"الهواء الجوي مركّب كيميائي له صيغة كيميائية ثابتة.","answer":false,"why":"بل هو مخلوط من عدة غازات (نيتروجين وأكسجين وأرجون وCO₂)"},{"type":"tf","q":"الجزيء قد يكون جزيء عنصر (مثل O₂) أو جزيء مركّب (مثل CO₂).","answer":true,"why":"المهم أن يتكون من ذرتين أو أكثر مرتبطتين معًا"},{"type":"tfr","q":"كتابة الحرف الثاني كبيرًا في الرمز الكيميائي (مثل CO بدل Co) تغيّر المعنى من عنصر إلى مركّب.","answer":true,"reasons":["كلاهما صحيح للكوبالت","لا فرق بينهما","CO أول أكسيد الكربون (مركب)، بينما Co عنصر الكوبالت"],"reason":2},{"type":"tfr","q":"كتلة الإلكترون النسبية تساوي ١ وهي مساوية لكتلة البروتون.","answer":false,"reasons":["بل كتلته ضئيلة جدًا (١/١٨٤٠) مقارنة بكتلة البروتون والنيوترون (=١)","نعم متساويتان","الإلكترون أثقل من البروتون"],"reason":0},{"type":"tfr","q":"تتشابه نظائر العنصر الواحد في التفاعلات الكيميائية لأن لها نفس عدد الإلكترونات.","answer":true,"reasons":["تختلف تمامًا في التفاعلات","فالاختلاف في النيوترونات يؤثر في الكتلة لا في السلوك الكيميائي","لها نفس عدد النيوترونات"],"reason":1},{"type":"tfr","q":"العدد الكتلي يساوي مجموع عدد البروتونات والنيوترونات في النواة.","answer":true,"reasons":["يساوي البروتونات + الإلكترونات","يساوي عدد الإلكترونات فقط","ولذلك عدد النيوترونات = العدد الكتلي − العدد الذري"],"reason":2},{"type":"essay","q":"قارن في جدول بين «المركّب» و«المخلوط» من حيث: الاتحاد الكيميائي، النسب، الخصائص، وطريقة الفصل.","model":"المركب: اتحاد كيميائي، نسب ثابتة، خصائص جديدة، يُفصل كيميائيًا فقط. المخلوط: بلا اتحاد، أي نسب، يحتفظ بخصائص مكوناته، يُفصل فيزيائيًا."},{"type":"essay","q":"صنّف المواد الآتية إلى عنصر أو مركّب أو مخلوط: النحاس (Cu)، ثاني أكسيد الكربون (CO₂)، الهواء، ماء البحر، غاز النيتروجين (N₂).","model":"عنصر: النحاس، غاز النيتروجين. مركّب: ثاني أكسيد الكربون. مخلوط: الهواء، ماء البحر."},{"type":"essay","q":"اشرح تجربة الحديد والكبريت قبل التسخين وبعده لتوضيح الفرق بين المخلوط والمركّب.","model":"قبل التسخين: مخلوط يُرى فيه الأصفر والرمادي وينجذب الحديد للمغناطيس. بعد التسخين: تفاعل كيميائي ينتج مركب كبريتيد الحديد الأسود (FeS) الذي لا ينجذب للمغناطيس."},{"type":"essay","q":"لماذا يُعدّ ملح الطعام (NaCl) آمنًا للأكل رغم أن الصوديوم فلز نشط خطر والكلور غاز سام؟","model":"لأنه مركّب كيميائي ناتج عن اتحاد كيميائي، والمركبات تكتسب خصائص جديدةً تمامًا تختلف عن خصائص عناصرها الأصلية."},{"type":"essay","q":"ميّز بين «الذرة» و«الجزيء» مع ذكر مثال لجزيء عنصر ومثال لجزيء مركّب.","model":"الذرة أصغر وحدة للعنصر، والجزيء ذرتان أو أكثر مرتبطتان معًا. جزيء عنصر: O₂ أو H₂. جزيء مركّب: H₂O أو CO₂."}]},
  {"id":"g9-chem-1-u3","grade":"g9","subject":"chemistry","term":1,"title":"الوحدة الثالثة: الجدول الدوري","levels":{"easy":[{"type":"mcq","q":"على أي أساس تُرتّب العناصر في الجدول الدوري الحديث؟","options":["حسب الكتلة الذرية فقط","حسب الكثافة","حسب الترتيب الأبجدي","تصاعديًا حسب العدد الذري (عدد البروتونات)"],"answer":3,"why":"الترتيب الحديث يقوم على العدد الذري التصاعدي."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة الأولى (الفلزات القلوية)، فإن النشاط الكيميائي:","options":["يزداد (البوتاسيوم أنشط من الصوديوم والليثيوم)","يقلّ تدريجيًا","يبقى ثابتًا","ينعدم تمامًا"],"answer":0,"why":"يزداد نصف القطر فيسهل فقد الإلكترون الخارجي فيزداد النشاط."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة السابعة (الهالوجينات)، فإن النشاط الكيميائي:","options":["يتحول إلى غاز نبيل","يقلّ (الفلور والكلور أنشط من البروم واليود)","يبقى ثابتًا","يزداد بشدة"],"answer":1,"why":"الذرة الأصغر في الأعلى تجذب الإلكترون بقوة أكبر فتكون أنشط."},{"type":"mcq","q":"ما الحالة الفيزيائية واللون لـ«البروم (Br₂)» عند درجة حرارة الغرفة؟","options":["صلب رمادي داكن","غاز أصفر مخضر","سائل بني محمر","غاز عديم اللون"],"answer":2,"why":"الكلور غاز أصفر مخضر، البروم سائل بني محمر، اليود صلب رمادي داكن."}],"medium":[{"type":"mcq","q":"أُضيف ماء الكلور إلى محلول بروميد البوتاسيوم (KBr) فتغيّر اللون إلى البرتقالي لأن:","options":["البروم أنشط من الكلور","تكون غاز الهيدروجين","لم يحدث تفاعل","الكلور أنشط من البروم فيحلّ محله ويطرد البروم (Br₂)"],"answer":3,"why":"الهالوجين الأكثر نشاطًا يطرد الأقل نشاطًا من محلول ملحه."},{"type":"mcq","q":"لماذا يُستخدم «الهيليوم» بدلًا من «الهيدروجين» في ملء المناطيد الهوائية؟","options":["لأن الهيليوم خامل غير قابل للاشتعال مع كونه قليل الكثافة، بينما الهيدروجين شديد الاشتعال","لأن الهيليوم أثقل من الهواء","لأن الهيدروجين غاز نبيل","لأن الهيليوم سائل"],"answer":0,"why":"الأمان والخمول الكيميائي هما ميزة الهيليوم الكبرى."},{"type":"mcq","q":"لماذا يُملأ مصباح الفتيل المتوهج بغاز «الأرجون» بدلًا من الهواء؟","options":["لأنه أثقل من الحديد","لأنه غاز نبيل خامل يمنع تأكسد واحتراق فتيل التنجستن الساخن","لأنه يبرّد المصباح إلى ٠°C","لأنه يتفاعل مع الفتيل ليعطي ضوءًا"],"answer":1,"why":"الأرجون يوفر وسطًا خاملًا يحمي الفتيل من الأكسجين."},{"type":"tfr","q":"استخدم مندليف الفراغات في جدوله للتنبؤ بخصائص عناصر لم تكن مكتشفةً بعد.","answer":true,"reasons":["ولما اكتُشفت لاحقًا (كالجاليوم والجرمانيوم) طابقت توقعاته بدقة مذهلة","لم يترك أي فراغات","رتّبها أبجديًا"],"reason":0},{"type":"tfr","q":"في الدورة الواحدة يكون لجميع العناصر نفس عدد مستويات الطاقة المشغولة.","answer":true,"reasons":["لها نفس عدد إلكترونات التكافؤ","فجميع عناصر الدورة الثالثة لها ٣ مستويات طاقة","لها نفس العدد الذري"],"reason":1}],"hard":[{"type":"mcq","q":"أي خاصية مما يأتي «تميّز العناصر الانتقالية» عن فلزات المجموعة الأولى؟","options":["انخفاض كثافتها وطَفوها على الماء","ليونتها وسهولة قطعها بالسكين","تكوين مركّبات ملوّنة وتعدد الشحنات والعمل كعوامل حفّازة","تفاعلها العنيف مع الماء البارد"],"answer":2,"why":"الانتقالية صلبة وكثيفة وملوّنة المركبات وحفّازة."},{"type":"mcq","q":"ما الغاز المتصاعد عند وضع قطعة صغيرة من الصوديوم في الماء؟","options":["غاز الأكسجين (O₂)","ثاني أكسيد الكربون","غاز الكلور (Cl₂)","غاز الهيدروجين (H₂) ويتكوّن محلول قلوي (NaOH)"],"answer":3,"why":"2Na + 2H₂O → 2NaOH + H₂."},{"type":"mcq","q":"أي لافلز يُعدّ استثناءً مهمًا لأنه «يوصل الكهرباء»؟","options":["الجرافيت (الكربون)","الكبريت","اليود","الفوسفور"],"answer":0,"why":"الجرافيت لافلز موصل للكهرباء لوجود إلكترونات حرة متحركة."},{"type":"essay","q":"قارن في جدول بين «فلزات المجموعة الأولى (القلوية)» و«العناصر الانتقالية» من حيث: الصلابة والكثافة، لون المركبات، والنشاط مع الماء.","model":"المجموعة الأولى: لينة منخفضة الكثافة، مركباتها بيضاء عديمة اللون، تتفاعل بشدة مع الماء البارد. الانتقالية: صلبة عالية الكثافة والانصهار، مركباتها ملوّنة، لا تتفاعل مع الماء البارد (أو بطيئة جدًا) وتعمل كحفازات."},{"type":"essay","q":"توقّع ما يحدث عند إضافة ماء الكلور إلى محلول يوديد البوتاسيوم (KI) مع كتابة المعادلة اللفظية والرمزية.","model":"يتغير لون المحلول إلى البني الداكن بسبب تحرّر اليود لأن الكلور أنشط من اليود. كلور + يوديد البوتاسيوم ← كلوريد البوتاسيوم + يود. Cl₂ + 2KI → 2KCl + I₂."}]},"test":[{"type":"mcq","q":"على أي أساس تُرتّب العناصر في الجدول الدوري الحديث؟","options":["حسب الكتلة الذرية فقط","حسب الكثافة","حسب الترتيب الأبجدي","تصاعديًا حسب العدد الذري (عدد البروتونات)"],"answer":3,"why":"الترتيب الحديث يقوم على العدد الذري التصاعدي."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة الأولى (الفلزات القلوية)، فإن النشاط الكيميائي:","options":["يزداد (البوتاسيوم أنشط من الصوديوم والليثيوم)","يقلّ تدريجيًا","يبقى ثابتًا","ينعدم تمامًا"],"answer":0,"why":"يزداد نصف القطر فيسهل فقد الإلكترون الخارجي فيزداد النشاط."},{"type":"mcq","q":"عند النزول من الأعلى إلى الأسفل في المجموعة السابعة (الهالوجينات)، فإن النشاط الكيميائي:","options":["يتحول إلى غاز نبيل","يقلّ (الفلور والكلور أنشط من البروم واليود)","يبقى ثابتًا","يزداد بشدة"],"answer":1,"why":"الذرة الأصغر في الأعلى تجذب الإلكترون بقوة أكبر فتكون أنشط."},{"type":"mcq","q":"ما الحالة الفيزيائية واللون لـ«البروم (Br₂)» عند درجة حرارة الغرفة؟","options":["صلب رمادي داكن","غاز أصفر مخضر","سائل بني محمر","غاز عديم اللون"],"answer":2,"why":"الكلور غاز أصفر مخضر، البروم سائل بني محمر، اليود صلب رمادي داكن."},{"type":"mcq","q":"أُضيف ماء الكلور إلى محلول بروميد البوتاسيوم (KBr) فتغيّر اللون إلى البرتقالي لأن:","options":["البروم أنشط من الكلور","تكون غاز الهيدروجين","لم يحدث تفاعل","الكلور أنشط من البروم فيحلّ محله ويطرد البروم (Br₂)"],"answer":3,"why":"الهالوجين الأكثر نشاطًا يطرد الأقل نشاطًا من محلول ملحه."},{"type":"mcq","q":"لماذا يُستخدم «الهيليوم» بدلًا من «الهيدروجين» في ملء المناطيد الهوائية؟","options":["لأن الهيليوم خامل غير قابل للاشتعال مع كونه قليل الكثافة، بينما الهيدروجين شديد الاشتعال","لأن الهيليوم أثقل من الهواء","لأن الهيدروجين غاز نبيل","لأن الهيليوم سائل"],"answer":0,"why":"الأمان والخمول الكيميائي هما ميزة الهيليوم الكبرى."},{"type":"mcq","q":"لماذا يُملأ مصباح الفتيل المتوهج بغاز «الأرجون» بدلًا من الهواء؟","options":["لأنه أثقل من الحديد","لأنه غاز نبيل خامل يمنع تأكسد واحتراق فتيل التنجستن الساخن","لأنه يبرّد المصباح إلى ٠°C","لأنه يتفاعل مع الفتيل ليعطي ضوءًا"],"answer":1,"why":"الأرجون يوفر وسطًا خاملًا يحمي الفتيل من الأكسجين."},{"type":"mcq","q":"أي خاصية مما يأتي «تميّز العناصر الانتقالية» عن فلزات المجموعة الأولى؟","options":["انخفاض كثافتها وطَفوها على الماء","ليونتها وسهولة قطعها بالسكين","تكوين مركّبات ملوّنة وتعدد الشحنات والعمل كعوامل حفّازة","تفاعلها العنيف مع الماء البارد"],"answer":2,"why":"الانتقالية صلبة وكثيفة وملوّنة المركبات وحفّازة."},{"type":"mcq","q":"ما الغاز المتصاعد عند وضع قطعة صغيرة من الصوديوم في الماء؟","options":["غاز الأكسجين (O₂)","ثاني أكسيد الكربون","غاز الكلور (Cl₂)","غاز الهيدروجين (H₂) ويتكوّن محلول قلوي (NaOH)"],"answer":3,"why":"2Na + 2H₂O → 2NaOH + H₂."},{"type":"mcq","q":"أي لافلز يُعدّ استثناءً مهمًا لأنه «يوصل الكهرباء»؟","options":["الجرافيت (الكربون)","الكبريت","اليود","الفوسفور"],"answer":0,"why":"الجرافيت لافلز موصل للكهرباء لوجود إلكترونات حرة متحركة."},{"type":"mcq","q":"لماذا يُحفظ الصوديوم والبوتاسيوم تحت طبقة من الزيت (البرافين)؟","options":["لزيادة كثافتهما","لمنع تفاعلهما السريع مع أكسجين ورطوبة الهواء","لتغيير لونهما","لإذابتهما في الزيت"],"answer":1,"why":"الزيت يعزلهما عن الهواء والماء."},{"type":"mcq","q":"ما السبب الأساسي لتكرار الخصائص الكيميائية بانتظام في الجدول الدوري؟","options":["تساوي الكتل الذرية","تساوي عدد النيوترونات","تكرار عدد إلكترونات المستوى الخارجي (التكافؤ) في بداية كل دورة","تشابه ألوان العناصر"],"answer":2,"why":"إلكترونات التكافؤ هي التي تتحكم في السلوك الكيميائي."},{"type":"tf","q":"تقع الفلزات على يسار ووسط الجدول الدوري، بينما تقع اللافلزات على يمينه.","answer":true,"why":"ويفصل بينهما خط متعرج يضم أشباه الفلزات كالسيليكون"},{"type":"tf","q":"يزداد النشاط الكيميائي بالنزول لأسفل في كلٍّ من المجموعة الأولى والمجموعة السابعة معًا.","answer":false,"why":"يزداد للأسفل في المجموعة الأولى، لكنه «يقلّ» للأسفل في المجموعة السابعة!"},{"type":"tf","q":"يمكن لليود (I₂) أن يحل محل الكلور في محلول كلوريد الصوديوم (NaCl).","answer":false,"why":"لا يحدث تفاعل لأن اليود أقل نشاطًا من الكلور"},{"type":"tf","q":"تتميّز العناصر الانتقالية بصلابتها وكثافتها العالية وتكوينها لمركبات ملوّنة.","answer":true,"why":"مثل أملاح النحاس الزرقاء وأملاح الحديد الخضراء والبنية"},{"type":"tfr","q":"استخدم مندليف الفراغات في جدوله للتنبؤ بخصائص عناصر لم تكن مكتشفةً بعد.","answer":true,"reasons":["ولما اكتُشفت لاحقًا (كالجاليوم والجرمانيوم) طابقت توقعاته بدقة مذهلة","لم يترك أي فراغات","رتّبها أبجديًا"],"reason":0},{"type":"tfr","q":"في الدورة الواحدة يكون لجميع العناصر نفس عدد مستويات الطاقة المشغولة.","answer":true,"reasons":["لها نفس عدد إلكترونات التكافؤ","فجميع عناصر الدورة الثالثة لها ٣ مستويات طاقة","لها نفس العدد الذري"],"reason":1},{"type":"tfr","q":"يزداد حجم الذرة كلما نزلنا إلى أسفل في المجموعة الواحدة.","answer":true,"reasons":["يقل حجم الذرة للأسفل","يبقى ثابتًا","بسبب زيادة عدد مستويات الطاقة حول النواة"],"reason":2},{"type":"tfr","q":"تُعدّ عناصر المجموعة الرابعة (الكربون والسيليكون) الأقل في درجة الانصهار في دورتيها.","answer":false,"reasons":["بل هي «الأعلى» في درجة الانصهار بسبب تراكيبها التساهمية الضخمة","نعم الأقل","تساوي صفرًا"],"reason":0},{"type":"essay","q":"قارن في جدول بين «فلزات المجموعة الأولى (القلوية)» و«العناصر الانتقالية» من حيث: الصلابة والكثافة، لون المركبات، والنشاط مع الماء.","model":"المجموعة الأولى: لينة منخفضة الكثافة، مركباتها بيضاء عديمة اللون، تتفاعل بشدة مع الماء البارد. الانتقالية: صلبة عالية الكثافة والانصهار، مركباتها ملوّنة، لا تتفاعل مع الماء البارد (أو بطيئة جدًا) وتعمل كحفازات."},{"type":"essay","q":"توقّع ما يحدث عند إضافة ماء الكلور إلى محلول يوديد البوتاسيوم (KI) مع كتابة المعادلة اللفظية والرمزية.","model":"يتغير لون المحلول إلى البني الداكن بسبب تحرّر اليود لأن الكلور أنشط من اليود. كلور + يوديد البوتاسيوم ← كلوريد البوتاسيوم + يود. Cl₂ + 2KI → 2KCl + I₂."},{"type":"essay","q":"صف تدرّج الحالة الفيزيائية واللون ودرجة الغليان والنشاط الكيميائي عند النزول لأسفل في المجموعة السابعة (Cl₂ → Br₂ → I₂).","model":"الحالة: غاز ← سائل ← صلب. اللون يغمق: أصفر مخضر ← بني محمر ← رمادي داكن. درجة الغليان: تزداد. النشاط الكيميائي: يقلّ."},{"type":"essay","q":"اذكر استخدامين صناعيين للغازات النبيلة وفسّر ارتباط كل استخدام بخصائصها.","model":"١) الهيليوم في المناطيد: كثافته منخفضة جدًا وخامل غير قابل للاشتعال. ٢) الأرجون في مصابيح الفتيل واللحام: خامل يمنع تأكسد الفلز الساخن."},{"type":"essay","q":"كيف تتغير خصائص العناصر عند الانتقال عبر الدورة الثالثة من اليسار (Na) إلى اليمين (Ar)؟","model":"تتدرج من فلزات نشطة (Na, Mg, Al) ← شبه فلز (Si) ← لافلزات (P, S, Cl) ← غاز نبيل خامل (Ar)، وتتحول الأكاسيد من قاعدية إلى مترددة إلى حمضية."}]},
  {"id":"g9-chem-1-u4","grade":"g9","subject":"chemistry","term":1,"title":"الوحدة الرابعة: الروابط الكيميائيّة","levels":{"easy":[{"type":"mcq","q":"أي المركّبات الآتية يحتوي على «رابطة أيونية»؟","options":["أكسيد المغنيسيوم (MgO)","ثاني أكسيد الكربون (CO₂)","الميثان (CH₄)","الأمونيا (NH₃)"],"answer":0,"why":"المغنيسيوم فلز والأكسجين لافلز ← رابطة أيونية."},{"type":"mcq","q":"لماذا «لا يوصل» كلوريد الصوديوم الصلب الكهرباء، بينما يوصلها عند إذابته في الماء أو صهره؟","options":["لأنه يحتوي إلكترونات حرة فقط في الماء","لأن الأيونات في الصلب مقيدة الحركة، وتصبح حرة الحركة عند الصهر أو الذوبان","لأن الماء يحوله إلى فلز","لأن الروابط التساهمية تنكسر"],"answer":1,"why":"شرط التوصيل الكهربائي وجود جسيمات مشحونة حرة الحركة."},{"type":"mcq","q":"ما نوع الرابطة بين ذرتَي النيتروجين في جزيء (N₂)؟","options":["رابطة تساهمية أحادية","رابطة أيونية","رابطة تساهمية ثلاثية (٣ أزواج مشتركة)","رابطة فلزية"],"answer":2,"why":"كل ذرة نيتروجين (٢، ٥) تحتاج ٣ إلكترونات فتتشاركان بثلاثة أزواج (N≡N)."},{"type":"mcq","q":"لماذا تكون درجة غليان غاز الميثان (CH₄) منخفضةً جدًا (−١٦١°C)؟","options":["لأنه مركب أيوني","لضعف الرابطة التساهمية بين C و H","لأنه فلز قلوي","لضعف قوى التجاذب «بين» جزيئات الميثان التساهمية البسيطة"],"answer":3,"why":"الروابط داخل الجزيء قوية، لكن القوى بين الجزيئات ضعيفة جدًا."}],"medium":[{"type":"mcq","q":"ما الذي يفسّر «قابلية الفلزات للطرق والسحب» دون أن تتكسّر؟","options":["انزلاق طبقات الأيونات الموجبة فوق بعضها مع بقاء بحر الإلكترونات ممسكًا بها","وجود فراغات فارغة بدون روابط","تكون روابط تساهمية","عدم وجود أيونات موجبة"],"answer":0,"why":"الرابطة الفلزية غير اتجاهية فتسمح بانزلاق الطبقات."},{"type":"mcq","q":"كم زوجًا من الإلكترونات تتشارك به ذرتا الأكسجين في جزيء الأكسجين (O₂)؟","options":["زوج واحد","زوجان (رابطة تساهمية ثنائية O=O)","ثلاثة أزواج","لا تتشاركان"],"answer":1,"why":"كل ذرة أكسجين (٢، ٦) تحتاج إلكترونين فتتشاركان بزوجين."},{"type":"mcq","q":"لماذا لا يوصل محلول السكر في الماء التيار الكهربائي؟","options":["لأنه لا يذوب في الماء","لأنه فلز","لأنه مركب تساهمي لا يحتوي على أيونات أو إلكترونات حرة الحركة","لأنه مادة صلبة"],"answer":2,"why":"غياب الأيونات الحرة يمنع التوصيل الكهربائي."},{"type":"tfr","q":"في جزيء ثاني أكسيد الكربون (CO₂) ترتبط ذرة الكربون بكل ذرة أكسجين برابطة تساهمية ثنائية (O=C=O).","answer":true,"reasons":["برابطة أيونية","لأن الكربون يحتاج ٤ إلكترونات وكل أكسجين يحتاج إلكترونين","برابطة أحادية فقط"],"reason":1},{"type":"tfr","q":"في الصيغة الكيميائية، إذا تساوى تكافؤ الأيونين (مثل Ca²⁺ و O²⁻) نكتبهما Ca₂O₂ دون تبسيط.","answer":false,"reasons":["تُكتب CaO₂","نعم لا نبسّط","بل نبسّط النسبة لأبسط صورة فتُكتب CaO"],"reason":2}],"hard":[{"type":"mcq","q":"ما نوع الرابطة الكيميائية في جزيء الأمونيا (NH₃)؟","options":["فلزية","أيونية","تساهمية ثلاثية","تساهمية أحادية بين النيتروجين وكل ذرة هيدروجين"],"answer":3,"why":"كلاهما لافلز، وتتشارك ذرة N بزوج مع كل ذرة H."},{"type":"mcq","q":"تنشأ الرابطة الأيونية نتيجة:","options":["قوة تجاذب كهروستاتيكي قوية بين الأيونات الموجبة والسالبة","مشاركة إلكترونات بين لافلزين","بحر إلكترونات حرة في فلز","تجاذب نيوترونات"],"answer":0,"why":"انتقال الإلكترونات يولّد أيونات متعاكسة الشحنة تتجاذب بقوة."},{"type":"mcq","q":"مادة صلبة درجة انصهارها ٨٠٠°C، تذوب في الماء، توصل الكهرباء مصهورة ولا توصلها صلبة. نوع ترابطها هو:","options":["ترابط تساهمي بسيط","ترابط أيوني","ترابط فلزي","غاز نبيل"],"answer":1,"why":"هذه الخصائص الثلاث هي البصمة الكاملة للمركب الأيوني."},{"type":"essay","q":"قارن في جدول بين المركّبات الأيونية والجزيئات التساهمية البسيطة من حيث: نوع العناصر، درجة الانصهار، والتوصيل الكهربائي.","model":"الأيونية: فلز+لافلز، انصهار عالٍ جدًا، توصل مصهورة/محلولًا ولا توصل صلبة. التساهمية البسيطة: لافلز+لافلز، انصهار منخفض، لا توصل في أي حالة."},{"type":"essay","q":"صف تكوّن الرابطة الأيونية في أكسيد المغنيسيوم (MgO) بدلالة انتقال الإلكترونات وشحنات الأيونات.","model":"تفقد ذرة المغنيسيوم (٢،٨،٢) إلكترونين فتصبح Mg²⁺ (٢،٨)، وتكتسبهما ذرة الأكسجين (٢،٦) فتصبح O²⁻ (٢،٨)، فتتجاذب الأيونات بقوة كهروستاتيكية مكوّنةً MgO."}]},"test":[{"type":"mcq","q":"أي المركّبات الآتية يحتوي على «رابطة أيونية»؟","options":["أكسيد المغنيسيوم (MgO)","ثاني أكسيد الكربون (CO₂)","الميثان (CH₄)","الأمونيا (NH₃)"],"answer":0,"why":"المغنيسيوم فلز والأكسجين لافلز ← رابطة أيونية."},{"type":"mcq","q":"لماذا «لا يوصل» كلوريد الصوديوم الصلب الكهرباء، بينما يوصلها عند إذابته في الماء أو صهره؟","options":["لأنه يحتوي إلكترونات حرة فقط في الماء","لأن الأيونات في الصلب مقيدة الحركة، وتصبح حرة الحركة عند الصهر أو الذوبان","لأن الماء يحوله إلى فلز","لأن الروابط التساهمية تنكسر"],"answer":1,"why":"شرط التوصيل الكهربائي وجود جسيمات مشحونة حرة الحركة."},{"type":"mcq","q":"ما نوع الرابطة بين ذرتَي النيتروجين في جزيء (N₂)؟","options":["رابطة تساهمية أحادية","رابطة أيونية","رابطة تساهمية ثلاثية (٣ أزواج مشتركة)","رابطة فلزية"],"answer":2,"why":"كل ذرة نيتروجين (٢، ٥) تحتاج ٣ إلكترونات فتتشاركان بثلاثة أزواج (N≡N)."},{"type":"mcq","q":"لماذا تكون درجة غليان غاز الميثان (CH₄) منخفضةً جدًا (−١٦١°C)؟","options":["لأنه مركب أيوني","لضعف الرابطة التساهمية بين C و H","لأنه فلز قلوي","لضعف قوى التجاذب «بين» جزيئات الميثان التساهمية البسيطة"],"answer":3,"why":"الروابط داخل الجزيء قوية، لكن القوى بين الجزيئات ضعيفة جدًا."},{"type":"mcq","q":"ما الذي يفسّر «قابلية الفلزات للطرق والسحب» دون أن تتكسّر؟","options":["انزلاق طبقات الأيونات الموجبة فوق بعضها مع بقاء بحر الإلكترونات ممسكًا بها","وجود فراغات فارغة بدون روابط","تكون روابط تساهمية","عدم وجود أيونات موجبة"],"answer":0,"why":"الرابطة الفلزية غير اتجاهية فتسمح بانزلاق الطبقات."},{"type":"mcq","q":"كم زوجًا من الإلكترونات تتشارك به ذرتا الأكسجين في جزيء الأكسجين (O₂)؟","options":["زوج واحد","زوجان (رابطة تساهمية ثنائية O=O)","ثلاثة أزواج","لا تتشاركان"],"answer":1,"why":"كل ذرة أكسجين (٢، ٦) تحتاج إلكترونين فتتشاركان بزوجين."},{"type":"mcq","q":"لماذا لا يوصل محلول السكر في الماء التيار الكهربائي؟","options":["لأنه لا يذوب في الماء","لأنه فلز","لأنه مركب تساهمي لا يحتوي على أيونات أو إلكترونات حرة الحركة","لأنه مادة صلبة"],"answer":2,"why":"غياب الأيونات الحرة يمنع التوصيل الكهربائي."},{"type":"mcq","q":"ما نوع الرابطة الكيميائية في جزيء الأمونيا (NH₃)؟","options":["فلزية","أيونية","تساهمية ثلاثية","تساهمية أحادية بين النيتروجين وكل ذرة هيدروجين"],"answer":3,"why":"كلاهما لافلز، وتتشارك ذرة N بزوج مع كل ذرة H."},{"type":"mcq","q":"تنشأ الرابطة الأيونية نتيجة:","options":["قوة تجاذب كهروستاتيكي قوية بين الأيونات الموجبة والسالبة","مشاركة إلكترونات بين لافلزين","بحر إلكترونات حرة في فلز","تجاذب نيوترونات"],"answer":0,"why":"انتقال الإلكترونات يولّد أيونات متعاكسة الشحنة تتجاذب بقوة."},{"type":"mcq","q":"مادة صلبة درجة انصهارها ٨٠٠°C، تذوب في الماء، توصل الكهرباء مصهورة ولا توصلها صلبة. نوع ترابطها هو:","options":["ترابط تساهمي بسيط","ترابط أيوني","ترابط فلزي","غاز نبيل"],"answer":1,"why":"هذه الخصائص الثلاث هي البصمة الكاملة للمركب الأيوني."},{"type":"mcq","q":"ما الجسيمات المسؤولة عن توصيل الكهرباء في «أسلاك النحاس»؟","options":["الأيونات الموجبة المتحركة","النيوترونات","الإلكترونات الحرة (غير المتمركزة)","الجزيئات المتعادلة"],"answer":2,"why":"في الفلزات توصل الإلكترونات الحرة الكهرباء، أما في الأيونية المصهورة فتوصّلها الأيونات."},{"type":"mcq","q":"ما الصيغة الكيميائية الصحيحة لمركّب «هيدروكسيد الكالسيوم» (Ca²⁺ و OH⁻)؟","options":["Ca(OH)","CaOH₂","Ca₂OH","Ca(OH)₂"],"answer":3,"why":"تكافؤ الكالسيوم ٢ فنضع مجموعة الهيدروكسيد بين قوسين مع الرقم ٢."},{"type":"tf","q":"المركّبات الأيونية توصل التيار الكهربائي في الحالة الصلبة والمصهورة على حدٍّ سواء.","answer":false,"why":"لا توصل في الحالة الصلبة لأن أيوناتها مقيدة، وتوصل فقط مصهورةً أو مذابةً"},{"type":"tf","q":"السبب في انخفاض درجة غليان الماء والميثان هو ضعف الروابط التساهمية داخل الجزيء.","answer":false,"why":"بل بسبب ضعف «قوى التجاذب بين الجزيئات»، أما الروابط التساهمية داخل الجزيء فقوية جدًا!"},{"type":"tf","q":"تنشأ الرابطة التساهمية بين ذرات اللافلزات عبر المشاركة بأزواج الإلكترونات.","answer":true,"why":"مثل H₂O و CO₂ و CH₄ و Cl₂"},{"type":"tf","q":"تتكون الرابطة الفلزية من تجاذب بين شبكة الأيونات الموجبة وبحر الإلكترونات الحرة.","answer":true,"why":"وهو ما يفسر التوصيل الكهربائي والحراري والقابلية للطرق والسحب"},{"type":"tfr","q":"في جزيء ثاني أكسيد الكربون (CO₂) ترتبط ذرة الكربون بكل ذرة أكسجين برابطة تساهمية ثنائية (O=C=O).","answer":true,"reasons":["برابطة أيونية","لأن الكربون يحتاج ٤ إلكترونات وكل أكسجين يحتاج إلكترونين","برابطة أحادية فقط"],"reason":1},{"type":"tfr","q":"في الصيغة الكيميائية، إذا تساوى تكافؤ الأيونين (مثل Ca²⁺ و O²⁻) نكتبهما Ca₂O₂ دون تبسيط.","answer":false,"reasons":["تُكتب CaO₂","نعم لا نبسّط","بل نبسّط النسبة لأبسط صورة فتُكتب CaO"],"reason":2},{"type":"tfr","q":"يجب وضع أقواس حول المجموعة الأيونية عند تكرارها أكثر من مرة في الصيغة مثل Mg(NO₃)₂.","answer":true,"reasons":["حتى يشمل الرقم السفلي جميع ذرات المجموعة الأيونية","لا حاجة للأقواس أبدًا","تُوضع الأقواس حول الفلز فقط"],"reason":0},{"type":"tfr","q":"الرقم الروماني في «أكسيد الحديد (III)» يدل على عدد ذرات الحديد في الصيغة.","answer":false,"reasons":["نعم يدل على عدد الذرات","بل يدل على شحنة/تكافؤ أيون الحديد (+3)، وصيغته Fe₂O₃","يدل على عدد ذرات الأكسجين"],"reason":1},{"type":"essay","q":"قارن في جدول بين المركّبات الأيونية والجزيئات التساهمية البسيطة من حيث: نوع العناصر، درجة الانصهار، والتوصيل الكهربائي.","model":"الأيونية: فلز+لافلز، انصهار عالٍ جدًا، توصل مصهورة/محلولًا ولا توصل صلبة. التساهمية البسيطة: لافلز+لافلز، انصهار منخفض، لا توصل في أي حالة."},{"type":"essay","q":"صف تكوّن الرابطة الأيونية في أكسيد المغنيسيوم (MgO) بدلالة انتقال الإلكترونات وشحنات الأيونات.","model":"تفقد ذرة المغنيسيوم (٢،٨،٢) إلكترونين فتصبح Mg²⁺ (٢،٨)، وتكتسبهما ذرة الأكسجين (٢،٦) فتصبح O²⁻ (٢،٨)، فتتجاذب الأيونات بقوة كهروستاتيكية مكوّنةً MgO."},{"type":"essay","q":"فسّر لماذا يوصل الفلز (النحاس) الكهرباء وهو صلب، بينما لا يوصل الملح (NaCl) الكهرباء وهو صلب.","model":"النحاس به إلكترونات حرة متحركة حتى وهو صلب؛ أما NaCl الصلب فأيوناته مقيدة في الشبكة البلورية ولا تتحرك إلا بالصهر أو الذوبان."},{"type":"essay","q":"بيّن نوع وعدد الروابط التساهمية في كل جزيء: (أ) H₂O، (ب) O₂، (ج) N₂.","model":"(أ) H₂O: رابطتان تساهميتان أحاديتان. (ب) O₂: رابطة تساهمية ثنائية. (ج) N₂: رابطة تساهمية ثلاثية."},{"type":"essay","q":"لماذا يُعدّ كلوريد الهيدروجين (HCl) غازًا عند درجة حرارة الغرفة بينما كلوريد الصوديوم (NaCl) صلب ينصهر عند ٨٠١°C؟","model":"HCl جزيء تساهمي بسيط قوى التجاذب بين جزيئاته ضعيفة جدًا، أما NaCl فشبكة أيونية ذات قوى تجاذب كهروستاتيكية قوية جدًا تحتاج طاقةً هائلةً لتفكيكها."}]},
  {"id":"g9-chem-1-u5","grade":"g9","subject":"chemistry","term":1,"title":"الوحدة الخامسة: معدّل سرعة التفاعل وتغيّرات الطاقة","levels":{"easy":[{"type":"mcq","q":"تصاعد ٨٠ سم³ من غاز CO₂ خلال ٤٠ ثانية حتى توقف التفاعل. ما متوسط معدّل سرعة التفاعل؟","options":["٣٢٠٠ سم³/ث","٢ سم³/ث","٠٫٥ سم³/ث","٤٠ سم³/ث"],"answer":1,"why":"٨٠ ÷ ٤٠ = ٢ سم³/ث."},{"type":"mcq","q":"لماذا توضع «سدادة من القطن» في فوهة الدورق عند قياس سرعة التفاعل بنقصان الكتلة على الميزان؟","options":["لزيادة كتلة الدورق","لمنع خروج الغاز تمامًا","لتسمح بخروج الغاز المتصاعد وتمنع تطاير رذاذ السائل الحمضي للخارج","لتسخين التفاعل"],"answer":2,"why":"تمنع فقدان رذاذ السائل وتسمح بهروب CO₂ لتكون قراءة الميزان دقيقة."},{"type":"mcq","q":"في منحنى (حجم الغاز مقابل الزمن)، متى يكون التفاعل في «أقصى سرعة» له؟","options":["السرعة ثابتة طوال التفاعل","عندما يصبح المنحنى أفقيًا","في آخر ثانية قبل التوقف","في البداية تمامًا (حيث يكون ميل المنحنى أشدّ انحدارًا)"],"answer":3,"why":"تركيز المتفاعلات أعلى ما يمكن في البداية فيكون الميل أشد."},{"type":"mcq","q":"ماذا يعني تحوّل منحنى (حجم الغاز مقابل الزمن) إلى «خط أفقي»؟","options":["توقّف التفاعل تمامًا لاستهلاك المادة المحدّدة","تسارع التفاعل لأقصى حد","بدء تفاعل جديد","تعطل محقنة الغاز"],"answer":0,"why":"الميل = صفر يعني لم يعد يتصاعد أي غاز إضافي."}],"medium":[{"type":"mcq","q":"لماذا يتباطأ التفاعل الكيميائي تدريجيًا مع مرور الوقت؟","options":["لأن الكتلة تزداد","بسبب استهلاك المتفاعلات ونقص تركيزها فتقل التصادمات","لأن النواتج تزيد التركيز","لأن الزمن يقل"],"answer":1,"why":"نقص تركيز المتفاعلات يقلل معدل التصادمات الفعالة."},{"type":"mcq","q":"في تجربة إخفاء علامة (X) بتكوّن راسب الكبريت، استغرقت التجربة (أ) ١٥ ثانية والتجربة (ب) ٤٥ ثانية. أيهما أسرع؟","options":["التجربة (أ) لم تحدث","التجربة (ب) أسرع","التجربة (أ) أسرع ٣ مرات من (ب)","لهما نفس السرعة"],"answer":2,"why":"الزمن الأقصر يعني تفاعلًا أسرع (٤٥ ÷ ١٥ = ٣ أضعاف)."},{"type":"mcq","q":"ما الأداة الأدق لجمع وقياس حجم الغاز المتصاعد من تفاعل كيميائي؟","options":["الترمومتر","الميزان ذو الكفتين","ورقة الترشيح","محقنة الغاز المدرّجة (Gas syringe)"],"answer":3,"why":"محقنة الغاز تقيس الحجم مباشرةً بدقة عالية."},{"type":"tfr","q":"ثبات قراءة الميزان أو حجم الغاز في المحقنة يعني انتهاء التفاعل لاستهلاك أحد المتفاعلات.","answer":true,"reasons":["يعني زيادة السرعة","يعني أن التفاعل بدأ للتو","وهو ما يظهر كخط أفقي على الرسم البياني"],"reason":2},{"type":"tfr","q":"يعمل العامل الحفّاز على زيادة سرعة التفاعل عن طريق «خفض طاقة التنشيط».","answer":true,"reasons":["بتوفير مسار بديل أسهل للتفاعل دون أن يُستهلك","عن طريق رفع طاقة التنشيط","عن طريق زيادة كتلة المتفاعلات"],"reason":0}],"hard":[{"type":"mcq","q":"لماذا لا تصلح طريقة «نقصان الكتلة على الميزان» جيدًا عند تصاعد غاز الهيدروجين (H₂)؟","options":["لأن غاز الهيدروجين خفيف جدًا فيكون التغيّر في الكتلة ضئيلًا يصعب قياسه بدقة","لأن الهيدروجين لا يخرج من القطن","لأن الهيدروجين سائل","لأنه أثقل من CO₂"],"answer":0,"why":"الكتلة المولية لـ H₂ هي ٢ فقط بينما CO₂ هي ٤٤."},{"type":"mcq","q":"إذا أُعيد تفاعل كربونات الكالسيوم مع «ضعف» كمية المادة المحدّدة، فماذا يحدث لارتفاع الخط الأفقي النهائي؟","options":["يقل إلى النصف","يتضاعف الحجم النهائي للغاز إلى الضعف","يبقى كما هو","يصبح صفرًا"],"answer":1,"why":"كمية الناتج الكلي تتناسب طرديًا مع كمية المادة المحدّدة."},{"type":"mcq","q":"أي التفاعلات الآتية يُعدّ مثالًا لتفاعل كيميائي بطيء جدًا؟","options":["تفاعل الصوديوم مع الماء","احتراق الألعاب النارية","صدأ الحديد في الهواء الرطب","فوران قرص فيتامين سي في الماء"],"answer":2,"why":"صدأ الحديد يستغرق أيامًا وأشهرًا."},{"type":"essay","q":"في تجربة تفاعل المغنيسيوم مع حمض HCl، جمع طالب ٤٨ سم³ من الهيدروجين في ٢٤ ثانية ثم ثبت الحجم. احسب متوسط السرعة، وصف شكل المنحنى في المراحل الثلاث.","model":"متوسط السرعة = ٤٨ ÷ ٢٤ = ٢ سم³/ث. المنحنى: شديد الانحدار في البداية (أسرع)، ثم يقل ميله تدريجيًا (يتباطأ)، ثم يصبح أفقيًا عند ٤٨ سم³ (توقف التفاعل)."},{"type":"essay","q":"اذكر ثلاث طرق عملية مختلفة لقياس معدل سرعة تفاعل كيميائي مع مثال لكل طريقة.","model":"١) قياس حجم الغاز بمحقنة غاز (Mg + HCl). ٢) قياس نقصان الكتلة على ميزان إلكتروني مع سدادة قطن (CaCO₃ + HCl). ٣) قياس زمن اختفاء علامة X لتكوّن راسب (ثيوكبريتات الصوديوم + HCl)."}]},"test":[{"type":"mcq","q":"تصاعد ٨٠ سم³ من غاز CO₂ خلال ٤٠ ثانية حتى توقف التفاعل. ما متوسط معدّل سرعة التفاعل؟","options":["٣٢٠٠ سم³/ث","٢ سم³/ث","٠٫٥ سم³/ث","٤٠ سم³/ث"],"answer":1,"why":"٨٠ ÷ ٤٠ = ٢ سم³/ث."},{"type":"mcq","q":"لماذا توضع «سدادة من القطن» في فوهة الدورق عند قياس سرعة التفاعل بنقصان الكتلة على الميزان؟","options":["لزيادة كتلة الدورق","لمنع خروج الغاز تمامًا","لتسمح بخروج الغاز المتصاعد وتمنع تطاير رذاذ السائل الحمضي للخارج","لتسخين التفاعل"],"answer":2,"why":"تمنع فقدان رذاذ السائل وتسمح بهروب CO₂ لتكون قراءة الميزان دقيقة."},{"type":"mcq","q":"في منحنى (حجم الغاز مقابل الزمن)، متى يكون التفاعل في «أقصى سرعة» له؟","options":["السرعة ثابتة طوال التفاعل","عندما يصبح المنحنى أفقيًا","في آخر ثانية قبل التوقف","في البداية تمامًا (حيث يكون ميل المنحنى أشدّ انحدارًا)"],"answer":3,"why":"تركيز المتفاعلات أعلى ما يمكن في البداية فيكون الميل أشد."},{"type":"mcq","q":"ماذا يعني تحوّل منحنى (حجم الغاز مقابل الزمن) إلى «خط أفقي»؟","options":["توقّف التفاعل تمامًا لاستهلاك المادة المحدّدة","تسارع التفاعل لأقصى حد","بدء تفاعل جديد","تعطل محقنة الغاز"],"answer":0,"why":"الميل = صفر يعني لم يعد يتصاعد أي غاز إضافي."},{"type":"mcq","q":"لماذا يتباطأ التفاعل الكيميائي تدريجيًا مع مرور الوقت؟","options":["لأن الكتلة تزداد","بسبب استهلاك المتفاعلات ونقص تركيزها فتقل التصادمات","لأن النواتج تزيد التركيز","لأن الزمن يقل"],"answer":1,"why":"نقص تركيز المتفاعلات يقلل معدل التصادمات الفعالة."},{"type":"mcq","q":"في تجربة إخفاء علامة (X) بتكوّن راسب الكبريت، استغرقت التجربة (أ) ١٥ ثانية والتجربة (ب) ٤٥ ثانية. أيهما أسرع؟","options":["التجربة (أ) لم تحدث","التجربة (ب) أسرع","التجربة (أ) أسرع ٣ مرات من (ب)","لهما نفس السرعة"],"answer":2,"why":"الزمن الأقصر يعني تفاعلًا أسرع (٤٥ ÷ ١٥ = ٣ أضعاف)."},{"type":"mcq","q":"ما الأداة الأدق لجمع وقياس حجم الغاز المتصاعد من تفاعل كيميائي؟","options":["الترمومتر","الميزان ذو الكفتين","ورقة الترشيح","محقنة الغاز المدرّجة (Gas syringe)"],"answer":3,"why":"محقنة الغاز تقيس الحجم مباشرةً بدقة عالية."},{"type":"mcq","q":"لماذا لا تصلح طريقة «نقصان الكتلة على الميزان» جيدًا عند تصاعد غاز الهيدروجين (H₂)؟","options":["لأن غاز الهيدروجين خفيف جدًا فيكون التغيّر في الكتلة ضئيلًا يصعب قياسه بدقة","لأن الهيدروجين لا يخرج من القطن","لأن الهيدروجين سائل","لأنه أثقل من CO₂"],"answer":0,"why":"الكتلة المولية لـ H₂ هي ٢ فقط بينما CO₂ هي ٤٤."},{"type":"mcq","q":"إذا أُعيد تفاعل كربونات الكالسيوم مع «ضعف» كمية المادة المحدّدة، فماذا يحدث لارتفاع الخط الأفقي النهائي؟","options":["يقل إلى النصف","يتضاعف الحجم النهائي للغاز إلى الضعف","يبقى كما هو","يصبح صفرًا"],"answer":1,"why":"كمية الناتج الكلي تتناسب طرديًا مع كمية المادة المحدّدة."},{"type":"mcq","q":"أي التفاعلات الآتية يُعدّ مثالًا لتفاعل كيميائي بطيء جدًا؟","options":["تفاعل الصوديوم مع الماء","احتراق الألعاب النارية","صدأ الحديد في الهواء الرطب","فوران قرص فيتامين سي في الماء"],"answer":2,"why":"صدأ الحديد يستغرق أيامًا وأشهرًا."},{"type":"mcq","q":"لقياس سرعة تفاعل لحظية عند زمن محدد من منحنى (الحجم–الزمن)، نحسب:","options":["مجموع الأزمنة","المساحة تحت المنحنى","أعلى نقطة فقط","ميل المماس للمنحنى عند تلك النقطة"],"answer":3,"why":"ميل المماس يعطي معدل التغير اللحظي (السرعة اللحظية)."},{"type":"mcq","q":"ما الشرط الأساسي لحدوث «تصادم فعّال» ينتج عنه تفاعل كيميائي؟","options":["أن تتصادم الجسيمات بطاقة تساوي أو تفوق طاقة التنشيط (Ea)","مجرد أي تصادم مهما كانت طاقته ضعيفة","أن تكون الجسيمات ساكنة","أن تكون المادة صلبة فقط"],"answer":0,"why":"بدون بلوغ طاقة التنشيط يرتد الجسيمان دون تفاعل."},{"type":"tf","q":"يكون التفاعل الكيميائي أسرع ما يمكن في بدايته ثم يتباطأ تدريجيًا حتى يتوقف.","answer":true,"why":"لأن تركيز المتفاعلات يكون أعلى ما يمكن في البداية ثم يُستهلك تدريجيًا"},{"type":"tf","q":"سدادة القطن في تجربة نقصان الكتلة تمنع خروج غاز CO₂ من الدورق.","answer":false,"why":"بل تسمح بخروج غاز CO₂ وتمنع فقط تطاير رذاذ المحلول الحمضي"},{"type":"tf","q":"المنحنى الأكثر انحدارًا (أكبر ميل) على رسم (حجم الغاز–الزمن) يمثّل التفاعل الأسرع.","answer":true,"why":"ويصل إلى الخط الأفقي في زمن أقصر"},{"type":"tf","q":"في تجربة إخفاء علامة (X)، كلما زاد الزمن المستغرق لاختفاء العلامة كان التفاعل أسرع.","answer":false,"why":"العكس تمامًا: الزمن الأقصر يدل على التفاعل الأسرع (السرعة ∝ ١/الزمن)"},{"type":"tfr","q":"ثبات قراءة الميزان أو حجم الغاز في المحقنة يعني انتهاء التفاعل لاستهلاك أحد المتفاعلات.","answer":true,"reasons":["يعني زيادة السرعة","يعني أن التفاعل بدأ للتو","وهو ما يظهر كخط أفقي على الرسم البياني"],"reason":2},{"type":"tfr","q":"يعمل العامل الحفّاز على زيادة سرعة التفاعل عن طريق «خفض طاقة التنشيط».","answer":true,"reasons":["بتوفير مسار بديل أسهل للتفاعل دون أن يُستهلك","عن طريق رفع طاقة التنشيط","عن طريق زيادة كتلة المتفاعلات"],"reason":0},{"type":"tfr","q":"إضافة عامل حفّاز لتفاعل كيميائي تضاعف كمية الناتج النهائي إلى الضعف.","answer":false,"reasons":["نعم تضاعف الناتج","لا يغير الحفّاز كمية الناتج أبدًا، بل يختصر الزمن اللازم للحصول على نفس الكمية","تقلل الناتج للنصف"],"reason":1},{"type":"tfr","q":"زيادة تركيز الحمض تزيد عدد الجسيمات في وحدة الحجم فيزداد معدل التصادمات الفعالة.","answer":true,"reasons":["تقلل عدد الجسيمات","تبطئ التفاعل","فتزداد سرعة التفاعل ويصبح منحنى (الحجم–الزمن) أشد انحدارًا"],"reason":2},{"type":"essay","q":"في تجربة تفاعل المغنيسيوم مع حمض HCl، جمع طالب ٤٨ سم³ من الهيدروجين في ٢٤ ثانية ثم ثبت الحجم. احسب متوسط السرعة، وصف شكل المنحنى في المراحل الثلاث.","model":"متوسط السرعة = ٤٨ ÷ ٢٤ = ٢ سم³/ث. المنحنى: شديد الانحدار في البداية (أسرع)، ثم يقل ميله تدريجيًا (يتباطأ)، ثم يصبح أفقيًا عند ٤٨ سم³ (توقف التفاعل)."},{"type":"essay","q":"اذكر ثلاث طرق عملية مختلفة لقياس معدل سرعة تفاعل كيميائي مع مثال لكل طريقة.","model":"١) قياس حجم الغاز بمحقنة غاز (Mg + HCl). ٢) قياس نقصان الكتلة على ميزان إلكتروني مع سدادة قطن (CaCO₃ + HCl). ٣) قياس زمن اختفاء علامة X لتكوّن راسب (ثيوكبريتات الصوديوم + HCl)."},{"type":"essay","q":"علّل: لماذا نضع سدادة قطن (وليس سدادة مطاطية محكمة) عند قياس سرعة التفاعل على الميزان؟","model":"لأن السدادة المطاطية تحبس الغاز فلا تنقص الكتلة وقد ينفجر الدورق، بينما القطن يسمح بخروج غاز CO₂ ويمنع تطاير رذاذ الحمض للخارج."},{"type":"essay","q":"قارن بين منحنيين لتفاعلَين ينتجان نفس الحجم الكلي للغاز (٦٠ سم³)، لكن التفاعل A توقف بعد ٢٠ ثانية و B بعد ٥٠ ثانية.","model":"كلاهما يصل لنفس الخط الأفقي (٦٠ سم³)، لكن منحنى A أشد انحدارًا (أكبر ميل) ويصل للأفقي أولًا لأنه أسرع من B."},{"type":"essay","q":"فسّر لماذا تقل سرعة التفاعل تدريجيًا من الثانية الأولى حتى توقفه.","model":"مع استمرار التفاعل تُستهلك جسيمات المتفاعلات فيقل تركيزها، فتقل عدد التصادمات الفعالة في الثانية حتى ينفد أحد المتفاعلات ويتوقف التفاعل."}]},
  {"id":"g9-chem-2-u6","grade":"g9","subject":"chemistry","term":2,"title":"الوحدة السادسة: الأحماض والقواعد","levels":{"easy":[{"type":"mcq","q":"الأيون الذي تنتجه الأحماض عند ذوبانها في الماء هو:","options":["Cl⁻","OH⁻","H⁺","Na⁺"],"answer":2,"why":"تتميز المحاليل الحمضية بوجود أيونات الهيدروجين H⁺."},{"type":"mcq","q":"الأيون الذي تنتجه القلويات عند ذوبانها في الماء هو:","options":["H⁺","SO₄²⁻","O²⁻","OH⁻"],"answer":3,"why":"تطلق القلويات أيونات الهيدروكسيد OH⁻ في الماء."},{"type":"mcq","q":"يُسمّى التفاعل بين الحمض والقاعدة لتكوين ملح وماء:","options":["التعادل","الاحتراق","التبخر","الانصهار"],"answer":0,"why":"التعادل هو تفاعل حمض مع قاعدة لإنتاج ملح وماء."},{"type":"mcq","q":"أي المواد الآتية يُعد حمضًا مخبريًا قويًا؟","options":["كلوريد الصوديوم","حمض الهيدروكلوريك HCl","الماء المقطّر","هيدروكسيد الصوديوم NaOH"],"answer":1,"why":"HCl حمض معدني قوي يتأين كليًا في الماء."}],"medium":[{"type":"mcq","q":"أي العبارات الآتية صحيحة تمامًا؟","options":["القلويات لا تذوب في الماء","كل قاعدة هي قلوي","كل قلوي هو قاعدة، ولكن ليست كل قاعدة قلويًا","الأحماض تطلق أيونات OH⁻"],"answer":2,"why":"القلويات هي القواعد القابلة للذوبان في الماء فقط."},{"type":"mcq","q":"يُعد أكسيد النحاس (CuO) قاعدةً وليس قلويًا لأنه:","options":["يذوب في الماء ويعطي H⁺","مادة غازية","لا يتفاعل مع الأحماض","يتفاعل مع الحمض لكنه لا يذوب في الماء"],"answer":3,"why":"القاعدة التي لا تذوب في الماء لا تُسمّى قلويًا."},{"type":"mcq","q":"الفرق الأساسي بين الحمض القوي والحمض الضعيف هو:","options":["مدى التأين في الماء (كلي في القوي وجزئي في الضعيف)","اللون فقط","الكتلة المولية فقط","درجة الغليان"],"answer":0,"why":"الحمض القوي يتأين بالكامل بينما الضعيف يتأين جزئيًا."},{"type":"tfr","q":"عند لسعة نحلة (إفراز حمضي)، يُفضّل وضع خل (حمض) لتخفيف الألم.","answer":false,"reasons":["لأن الخل حمض يزيد الحموضة؛ يُفضّل وضع مادة قلوية لطيفة مثل صودا الخبز لمعادلة الحمض","لأن لسعة النحلة قلوية","لأن الخل قلوي"],"reason":0},{"type":"tfr","q":"كلما زادت قيمة pH فوق 7، زادت قوة المحلول القلوي.","answer":true,"reasons":["لأن القلويات تقع تحت 7","لأن القلوية تزداد من 8 (قلوي ضعيف) حتى 14 (قلوي قوي جدًّا)","لأن 14 يعني متعادلًا"],"reason":1}],"hard":[{"type":"mcq","q":"يحتوي محلول حمض الإيثانويك (الخل) على أيونات H⁺ أقل من محلول HCl بنفس التركيز لأن:","options":["الخل لا يحتوي هيدروجين","حمض الإيثانويك حمض ضعيف يتأين جزئيًا فقط","HCl لا يتأين في الماء","الخل قاعدة وليس حمضًا"],"answer":1,"why":"التأين الجزئي للحمض الضعيف ينتج تركيزًا أقل من أيونات H⁺."},{"type":"mcq","q":"يضيف المزارعون أحيانًا الجير المطفأ Ca(OH)₂ إلى تربة مزرعة حمضية بهدف:","options":["منع امتصاص الماء","زيادة حموضة التربة","معادلة الحموضة الزائدة ورفع pH التربة لنمو أفضل للنباتات","قتل الجذور"],"answer":2,"why":"Ca(OH)₂ قلوي يعادل الأحماض في التربة."},{"type":"mcq","q":"عند تخفيف حمض الكبريتيك المركّز بالماء في المختبر، الإجراء الآمن هو:","options":["إضافة الماء دفعة واحدة إلى الحمض المركّز","خلطه باليد","تسخين الحمض أولًا","إضافة الحمض ببطء إلى الماء مع التحريك"],"answer":3,"why":"إضافة الحمض للماء تشتّت الحرارة المتولدة وتمنع تطاير رذاذ الحمض."},{"type":"essay","q":"قارن بين القاعدة والقلوي مع ذكر مثال واحد لكل منهما.","model":"القاعدة مادة تتفاعل مع الحمض لإنتاج ملح وماء (مثل أكسيد النحاس CuO الذي لا يذوب في الماء). القلوي قاعدة تذوب في الماء وتطلق أيونات OH⁻ (مثل هيدروكسيد الصوديوم NaOH)."},{"type":"essay","q":"اذكر تطبيقين من حياتك اليومية لتفاعل التعادل.","model":"١) استخدام معجون الأسنان القلوي لمعادلة الأحماض في الفم وحماية الأسنان. ٢) تناول مضادات الحموضة القاعدية لمعادلة حمض الهيدروكلوريك الزائد في المعدة."}]},"test":[{"type":"mcq","q":"الأيون الذي تنتجه الأحماض عند ذوبانها في الماء هو:","options":["Cl⁻","OH⁻","H⁺","Na⁺"],"answer":2,"why":"تتميز المحاليل الحمضية بوجود أيونات الهيدروجين H⁺."},{"type":"mcq","q":"الأيون الذي تنتجه القلويات عند ذوبانها في الماء هو:","options":["H⁺","SO₄²⁻","O²⁻","OH⁻"],"answer":3,"why":"تطلق القلويات أيونات الهيدروكسيد OH⁻ في الماء."},{"type":"mcq","q":"يُسمّى التفاعل بين الحمض والقاعدة لتكوين ملح وماء:","options":["التعادل","الاحتراق","التبخر","الانصهار"],"answer":0,"why":"التعادل هو تفاعل حمض مع قاعدة لإنتاج ملح وماء."},{"type":"mcq","q":"أي المواد الآتية يُعد حمضًا مخبريًا قويًا؟","options":["كلوريد الصوديوم","حمض الهيدروكلوريك HCl","الماء المقطّر","هيدروكسيد الصوديوم NaOH"],"answer":1,"why":"HCl حمض معدني قوي يتأين كليًا في الماء."},{"type":"mcq","q":"أي العبارات الآتية صحيحة تمامًا؟","options":["القلويات لا تذوب في الماء","كل قاعدة هي قلوي","كل قلوي هو قاعدة، ولكن ليست كل قاعدة قلويًا","الأحماض تطلق أيونات OH⁻"],"answer":2,"why":"القلويات هي القواعد القابلة للذوبان في الماء فقط."},{"type":"mcq","q":"يُعد أكسيد النحاس (CuO) قاعدةً وليس قلويًا لأنه:","options":["يذوب في الماء ويعطي H⁺","مادة غازية","لا يتفاعل مع الأحماض","يتفاعل مع الحمض لكنه لا يذوب في الماء"],"answer":3,"why":"القاعدة التي لا تذوب في الماء لا تُسمّى قلويًا."},{"type":"mcq","q":"الفرق الأساسي بين الحمض القوي والحمض الضعيف هو:","options":["مدى التأين في الماء (كلي في القوي وجزئي في الضعيف)","اللون فقط","الكتلة المولية فقط","درجة الغليان"],"answer":0,"why":"الحمض القوي يتأين بالكامل بينما الضعيف يتأين جزئيًا."},{"type":"mcq","q":"يحتوي محلول حمض الإيثانويك (الخل) على أيونات H⁺ أقل من محلول HCl بنفس التركيز لأن:","options":["الخل لا يحتوي هيدروجين","حمض الإيثانويك حمض ضعيف يتأين جزئيًا فقط","HCl لا يتأين في الماء","الخل قاعدة وليس حمضًا"],"answer":1,"why":"التأين الجزئي للحمض الضعيف ينتج تركيزًا أقل من أيونات H⁺."},{"type":"mcq","q":"يضيف المزارعون أحيانًا الجير المطفأ Ca(OH)₂ إلى تربة مزرعة حمضية بهدف:","options":["منع امتصاص الماء","زيادة حموضة التربة","معادلة الحموضة الزائدة ورفع pH التربة لنمو أفضل للنباتات","قتل الجذور"],"answer":2,"why":"Ca(OH)₂ قلوي يعادل الأحماض في التربة."},{"type":"mcq","q":"عند تخفيف حمض الكبريتيك المركّز بالماء في المختبر، الإجراء الآمن هو:","options":["إضافة الماء دفعة واحدة إلى الحمض المركّز","خلطه باليد","تسخين الحمض أولًا","إضافة الحمض ببطء إلى الماء مع التحريك"],"answer":3,"why":"إضافة الحمض للماء تشتّت الحرارة المتولدة وتمنع تطاير رذاذ الحمض."},{"type":"mcq","q":"أي من المواد الآتية يُعد قلويًا ضعيفًا؟","options":["محلول الأمونيا (NH₃)","هيدروكسيد الصوديوم (NaOH)","هيدروكسيد البوتاسيوم (KOH)","حمض النيتريك (HNO₃)"],"answer":0,"why":"الأمونيا تتأين جزئيًا في الماء فتُعد قلويًا ضعيفًا."},{"type":"mcq","q":"قيمة pH للماء المقطّر النقي (المتعادل) تساوي:","options":["1","7","14","0"],"answer":1,"why":"الوسط المتعادل قيمته pH = 7."},{"type":"tf","q":"يمكن تذوّق الأحماض المخبرية للتحقق من طعمها الحامض.","answer":false,"why":"لأنها مواد آكلة وخطيرة قد تسبب حروقًا شديدة، ونفحصها بالكواشف لا بالتذوق"},{"type":"tf","q":"المعادلة الأيونية الصافية لأي تفاعل تعادل بين حمض قوي وقلوي قوي هي H⁺ + OH⁻ → H₂O.","answer":true,"why":"لأن أيونات H⁺ من الحمض تتحد مع OH⁻ من القلوي لتكوين جزيئات ماء متعادلة"},{"type":"tf","q":"يمكن أن يكون لدينا محلول مخفّف من حمض قوي، ومحلول مركّز من حمض ضعيف.","answer":true,"why":"لأن القوة تعتمد على نسبة التأين بينما التركيز يعتمد على كمية المذاب في حجم الماء"},{"type":"tf","q":"محلول هيدروكسيد الكالسيوم (ماء الجير) يُعد قلويًا لأنه يذوب قليلًا في الماء ويطلق OH⁻.","answer":true,"why":"ذوبانه الجزئي في الماء ينتج محلولًا قلويًا يحتوي على أيونات OH⁻"},{"type":"tfr","q":"عند لسعة نحلة (إفراز حمضي)، يُفضّل وضع خل (حمض) لتخفيف الألم.","answer":false,"reasons":["لأن الخل حمض يزيد الحموضة؛ يُفضّل وضع مادة قلوية لطيفة مثل صودا الخبز لمعادلة الحمض","لأن لسعة النحلة قلوية","لأن الخل قلوي"],"reason":0},{"type":"tfr","q":"كلما زادت قيمة pH فوق 7، زادت قوة المحلول القلوي.","answer":true,"reasons":["لأن القلويات تقع تحت 7","لأن القلوية تزداد من 8 (قلوي ضعيف) حتى 14 (قلوي قوي جدًّا)","لأن 14 يعني متعادلًا"],"reason":1},{"type":"tfr","q":"لا يتغيّر لون ورقة تباع الشمس الحمراء عند وضعها في محلول حمضي.","answer":true,"reasons":["لأنه يتحول إلى أخضر","لأنه يتحول إلى أزرق","لأن تباع الشمس في الحمض يكون أحمر أصلًا، فيبقى أحمر دون تغير"],"reason":2},{"type":"tfr","q":"يمكن لمحلول حمض قوي أن يكون له pH = 12 إذا كان مركّزًا جدًّا.","answer":false,"reasons":["لأن جميع الأحماض (مهما كان تركيزها) قيمتها أقل من 7، بينما 12 قلوي قوي","لأن الأحماض القوية لها pH = 14","لأن التركيز يحول الحمض لقلوي"],"reason":0},{"type":"essay","q":"قارن بين القاعدة والقلوي مع ذكر مثال واحد لكل منهما.","model":"القاعدة مادة تتفاعل مع الحمض لإنتاج ملح وماء (مثل أكسيد النحاس CuO الذي لا يذوب في الماء). القلوي قاعدة تذوب في الماء وتطلق أيونات OH⁻ (مثل هيدروكسيد الصوديوم NaOH)."},{"type":"essay","q":"اذكر تطبيقين من حياتك اليومية لتفاعل التعادل.","model":"١) استخدام معجون الأسنان القلوي لمعادلة الأحماض في الفم وحماية الأسنان. ٢) تناول مضادات الحموضة القاعدية لمعادلة حمض الهيدروكلوريك الزائد في المعدة."},{"type":"essay","q":"ميّز بوضوح بين «حمض قوي مخفّف» و«حمض ضعيف مركّز» من حيث الجسيمات في المحلول.","model":"الحمض القوي المخفّف فيه عدد قليل من جزيئات الحمض لكل لتر لكنها جميعًا متأينة كليًا إلى أيونات H⁺. أما الحمض الضعيف المركّز ففيه جزيئات كثيرة لكل لتر لكن نسبة صغيرة منها فقط تتأين إلى H⁺."},{"type":"essay","q":"فسّر لماذا ينصح الأطباء بعدم تنظيف الأسنان بالفرشاة فور شرب عصير ليمون حامض، والاكتفاء بالمضمضة بالماء أولًا.","model":"لأن الحمض يُضعف طبقة المينا مؤقتًا، والمضمضة بالماء تخفّف الحمض وتزيله قبل التفريش بالمعجون القلوي الذي يعادل ما تبقى."},{"type":"essay","q":"اكتب المعادلة اللفظية والرمزية لتفاعل تعادل حمض الهيدروكلوريك مع هيدروكسيد الصوديوم.","model":"اللفظية: حمض الهيدروكلوريك + هيدروكسيد الصوديوم → كلوريد الصوديوم + ماء. الرمزية: HCl + NaOH → NaCl + H₂O."}]},
  {"id":"g9-chem-2-u7","grade":"g9","subject":"chemistry","term":2,"title":"الوحدة السابعة: مُعادلات التفاعُلات الكيميائيّة","levels":{"easy":[{"type":"mcq","q":"المبدأ العلمي الذي يفرض موازنة المعادلات الكيميائية هو:","options":["قانون الكثافة","قانون التمدد الحراري","قانون الانعكاس","قانون حفظ الكتلة"],"answer":3,"why":"الذرات لا تفنى ولا تُستحدث، لذا تبقى الكتلة الكلية محفوظة."},{"type":"mcq","q":"ما المعامل الصحيح أمام Mg في المعادلة: ___ Mg + O₂ → 2MgO؟","options":["2","1","4","3"],"answer":0,"why":"لأن النواتج تحتوي 2 ذرة Mg."},{"type":"mcq","q":"كم ذرة أكسجين توجد في 2H₂SO₄؟","options":["6 ذرات","8 ذرات","4 ذرات","2 ذرة"],"answer":1,"why":"2 × 4 = 8 ذرات أكسجين."},{"type":"mcq","q":"أي الجزيئات الآتية يُكتب دائمًا ثنائي الذرة عند كونه عنصرًا حرًا؟","options":["الكربون C","الصوديوم Na","الأكسجين O₂","المغنيسيوم Mg"],"answer":2,"why":"الأكسجين غاز ثنائي الذرة O₂."}],"medium":[{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الحديد مع الأكسجين: Fe + O₂ → Fe₂O₃؟","options":["Fe + O₂ → Fe₂O₃","2Fe + O₂ → Fe₂O₃","2Fe + 3O₂ → Fe₂O₃","4Fe + 3O₂ → 2Fe₂O₃"],"answer":3,"why":"في الطرفين: 4 ذرات Fe و 6 ذرات O."},{"type":"mcq","q":"عند موازنة: Zn + ___ HCl → ZnCl₂ + H₂، ما المعامل المناسب أمام HCl؟","options":["2","1","3","4"],"answer":0,"why":"نحتاج 2 ذرة H و 2 ذرة Cl، إذن 2HCl."},{"type":"mcq","q":"كم عدد ذرات الهيدروجين في 3Ca(OH)₂؟","options":["3 ذرات","6 ذرات","2 ذرة","5 ذرات"],"answer":1,"why":"داخل القوس 2 ذرة H × المعامل 3 = 6 ذرات."},{"type":"tfr","q":"إذا وُضعت كربونات الكالسيوم مع حمض داخل دورق مغلق ببالون على ميزان حساس، تبقى قراءة الميزان ثابتةً تقريبًا.","answer":true,"reasons":["لأن الغاز بلا كتلة","لأن الغاز المتصاعد يُحبس داخل البالون فلا تُفقد أي كتلة من النظام","لأن التفاعل يتوقف"],"reason":1},{"type":"tfr","q":"يُكتب رمز الحالة للماء الناتج عن تفاعل التعادل على الصورة H₂O(aq).","answer":false,"reasons":["لأن الماء صلب","لأن الماء غاز دائمًا","لأن الماء سائل نقي فيُكتب H₂O(l) وليس (aq)"],"reason":2}],"hard":[{"type":"mcq","q":"ما المعامل الصحيح أمام O₂ عند موازنة احتراق الإيثان: 2C₂H₆ + ___ O₂ → 4CO₂ + 6H₂O؟","options":["14","5","7","6"],"answer":2,"why":"في النواتج: (4×2) + 6 = 14 ذرة O، إذن نحتاج 7O₂."},{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الألمنيوم مع حمض الهيدروكلوريك: Al + HCl → AlCl₃ + H₂؟","options":["Al + 6HCl → AlCl₃ + 3H₂","Al + 3HCl → AlCl₃ + H₂","2Al + 3HCl → 2AlCl₃ + 3H₂","2Al + 6HCl → 2AlCl₃ + 3H₂"],"answer":3,"why":"في كل طرف: 2Al، 6H، 6Cl."},{"type":"mcq","q":"ما مجموع المعاملات الصحيحة (بأبسط نسبة) في المعادلة الموزونة: N₂ + H₂ → NH₃؟","options":["6 (1 + 3 + 2)","4","5","7"],"answer":0,"why":"المعادلة هي 1N₂ + 3H₂ → 2NH₃، ومجموع المعاملات = 1 + 3 + 2 = 6."},{"type":"essay","q":"وازن المعادلتين الآتيتين مع توضيح عدد الذرات في كل طرف: (أ) K + H₂O → KOH + H₂، (ب) Al + O₂ → Al₂O₃.","model":"أ) 2K + 2H₂O → 2KOH + H₂ (كل طرف: 2K, 4H, 2O). ب) 4Al + 3O₂ → 2Al₂O₃ (كل طرف: 4Al, 6O)."},{"type":"essay","q":"فسّر لماذا تزداد كتلة شريط مغنيسيوم عند حرقه في الهواء المفتوح رغم أن الكتلة محفوظة.","model":"لأن المغنيسيوم يتحد مع غاز الأكسجين من الهواء لتكوين أكسيد المغنيسيوم الصلب؛ وكتلة MgO تساوي بالضبط كتلة Mg + كتلة O₂ الممتص."}]},"test":[{"type":"mcq","q":"المبدأ العلمي الذي يفرض موازنة المعادلات الكيميائية هو:","options":["قانون الكثافة","قانون التمدد الحراري","قانون الانعكاس","قانون حفظ الكتلة"],"answer":3,"why":"الذرات لا تفنى ولا تُستحدث، لذا تبقى الكتلة الكلية محفوظة."},{"type":"mcq","q":"ما المعامل الصحيح أمام Mg في المعادلة: ___ Mg + O₂ → 2MgO؟","options":["2","1","4","3"],"answer":0,"why":"لأن النواتج تحتوي 2 ذرة Mg."},{"type":"mcq","q":"كم ذرة أكسجين توجد في 2H₂SO₄؟","options":["6 ذرات","8 ذرات","4 ذرات","2 ذرة"],"answer":1,"why":"2 × 4 = 8 ذرات أكسجين."},{"type":"mcq","q":"أي الجزيئات الآتية يُكتب دائمًا ثنائي الذرة عند كونه عنصرًا حرًا؟","options":["الكربون C","الصوديوم Na","الأكسجين O₂","المغنيسيوم Mg"],"answer":2,"why":"الأكسجين غاز ثنائي الذرة O₂."},{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الحديد مع الأكسجين: Fe + O₂ → Fe₂O₃؟","options":["Fe + O₂ → Fe₂O₃","2Fe + O₂ → Fe₂O₃","2Fe + 3O₂ → Fe₂O₃","4Fe + 3O₂ → 2Fe₂O₃"],"answer":3,"why":"في الطرفين: 4 ذرات Fe و 6 ذرات O."},{"type":"mcq","q":"عند موازنة: Zn + ___ HCl → ZnCl₂ + H₂، ما المعامل المناسب أمام HCl؟","options":["2","1","3","4"],"answer":0,"why":"نحتاج 2 ذرة H و 2 ذرة Cl، إذن 2HCl."},{"type":"mcq","q":"كم عدد ذرات الهيدروجين في 3Ca(OH)₂؟","options":["3 ذرات","6 ذرات","2 ذرة","5 ذرات"],"answer":1,"why":"داخل القوس 2 ذرة H × المعامل 3 = 6 ذرات."},{"type":"mcq","q":"ما المعامل الصحيح أمام O₂ عند موازنة احتراق الإيثان: 2C₂H₆ + ___ O₂ → 4CO₂ + 6H₂O؟","options":["14","5","7","6"],"answer":2,"why":"في النواتج: (4×2) + 6 = 14 ذرة O، إذن نحتاج 7O₂."},{"type":"mcq","q":"ما المعادلة الموزونة الصحيحة لتفاعل الألمنيوم مع حمض الهيدروكلوريك: Al + HCl → AlCl₃ + H₂؟","options":["Al + 6HCl → AlCl₃ + 3H₂","Al + 3HCl → AlCl₃ + H₂","2Al + 3HCl → 2AlCl₃ + 3H₂","2Al + 6HCl → 2AlCl₃ + 3H₂"],"answer":3,"why":"في كل طرف: 2Al، 6H، 6Cl."},{"type":"mcq","q":"ما مجموع المعاملات الصحيحة (بأبسط نسبة) في المعادلة الموزونة: N₂ + H₂ → NH₃؟","options":["6 (1 + 3 + 2)","4","5","7"],"answer":0,"why":"المعادلة هي 1N₂ + 3H₂ → 2NH₃، ومجموع المعاملات = 1 + 3 + 2 = 6."},{"type":"mcq","q":"عند تسخين 10 g من كربونات الكالسيوم في إناء مفتوح، نتج 5.6 g من أكسيد الكالسيوم الصلب. ما كتلة غاز CO₂ المتصاعد؟","options":["5.6 g","4.4 g","15.6 g","10 g"],"answer":1,"why":"بحفظ الكتلة: 10 − 5.6 = 4.4 g من CO₂."},{"type":"mcq","q":"الرمز (aq) في المعادلة الكيميائية يعني أن المادة:","options":["صلبة","غازية","مذابة في الماء (محلول مائي)","منصهرة بالتسخين"],"answer":2,"why":"aq اختصار لـ aqueous أي محلول مائي."},{"type":"tf","q":"يجوز تغيير الصيغة الكيميائية لـ MgO إلى MgO₂ لتسهيل موازنة الأكسجين.","answer":false,"why":"لأن تغيير الرقم السفلي يغيّر هوية المركب كيميائيًا؛ يجب تغيير المعاملات فقط"},{"type":"tf","q":"مجموع كتل المتفاعلات في إناء مغلق يساوي دائمًا مجموع كتل النواتج.","answer":true,"why":"تحقيقًا لقانون حفظ الكتلة حيث يُعاد ترتيب الذرات نفسها دون فقد أو زيادة"},{"type":"tf","q":"في المعادلة الموزونة: Fe₂O₃ + 3CO → 2Fe + 3CO₂، عدد ذرات الأكسجين في كل طرف هو 6.","answer":true,"why":"في اليسار: 3 + 3 = 6، وفي اليمين: 3 × 2 = 6 ذرات أكسجين"},{"type":"tf","q":"تدل المعادلة اللفظية وحدها على النسبة العددية الدقيقة للذرات المتفاعلة.","answer":false,"why":"المعادلة اللفظية تذكر أسماء المواد فقط، بينما المعادلة الرمزية الموزونة هي التي تُظهر النسب الذرية"},{"type":"tfr","q":"إذا وُضعت كربونات الكالسيوم مع حمض داخل دورق مغلق ببالون على ميزان حساس، تبقى قراءة الميزان ثابتةً تقريبًا.","answer":true,"reasons":["لأن الغاز بلا كتلة","لأن الغاز المتصاعد يُحبس داخل البالون فلا تُفقد أي كتلة من النظام","لأن التفاعل يتوقف"],"reason":1},{"type":"tfr","q":"يُكتب رمز الحالة للماء الناتج عن تفاعل التعادل على الصورة H₂O(aq).","answer":false,"reasons":["لأن الماء صلب","لأن الماء غاز دائمًا","لأن الماء سائل نقي فيُكتب H₂O(l) وليس (aq)"],"reason":2},{"type":"tfr","q":"يجب أن يتساوى مجموع الشحنات الكهربائية في طرفي المعادلة الأيونية الموزونة.","answer":true,"reasons":["تمامًا كما يجب أن يتساوى عدد الذرات في الطرفين","لأن الشحنات لا تُوازن","لأن كل الأيونات موجبة"],"reason":0},{"type":"tfr","q":"تُستخدم المعادلات الأيونية الصافية لتوضيح أن جميع تفاعلات الترسيب لنفس الراسب لها نفس التغيّر الكيميائي الأساسي.","answer":true,"reasons":["لأنها تخفي الراسب","فسواء استخدمنا NaCl أو KCl مع AgNO₃ فإن التفاعل الحقيقي هو دائمًا Ag⁺ + Cl⁻ → AgCl(s)","لأنها لا تحفظ الكتلة"],"reason":1},{"type":"essay","q":"وازن المعادلتين الآتيتين مع توضيح عدد الذرات في كل طرف: (أ) K + H₂O → KOH + H₂، (ب) Al + O₂ → Al₂O₃.","model":"أ) 2K + 2H₂O → 2KOH + H₂ (كل طرف: 2K, 4H, 2O). ب) 4Al + 3O₂ → 2Al₂O₃ (كل طرف: 4Al, 6O)."},{"type":"essay","q":"فسّر لماذا تزداد كتلة شريط مغنيسيوم عند حرقه في الهواء المفتوح رغم أن الكتلة محفوظة.","model":"لأن المغنيسيوم يتحد مع غاز الأكسجين من الهواء لتكوين أكسيد المغنيسيوم الصلب؛ وكتلة MgO تساوي بالضبط كتلة Mg + كتلة O₂ الممتص."},{"type":"essay","q":"وازن المعادلات الآتية: (أ) NaOH + H₂SO₄ → Na₂SO₄ + H₂O، (ب) CaCO₃ + HCl → CaCl₂ + H₂O + CO₂.","model":"أ) 2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O. ب) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂."},{"type":"essay","q":"لماذا يُفضّل الكيميائيون المعادلات الرمزية الموزونة على المعادلات اللفظية في المصانع والمختبرات؟","model":"لأنها عالمية ومختصرة، وتُظهر الصيغ الدقيقة والنسب المولية والكتلية اللازمة لحساب كميات المتفاعلات دون هدر."},{"type":"essay","q":"احسب كتلة أكسيد المغنيسيوم الناتجة عن تفاعل 2.4 g من المغنيسيوم تمامًا مع 1.6 g من الأكسجين.","model":"بحسب قانون حفظ الكتلة: كتلة MgO = 2.4 + 1.6 = 4.0 g."}]},
  {"id":"g9-chem-2-u8","grade":"g9","subject":"chemistry","term":2,"title":"الوحدة الثامنة: تكوين الأملاح","levels":{"easy":[{"type":"mcq","q":"الطريقة المستخدمة لتحضير ملح غير ذائب في الماء هي:","options":["الترسيب","المعايرة","التقطير","الكروماتوجرافيا"],"answer":0,"why":"الأملاح غير الذائبة تُحضّر بخلط محلولين ذائبين لتكوين راسب."},{"type":"mcq","q":"لفصل فائض أكسيد النحاس الصلب عن محلول كبريتات النحاس نستخدم عملية:","options":["الانصهار","الترشيح","المعايرة","التقطير"],"answer":1,"why":"الترشيح يفصل المادة الصلبة غير الذائبة عن المحلول."},{"type":"mcq","q":"الأداة المخبرية المستخدمة لإضافة الحمض قطرةً قطرةً بدقة في المعايرة هي:","options":["الكأس العادي","المسطرة","السحّاحة (Burette)","المغناطيس"],"answer":2,"why":"السحاحة تقيس الحجوم المتغيرة بدقة عالية في المعايرة."},{"type":"mcq","q":"عند تحضير ملح كلوريد البوتاسيوم (KCl) من KOH و HCl نستخدم طريقة:","options":["الترسيب","فائض فلز البوتاسيوم","التسامي","المعايرة"],"answer":3,"why":"لأن KOH و HCl و KCl جميعها محاليل ذائبة."}],"medium":[{"type":"mcq","q":"لماذا يُسخّن حمض الكبريتيك برفق قبل إضافة أكسيد النحاس عند تحضير كبريتات النحاس؟","options":["لزيادة سرعة التفاعل","لتجميد الحمض","لإذابة ورقة الترشيح","لمنع تكون الملح"],"answer":0,"why":"التسخين يسرّع التفاعل بين الأكسيد الصلب والحمض."},{"type":"mcq","q":"بعد ترشيح راسب كبريتات الباريوم (BaSO₄)، الخطوتان التاليتان للحصول على عينة نقية وجافة هما:","options":["خلطه بالرمل","غسله بماء مقطّر ثم تجفيفه بين ورقتي ترشيح أو في فرن دافئ","إضافة كاشف عام","إذابته في ماء مغلي ثم ترشيحه"],"answer":1,"why":"الغسل يزيل المحلول العالق والتجفيف يزيل الماء."},{"type":"mcq","q":"أي زوج من المحاليل الذائبة يصلح لتحضير راسب كربونات الكالسيوم (CaCO₃)؟","options":["أكسيد الكالسيوم + رمل","كبريتات الكالسيوم + ماء","نترات الكالسيوم + كربونات الصوديوم","كلوريد الصوديوم + نترات البوتاسيوم"],"answer":2,"why":"نترات الكالسيوم توفر Ca²⁺ وكربونات الصوديوم توفر CO₃²⁻ وكلاهما ذائبان."},{"type":"tfr","q":"في عملية الترسيب، نحتاج لإجراء خطوة التبخير والتبلور للحصول على الراسب.","answer":false,"reasons":["لأن الراسب ذائب","لأن الترشيح يذيب الراسب","الراسب صلب بالفعل فيُفصل مباشرة بالترشيح ثم الغسل والتجفيف دون تبخير"],"reason":2},{"type":"tfr","q":"جميع أملاح الكبريتات تذوب في الماء دون استثناء.","answer":false,"reasons":["لأن كبريتات الباريوم والرصاص والكالسيوم لا تذوب في الماء","لأن الكبريتات كلها غير ذائبة","لأن كبريتات الصوديوم غير ذائبة"],"reason":0}],"hard":[{"type":"mcq","q":"أضاف طالب فائضًا من كربونات المغنيسيوم إلى حمض النيتريك. كيف يعرف أن الحمض استُهلك بالكامل؟","options":["عندما يغلي المحلول","عندما يتجمد المحلول","عندما يتحول اللون إلى الأسود","عندما يتوقف الفوران وتبقى كمية صلبة غير ذائبة في القاع"],"answer":3,"why":"توقف الفقاعات وبقاء مسحوق في القاع يؤكد انتهاء كل الحمض."},{"type":"mcq","q":"ما الخطأ في محاولة تحضير كلوريد الصوديوم بإضافة فائض من NaOH الصلب إلى HCl ثم الترشيح؟","options":["أن فائض NaOH يذوب في الماء فيمر عبر ورق الترشيح ويلوّث الملح","أن NaOH لا يتفاعل مع HCl","أن NaCl غير ذائب","أن HCl صلب"],"answer":0,"why":"الترشيح لا يفصل المواد الذائبة في الماء."},{"type":"mcq","q":"لتحضير كبريتات الرصاص (PbSO₄) غير الذائبة، نخلط محلول نترات الرصاص مع محلول:","options":["كربونات الكالسيوم الصلبة","كبريتات الصوديوم أو حمض الكبريتيك المخفف","نترات البوتاسيوم","كلوريد الصوديوم"],"answer":1,"why":"نحتاج مصدرًا ذائبًا لأيون الكبريتات SO₄²⁻."},{"type":"essay","q":"لماذا نُوقف تسخين محلول كبريتات النحاس عند «نقطة التبلور» ولا نبخّر الماء كله حتى الجفاف؟","model":"لأن التبريد البطيء من نقطة التبلور يُكوّن بلورات زرقاء منتظمة وكبيرة تحتفظ بماء تبلورها، بينما التسخين للجفاف قد يفقدها ماء التبلور ويحولها لمسحوق أبيض أو يفككها."},{"type":"essay","q":"صف باختصار خطوات تحضير ملح نترات البوتاسيوم (KNO₃) النقي من HNO₃ و KOH.","model":"نقيس حجمًا محددًا من KOH بالماصة ونضيف كاشفًا، ثم نعاير بـ HNO₃ من السحاحة حتى يتغير اللون ونسجل الحجم. نعيد الخلط بنفس الحجمين دون كاشف، ثم نبخّر جزئيًا ونتركه يتبلور ونجفف البلورات."}]},"test":[{"type":"mcq","q":"الطريقة المستخدمة لتحضير ملح غير ذائب في الماء هي:","options":["الترسيب","المعايرة","التقطير","الكروماتوجرافيا"],"answer":0,"why":"الأملاح غير الذائبة تُحضّر بخلط محلولين ذائبين لتكوين راسب."},{"type":"mcq","q":"لفصل فائض أكسيد النحاس الصلب عن محلول كبريتات النحاس نستخدم عملية:","options":["الانصهار","الترشيح","المعايرة","التقطير"],"answer":1,"why":"الترشيح يفصل المادة الصلبة غير الذائبة عن المحلول."},{"type":"mcq","q":"الأداة المخبرية المستخدمة لإضافة الحمض قطرةً قطرةً بدقة في المعايرة هي:","options":["الكأس العادي","المسطرة","السحّاحة (Burette)","المغناطيس"],"answer":2,"why":"السحاحة تقيس الحجوم المتغيرة بدقة عالية في المعايرة."},{"type":"mcq","q":"عند تحضير ملح كلوريد البوتاسيوم (KCl) من KOH و HCl نستخدم طريقة:","options":["الترسيب","فائض فلز البوتاسيوم","التسامي","المعايرة"],"answer":3,"why":"لأن KOH و HCl و KCl جميعها محاليل ذائبة."},{"type":"mcq","q":"لماذا يُسخّن حمض الكبريتيك برفق قبل إضافة أكسيد النحاس عند تحضير كبريتات النحاس؟","options":["لزيادة سرعة التفاعل","لتجميد الحمض","لإذابة ورقة الترشيح","لمنع تكون الملح"],"answer":0,"why":"التسخين يسرّع التفاعل بين الأكسيد الصلب والحمض."},{"type":"mcq","q":"بعد ترشيح راسب كبريتات الباريوم (BaSO₄)، الخطوتان التاليتان للحصول على عينة نقية وجافة هما:","options":["خلطه بالرمل","غسله بماء مقطّر ثم تجفيفه بين ورقتي ترشيح أو في فرن دافئ","إضافة كاشف عام","إذابته في ماء مغلي ثم ترشيحه"],"answer":1,"why":"الغسل يزيل المحلول العالق والتجفيف يزيل الماء."},{"type":"mcq","q":"أي زوج من المحاليل الذائبة يصلح لتحضير راسب كربونات الكالسيوم (CaCO₃)؟","options":["أكسيد الكالسيوم + رمل","كبريتات الكالسيوم + ماء","نترات الكالسيوم + كربونات الصوديوم","كلوريد الصوديوم + نترات البوتاسيوم"],"answer":2,"why":"نترات الكالسيوم توفر Ca²⁺ وكربونات الصوديوم توفر CO₃²⁻ وكلاهما ذائبان."},{"type":"mcq","q":"أضاف طالب فائضًا من كربونات المغنيسيوم إلى حمض النيتريك. كيف يعرف أن الحمض استُهلك بالكامل؟","options":["عندما يغلي المحلول","عندما يتجمد المحلول","عندما يتحول اللون إلى الأسود","عندما يتوقف الفوران وتبقى كمية صلبة غير ذائبة في القاع"],"answer":3,"why":"توقف الفقاعات وبقاء مسحوق في القاع يؤكد انتهاء كل الحمض."},{"type":"mcq","q":"ما الخطأ في محاولة تحضير كلوريد الصوديوم بإضافة فائض من NaOH الصلب إلى HCl ثم الترشيح؟","options":["أن فائض NaOH يذوب في الماء فيمر عبر ورق الترشيح ويلوّث الملح","أن NaOH لا يتفاعل مع HCl","أن NaCl غير ذائب","أن HCl صلب"],"answer":0,"why":"الترشيح لا يفصل المواد الذائبة في الماء."},{"type":"mcq","q":"لتحضير كبريتات الرصاص (PbSO₄) غير الذائبة، نخلط محلول نترات الرصاص مع محلول:","options":["كربونات الكالسيوم الصلبة","كبريتات الصوديوم أو حمض الكبريتيك المخفف","نترات البوتاسيوم","كلوريد الصوديوم"],"answer":1,"why":"نحتاج مصدرًا ذائبًا لأيون الكبريتات SO₄²⁻."},{"type":"mcq","q":"يمكن استخدام «الفحم النشط» أحيانًا بدلًا من إعادة المعايرة دون كاشف بغرض:","options":["ترسيب الملح","زيادة حموضة المحلول","امتزاز وإزالة لون الكاشف ثم ترشيح الفحم","تحويل القلوي إلى حمض"],"answer":2,"why":"الفحم النشط يمتص صبغة الكاشف ثم يُفصل بالترشيح."},{"type":"mcq","q":"أي الأملاح الآتية يذوب في الماء؟","options":["كربونات النحاس CuCO₃","كلوريد الفضة AgCl","كبريتات الباريوم BaSO₄","نترات الرصاص Pb(NO₃)₂"],"answer":3,"why":"جميع أملاح النترات ذائبة في الماء دون استثناء."},{"type":"tf","q":"لا يمكن تحضير كبريتات النحاس بتفاعل فلز النحاس مباشرة مع حمض الكبريتيك المخفف.","answer":true,"why":"لأن النحاس لا يتفاعل مع الأحماض المخففة، لذا نستخدم أكسيد النحاس أو كربونات النحاس بدلًا منه"},{"type":"tf","q":"في طريقة المعايرة، نضيف الكاشف فقط لتحديد الحجم الدقيق اللازم للتعادل، ثم نعيد التجربة بدونه.","answer":true,"why":"حتى لا يلوّث الكاشف لون ونقاوة بلورات الملح الناتج"},{"type":"tf","q":"جميع أملاح النترات وأملاح الصوديوم والبوتاسيوم ذائبة في الماء، مما يجعلها مثالية لتحضير الرواسب.","answer":true,"why":"لأنها تضمن توفير الأيونات الموجبة والسالبة في صورة محاليل مائية صافية لخلطها"},{"type":"tf","q":"لا يُصلح استخدام فلز البوتاسيوم مع حمض الكبريتيك لتحضير كبريتات البوتاسيوم في المختبر المدرسي.","answer":true,"why":"لأن تفاعل البوتاسيوم مع الحمض شديد العنف والخطورة وقد يسبب انفجارًا"},{"type":"tfr","q":"في عملية الترسيب، نحتاج لإجراء خطوة التبخير والتبلور للحصول على الراسب.","answer":false,"reasons":["لأن الراسب ذائب","لأن الترشيح يذيب الراسب","الراسب صلب بالفعل فيُفصل مباشرة بالترشيح ثم الغسل والتجفيف دون تبخير"],"reason":2},{"type":"tfr","q":"جميع أملاح الكبريتات تذوب في الماء دون استثناء.","answer":false,"reasons":["لأن كبريتات الباريوم والرصاص والكالسيوم لا تذوب في الماء","لأن الكبريتات كلها غير ذائبة","لأن كبريتات الصوديوم غير ذائبة"],"reason":0},{"type":"tfr","q":"تحوّل كبريتات النحاس المائية إلى لامائية بالتسخين هو تفاعل عكسي.","answer":true,"reasons":["لأنها تتحول إلى نحاس صلب","لأنه يمكن إعادتها إلى اللون الأزرق المائي بإضافة الماء مرة أخرى","لأنها لا تعود زرقاء أبدًا"],"reason":1},{"type":"tfr","q":"تنطلق طاقة حرارية (تفاعل طارد للحرارة) عند إضافة الماء إلى كبريتات النحاس اللامائية البيضاء.","answer":true,"reasons":["لأنه لا يحدث تغير في الطاقة","لأن التفاعل يبرد الأنبوب","لأن عكس التسخين الماص للحرارة هو تفاعل طارد للحرارة يرفع حرارة الأنبوب"],"reason":2},{"type":"essay","q":"لماذا نُوقف تسخين محلول كبريتات النحاس عند «نقطة التبلور» ولا نبخّر الماء كله حتى الجفاف؟","model":"لأن التبريد البطيء من نقطة التبلور يُكوّن بلورات زرقاء منتظمة وكبيرة تحتفظ بماء تبلورها، بينما التسخين للجفاف قد يفقدها ماء التبلور ويحولها لمسحوق أبيض أو يفككها."},{"type":"essay","q":"صف باختصار خطوات تحضير ملح نترات البوتاسيوم (KNO₃) النقي من HNO₃ و KOH.","model":"نقيس حجمًا محددًا من KOH بالماصة ونضيف كاشفًا، ثم نعاير بـ HNO₃ من السحاحة حتى يتغير اللون ونسجل الحجم. نعيد الخلط بنفس الحجمين دون كاشف، ثم نبخّر جزئيًا ونتركه يتبلور ونجفف البلورات."},{"type":"essay","q":"قارن بين خطوات تنقية الملح الذائب المحضّر بطريقة الفائض وخطوات تنقية الملح غير الذائب المحضّر بالترسيب.","model":"في الملح الذائب: نرشح للتخلص من الفائض الصلب ونحتفظ بالرشيح السائل ثم نبخّره جزئيًا ونبرّده للتبلور ونجفف البلورات. في الملح غير الذائب: نرشح للاحتفاظ بالراسب الصلب فوق ورق الترشيح، ثم نغسله بماء مقطر ونجففه."},{"type":"essay","q":"اشرح لماذا ينجح تحضير كلوريد الخارصين باستخدام فلز الخارصين مع HCl، بينما لا ينجح تحضير كلوريد النحاس باستخدام فلز النحاس مع HCl.","model":"لأن الخارصين أنشط من الهيدروجين فيتفاعل مع HCl منتجًا ZnCl₂ + H₂، أما النحاس فأقل نشاطًا من الهيدروجين فلا يتفاعل مع الحمض المخفف؛ لذا نستخدم CuO أو CuCO₃ بدلًا منه."},{"type":"essay","q":"اكتب خطوات تحضير عينة نقية وجافة من كلوريد الفضة (AgCl) مع المعادلة الرمزية الموزونة ورموز الحالة.","model":"نخلط محلول نترات الفضة مع محلول كلوريد الصوديوم فيتكون راسب أبيض من AgCl. نرشح الخليط ونغسل الراسب بماء مقطر ثم نجففه. المعادلة: AgNO₃(aq) + NaCl(aq) → AgCl(s) + NaNO₃(aq)."}]},
  {"id":"g9-chem-2-u9","grade":"g9","subject":"chemistry","term":2,"title":"الوحدة التاسعة: التحليل الكيميائيّ","levels":{"easy":[{"type":"mcq","q":"الفرع الذي يحدّد «هوية ونوع» الأيونات في عينة مجهولة هو:","options":["التحليل الكمي","التحليل النوعي","التقطير","الانصهار"],"answer":1,"why":"التحليل النوعي يكشف عن نوع المواد الموجودة."},{"type":"mcq","q":"الفرع الذي يقيس «مقدار أو تركيز» مادة معينة في عينة هو:","options":["التحليل النوعي","الترشيح","التحليل الكمي","التسامي"],"answer":2,"why":"التحليل الكمي يعطي قيمًا عددية للكمية أو التركيز."},{"type":"mcq","q":"الماء المناسب لإذابة العينات قبل اختبارات الكشف عن الأيونات هو:","options":["ماء الصنبور","ماء البحر","الماء المعدني","الماء المقطّر"],"answer":3,"why":"الماء المقطّر نقي وخالٍ من الأيونات المذابة."},{"type":"mcq","q":"فحص عينة من مصنع أدوية للتأكد من خلوها من الشوائب يُسمّى:","options":["مراقبة الجودة","الاحتباس الحراري","التعادل","الصدأ"],"answer":0,"why":"التحليل الكيميائي أساس مراقبة الجودة في المصانع."}],"medium":[{"type":"mcq","q":"إثبات وجود غاز ثاني أكسيد الكربون بتعكير ماء الجير هو مثال على:","options":["التحليل الكمي","التحليل النوعي","التقطير التجزيئي","المعايرة الحجمية"],"answer":1,"why":"تحديد هوية الغاز دون قياس كتلته هو تحليل نوعي."},{"type":"mcq","q":"استخدام المعايرة لمعرفة تركيز حمض مجهول بوحدة mol/dm³ يُعد:","options":["تحليلًا نوعيًا فقط","ترشيحًا","تحليلًا كميًا","تبلورًا"],"answer":2,"why":"حساب التركيز العددي هو تحليل كمي."},{"type":"mcq","q":"ما الخطر المحتمل إذا استخدم طالب ماء الصنبور لإجراء اختبار الكشف عن أيونات الكلوريد؟","options":["توقف الذوبان","انفجار الأنبوب","تغير لون الزجاج","الحصول على نتيجة إيجابية كاذبة بسبب وجود كلوريد في ماء الصنبور أصلًا"],"answer":3,"why":"ماء الصنبور المعالج يحتوي أيونات كلوريد قد تضلل نتيجة الاختبار."},{"type":"tfr","q":"يُعد فحص نسبة الملوحة في محطات تحلية المياه بسلطنة عُمان تطبيقًا عمليًا للتحليل الكمي.","answer":true,"reasons":["لأنه يقيس تركيز الأملاح الذائبة بالأرقام للتأكد من صلاحية المياه للشرب","لأنه تحليل نوعي فقط","لأنه لا يستخدم الكيمياء"],"reason":0},{"type":"tfr","q":"إذا حوّل سائلٌ كبريتات النحاس البيضاء إلى الزرقاء فهذا دليل قاطع أنه ماء نقي صالح للشرب.","answer":false,"reasons":["لأن كبريتات النحاس لا تكشف الماء","لأن أي محلول مائي (حتى لو كان حمضًا أو ماءً مالحًا) يحوّلها للأزرق؛ النقاء يُفحص بدرجة الغليان/التجمد","لأن الماء النقي لا يغير لونها"],"reason":1}],"hard":[{"type":"mcq","q":"في حادث تسرب نفطي محتمل، أخذ باحث عينة ماء بحر فأثبت وجود مركبات هيدروكربونية بتركيز 12 mg/L. ما نوع التحليل الذي أجراه؟","options":["تحليل نوعي (إثبات الوجود) وكمي (قياس 12 mg/L)","نوعي فقط","كمي فقط","فيزيائي فقط"],"answer":0,"why":"تحديد الهوية نوعي، وقياس التركيز 12 mg/L كمي."},{"type":"mcq","q":"لماذا تُفضّل شركات الأدوية أجهزة التحليل الآلي في خطوط الإنتاج؟","options":["لأنها مجانية تمامًا","لسرعتها الفائقة ودقتها العالية وقدرتها على تحليل عينات صغيرة جدًّا بتكرار موثوق","لأنها لا تحتاج إلى فنيين","لأنها تغيّر تركيب الدواء"],"answer":1,"why":"الدقة والسرعة والحساسية العالية أساسية لضمان أمان الدواء."},{"type":"mcq","q":"أي من الآتي يُعد مثالًا على استخدام التحليل الكيميائي في الأدلة الجنائية؟","options":["بناء الجسور","صناعة الزجاج","التعرف على آثار سموم أو ألياف أو بقايا بارود في مسرح حادث","توليد الكهرباء"],"answer":2,"why":"التحليل الجنائي يطابق آثار المواد الكيميائية في مسرح الحادث."},{"type":"essay","q":"قارن بين التحليل الكيميائي النوعي والتحليل الكمي مع مثال واحد لكل منهما.","model":"التحليل النوعي يحدد نوع المادة الموجودة (مثل التأكد من وجود أيون النحاس في عينة ماء). التحليل الكمي يقيس كمية أو تركيز المادة (مثل قياس تركيز النحاس بـ 0.5 mg/L)."},{"type":"essay","q":"اذكر فائدتين للتحليل الكيميائي في حماية البيئة الزراعية والبحرية.","model":"١) قياس pH وعناصر التربة لتحديد السماد المناسب دون إفراط. ٢) رصد الملوثات الكيميائية أو المعادن الثقيلة في مياه البحر والهواء مبكرًا."}]},"test":[{"type":"mcq","q":"الفرع الذي يحدّد «هوية ونوع» الأيونات في عينة مجهولة هو:","options":["التحليل الكمي","التحليل النوعي","التقطير","الانصهار"],"answer":1,"why":"التحليل النوعي يكشف عن نوع المواد الموجودة."},{"type":"mcq","q":"الفرع الذي يقيس «مقدار أو تركيز» مادة معينة في عينة هو:","options":["التحليل النوعي","الترشيح","التحليل الكمي","التسامي"],"answer":2,"why":"التحليل الكمي يعطي قيمًا عددية للكمية أو التركيز."},{"type":"mcq","q":"الماء المناسب لإذابة العينات قبل اختبارات الكشف عن الأيونات هو:","options":["ماء الصنبور","ماء البحر","الماء المعدني","الماء المقطّر"],"answer":3,"why":"الماء المقطّر نقي وخالٍ من الأيونات المذابة."},{"type":"mcq","q":"فحص عينة من مصنع أدوية للتأكد من خلوها من الشوائب يُسمّى:","options":["مراقبة الجودة","الاحتباس الحراري","التعادل","الصدأ"],"answer":0,"why":"التحليل الكيميائي أساس مراقبة الجودة في المصانع."},{"type":"mcq","q":"إثبات وجود غاز ثاني أكسيد الكربون بتعكير ماء الجير هو مثال على:","options":["التحليل الكمي","التحليل النوعي","التقطير التجزيئي","المعايرة الحجمية"],"answer":1,"why":"تحديد هوية الغاز دون قياس كتلته هو تحليل نوعي."},{"type":"mcq","q":"استخدام المعايرة لمعرفة تركيز حمض مجهول بوحدة mol/dm³ يُعد:","options":["تحليلًا نوعيًا فقط","ترشيحًا","تحليلًا كميًا","تبلورًا"],"answer":2,"why":"حساب التركيز العددي هو تحليل كمي."},{"type":"mcq","q":"ما الخطر المحتمل إذا استخدم طالب ماء الصنبور لإجراء اختبار الكشف عن أيونات الكلوريد؟","options":["توقف الذوبان","انفجار الأنبوب","تغير لون الزجاج","الحصول على نتيجة إيجابية كاذبة بسبب وجود كلوريد في ماء الصنبور أصلًا"],"answer":3,"why":"ماء الصنبور المعالج يحتوي أيونات كلوريد قد تضلل نتيجة الاختبار."},{"type":"mcq","q":"في حادث تسرب نفطي محتمل، أخذ باحث عينة ماء بحر فأثبت وجود مركبات هيدروكربونية بتركيز 12 mg/L. ما نوع التحليل الذي أجراه؟","options":["تحليل نوعي (إثبات الوجود) وكمي (قياس 12 mg/L)","نوعي فقط","كمي فقط","فيزيائي فقط"],"answer":0,"why":"تحديد الهوية نوعي، وقياس التركيز 12 mg/L كمي."},{"type":"mcq","q":"لماذا تُفضّل شركات الأدوية أجهزة التحليل الآلي في خطوط الإنتاج؟","options":["لأنها مجانية تمامًا","لسرعتها الفائقة ودقتها العالية وقدرتها على تحليل عينات صغيرة جدًّا بتكرار موثوق","لأنها لا تحتاج إلى فنيين","لأنها تغيّر تركيب الدواء"],"answer":1,"why":"الدقة والسرعة والحساسية العالية أساسية لضمان أمان الدواء."},{"type":"mcq","q":"أي من الآتي يُعد مثالًا على استخدام التحليل الكيميائي في الأدلة الجنائية؟","options":["بناء الجسور","صناعة الزجاج","التعرف على آثار سموم أو ألياف أو بقايا بارود في مسرح حادث","توليد الكهرباء"],"answer":2,"why":"التحليل الجنائي يطابق آثار المواد الكيميائية في مسرح الحادث."},{"type":"mcq","q":"عند معايرة عينة تربة حمضية، يحدد الفحص الأول أنها حمضية (pH < 7) والفحص الثاني يحدد كمية الجير اللازمة بالضبط لكل هكتار. الفحصان على الترتيب هما:","options":["كلاهما نوعي","كمي ثم نوعي","كلاهما فيزيائي","نوعي ثم كمي"],"answer":3,"why":"معرفة الحموضة نوعي، وحساب الكمية الدقيقة اللازمة كمي."},{"type":"mcq","q":"تتحوّل كبريتات النحاس اللامائية عند إضافة الماء إليها من:","options":["الأبيض إلى الأزرق","الأزرق إلى الأبيض","الأزرق إلى الوردي","الوردي إلى الأخضر"],"answer":0,"why":"CuSO₄ اللامائي أبيض، ومع الماء يصبح CuSO₄·5H₂O أزرق."},{"type":"tf","q":"تعتمد المختبرات الطبية على التحليل الكيميائي النوعي والكمي معًا لتشخيص الأمراض.","answer":true,"why":"فالكشف عن وجود مادة غير طبيعية نوعي، وقياس نسبتها في الدم كمي"},{"type":"tf","q":"الأجهزة التحليلية الآلية الحديثة أقل حساسية من الاختبارات اليدوية البسيطة.","answer":false,"why":"بل هي أكثر حساسية وسرعة بكثير ويمكنها كشف تراكيز ضئيلة جدًّا"},{"type":"tf","q":"يمكن أن يُعطي التحليل النوعي وحده جميع المعلومات اللازمة لتحديد هل مستوى الرصاص في الماء آمن أم سام.","answer":false,"why":"نحتاج للتحليل الكمي أيضًا لمعرفة هل تركيز الرصاص يتجاوز الحد الآمن المسموح به أم لا"},{"type":"tf","q":"تسهم المعايرة الدقيقة لأجهزة التحليل الكيميائي في تقليل الأخطاء المنتظمة وزيادة موثوقية النتائج.","answer":true,"why":"المعايرة بمحاليل قياسية معروفة تضمن صحة القراءات الرقمية"},{"type":"tfr","q":"يُعد فحص نسبة الملوحة في محطات تحلية المياه بسلطنة عُمان تطبيقًا عمليًا للتحليل الكمي.","answer":true,"reasons":["لأنه يقيس تركيز الأملاح الذائبة بالأرقام للتأكد من صلاحية المياه للشرب","لأنه تحليل نوعي فقط","لأنه لا يستخدم الكيمياء"],"reason":0},{"type":"tfr","q":"إذا حوّل سائلٌ كبريتات النحاس البيضاء إلى الزرقاء فهذا دليل قاطع أنه ماء نقي صالح للشرب.","answer":false,"reasons":["لأن كبريتات النحاس لا تكشف الماء","لأن أي محلول مائي (حتى لو كان حمضًا أو ماءً مالحًا) يحوّلها للأزرق؛ النقاء يُفحص بدرجة الغليان/التجمد","لأن الماء النقي لا يغير لونها"],"reason":1},{"type":"tfr","q":"يحتوي الهواء الرطب على بخار ماء كافٍ لتحويل ورق كلوريد الكوبلت الأزرق إلى وردي مع الوقت.","answer":true,"reasons":["لأن الهواء يحوله للأبيض","لأن الكوبلت يتفاعل مع النيتروجين","لذلك يُحفظ في وعاء محكم وجاف بعيدًا عن الرطوبة"],"reason":2},{"type":"tfr","q":"يتجمّد ماء البحر المالح عند درجة حرارة أقل من 0°C بسبب الأملاح الذائبة فيه.","answer":true,"reasons":["الشوائب والأملاح المذابة تخفض درجة تجمد الماء تحت الصفر السيليزي","ماء البحر يتجمد عند 4°C","الملح يرفع درجة التجمد"],"reason":0},{"type":"essay","q":"قارن بين التحليل الكيميائي النوعي والتحليل الكمي مع مثال واحد لكل منهما.","model":"التحليل النوعي يحدد نوع المادة الموجودة (مثل التأكد من وجود أيون النحاس في عينة ماء). التحليل الكمي يقيس كمية أو تركيز المادة (مثل قياس تركيز النحاس بـ 0.5 mg/L)."},{"type":"essay","q":"اذكر فائدتين للتحليل الكيميائي في حماية البيئة الزراعية والبحرية.","model":"١) قياس pH وعناصر التربة لتحديد السماد المناسب دون إفراط. ٢) رصد الملوثات الكيميائية أو المعادن الثقيلة في مياه البحر والهواء مبكرًا."},{"type":"essay","q":"اشرح كيف يتكامل التحليل النوعي والكمي عند فحص مصنع لمياه الشرب المعبأة.","model":"أولًا يكشف التحليل النوعي عن الأيونات الموجودة والتأكد من خلوها من مواد سامة، ثم يقيس التحليل الكمي تركيز كل أيون (مثل الصوديوم والكالسيوم والنترات) للتأكد من بقائه ضمن الحدود الصحية الآمنة."},{"type":"essay","q":"ما أبرز ثلاث مزايا وثلاثة تحديات لاستخدام أجهزة التحليل الآلية الحديثة مقارنةً بالطرق اليدوية؟","model":"المزايا: سرعة عالية، دقة وحساسية فائقة، تحتاج عينات صغيرة جدًّا. التحديات: تكلفتها الشرائية والصيانة العالية، تحتاج كهرباء وتدريبًا متخصصًا، وتحتاج معايرة مستمرة."},{"type":"essay","q":"اقترح خطة فحص كيميائي سريعة لشكوى مزارع من ضعف نمو محصوله وتغيّر طعم ماء البئر.","model":"١) قياس pH التربة والماء. ٢) تحليل نوعي للأيونات (كالكلوريد والكبريتات والحديد) والملوحة. ٣) تحليل كمي لتركيز الأملاح الذائبة والعناصر المغذية لتحديد سبب المشكلة وعلاجها."}]},
  {"id":"g9-chem-2-u10","grade":"g9","subject":"chemistry","term":2,"title":"الوحدة العاشرة: الأرض والغلاف الجوّي","levels":{"easy":[{"type":"mcq","q":"الغاز الأكثر وفرةً في الغلاف الجوي للأرض هو:","options":["الأكسجين (21%)","ثاني أكسيد الكربون (0.04%)","النيتروجين (78%)","الأرجون (0.9%)"],"answer":2,"why":"يمثّل النيتروجين نحو 78% من الهواء الجاف."},{"type":"mcq","q":"أي الغازات الآتية يشكّل نحو 21% من الهواء الجاف النقي؟","options":["الميثان CH₄","النيتروجين N₂","الهيدروجين H₂","الأكسجين O₂"],"answer":3,"why":"نسبة الأكسجين في الهواء الجاف تقارب 21%."},{"type":"mcq","q":"الغاز السام الناتج عن الاحتراق غير الكامل للوقود هو:","options":["أول أكسيد الكربون CO","النيتروجين N₂","الأرجون Ar","الأكسجين O₂"],"answer":0,"why":"الاحتراق غير الكامل ينتج CO السام."},{"type":"mcq","q":"المبدأ الفيزيائي الذي يعتمد عليه التقطير التجزيئي للهواء المسال هو اختلاف الغازات في:","options":["اللون","درجة الغليان","الرائحة","الذوبان في الزيت"],"answer":1,"why":"يغلي النيتروجين عند −196°C والأكسجين عند −183°C."}],"medium":[{"type":"mcq","q":"لماذا تُعبّأ أكياس رقائق البطاطس بغاز النيتروجين (N₂)؟","options":["لأنه يساعد على الاحتراق","لأنه يرفع حموضة الطعام","لأنه غاز خامل يمنع تأكسد الدهون وتلف الطعام","لأنه يعطي لونًا أزرق"],"answer":2,"why":"النيتروجين غير نشط كيميائيًا فيحفظ الطعام طازجًا."},{"type":"mcq","q":"كيف تتكوّن أكاسيد النيتروجين (NOₓ) داخل محركات السيارات؟","options":["من صدأ الهيكل","من وجود النيتروجين في ماء التبريد","من إطارات السيارة","بتفاعل نيتروجين الهواء مع أكسجين الهواء عند درجات الحرارة العالية في المحرك"],"answer":3,"why":"الحرارة العالية في المحرك تكفي لكسر رابطة N₂ وتفاعله مع O₂."},{"type":"mcq","q":"أي زوج من الغازات الآتية يُعد المسبّب الرئيس لظاهرة المطر الحمضي؟","options":["SO₂ و NOₓ","N₂ و Ar","O₂ و H₂","CH₄ و He"],"answer":0,"why":"تذوب SO₂ و NO₂ في ماء المطر مكونةً أحماض الكبريتوز والنيتريك."},{"type":"tfr","q":"الأرجون غاز نشط جدًّا يُستخدم في صناعة الأسمدة الزراعية.","answer":false,"reasons":["الأرجون يسبب المطر الحمضي","الأرجون غاز نبيل خامل جدًّا (المجموعة ١٨)، أما النيتروجين فهو المستخدم في صناعة الأمونيا والأسمدة","الأرجون يشكّل 78% من الهواء"],"reason":1},{"type":"tfr","q":"التفكك الحراري لكربونات الكالسيوم هو تفاعل «ماصّ للحرارة».","answer":true,"reasons":["لأنه يحدث في الثلاجة","لأنه ينطلق منه لهب","لأنه يتطلب تزويدًا مستمرًا بالحرارة العالية لكسر الروابط وتفكيك CaCO₃"],"reason":2}],"hard":[{"type":"mcq","q":"في تجربة تمرير 80 cm³ من الهواء فوق نحاس ساخن حتى ثبات الحجم بعد التبريد، ما الحجم المتوقّع للهواء المتبقي؟","options":["نحو 17 cm³","نحو 63 cm³","نحو 80 cm³","نحو 40 cm³"],"answer":1,"why":"يُستهلك 21% من 80 cm³ (≈ 16.8 cm³)، فيبقى 80 − 16.8 ≈ 63 cm³."},{"type":"mcq","q":"في برج التقطير التجزيئي للهواء المسال، لماذا يُزال بخار الماء وثاني أكسيد الكربون «قبل» التبريد الشديد؟","options":["لأنهما يغليان قبل النيتروجين","لأنهما يتفاعلان مع الأرجون","لأنهما يتجمّدان إلى جليد وجليد جاف فيسدّان الأنابيب","لأنهما غير موجودين في الهواء"],"answer":2,"why":"تجمد H₂O عند 0°C و CO₂ عند −78°C يغلق أنابيب المصنع."},{"type":"mcq","q":"ما الغاز الذي يخرج «أولًا» من أعلى برج التقطير التجزيئي للهواء المسال (علما أن غليان N₂ = −196°C، Ar = −186°C، O₂ = −183°C)؟","options":["الأرجون Ar","الأكسجين O₂","تخرج جميعها معًا","النيتروجين N₂ (لأن درجة غليانه هي الأدنى)"],"answer":3,"why":"المادة ذات درجة الغليان الأدنى (−196°C) تتبخر أولًا عند التسخين التدريجي."},{"type":"essay","q":"لماذا يُعد أول أكسيد الكربون (CO) غازًا شديد الخطورة على الإنسان؟","model":"لأنه غاز عديم اللون والرائحة (يصعب اكتشافه) ويرتبط بقوة بهيموجلوبين الدم فيمنعه من نقل الأكسجين إلى خلايا الجسم، ما قد يسبب الاختناق والوفاة."},{"type":"essay","q":"اذكر طريقتين عمليتين لتقليل انبعاثات الغازات المسبّبة للمطر الحمضي من السيارات ومحطات الطاقة.","model":"١) إزالة الكبريت من الوقود قبل حرقه أو معالجة غازات المداخن بأكسيد الكالسيوم لتقليل SO₂. ٢) تركيب المحوّل الحفّاز في عوادم السيارات لتحويل NO و CO إلى N₂ و CO₂."}]},"test":[{"type":"mcq","q":"الغاز الأكثر وفرةً في الغلاف الجوي للأرض هو:","options":["الأكسجين (21%)","ثاني أكسيد الكربون (0.04%)","النيتروجين (78%)","الأرجون (0.9%)"],"answer":2,"why":"يمثّل النيتروجين نحو 78% من الهواء الجاف."},{"type":"mcq","q":"أي الغازات الآتية يشكّل نحو 21% من الهواء الجاف النقي؟","options":["الميثان CH₄","النيتروجين N₂","الهيدروجين H₂","الأكسجين O₂"],"answer":3,"why":"نسبة الأكسجين في الهواء الجاف تقارب 21%."},{"type":"mcq","q":"الغاز السام الناتج عن الاحتراق غير الكامل للوقود هو:","options":["أول أكسيد الكربون CO","النيتروجين N₂","الأرجون Ar","الأكسجين O₂"],"answer":0,"why":"الاحتراق غير الكامل ينتج CO السام."},{"type":"mcq","q":"المبدأ الفيزيائي الذي يعتمد عليه التقطير التجزيئي للهواء المسال هو اختلاف الغازات في:","options":["اللون","درجة الغليان","الرائحة","الذوبان في الزيت"],"answer":1,"why":"يغلي النيتروجين عند −196°C والأكسجين عند −183°C."},{"type":"mcq","q":"لماذا تُعبّأ أكياس رقائق البطاطس بغاز النيتروجين (N₂)؟","options":["لأنه يساعد على الاحتراق","لأنه يرفع حموضة الطعام","لأنه غاز خامل يمنع تأكسد الدهون وتلف الطعام","لأنه يعطي لونًا أزرق"],"answer":2,"why":"النيتروجين غير نشط كيميائيًا فيحفظ الطعام طازجًا."},{"type":"mcq","q":"كيف تتكوّن أكاسيد النيتروجين (NOₓ) داخل محركات السيارات؟","options":["من صدأ الهيكل","من وجود النيتروجين في ماء التبريد","من إطارات السيارة","بتفاعل نيتروجين الهواء مع أكسجين الهواء عند درجات الحرارة العالية في المحرك"],"answer":3,"why":"الحرارة العالية في المحرك تكفي لكسر رابطة N₂ وتفاعله مع O₂."},{"type":"mcq","q":"أي زوج من الغازات الآتية يُعد المسبّب الرئيس لظاهرة المطر الحمضي؟","options":["SO₂ و NOₓ","N₂ و Ar","O₂ و H₂","CH₄ و He"],"answer":0,"why":"تذوب SO₂ و NO₂ في ماء المطر مكونةً أحماض الكبريتوز والنيتريك."},{"type":"mcq","q":"في تجربة تمرير 80 cm³ من الهواء فوق نحاس ساخن حتى ثبات الحجم بعد التبريد، ما الحجم المتوقّع للهواء المتبقي؟","options":["نحو 17 cm³","نحو 63 cm³","نحو 80 cm³","نحو 40 cm³"],"answer":1,"why":"يُستهلك 21% من 80 cm³ (≈ 16.8 cm³)، فيبقى 80 − 16.8 ≈ 63 cm³."},{"type":"mcq","q":"في برج التقطير التجزيئي للهواء المسال، لماذا يُزال بخار الماء وثاني أكسيد الكربون «قبل» التبريد الشديد؟","options":["لأنهما يغليان قبل النيتروجين","لأنهما يتفاعلان مع الأرجون","لأنهما يتجمّدان إلى جليد وجليد جاف فيسدّان الأنابيب","لأنهما غير موجودين في الهواء"],"answer":2,"why":"تجمد H₂O عند 0°C و CO₂ عند −78°C يغلق أنابيب المصنع."},{"type":"mcq","q":"ما الغاز الذي يخرج «أولًا» من أعلى برج التقطير التجزيئي للهواء المسال (علما أن غليان N₂ = −196°C، Ar = −186°C، O₂ = −183°C)؟","options":["الأرجون Ar","الأكسجين O₂","تخرج جميعها معًا","النيتروجين N₂ (لأن درجة غليانه هي الأدنى)"],"answer":3,"why":"المادة ذات درجة الغليان الأدنى (−196°C) تتبخر أولًا عند التسخين التدريجي."},{"type":"mcq","q":"أي من الآتي يفسّر لماذا لا يُستخدم المحوّل الحفّاز لتقليل غاز ثاني أكسيد الكربون (CO₂)؟","options":["لأن المحوّل الحفّاز يُنتج CO₂ أصلًا عند أكسدة CO السام (2CO + 2NO → 2CO₂ + N₂)","لأن CO₂ غاز سام أكثر من CO","لأن البلاتين يمتص CO₂","لأن السيارات لا تنتج CO₂"],"answer":0,"why":"المحوّل الحفّاز يحوّل CO السام إلى CO₂ الأقل سمّية، لكنه لا يزيل CO₂."},{"type":"mcq","q":"الصيغة الكيميائية للحجر الجيري (كربونات الكالسيوم) هي:","options":["Ca(OH)₂","CaCO₃","CaO","CaCl₂"],"answer":1,"why":"الحجر الجيري يتكوّن أساسًا من كربونات الكالسيوم CaCO₃."},{"type":"tf","q":"يجب انتظار تبريد الأنبوب حتى درجة حرارة الغرفة قبل قراءة الحجم النهائي في تجربة النحاس والهواء.","answer":true,"why":"لأن الهواء الساخن يكون متمددًا فيعطي قراءة حجم أكبر من الحقيقي ويقلل نسبة الأكسجين المحسوبة"},{"type":"tf","q":"يُعد غازا ثاني أكسيد الكربون والميثان من الغازات الدفيئة المسؤولة عن الاحتباس الحراري.","answer":true,"why":"لأنهما يمتصان الأشعة تحت الحمراء الصادرة من الأرض ويعيدان إشعاعها نحوها"},{"type":"tf","q":"تُستخدم فلزات انتقالية ثمينة كالبلاتين والروديوم في المحوّل الحفّاز لأنها تعمل كعوامل حفّازة تسرّع التفاعلات دون أن تُستهلك.","answer":true,"why":"وتُصمَّم على شكل قرص عسل ذي مساحة سطح كبيرة جدًّا لزيادة كفاءة التحويل"},{"type":"tf","q":"يؤدي استخدام الوقود المحتوي على الرصاص إلى «تسميم» المحوّل الحفّاز وإتلافه.","answer":true,"why":"لأن الرصاص يغطّي سطح البلاتين الحفّاز ويمنع الغازات من التفاعل؛ لذا نستخدم بنزينًا خاليًا من الرصاص"},{"type":"tfr","q":"الأرجون غاز نشط جدًّا يُستخدم في صناعة الأسمدة الزراعية.","answer":false,"reasons":["الأرجون يسبب المطر الحمضي","الأرجون غاز نبيل خامل جدًّا (المجموعة ١٨)، أما النيتروجين فهو المستخدم في صناعة الأمونيا والأسمدة","الأرجون يشكّل 78% من الهواء"],"reason":1},{"type":"tfr","q":"التفكك الحراري لكربونات الكالسيوم هو تفاعل «ماصّ للحرارة».","answer":true,"reasons":["لأنه يحدث في الثلاجة","لأنه ينطلق منه لهب","لأنه يتطلب تزويدًا مستمرًا بالحرارة العالية لكسر الروابط وتفكيك CaCO₃"],"reason":2},{"type":"tfr","q":"ماء الجير هو الاسم الشائع لمحلول أكسيد الكالسيوم الصلب غير الذائب.","answer":false,"reasons":["ماء الجير هو المحلول المائي الرائق لهيدروكسيد الكالسيوم Ca(OH)₂(aq)","ماء الجير هو حمض الكربونيك","ماء الجير هو CaCO₃ الذائب"],"reason":0},{"type":"tfr","q":"يُعد الحجر الجيري موردًا غير متجدد لكنه متوفر بكثرة في القشرة الأرضية، ويمكن إعادة تأهيل المحاجر بعد إغلاقها.","answer":true,"reasons":["لأن الحجر الجيري ينمو كل سنة كالأشجار","يمكن تحويل المحاجر المغلقة إلى بحيرات أو محميات طبيعية لتقليل الأثر البيئي","لأن المحاجر بلا أثر بيئي"],"reason":1},{"type":"essay","q":"لماذا يُعد أول أكسيد الكربون (CO) غازًا شديد الخطورة على الإنسان؟","model":"لأنه غاز عديم اللون والرائحة (يصعب اكتشافه) ويرتبط بقوة بهيموجلوبين الدم فيمنعه من نقل الأكسجين إلى خلايا الجسم، ما قد يسبب الاختناق والوفاة."},{"type":"essay","q":"اذكر طريقتين عمليتين لتقليل انبعاثات الغازات المسبّبة للمطر الحمضي من السيارات ومحطات الطاقة.","model":"١) إزالة الكبريت من الوقود قبل حرقه أو معالجة غازات المداخن بأكسيد الكالسيوم لتقليل SO₂. ٢) تركيب المحوّل الحفّاز في عوادم السيارات لتحويل NO و CO إلى N₂ و CO₂."},{"type":"essay","q":"اشرح خطوات فصل الأكسجين والنيتروجين من الهواء الجوي بالتقطير التجزيئي مع ذكر درجات الغليان.","model":"١) يُرشّح الهواء ويُزال منه بخار الماء و CO₂ لمنع انسداد الأنابيب. ٢) يُضغط ويُبرّد حتى −200°C فيتحول إلى سائل. ٣) يُسخّن تدريجيًا في برج التقطير: يتبخر النيتروجين أولًا عند −196°C ويُجمع من الأعلى، ثم الأرجون (−186°C)، ويبقى الأكسجين السائل ليغلي عند −183°C."},{"type":"essay","q":"لماذا يختلف حجم الغاز المتبقي في تجربة النحاس الساخن إذا لم يُستخدم «فائض» من النحاس؟","model":"إذا لم يوجد فائض من النحاس فقد لا يتفاعل كل الأكسجين الموجود في الهواء، فيبقى حجم الهواء أكبر من 79% وتكون نسبة الأكسجين المحسوبة أقل من 21%."},{"type":"essay","q":"اكتب المعادلة الرمزية الموزونة لتفاعل النحاس مع الأكسجين في تجربة قياس نسبة الأكسجين، واذكر التغيّر اللوني الملاحظ.","model":"2Cu(s) + O₂(g) → 2CuO(s). يتغيّر لون النحاس من البني المحمر اللامع إلى الأسود (أكسيد النحاس)."}]}
);
